enum CloudDownloadItemStatus {
  pending,
  downloading,
  completed,
  failed,
  skipped
}

class CloudDownloadItem {
  final String id;
  final String pageId;
  final String nodeId;
  final String label;
  final String fileName;
  final String kind;
  double progress;
  CloudDownloadItemStatus status;
  bool skip;
  String? error;

  CloudDownloadItem({
    required this.id,
    required this.pageId,
    required this.nodeId,
    required this.label,
    required this.fileName,
    required this.kind,
    this.progress = 0,
    this.status = CloudDownloadItemStatus.pending,
    this.skip = false,
    this.error,
  });

  bool get canSkip =>
      status == CloudDownloadItemStatus.pending ||
      status == CloudDownloadItemStatus.skipped;
  bool get canRetry =>
      status == CloudDownloadItemStatus.failed &&
      (kind == 'attachment' || kind == 'video');
}

/// AI 要約・解説に使った「資料の文脈」をページ単位で保持するためのクラス。
/// 要約完了後、ユーザーが「この資料についてもう少し質問したい」と思った
/// ときに参照する。ファイル要約 (summarize) のページにのみ作成される
/// (explain は概念解説で AI 内部知識ベースなので追加文脈は不要)。
///
/// テキスト系ファイル: textContent に本文を保存。
/// バイナリ系 (PDF/docx/pptx): filePath だけ保存し、毎回 AI に再添付する。
class AiPageContext {
  /// 資料ファイル名 (UI 表示用)
  final String fileName;

  /// テキスト系ファイルの本文 (60K 文字に切り詰め済み)。バイナリは null。
  final String? textContent;

  /// バイナリドキュメント (pdf/docx/pptx) のフルパス。テキストは null。
  /// ファイルが移動・削除された場合のフォールバックは textContent 無しで askAi。
  final String? filePath;

  /// 拡張子 ('pdf'/'docx'/'pptx'/'txt' など)。バイナリ判定に使う。
  final String? ext;

  /// 追加質問の履歴 (ユーザーが Q&A した分だけ蓄積)。
  /// chronological 順 (古い → 新しい)。
  final List<AiQAEntry> qaHistory;

  AiPageContext({
    required this.fileName,
    this.textContent,
    this.filePath,
    this.ext,
  }) : qaHistory = [];
}

