  // ── OpenRouter (= ユーザー要望: 各社のキーを個別に取得しなくても、
  //    1 つのキーで色々なモデルを切り替えて叩けるように)。 OpenAI 互換
  //    API。 モデルは "openai/gpt-4o-mini" のような provider/model 形式。
  //    エンドポイントは差し替え可能 (将来、 手数料上乗せの自前リレー
  //    サーバーへ向けられるように prefs で上書きできる)。 ──
  String? _openrouterApiKey;
  String? get openrouterApiKey => _openrouterApiKey;
  bool get hasOpenrouterKey => (_openrouterApiKey ?? '').isNotEmpty;
  Future<void> setOpenrouterApiKey(String key) async {
    _openrouterApiKey = key.trim();
    final prefs = await _prefsWithRetry();
    await prefs.setString('openrouter_api_key', _openrouterApiKey!);
    notifyListeners();
  }

  String _openrouterModel = 'openai/gpt-4o-mini';
  String get openrouterModel => _openrouterModel;
  Future<void> setOpenrouterModel(String model) async {
    _openrouterModel =
        model.trim().isEmpty ? 'openai/gpt-4o-mini' : model.trim();
    final prefs = await _prefsWithRetry();
    await prefs.setString('openrouter_model', _openrouterModel);
    notifyListeners();
  }

  /// OpenRouter 互換エンドポイント (既定は本家)。 自前のリレーサーバー
  /// (手数料上乗せ用) に差し替える時は prefs `openrouter_base_url` を設定。
  String _openrouterBaseUrl = 'https://openrouter.ai/api/v1';
  String get openrouterBaseUrl => _openrouterBaseUrl;

  /// 使用するAIプロバイダ
  /// ('gemini' | 'openai' | 'anthropic' | 'grok' | 'deepseek' | 'openrouter')
  String _aiProvider = 'gemini';
  String get aiProvider => _aiProvider;
  Future<void> setAiProvider(String provider) async {
    if (!['gemini', 'openai', 'anthropic', 'grok', 'deepseek', 'openrouter']
        .contains(provider)) {
      return;
    }
    _aiProvider = provider;
    final prefs = await _prefsWithRetry();
    await prefs.setString('aiProvider', provider);
    notifyListeners();
  }

  // ── ノードAIボタンの「ブラウザAI」 ターゲット ──────────────────────────
  // ノードのAIボタンは API キーを叩かず、 ノードタイトルの用語を Web の AI
  // (ChatGPT / Gemini / Perplexity 等) にクエリとして渡してアプリ内で開く。
  // どの AI を使うかは AIボタンの右クリック / 長押しで切り替え、 ここに保持・
  // 永続化する。 `{q}` をエンコード済みクエリで置換して URL を作る。
  static const List<Map<String, String>> browserAiTargets = [
    {'id': 'chatgpt', 'label': 'ChatGPT', 'url': 'https://chatgpt.com/?q={q}'},
    {
      'id': 'gemini',
      'label': 'Gemini',
      'url': 'https://gemini.google.com/app?q={q}'
    },
    {
      'id': 'perplexity',
      'label': 'Perplexity',
      'url': 'https://www.perplexity.ai/search?q={q}'
    },
    {'id': 'claude', 'label': 'Claude', 'url': 'https://claude.ai/new?q={q}'},
    {'id': 'grok', 'label': 'Grok', 'url': 'https://grok.com/?q={q}'},
    // DeepSeek (= ユーザー要望: ノードAIボタンの「質問モード」 にも DeepSeek を
    //   選べるように)。 Web チャットは ?q= でクエリ事前入力に対応。
    {
      'id': 'deepseek',
      'label': 'DeepSeek',
      'url': 'https://chat.deepseek.com/?q={q}'
    },
    // ── Google は「AI を選ぶ」 リストから除外 (= ユーザー要望:
    //   「google 検索が立ち上がるボタンは要らない、 AI じゃない」) ──
    // Google 検索は専用の googleSearch ボタンから使う。 以前ここに google
    // エントリがあったが、 AI チャット判定・分割パネル等では元々 id=='google'
    // を弾いていた (各所の `!= 'google'` ガードは無害な保険として残置)。
  ];
  String _browserAiTarget = 'chatgpt';
  String get browserAiTarget => _browserAiTarget;
  Map<String, String> get browserAiTargetDef => browserAiTargets.firstWhere(
        (e) => e['id'] == _browserAiTarget,
        orElse: () => browserAiTargets.first,
      );
  String get browserAiTargetLabel => browserAiTargetDef['label'] ?? 'AI';
  Future<void> setBrowserAiTarget(String id) async {
    if (browserAiTargets.every((e) => e['id'] != id)) return;
    _browserAiTarget = id;
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setString('browser_ai_target', id);
    } catch (_) {}
    notifyListeners();
  }

  /// ブラウザ版 AI に文字を渡すときに先頭へ付ける「前提条件」
  /// (= ユーザー要望: 「日本語で答えて」 「以下の用語を解説して」 等)。
  String _browserAiPrefix = '';
  String get browserAiPrefix => _browserAiPrefix;
  Future<void> setBrowserAiPrefix(String v) async {
    _browserAiPrefix = v;
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setString('browser_ai_prefix', v);
    } catch (_) {}
    notifyListeners();
  }

  /// 前提条件を本文の先頭に付けて返す (前提条件が空なら本文そのまま)。
  /// ブラウザ AI へ文字を渡す全経路 (ノードの AI ボタン・範囲選択など) で使う。
  String browserAiApplyPrefix(String text) {
    final p = _browserAiPrefix.trim();
    if (p.isEmpty) return text;
    return '$p\n\n$text';
  }

  /// ノードタイトル等のクエリを、 現在の ブラウザAI ターゲットの URL に
  /// 埋め込んで返す。 query は URL エンコードされる。
  String browserAiUrlForQuery(String query) {
    final tmpl =
        browserAiTargetDef['url'] ?? 'https://www.google.com/search?q={q}';
    return tmpl.replaceAll('{q}', Uri.encodeQueryComponent(query.trim()));
  }

  /// 現在選択中のプロバイダの「使える状態」 (= API キーが設定済みか)。
  /// 自分のキーの有無だけを見る (代行実行の判定はこちらを使う)。
  bool get hasOwnAiKey {
    switch (_aiProvider) {
      case 'openai':
        return hasOpenaiKey;
      case 'anthropic':
        return hasAnthropicKey;
      case 'grok':
        return hasGrokKey;
      case 'deepseek':
        return hasDeepseekKey;
      case 'openrouter':
        return hasOpenrouterKey;
      default:
        return hasGeminiKey;
    }
  }

  bool get hasActiveAiKey {
    // ★ AI はこちらが用意したキー (代行サーバー) のみ (= ユーザー要望)。
    //   残高があれば使える。 BYOK は廃止。
    return canUseAiRelay;
    // ignore: dead_code
    if (canUseAiRelay) return true;
    switch (_aiProvider) {
      case 'openai':
        return hasOpenaiKey;
      case 'anthropic':
        return hasAnthropicKey;
      case 'grok':
        return hasGrokKey;
      case 'deepseek':
        return hasDeepseekKey;
      case 'openrouter':
        return hasOpenrouterKey;
      default:
        return hasGeminiKey;
    }
  }

  // ── アプリ言語設定（AI出力の言語にも適用）─────────────────────────────────
  /// サポート言語コード
  /// 並び順: 話者人口（L1 + L2）の多い順（Ethnologue 基準の概算）
  ///   en : English            ~ 1.5B
  ///   zh : Chinese (Mandarin) ~ 1.1B
  ///   es : Spanish            ~ 560M
  ///   fr : French             ~ 310M
  ///   pt : Portuguese         ~ 265M
  ///   ru : Russian            ~ 255M
  ///   de : German             ~ 135M
  ///   ja : Japanese           ~ 125M
  ///   ko : Korean             ~  82M
  /// アプリがUI上対応している言語コード一覧（Ethnologue 第27版・2025 の
  /// L1+L2 合計話者数で上位30）。世界人口 81億の約94%をカバーする。
  ///
  /// すべての翻訳キーが全言語に揃っているのは原9言語
  /// (en/ja/zh/ko/es/fr/de/pt/ru) のみ。それ以外の21言語は段階的に
  /// 翻訳を追加していく方針で、未翻訳キーは t() のフォールバックチェーン
  /// (要求言語 → en → ja → key) により英語表記で表示される。
  ///
  /// アラビア語系・ペルシャ語系・ウルドゥー語・西パンジャブ語は RTL 言語だが、
  /// 現状の MaterialApp は LTR 固定で動作する。RTL 対応は別途 Directionality を
  /// 言語ごとに切り替える対応が必要 (TODO)。
  static const List<String> supportedLanguages = [
    'en', // English (1位)
    'zh', // Mandarin Chinese (2位)
    'hi', // Hindi (3位)
    'es', // Spanish (4位)
    'ar', // Modern Standard Arabic (5位)
    'fr', // French (6位)
    'bn', // Bengali (7位)
    'pt', // Portuguese (8位)
    'ru', // Russian (9位)
    'id', // Indonesian (10位)
    'ur', // Urdu (11位)
    'de', // German (12位)
    'ja', // Japanese (13位)
    'pcm', // Nigerian Pidgin (14位)
    'arz', // Egyptian Arabic (15位)
    'mr', // Marathi (16位)
    'vi', // Vietnamese (17位)
    'te', // Telugu (18位)
    'ha', // Hausa (19位)
    'tr', // Turkish (20位)
    'pnb', // Western Punjabi (21位)
    'sw', // Swahili (22位)
    'tl', // Tagalog (23位)
    'ta', // Tamil (24位)
    'yue', // Yue / Cantonese (25位)
    'wuu', // Wu / Shanghainese (26位)
    'fa', // Iranian Persian (27位)
    'ko', // Korean (28位)
    'th', // Thai (29位)
    'jv', // Javanese (30位)
  ];

