  /// 指定キーの翻訳を現在の言語で返す。
  ///
  /// フォールバックチェーン:
  ///   1. 要求言語 (`_appLanguage`) の翻訳
  ///   2. 英語 (`'en'`) の翻訳
  ///   3. 日本語 (`'ja'`) の翻訳
  ///   4. キー文字列そのもの
  ///
  /// 上位30言語に拡張したが、原9言語以外 (= ヒンディー / アラビア / ベンガル
  /// 等) はまだ全キーの翻訳が揃っていない。未翻訳のキーは英語にフォールバック
  /// するので、ユーザーに「日本語が混じる」現象は起きない。
  String t(String key) {
    final entry = _translations[key];
    if (entry == null) return key;
    return entry[_appLanguage] ?? entry['en'] ?? entry['ja'] ?? key;
  }

  // ── AI生成設定 ──────────────────────────────────────────────────
  /// 生成深さ: 1=子ノードのみ, 2=子＋孫ノード
  int aiDepth = 1;

  /// 子ノード生成数の範囲
  int aiChildMin = 5;
  int aiChildMax = 8;

  /// 孫ノード生成数の範囲（aiDepth==2 の場合のみ使用）
  int aiGrandchildMin = 3;
  int aiGrandchildMax = 5;

  /// 選択モデル: 'flash' または 'pro'
  String aiModelTier = 'flash';

  // ── 使用量トラッキング ──────────────────────────────────────────────────
  /// 直近のリクエストのトークン数とコスト
  int lastInputTokens = 0;
  int lastOutputTokens = 0;
  double lastCostUsd = 0.0;

  /// 累計使用量（永続化）
  int totalInputTokens = 0;
  int totalOutputTokens = 0;
  double totalCostUsd = 0.0;

  /// Gemini API価格（2026年4月時点、USD/1M トークン）
  /// - Flash (gemini-2.5-flash): $0.30 input / $2.50 output
  /// - Pro   (gemini-2.5-pro):   $1.25 input / $10.00 output
  static const Map<String, Map<String, double>> _pricing = {
    'flash': {'input': 0.30, 'output': 2.50},
    'pro': {'input': 1.25, 'output': 10.00},
  };

  /// コスト計算（USD）
  static double calcCostUsd(String tier, int inputTokens, int outputTokens) {
    final p = _pricing[tier] ?? _pricing['flash']!;
    final ic = (inputTokens / 1000000) * p['input']!;
    final oc = (outputTokens / 1000000) * p['output']!;
    return ic + oc;
  }

  // ─── 従量課金の上乗せ ───
  //
  // AI は代行サーバー (アプリ側のキー) 経由でのみ動く。 実際の請求額を
  // 決めているのは Worker 側の `MARKUP` で、 **こちらの値は表示用**。
  //
  // ★ Worker の MARKUP と必ず同じ値にすること。 ずれていると、 画面に出る
  //   「取り分」 が実際と食い違う (2026-08-10: 0.10 のままで 0.20 と
  //   ずれていたのを修正)。
  static const double kUsageMarkupRate = 0.20;

  /// 原価 [costUsd] に上乗せした「請求額」。
  static double billedCostUsd(double costUsd) =>
      costUsd * (1 + kUsageMarkupRate);

  /// 原価との差額 (= 取り分)。
  static double marginUsd(double costUsd) => costUsd * kUsageMarkupRate;

  /// 代行実行した分の累計 **原価** (上乗せ前)。
  double _appKeyCostUsd = 0.0;
  double get appKeyCostUsd => _appKeyCostUsd;

  /// 代行実行した分の累計 **請求額** (上乗せ後)。
  ///
  /// ★ Worker が計算した値をそのまま積む。 以前は原価用の入れ物へ請求額を
  ///   入れた上で更に 1.1 倍していたため、 二重に上乗せされた額が出ていた。
  double _appKeyBilledUsd = 0.0;
  double get appKeyBilledUsd => _appKeyBilledUsd;

  /// 代行実行分の取り分 (= 請求額 − 原価)。
  double get appKeyMarginUsd =>
      (_appKeyBilledUsd - _appKeyCostUsd).clamp(0.0, double.infinity);

  /// 代行実行の使用量を記録する (アプリ側キーで動かした時だけ呼ぶ)。
  /// [costUsd] を渡すとその原価をそのまま積む (= Worker が計算した値)。
  /// 省略した場合は [tier] とアプリ内の料金表から概算する。
  void recordAppKeyUsage({
    required int inputTokens,
    required int outputTokens,
    double? costUsd,
    double? billedUsd,
    String tier = 'flash',
  }) {
    totalInputTokens += inputTokens;
    totalOutputTokens += outputTokens;
    final cost = costUsd ?? calcCostUsd(tier, inputTokens, outputTokens);
    _appKeyCostUsd += cost;
    // 請求額はサーバーの値が正。 来ていなければ表示用の率で概算する。
    _appKeyBilledUsd += billedUsd ?? billedCostUsd(cost);
    // ignore: discarded_futures
    _saveUsageTotals();
    // ignore: discarded_futures
    _prefsWithRetry().then((p) {
      p.setDouble('appKeyCostUsd', _appKeyCostUsd);
      p.setDouble('appKeyBilledUsd', _appKeyBilledUsd);
    });
    notifyListeners();
  }

  /// USDを日本円に概算変換（1 USD ≒ 170円で固定）
  static double usdToJpy(double usd) => usd * 170.0;

  /// 金額を整形（$0.0012 / ¥0.19 のように）
  static String formatCost(double usd) {
    final jpy = usdToJpy(usd);
    if (usd < 0.01) {
      return '\$${usd.toStringAsFixed(4)} (約¥${jpy.toStringAsFixed(2)})';
    }
    return '\$${usd.toStringAsFixed(3)} (約¥${jpy.toStringAsFixed(2)})';
  }

  Future<void> _loadAiSettings() async {
    final prefs = await _prefsWithRetry();
    aiDepth = prefs.getInt('aiDepth') ?? 1;
    aiChildMin = prefs.getInt('aiChildMin') ?? 5;
    aiChildMax = prefs.getInt('aiChildMax') ?? 8;
    aiGrandchildMin = prefs.getInt('aiGrandchildMin') ?? 3;
    aiGrandchildMax = prefs.getInt('aiGrandchildMax') ?? 5;
    aiModelTier = prefs.getString('aiModelTier') ?? 'flash';
    totalInputTokens = prefs.getInt('totalInputTokens') ?? 0;
    _appKeyCostUsd = prefs.getDouble('appKeyCostUsd') ?? 0.0;
    _appKeyBilledUsd =
        prefs.getDouble('appKeyBilledUsd') ?? billedCostUsd(_appKeyCostUsd);
    _relayModel = prefs.getString('relayModel') ?? 'gemini-flash-latest';
    // 考える深さ (= ユーザー要望)。 既定は「普通」。
    //   廃止した 'auto' が残っている端末は、 そのまま「普通」 になる。
    final rl = prefs.getString('relayReasoning');
    if (rl != null && relayReasoningLevels.contains(rl)) _relayReasoning = rl;
    _openTarget = prefs.getString('openTarget') ?? 'same';
    totalOutputTokens = prefs.getInt('totalOutputTokens') ?? 0;
    totalCostUsd = prefs.getDouble('totalCostUsd') ?? 0.0;
  }

  Future<void> saveAiSettings() async {
    final prefs = await _prefsWithRetry();
    await prefs.setInt('aiDepth', aiDepth);
    await prefs.setInt('aiChildMin', aiChildMin);
    await prefs.setInt('aiChildMax', aiChildMax);
    await prefs.setInt('aiGrandchildMin', aiGrandchildMin);
    await prefs.setInt('aiGrandchildMax', aiGrandchildMax);
    await prefs.setString('aiModelTier', aiModelTier);
    notifyListeners();
  }

  /// 累計使用量を永続化
  Future<void> _saveUsageTotals() async {
    final prefs = await _prefsWithRetry();
    await prefs.setInt('totalInputTokens', totalInputTokens);
    await prefs.setInt('totalOutputTokens', totalOutputTokens);
    await prefs.setDouble('totalCostUsd', totalCostUsd);
  }

  /// 累計使用量をリセット
  Future<void> resetUsageTotals() async {
    totalInputTokens = 0;
    totalOutputTokens = 0;
    totalCostUsd = 0.0;
    await _saveUsageTotals();
    notifyListeners();
  }

  /// 起動時に最優先で読む UI 状態 (= ユーザー報告 (複数回): モバイルで言語
  /// ピッカーが出ない / 言語が英語のまま / 下部ボタンが集中ロックだけで他が空)。
  /// _loadGeminiApiKey の途中で万一ハング/例外が起きても、 これらだけは確実に
  /// 読めるように、 短く各行 try/catch で読み、 初期化 Completer もここで完了
  /// させる (= ピッカー判定を確実に走らせる)。 _loadGeminiApiKey でも同じものを
  /// 読むが冪等。
  /// SharedPreferences を取得する (= release 起動レース対策)。
  /// ★ ユーザー報告: Android の **release** ビルドだけ、 初回起動時に
  ///   言語/タイムゾーン/ユーザー名の設定が一切出ない / 言語が英語固定 /
  ///   下部ボタンが空。 原因は AOT の高速起動で、 起動直後 (~1秒) はまだ
  ///   shared_preferences プラグインのプラットフォームチャンネルが準備でき
  ///   ておらず、 コンストラクタから即発火する各 _load* の getInstance() が
  ///   `channel-error (Unable to establish connection on channel ...
  ///   SharedPreferencesApi.getAll)` で失敗していたこと。 その結果
  ///   _isFirstLaunch が確定せず (false のまま) オンボーディングが出ず、
  ///   設定も既定値のままになる。 debug は起動が遅くチャンネルが先に準備
  ///   できるため再現しない。
  /// 対策: getInstance() が失敗したら 200ms 待って再試行する (最大 ~3秒)。
  ///   getInstance() はエラー時に内部 completer を破棄するので、 再呼び出し
  ///   で確実に再試行される。 起動後の通常呼び出しはキャッシュ済みで即成功
  ///   するため、 この再試行は無害 (待ちは発生しない)。
  Future<SharedPreferences> _prefsWithRetry({int tries = 15}) async {
    for (int i = 0; i < tries; i++) {
      try {
        return await SharedPreferences.getInstance();
      } catch (_) {
        await Future<void>.delayed(const Duration(milliseconds: 200));
      }
    }
    // 最後にもう一度 (なお失敗するなら例外を伝播 = 各呼び出し側の try/catch
    //   が従来どおりハンドルする)。
    return await SharedPreferences.getInstance();
  }

  Future<void> _loadEssentialUiState() async {
    final SharedPreferences prefs;
    try {
      prefs = await _prefsWithRetry();
    } catch (_) {
      if (!_initialLoadCompleter.isCompleted) {
        _initialLoadCompleter.complete();
      }
      return;
    }
    try {
      _appLanguage = prefs.getString('appLanguage') ?? 'en';
    } catch (_) {}
    try {
      _isFirstLaunch = !(prefs.getBool('langPickerShown') ?? false);
    } catch (_) {}
    // 下部バー 2 段目 (見た目は6スロット、カスタムは5枠): 空なら既定。
    try {
      final j = prefs.getString('customBottomButtons');
      if (j != null && j.isNotEmpty) {
        _customBottomButtons
          ..clear()
          ..addAll((jsonDecode(j) as List)
              .map((e) => e.toString())
              .take(mobileBottomCustomSlots));
      }
    } catch (_) {}
    if (_customBottomButtons.isEmpty) {
      _customBottomButtons.addAll(defaultBottomBottomButtons);
    }
    // 下部バー 1 段目 (6 スロット): 空なら既定。
    try {
      final j = prefs.getString('customBottomTopButtons');
      if (j != null && j.isNotEmpty) {
        _customBottomTopButtons
          ..clear()
          ..addAll((jsonDecode(j) as List)
              .map((e) => e.toString())
              .take(mobileBottomTopCustomSlots));
      }
    } catch (_) {}
    if (_customBottomTopButtons.isEmpty) {
      _customBottomTopButtons.addAll(defaultBottomTopButtons);
    }
    notifyListeners();
    if (!_initialLoadCompleter.isCompleted) {
      _initialLoadCompleter.complete();
    }
  }

  Future<void> _loadGeminiApiKey() async {
    final prefs = await _prefsWithRetry();
    // ★ 最重要 UI フラグは何よりも先に確定させる (= ユーザー報告: モバイルで
    //   初回の言語ピッカーが出ない / 言語が英語のまま変えられない / 下部ボタンが
    //   設定できない)。 この後の読み込みで万一どこかで例外が出ても、 言語と
    //   初回起動フラグだけは確実に読めているよう、 先頭で個別 try/catch して読む。
    //   (後段にも同じ読み込みがあるが冪等。 多重読みのコストは無視できる)。
    try {
      _appLanguage = prefs.getString('appLanguage') ?? 'en';
    } catch (_) {}
    try {
      _isFirstLaunch = !(prefs.getBool('langPickerShown') ?? false);
    } catch (_) {}
    // ── BYOK (Bring Your Own Key) ── (= ユーザー要望)
    // Gemini キーは「利用者が自分で取得して設定画面に入力する」 ものとする。
    // ビルド時に開発者のキーを焼き込まない (逆コンパイルでの抜き取り/不正利用
    // 対策)。 そのため dart-define の GEMINI_API_KEY フォールバックは廃止。
    _geminiApiKey = prefs.getString('gemini_api_key');
    // 他社AI APIキーとプロバイダ・言語設定も読み込む
    _openaiApiKey = prefs.getString('openai_api_key');
    _anthropicApiKey = prefs.getString('anthropic_api_key');
    _aiProvider = prefs.getString('aiProvider') ?? 'gemini';
    _imageGenModel = prefs.getString('imageGenModel') ?? 'auto';
    // Ollama は廃止したため、 旧設定で 'ollama' が選ばれていたら gemini に戻す。
    if (_aiProvider == 'ollama') _aiProvider = 'gemini';
    // Grok (x.ai) / DeepSeek の API キーとモデル
    _grokApiKey = prefs.getString('grok_api_key');
    _grokModel = prefs.getString('grok_model') ?? 'grok-3';
    _deepseekApiKey = prefs.getString('deepseek_api_key');
    _deepseekModel = prefs.getString('deepseek_model') ?? 'deepseek-chat';
    // OpenRouter (= 1 キーで各社モデル切替。 baseUrl はリレー差替用)
    _openrouterApiKey = prefs.getString('openrouter_api_key');
    _openrouterModel =
        prefs.getString('openrouter_model') ?? 'openai/gpt-4o-mini';
    _openrouterBaseUrl =
        prefs.getString('openrouter_base_url') ?? 'https://openrouter.ai/api/v1';
    // ノードAIボタンの ブラウザAI ターゲット (ChatGPT/Gemini/…)
    _browserAiTarget = prefs.getString('browser_ai_target') ?? 'chatgpt';
    // 念のため try/catch (= 起動フロー保護: ここで例外が出ても言語/初回起動/
    //   下部ボタンの読み込みが止まらないように)。
    try {
      if (browserAiTargets.every((e) => e['id'] != _browserAiTarget)) {
        _browserAiTarget = 'chatgpt';
      }
    } catch (_) {}
    // ブラウザ AI の前提条件 (= ユーザー要望)
    _browserAiPrefix = prefs.getString('browser_ai_prefix') ?? '';
    // ── PDF 最終ページ記憶のロード ──
    try {
      final lastPagesJson = prefs.getString('lastPdfPages_v1');
      if (lastPagesJson != null) {
        final decoded = jsonDecode(lastPagesJson) as Map<String, dynamic>;
        _lastPdfPages = decoded.map((k, v) => MapEntry(k, (v as num).toInt()));
      }
    } catch (e) {
      debugPrint('lastPdfPages ロード失敗: $e');
    }
    // Ollama 設定の復元 (廃止済み) は削除。 旧 'ollama' プロバイダ選択は
    // 上の _aiProvider 読み込み時に gemini へ移行済み。
    _openaiModel = prefs.getString('openaiModel') ?? 'gpt-4o-mini';
    _anthropicModel = prefs.getString('anthropicModel') ?? 'claude-haiku-4-5';
    _appLanguage = prefs.getString('appLanguage') ?? 'en';
    // 音声入力の区切り語
    _voiceDelimiter = prefs.getString('voiceDelimiter') ?? '';
    _voicePauseSeconds = (prefs.getInt('voicePauseSeconds') ?? 3).clamp(1, 10);
    // メニュー時計の時差 (分)。 保存値があればそれを使い (= ユーザーが
    // 過去に設定済み)、 無ければ「設定言語の地域の時刻」 を既定にする。
    final savedClockOffset = prefs.getInt('clockOffsetMinutes');
    if (savedClockOffset != null) {
      _clockOffsetMinutes = savedClockOffset.clamp(-720, 840);
      // 旧バージョンには userSet フラグが無いので、 保存値があれば
      // ユーザー設定扱いにして言語デフォルトで上書きしない。
      _clockOffsetUserSet = prefs.getBool('clockOffsetUserSet') ?? true;
    } else {
      _clockOffsetMinutes = _defaultClockOffsetForLanguage();
      _clockOffsetUserSet = false;
    }
    // Ctrl+1〜9 のショートカット基準フォルダーの読み込み
    _shortcutFolderId = prefs.getString(_kShortcutFolderId);
    // 初回起動判定: 専用フラグ 'langPickerShown' で追跡
    // （appLanguage と分離することで、既存ユーザーもアップデート後に
    //  言語確認ダイアログを一度表示できる）
    _isFirstLaunch = !(prefs.getBool('langPickerShown') ?? false);
    // ダーク/ライトモード (デフォルト: ライト)
    _isDarkMode = prefs.getBool('isDarkMode') ?? false;
    // PDF ↑↓ ステップ。 デフォルトを 10 (= 1 押下で 1/10 ページ) に。
    // 旧デフォルト 1 (= 1 押下で 1 ページ丸ごと) は「進み過ぎて読みにくい」
    //   というユーザー報告があったため、 細かめの既定値に変更。 既に設定済み
    //   のユーザーの値はそのまま尊重する。
    _pdfArrowStepDivisor =
        (prefs.getInt('pdfArrowStepDivisor') ?? 10).clamp(1, 100);
    _pdfScrollHorizontal = prefs.getBool('pdfScrollHorizontal') ?? false;
    _eventNotifyLeadMinutes =
        (prefs.getInt('eventNotifyLeadMinutes') ?? 15).clamp(0, 1440);
    _nodeSearchUseYoutube = prefs.getBool('nodeSearchUseYoutube') ?? false;
    _hideMiniMap = prefs.getBool('hideMiniMap') ?? false;
    // ページ一覧のアイコン指定 (= ユーザー要望)。
    // ignore: discarded_futures
    _loadPageIcons();
    // 既定で動画の横に並べる (= ユーザー要望: 動画画面の中ではなく横に)。
    _videoPanelSideBySide = prefs.getBool('videoPanelSideBySide') ?? true;
    _cameraUnmirror = prefs.getBool('cameraUnmirror') ?? true;
    _cameraSkipEdit = prefs.getBool('cameraSkipEdit') ?? true;
    // 要素からの検索の開き方 (= ユーザー要望: 動作設定で選べるように)。
    //   既定は「アプリの外の窓」。 スマホは外の窓を作れないので、 画面側が
    //   全画面へ読み替える。
    final nsMode = prefs.getString('nodeSearchOpenMode') ?? '';
    if (nodeSearchOpenModes.contains(nsMode)) _nodeSearchOpenMode = nsMode;
    _nodeLinkUseAttach = prefs.getBool('nodeLinkUseAttach') ?? false;
    _nodeEditUseRich = prefs.getBool('nodeEditUseRich') ?? false;
    _nodeCalendarUseFlashcard =
        prefs.getBool('nodeCalendarUseFlashcard') ?? false;
    _pdfAiPanelDefault = prefs.getString('pdfAiPanelDefault') ?? 'chatgpt';
    final migratedSpreadDefault =
        prefs.getBool('pdfSpreadDefaultMigrationV1') ?? false;
    if (!migratedSpreadDefault) {
      _pdfFitPageDefault = false;
      _pdfInitialViewMode = 'spread';
      try {
        await prefs.setBool('pdfFitPageDefault', false);
        await prefs.setString('pdfInitialViewMode', 'spread');
        await prefs.setBool('pdfSpreadDefaultMigrationV1', true);
      } catch (_) {}
    } else {
      _pdfFitPageDefault = prefs.getBool('pdfFitPageDefault') ?? false;
      _pdfInitialViewMode = prefs.getString('pdfInitialViewMode') ?? 'spread';
    }
    _decoTextAnchorX =
        (prefs.getDouble('decoTextAnchorX') ?? 0.5).clamp(0.0, 1.0);
    _decoTextAnchorY =
        (prefs.getDouble('decoTextAnchorY') ?? 0.5).clamp(0.0, 1.0);
    // PDF ←→ ページジャンプ数 (デフォルト: 1 ページ)
    _pdfPageJumpCount = (prefs.getInt('pdfPageJumpCount') ?? 1).clamp(1, 50);
    // PDF ハイライト (マーカー) の復元
    try {
      final str = prefs.getString('pdfHighlights');
      if (str != null && str.isNotEmpty) {
        final decoded = jsonDecode(str);
        if (decoded is Map) {
          _pdfHighlights.clear();
          decoded.forEach((k, v) {
            if (k is String && v is List) {
              _pdfHighlights[k] = v
                  .whereType<Map>()
                  .map((e) => PdfHighlight.fromJson(e.cast<String, dynamic>()))
                  .toList();
            }
          });
        }
      }
    } catch (_) {}
    // PDF メモフォルダのピン留め状態の復元 (= ユーザー要望)。
    // ★ 起動フロー保護 (= ユーザー報告: モバイルで初回の言語ピッカーが出ない /
    //   言語が英語のまま変えられない / 下部ボタンが設定できない)。 ここで例外が
    //   出ると _loadGeminiApiKey が中断し、 後続の言語/下部ボタン読み込みと
    //   initialLoadDone の完了がスキップされてしまうため、 個別に try/catch で握る。
    try {
      await _loadPdfMemoPinnedFolders();
    } catch (_) {}
    try {
      await _loadPdfMemoFolderTopIndex();
    } catch (_) {}
    // リンク・PDF をアプリ内で開くか (デフォルト: true)
    _openLinksInApp = prefs.getBool('openLinksInApp') ?? true;
    // 接続線の描画スタイル (curve / straight / elbow)
    final lineStyle = prefs.getString('connectionLineStyle');
    if (lineStyle != null &&
        {'curve', 'straight', 'elbow'}.contains(lineStyle)) {
      _connectionLineStyle = lineStyle;
    }
    _connectionElbowSplitRatio =
        (prefs.getDouble('connectionElbowSplitRatio') ?? 0.5)
            .clamp(0.1, 0.9)
            .toDouble();
    _connectionElbowPointCount =
        (prefs.getInt('connectionElbowPointCount') ?? 2).clamp(1, 8).toInt();
    _connectionStrokeWidth = (prefs.getDouble('connectionStrokeWidth') ?? 2.0)
        .clamp(1.0, 8.0)
        .toDouble();
    _connectionShowArrow = prefs.getBool('connectionShowArrow') ?? true;
    _connectionArrowHeadScale =
        (prefs.getDouble('connectionArrowHeadScale') ?? 0.5)
            .clamp(0.5, 3.0)
            .toDouble();
    _connectionBidirectional =
        prefs.getBool('connectionBidirectional') ?? false;
    _connectionLineColorValue = prefs.getInt('connectionLineColorValue');
    _connectionRelationshipType =
        prefs.getString('connectionRelationshipType') == 'association'
            ? 'association'
            : 'parentChild';
    // 画像貼り付けスケール (%): 0 = OFF / 1〜100 = 画像 × (% / 100)
    // 旧キー `pasteImageOriginalSize` (bool) があれば true→100, false→0 で
    // マイグレーション (= 旧バージョンユーザーの設定が壊れないように)。
    final newScale = prefs.getInt('pasteImageScalePercent');
    if (newScale != null) {
      _pasteImageScalePercent = newScale.clamp(0, 100);
    } else {
      final legacyOriginal = prefs.getBool('pasteImageOriginalSize');
      if (legacyOriginal != null) {
        _pasteImageScalePercent = legacyOriginal ? 100 : 0;
        try {
          await prefs.setInt('pasteImageScalePercent', _pasteImageScalePercent);
        } catch (_) {}
      } else {
        _pasteImageScalePercent = 50; // デフォルト 50%
      }
    }
    // ノード生成直後にノード内で直接タイトル入力を始めるか (デフォルト: true)
    _promptForTitleOnNodeCreate =
        prefs.getBool('promptForTitleOnNodeCreate') ?? true;
    _suppressPageDeleteUndoPrompt =
        prefs.getBool('suppressPageDeleteUndoPrompt') ?? false;
    _geofenceLockEnabled = prefs.getBool('geofenceLockEnabled') ?? false;
    _geofenceLat = prefs.getDouble('geofenceLat');
    _geofenceLon = prefs.getDouble('geofenceLon');
    _geofenceRadiusKm = prefs.getDouble('geofenceRadiusKm') ?? 1.0;
    final savedGeofenceMode = prefs.getString('geofenceMode') ?? 'enter';
    _geofenceMode = savedGeofenceMode == 'exit' || savedGeofenceMode == 'enter'
        ? savedGeofenceMode
        : 'enter';
    _geofenceLockMinutes = prefs.getInt('geofenceLockMinutes') ?? 15;
    // ノード分割の区切り文字 (デフォルト: 改行)
    final savedSplitDelim = prefs.getString('nodeSplitDelimiter');
    if (savedSplitDelim != null && savedSplitDelim.isNotEmpty) {
      _nodeSplitDelimiter = savedSplitDelim;
    }
    // 集中ロック設定
    _focusLockHideSeconds = prefs.getBool('focusLockHideSeconds') ?? false;
    _lockAmbientEnabled = prefs.getBool('lockAmbientEnabled') ?? true;
    _focusLockAllowMemoAi = prefs.getBool('focusLockAllowMemoAi') ?? true;
    _focusLockAllowMemoGoogle =
        prefs.getBool('focusLockAllowMemoGoogle') ?? true;
    _focusLockAllowMemoYoutube =
        prefs.getBool('focusLockAllowMemoYoutube') ?? true;
    _focusLockYoutubeKeywordGate =
        prefs.getBool('focusLockYoutubeKeywordGate') ?? true;
    _focusLockAllowContentAccess =
        prefs.getBool('focusLockAllowContentAccess') ?? true;
    _focusLockContentPageIds =
        (prefs.getStringList('focusLockContentPageIds') ?? const <String>[])
            .toSet();
    // 既定は「関連動画を表示する」 (= ユーザー要望: 隠すのは OFF)。
    _hideEmbedRelated = prefs.getBool('hideEmbedRelated') ?? false;
    _focusLockHideUnlockBtn = prefs.getBool('focusLockHideUnlockBtn') ?? false;
    // 未設定なら ToDo タスクベース (= ユーザー要望)。
    _focusLockMode = prefs.getString('focusLockMode') ?? 'tasks';
    if (!{'timer', 'tasks'}.contains(_focusLockMode)) {
      _focusLockMode = 'timer';
    }
    _focusLockTasks = <FocusLockTask>[];
    try {
      final rawTasks = prefs.getString('focusLockTasksV1');
      if (rawTasks != null && rawTasks.isNotEmpty) {
        final decoded = jsonDecode(rawTasks);
        if (decoded is List) {
          _focusLockTasks = decoded
              .whereType<Map>()
              .map((item) =>
                  FocusLockTask.fromJson(Map<String, dynamic>.from(item)))
              .where((task) => task.title.isNotEmpty)
              .toList();
        }
      }
    } catch (_) {
      _focusLockTasks = <FocusLockTask>[];
    }
    _focusLockLastDurationSeconds =
        (prefs.getInt('focusLockLastDurationSeconds') ?? (15 * 60))
            .clamp(0, 600 * 60)
            .toInt();
    _appLockLastDurationSeconds = (prefs.getInt('appLockLastDurationSeconds') ??
            _focusLockLastDurationSeconds)
        .clamp(0, 600 * 60)
        .toInt();
    _appLockButtonMode = prefs.getString('appLockButtonMode') ?? 'ask';
    if (!{'ask', 'duration', 'until'}.contains(_appLockButtonMode)) {
      _appLockButtonMode = 'ask';
    }
    _appLockButtonDurationSeconds =
        (prefs.getInt('appLockButtonDurationSeconds') ??
                _appLockLastDurationSeconds)
            .clamp(0, 600 * 60)
            .toInt();
    _appLockButtonUntilMin =
        (prefs.getInt('appLockButtonUntilMin') ?? (23 * 60))
            .clamp(0, 1439)
            .toInt();
    _appLockButtonScheduleEnabled =
        prefs.getBool('appLockButtonScheduleEnabled') ?? false;
    _appLockButtonScheduleStartMin =
        (prefs.getInt('appLockButtonScheduleStartMin') ?? (22 * 60))
            .clamp(0, 1439)
            .toInt();
    _appLockButtonScheduleEndMin =
        (prefs.getInt('appLockButtonScheduleEndMin') ?? (6 * 60))
            .clamp(0, 1439)
            .toInt();
    _appLockDisableButtonUnlock =
        prefs.getBool('appLockDisableButtonUnlock') ?? true;
    _focusLockScheduleEnabled =
        prefs.getBool('focusLockScheduleEnabled') ?? false;
    _focusLockScheduleStartMin =
        prefs.getInt('focusLockScheduleStartMin') ?? (22 * 60);
    _focusLockScheduleEndMin =
        prefs.getInt('focusLockScheduleEndMin') ?? (6 * 60);
    try {
      final raw = prefs.getString('focusLockSchedules');
      if (raw != null && raw.isNotEmpty) {
        final list = jsonDecode(raw) as List;
        _focusLockSchedules = list
            .map((e) => FocusLockSchedule.fromJson(e as Map<String, dynamic>))
            .toList();
      }
    } catch (_) {}
    if (_focusLockSchedules.isEmpty && _focusLockScheduleEnabled) {
      _focusLockScheduleEnabled = false;
      try {
        await prefs.setBool('focusLockScheduleEnabled', false);
      } catch (_) {}
    }
    final storedDesktopHeaderPlacement =
        prefs.getString('desktopHeaderButtonPlacement');
    _desktopHeaderButtonPlacement =
        desktopHeaderButtonPlacements.contains(storedDesktopHeaderPlacement)
            ? storedDesktopHeaderPlacement!
            : 'top';
    _desktopHeaderButtonPlacementById.clear();
    try {
      final raw = prefs.getString('desktopHeaderButtonPlacementById');
      if (raw != null && raw.isNotEmpty) {
        final decoded = jsonDecode(raw) as Map<String, dynamic>;
        for (final entry in decoded.entries) {
          final placement = entry.value.toString();
          if (desktopHeaderButtonPlacements.contains(placement)) {
            _desktopHeaderButtonPlacementById[entry.key] = placement;
          }
        }
      }
    } catch (_) {}
    _desktopHeaderEnabledDockPlacements.clear();
    try {
      final raw = prefs.getString('desktopHeaderEnabledDockPlacements');
      if (raw != null && raw.isNotEmpty) {
        final decoded = jsonDecode(raw) as List<dynamic>;
        _desktopHeaderEnabledDockPlacements.addAll(decoded
            .map((value) => value.toString())
            .where(desktopHeaderButtonPlacements.contains));
      }
    } catch (_) {}
    // 旧設定には「表示するバー」の概念が無いため、従来の一括配置と
    // ボタン別配置から使用中の辺を推定して、そのまま見える状態で移行する。
    if (_desktopHeaderEnabledDockPlacements.isEmpty) {
      _desktopHeaderEnabledDockPlacements.add(_desktopHeaderButtonPlacement);
      _desktopHeaderEnabledDockPlacements
          .addAll(_desktopHeaderButtonPlacementById.values);
    }
    final storedBarCollisionMode =
        prefs.getString('desktopHeaderBarCollisionMode');
    _desktopHeaderBarCollisionMode =
        desktopHeaderBarCollisionModes.contains(storedBarCollisionMode)
            ? storedBarCollisionMode!
            : 'ask';
    _desktopBottomDockWidth =
        (prefs.getDouble('desktopBottomDockWidth') ?? 640.0)
            .clamp(180.0, 1600.0)
            .toDouble();
    _desktopBottomDockCollapsed =
        prefs.getBool('desktopBottomDockCollapsed') ?? false;
    _desktopHeaderDockCollapsedByPlacement
      ..clear()
      ..addAll({
        'top': false,
        'bottom': _desktopBottomDockCollapsed,
        'left': false,
        'right': false,
      });
    try {
      final raw = prefs.getString('desktopHeaderDockCollapsedByPlacement');
      if (raw != null && raw.isNotEmpty) {
        final decoded = jsonDecode(raw) as Map<String, dynamic>;
        for (final placement in desktopHeaderButtonPlacements) {
          final value = decoded[placement];
          if (value is bool) {
            _desktopHeaderDockCollapsedByPlacement[placement] = value;
          }
        }
      }
    } catch (_) {}
    // 旧バージョンの bottom 専用キーも維持しつつ、以後は4辺共通状態を正とする。
    _desktopBottomDockCollapsed =
        _desktopHeaderDockCollapsedByPlacement['bottom'] ?? false;
    _desktopBottomDockFloating =
        prefs.getBool('desktopBottomDockFloating') ?? false;
    _desktopBottomDockEmbedded =
        prefs.getBool('desktopBottomDockEmbedded') ?? false;
    // 高リフレッシュレート関連 (= ユーザー要望)。
    _highRefreshRate = prefs.getBool('highRefreshRate') ?? true;
    _askRefreshOnVideo = prefs.getBool('askRefreshOnVideo') ?? true;
    _matchRefreshOnVideo = prefs.getBool('matchRefreshOnVideo') ?? true;
    _desktopBottomDockX = (prefs.getDouble('desktopBottomDockX') ?? 0.5)
        .clamp(0.0, 1.0)
        .toDouble();
    _desktopBottomDockY = (prefs.getDouble('desktopBottomDockY') ?? 0.88)
        .clamp(0.0, 1.0)
        .toDouble();
    for (final placement in const <String>['left', 'right']) {
      _desktopSideDockHeightByPlacement[placement] =
          (prefs.getDouble('desktopSideDockHeight_$placement') ?? 2400.0)
              .clamp(176.0, 2400.0)
              .toDouble();
      _desktopSideDockFloatingByPlacement[placement] =
          prefs.getBool('desktopSideDockFloating_$placement') ?? false;
      // 左右バーの画面端埋め込み (= ユーザー要望)。
      _desktopSideDockEmbeddedByPlacement[placement] =
          prefs.getBool('desktopSideDockEmbedded_$placement') ?? false;
      _desktopSideDockXByPlacement[placement] =
          (prefs.getDouble('desktopSideDockX_$placement') ??
                  (placement == 'left' ? 0.04 : 0.96))
              .clamp(0.0, 1.0)
              .toDouble();
      _desktopSideDockYByPlacement[placement] =
          (prefs.getDouble('desktopSideDockY_$placement') ?? 0.52)
              .clamp(0.0, 1.0)
              .toDouble();
    }

    // カスタムヘッダーボタン
    final customButtonsJson = prefs.getString('customHeaderButtons');
    if (customButtonsJson != null && customButtonsJson.isNotEmpty) {
      try {
        final list = jsonDecode(customButtonsJson) as List<dynamic>;
        _customHeaderButtons
          ..clear()
          // 旧バージョンで 'aiSettings' を追加していたユーザー向けの後処理:
          // AI設定は設定シート / ⋮メニューに集約したのでカスタム項目からは除外。
          // ロード時に取り除き、次回保存で永続的に消える。
          ..addAll(
              list.map((e) => e as String).where((id) => id != 'aiSettings'));
        // 新機能 'mapMemo' を既存ユーザーにも 1 度だけヘッダーへ追加する
        //   (= ユーザー要望: デフォルトでマップメモをヘッダーに設定)。
        //   一度実行したら以降はユーザーの配置 (削除含む) を尊重する。
        if (prefs.getBool('mig_mapMemo_header_v1') != true) {
          if (!_customHeaderButtons.contains('mapMemo')) {
            _customHeaderButtons.insert(0, 'mapMemo');
          }
          if (!_customHeaderButtons.contains('shortcuts')) {
            _customHeaderButtons.add('shortcuts');
          }
          prefs.setBool('mig_mapMemo_header_v1', true);
          // 移行結果を永続化しないと次回起動で元の (mapMemo 無し) 値に戻って
          //   しまうため、 ここで保存しておく。
          prefs.setString(
              'customHeaderButtons', jsonEncode(_customHeaderButtons));
        }
      } catch (_) {}
    } else {
      // ── 初回起動時のデフォルト ──
      // 保存値が無い (= 一度もカスタマイズしていない) ときだけ、現在の
      // 既定ヘッダー構成を入れる。既にカスタマイズ済みのユーザーの配置は
      // (空であっても) 尊重する。
      _customHeaderButtons
        ..clear()
        ..addAll(defaultHeaderButtons);
      prefs.setBool('mig_mapMemo_header_v1', true);
      prefs.setBool('mig_customize_header_button_v1', true);
      prefs.setBool('mig_share_page_lan_header_v1', true);
      prefs.setBool('mig_header_share_customize_defaults_v2', true);
    }
    // ギャラリー (normal 以外) ヘッダーボタン。 保存値が「無い」 ときだけ
    //   現状と同じデフォルト構成を入れる。 保存済みの空配列 '[]' は (= 意図的に
    //   全消し) 尊重する (空文字/絶対不在の時のみシード)。
    final galleryButtonsJson = prefs.getString('galleryHeaderButtons');
    if (galleryButtonsJson != null && galleryButtonsJson.isNotEmpty) {
      try {
        final list = jsonDecode(galleryButtonsJson) as List<dynamic>;
        _galleryHeaderButtons
          ..clear()
          ..addAll(list.map((e) => e as String));
      } catch (_) {
        _galleryHeaderButtons
          ..clear()
          ..addAll(defaultGalleryHeaderButtons);
      }
    } else {
      _galleryHeaderButtons
        ..clear()
        ..addAll(defaultGalleryHeaderButtons);
    }
    if (prefs.getBool('mig_gallery_range_select_header_v1') != true) {
      if (!_galleryHeaderButtons.contains('rangeSelect')) {
        final insertAt = _galleryHeaderButtons.contains('mapMemo')
            ? _galleryHeaderButtons.indexOf('mapMemo') + 1
            : 0;
        _galleryHeaderButtons.insert(insertAt, 'rangeSelect');
      }
      prefs.setBool('mig_gallery_range_select_header_v1', true);
      prefs.setString(
          'galleryHeaderButtons', jsonEncode(_galleryHeaderButtons));
    }
    if (prefs.getBool('mig_customize_header_button_v1') != true) {
      if (!_customHeaderButtons.contains('customizeHeader')) {
        final insertAt = _customHeaderButtons.contains('shortcuts')
            ? _customHeaderButtons.indexOf('shortcuts')
            : _customHeaderButtons.length;
        _customHeaderButtons.insert(insertAt, 'customizeHeader');
      }
      if (!_galleryHeaderButtons.contains('customizeHeader')) {
        _galleryHeaderButtons.add('customizeHeader');
      }
      prefs.setBool('mig_customize_header_button_v1', true);
      prefs.setString('customHeaderButtons', jsonEncode(_customHeaderButtons));
      prefs.setString(
          'galleryHeaderButtons', jsonEncode(_galleryHeaderButtons));
    }
    if (prefs.getBool('mig_share_page_lan_header_v1') != true) {
      void addShareButton(List<String> buttons) {
        if (buttons.contains('sharePageLan')) return;
        final insertAt = buttons.contains('customizeHeader')
            ? buttons.indexOf('customizeHeader')
            : buttons.length;
        buttons.insert(insertAt, 'sharePageLan');
      }

      addShareButton(_customHeaderButtons);
      addShareButton(_galleryHeaderButtons);
      prefs.setBool('mig_share_page_lan_header_v1', true);
      prefs.setString('customHeaderButtons', jsonEncode(_customHeaderButtons));
      prefs.setString(
          'galleryHeaderButtons', jsonEncode(_galleryHeaderButtons));
    }
    if (prefs.getBool('mig_header_share_customize_defaults_v2') != true) {
      void ensureHeaderUtilities(List<String> buttons) {
        if (!buttons.contains('customizeHeader')) {
          buttons.add('customizeHeader');
        }
        if (!buttons.contains('sharePageLan')) {
          final insertAt = buttons.contains('customizeHeader')
              ? buttons.indexOf('customizeHeader')
              : buttons.length;
          buttons.insert(insertAt, 'sharePageLan');
        }
      }

      ensureHeaderUtilities(_customHeaderButtons);
      ensureHeaderUtilities(_galleryHeaderButtons);
      prefs.setBool('mig_header_share_customize_defaults_v2', true);
      prefs.setString('customHeaderButtons', jsonEncode(_customHeaderButtons));
      prefs.setString(
          'galleryHeaderButtons', jsonEncode(_galleryHeaderButtons));
    }
    if (prefs.getBool('mig_header_default_buttons_v3') != true) {
      bool isOldDefaultHeader(List<String> buttons) {
        const oldDefaults = <List<String>>[
          ['mapMemo', 'customizeHeader', 'shortcuts'],
          ['mapMemo', 'sharePageLan', 'customizeHeader', 'shortcuts'],
          ['mapMemo', 'customizeHeader', 'sharePageLan', 'shortcuts'],
        ];
        return oldDefaults.any((candidate) =>
            candidate.length == buttons.length &&
            List.generate(candidate.length, (i) => i)
                .every((i) => candidate[i] == buttons[i]));
      }

      bool changed = false;
      if (isOldDefaultHeader(_customHeaderButtons)) {
        _customHeaderButtons
          ..clear()
          ..addAll(defaultHeaderButtons);
        changed = true;
      }
      if (_galleryHeaderButtons.length == 6 &&
          _galleryHeaderButtons[0] == 'mapMemo' &&
          _galleryHeaderButtons[1] == 'rangeSelect' &&
          _galleryHeaderButtons[2] == 'openAi' &&
          _galleryHeaderButtons[3] == 'sharePageLan' &&
          _galleryHeaderButtons[4] == 'customizeHeader' &&
          _galleryHeaderButtons[5] == 'flashcard') {
        _galleryHeaderButtons
          ..clear()
          ..addAll(defaultGalleryHeaderButtons);
        changed = true;
      }
      prefs.setBool('mig_header_default_buttons_v3', true);
      if (changed) {
        prefs.setString(
            'customHeaderButtons', jsonEncode(_customHeaderButtons));
        prefs.setString(
            'galleryHeaderButtons', jsonEncode(_galleryHeaderButtons));
      }
    }
    // ── モバイルのみ: 「下部ボタンを格納」 ボタンをヘッダーへ 1 度だけ追加 ──
    // (= ユーザー要望: ヘッダーの所に下部ボタンを格納するボタンを持ってくる)。
    // 下部ボタンバー自体がモバイル専用のため、 デスクトップには追加しない。
    // 一度実行したら以降はユーザーの配置 (削除含む) を尊重する。
    if (!kIsWeb &&
        (Platform.isAndroid || Platform.isIOS) &&
        prefs.getBool('mig_toggle_bottom_bar_header_v1') != true) {
      void addToggle(List<String> buttons) {
        if (buttons.contains('toggleBottomBar')) return;
        final insertAt = buttons.contains('rangeSelect')
            ? buttons.indexOf('rangeSelect') + 1
            : 0;
        buttons.insert(insertAt, 'toggleBottomBar');
      }

      addToggle(_customHeaderButtons);
      addToggle(_galleryHeaderButtons);
      prefs.setBool('mig_toggle_bottom_bar_header_v1', true);
      prefs.setString('customHeaderButtons', jsonEncode(_customHeaderButtons));
      prefs.setString(
          'galleryHeaderButtons', jsonEncode(_galleryHeaderButtons));
    }
    // ── 「下部ボタンを格納」 はヘッダー専用にした (= ユーザー要望) ──
    //   過去に下部バーへ置いた設定が残っていると、 格納した瞬間に自分ごと
    //   隠れて戻せなくなるので、 下部バー側からは取り除く。
    if (_customBottomButtons.remove('toggleBottomBar')) {
      prefs.setString('customBottomButtons', jsonEncode(_customBottomButtons));
    }
    // ── Android のみ: フローティングメモボタンをヘッダーへ 1 度だけ追加 ──
    // (= ユーザー要望: 他のアプリの上に小さくメモを表示して書けるように)。
    if (!kIsWeb &&
        Platform.isAndroid &&
        prefs.getBool('mig_floating_memo_header_v1') != true) {
      if (!_customHeaderButtons.contains('floatingMemo')) {
        final insertAt = _customHeaderButtons.contains('mapMemo')
            ? _customHeaderButtons.indexOf('mapMemo') + 1
            : 0;
        _customHeaderButtons.insert(insertAt, 'floatingMemo');
      }
      prefs.setBool('mig_floating_memo_header_v1', true);
      prefs.setString('customHeaderButtons', jsonEncode(_customHeaderButtons));
    }
    // ── 既定ヘッダー v4 ──
    // ノード生成を左端にし、主要ユーティリティと Google サービスを初期状態
    // から使えるようにする。既存ユーザーにも一度だけ不足分を補い、それ以降
    // の削除・並び替えはこの移行フラグによって尊重する。
    if (prefs.getBool('mig_header_default_buttons_v4') != true) {
      void applyV4Defaults(List<String> buttons) {
        buttons.removeWhere((id) => id == 'addNode');
        buttons.insert(0, 'addNode');
        for (final id in const <String>[
          'shortcuts',
          'qrReader',
          'refMenu',
          'openGoogleDrive',
          'openGoogleEarth',
          'openGoogleMaps',
        ]) {
          if (!buttons.contains(id)) buttons.add(id);
        }
      }

      applyV4Defaults(_customHeaderButtons);
      applyV4Defaults(_galleryHeaderButtons);
      prefs.setBool('mig_header_default_buttons_v4', true);
      prefs.setString('customHeaderButtons', jsonEncode(_customHeaderButtons));
      prefs.setString(
          'galleryHeaderButtons', jsonEncode(_galleryHeaderButtons));
    }
    // ── 範囲選択を通常ヘッダーの既定に追加 (= ユーザー要望) ──
    // defaultHeaderButtons には rangeSelect が入っているが、既存ユーザーが
    // 保存済みの customHeaderButtons には無いことがあるため、一度だけ補う。
    // 以降の削除・並び替えはこのフラグで尊重する。ギャラリー側は別移行
    // (mig_gallery_range_select_header_v1) 済みだが、念のため両方確認する。
    if (prefs.getBool('mig_header_range_select_v1') != true) {
      void ensureRangeSelect(List<String> buttons) {
        if (buttons.contains('rangeSelect')) return;
        final anchor = buttons.contains('mapMemo')
            ? buttons.indexOf('mapMemo') + 1
            : (buttons.contains('addNode')
                ? buttons.indexOf('addNode') + 1
                : 0);
        buttons.insert(anchor.clamp(0, buttons.length).toInt(), 'rangeSelect');
      }

      ensureRangeSelect(_customHeaderButtons);
      ensureRangeSelect(_galleryHeaderButtons);
      prefs.setBool('mig_header_range_select_v1', true);
      prefs.setString('customHeaderButtons', jsonEncode(_customHeaderButtons));
      prefs.setString(
          'galleryHeaderButtons', jsonEncode(_galleryHeaderButtons));
    }
    // ── 全選択を既定ヘッダーへ追加し、主要な選択操作をノード生成の隣へ ──
    // 一度だけ既存配置にも適用する。以後は移行フラグにより、ユーザーが行った
    // 削除・並べ替えを尊重する。
    if (prefs.getBool('mig_header_select_all_v1') != true) {
      void placeSelectionActions(List<String> buttons) {
        buttons.removeWhere((id) => id == 'selectAll' || id == 'rangeSelect');
        final addNodeIndex = buttons.indexOf('addNode');
        final insertAt = addNodeIndex >= 0 ? addNodeIndex + 1 : 0;
        buttons.insert(insertAt.clamp(0, buttons.length), 'selectAll');
        buttons.insert((insertAt + 1).clamp(0, buttons.length), 'rangeSelect');
      }

      placeSelectionActions(_customHeaderButtons);
      placeSelectionActions(_galleryHeaderButtons);
      prefs.setBool('mig_header_select_all_v1', true);
      prefs.setString('customHeaderButtons', jsonEncode(_customHeaderButtons));
      prefs.setString(
          'galleryHeaderButtons', jsonEncode(_galleryHeaderButtons));
    }
    // モバイル下部バーのカスタム項目（見た目は拡大率込みで6スロット）
    final customBottomJson = prefs.getString('customBottomButtons');
    if (customBottomJson != null && customBottomJson.isNotEmpty) {
      try {
        final list = jsonDecode(customBottomJson) as List<dynamic>;
        _customBottomButtons
          ..clear()
          ..addAll(list.map((e) => e as String).take(mobileBottomCustomSlots));
      } catch (_) {}
    }
    // ── 保存値が無い / 空 なら 2 段目デフォルトで初期化 ──
    //   [openYoutube, cutMode, calendar, sync, addPage] (lockScale は別管理)。
    //   (= ユーザー報告: 下部ボタンが「集中ロックだけで他が空」。 過去ビルドで
    //    空配列 "[]" が保存されると、 旧実装は「prefs から読んだ」 扱いにして
    //    既定を入れずに空のままにしていた。 customBottomTopButtons と同じく
    //    「空なら既定」 に統一して、 空配列が残っていても既定が復活するように。)
    if (_customBottomButtons.isEmpty) {
      _customBottomButtons.addAll(defaultBottomBottomButtons);
    }
    // モバイル下部バー 3 行目 (= ユーザー要望: Max のみ。 既定は空 + 無効)。
    _bottomThirdRowEnabled = prefs.getBool('bottomThirdRowEnabled') ?? false;
    final customBottomThirdJson = prefs.getString('customBottomThirdButtons');
    if (customBottomThirdJson != null && customBottomThirdJson.isNotEmpty) {
      try {
        final list = jsonDecode(customBottomThirdJson) as List<dynamic>;
        _customBottomThirdButtons
          ..clear()
          ..addAll(
              list.map((e) => e as String).take(mobileBottomThirdCustomSlots));
      } catch (_) {}
    }
    // モバイル下部バー 4 行目 (= Max のみ。 既定は空 + 無効)。
    _bottomFourthRowEnabled = prefs.getBool('bottomFourthRowEnabled') ?? false;
    final customBottomFourthJson = prefs.getString('customBottomFourthButtons');
    if (customBottomFourthJson != null && customBottomFourthJson.isNotEmpty) {
      try {
        final list = jsonDecode(customBottomFourthJson) as List<dynamic>;
        _customBottomFourthButtons
          ..clear()
          ..addAll(
              list.map((e) => e as String).take(mobileBottomFourthCustomSlots));
      } catch (_) {}
    }
    // モバイル下部バー 1 行目 (6 スロット) - link / file / rangeSelect /
    // addNode / undo / redo がデフォルト。ユーザーが並び替え/差し替え可能。
    // 保存値が無ければデフォルトで初期化する。
    // ── 通常モード (2x6) のロード ──
    final customBottomTopJson = prefs.getString('customBottomTopButtons');
    if (customBottomTopJson != null && customBottomTopJson.isNotEmpty) {
      try {
        final list = jsonDecode(customBottomTopJson) as List<dynamic>;
        _customBottomTopButtons
          ..clear()
          ..addAll(
              list.map((e) => e as String).take(mobileBottomTopCustomSlots));
      } catch (_) {}
    }
    if (_customBottomTopButtons.isEmpty) {
      _customBottomTopButtons.addAll(defaultBottomTopButtons);
    }

    // ── 分割モード (2x2) のロード ──
    // 別キー `customBottomTopButtonsSplit` で独立永続化。
    // 旧バージョンからのアップグレード時はキーが存在せず、 デフォルトを
    // 通常モードからコピーする (= 初期状態は両モード同じ配置)。
    final customBottomTopSplitJson =
        prefs.getString('customBottomTopButtonsSplit');
    if (customBottomTopSplitJson != null) {
      try {
        final list = jsonDecode(customBottomTopSplitJson) as List<dynamic>;
        _customBottomTopButtonsSplit
          ..clear()
          ..addAll(list.map((e) => e.toString()));
      } catch (e) {
        debugPrint('customBottomTopButtonsSplit decode 失敗: $e');
      }
    }
    if (_customBottomTopButtonsSplit.isEmpty) {
      // 初回 (= 旧バージョンから移行): 通常モード設定をコピー
      _customBottomTopButtonsSplit.addAll(_customBottomTopButtons);
    }
    // ── 「下部ボタンを格納」 が下部バーに入っていたら取り除く ──
    // 押した瞬間に自分ごと隠れて二度と戻せなくなるため、 ヘッダー専用にした
    // (= ユーザー要望)。 以前のビルドで下部へ置いてしまった人が詰まらない
    // よう、 読み込み時に落とす。
    for (final list in [
      _customBottomButtons,
      _customBottomTopButtons,
      _customBottomTopButtonsSplit,
      _customBottomThirdButtons,
      _customBottomFourthButtons,
    ]) {
      list.removeWhere((id) => id == 'toggleBottomBar');
    }
    // lockScale ボタン (拡大率) の表示スロット (0=左端=デフォルト)
    _lockScaleBottomSlot = prefs.getInt('lockScaleBottomSlot') ?? 0;
    _lockScaleBottomSlot = _lockScaleBottomSlot.clamp(0, 5);
    // ヘッダーアイコン色: ON状態（右クリック→色変更の永続化）
    final iconColorsJson = prefs.getString('headerIconColors');
    if (iconColorsJson != null && iconColorsJson.isNotEmpty) {
      try {
        final map = jsonDecode(iconColorsJson) as Map<String, dynamic>;
        _headerIconColors
          ..clear()
          ..addAll(map.map((k, v) => MapEntry(k, (v as num).toInt())));
      } catch (_) {}
    }
    // ── ボトムバー専用の色デフォルト適用 ──
    // ユーザーが個別にカスタムしていない ID については、隣接ボタンで色が
    // 被らないよう設計したパレットで初期色を埋める。これにより初回起動時
    // から色のリズムが整って見える。ユーザーが長押し→色変更すると
    // _headerIconColors[id] が上書きされるので、その場合は自動でユーザー
    // 設定が優先される (永続化済み)。
    bool needsSaveDefaultColors = false;
    _defaultButtonColors.forEach((id, color) {
      if (!_headerIconColors.containsKey(id)) {
        _headerIconColors[id] = color;
        needsSaveDefaultColors = true;
      }
    });
    if (needsSaveDefaultColors) {
      // ユーザー設定として書き込んでおくことで、デフォルトを変更しても
      // 既存ユーザーのカスタマイズは尊重される (= 次回以降は保存値が
      // 使われ、_defaultButtonColors を変えても影響しない)。
      // ignore: discarded_futures
      _saveHeaderIconColors();
    }
    // ヘッダーアイコン色: OFF状態（トグル系アイコンがOFFの時に使う色。デフォルトは灰色）
    final iconColorsOffJson = prefs.getString('headerIconColorsOff');
    if (iconColorsOffJson != null && iconColorsOffJson.isNotEmpty) {
      try {
        final map = jsonDecode(iconColorsOffJson) as Map<String, dynamic>;
        _headerIconColorsOff
          ..clear()
          ..addAll(map.map((k, v) => MapEntry(k, (v as num).toInt())));
      } catch (_) {}
    }
    // ── load 完了通知 ──
    // この関数 (_loadGeminiApiKey) は非同期で走るが、コンストラクタでは
    // await されない。そのため、UI の最初の build 時にはここで読み込んだ
    // 値 (例: _headerIconColors のデフォルト色マップ) がまだ反映されない。
    // load 完了したことを Consumer に通知して、再 build をトリガーする。
    notifyListeners();
    // 初期化完了 Future を完了させる。UI 側 (initState の addPostFrameCallback)
    // が `await provider.initialLoadDone` で待っているので、ここで isFirstLaunch
    // などのフラグが確定した状態で UI に判定させる。
    if (!_initialLoadCompleter.isCompleted) {
      _initialLoadCompleter.complete();
    }
  }

  /// 初期化用 Completer。`_loadGeminiApiKey` (= 言語フラグ・色設定など多くの
  /// SharedPreferences 値を読み込む) が完了したら complete される。
  ///
  /// UI 側で `await provider.initialLoadDone` してから `isFirstLaunch` などを
  /// 判定すれば、確実にロード完了後の値で初回起動フローを分岐できる。
  final Completer<void> _initialLoadCompleter = Completer<void>();
  Future<void> get initialLoadDone => _initialLoadCompleter.future;
  bool _disposed = false;
  Timer? _startupSafetyTimer;

  /// 初回起動フラグ（言語選択ダイアログ表示に使用）
  bool _isFirstLaunch = false;
  bool get isFirstLaunch => _isFirstLaunch;
  Future<void> completeFirstLaunch() async {
    _isFirstLaunch = false;
    final prefs = await _prefsWithRetry();
    // 専用フラグで初回起動完了を記録（次回以降はダイアログ非表示）
    await prefs.setBool('langPickerShown', true);
    // 言語も念のため保存（appLanguage が未設定ならデフォルトで書き込む）
    await prefs.setString('appLanguage', _appLanguage);
    notifyListeners();
  }

  /// ユーザーがヘッダーに追加したコマンドID（順序付き）
  /// 値は _commandDefs の 'id' に対応。ここに含まれるコマンドは AppBar のアクションとして表示される
  /// 配置候補から廃止したボタン ID (= ユーザー要望)。 永続値に残っていても
  /// 各バーの取得時に除外して表示しない (= 移行コード不要で「無くす」)。
  ///   - 'weather': 天気のカスタムボタンは廃止。 代わりにメニュー上部の時刻表示
  ///     (時計+天気) をタップして天気を設定/取得する。
  ///   - 'ocrSearch': APIキー必須のAI OCR実装だったため廃止。
  static const Set<String> _removedButtonIds = {
    'weather',
    'ocrSearch',
    'openX',
    'openQiita',
    'openPaiza',
    'openProgate',
    'openAtCoder',
    'openAtocoder',
    // ナンパ練習はユーザー要望で機能ごと削除 (2026-07-30)。
    'pickupPractice',
    // マップ分割はヘッダー右上の常設ボタンへ移行 (2026-08-01、= ユーザー
    // 要望: 既に右上にあるからカスタムボタンからは削除)。
    'mapSplit',
    // テーマ (ダーク/ライト) 切替ボタンは廃止 (2026-08-13、= ユーザー要望:
    // 背景を自分で設定できるようになったので不要)。 設定のダークモード
    // トグルと Ctrl+Shift+L は残る。
    'themeMode',
    // LAN 共有は廃止 (2026-08-13、= ユーザー要望: サーバー経由のリアルタイム
    // 共同編集があるので、 SSL 化されていないページ共有は不要)。 過去の
    // 移行コードが再追加しても、 ここで弾かれて表示されない。
    'sharePageLan',
  };
  List<String> _filterRemovedButtons(List<String> ids) =>
      List.unmodifiable(ids.where((id) => !_removedButtonIds.contains(id)));

  /// PC版のカスタムヘッダーボタンの表示位置。
  /// top=従来のAppBar、bottom=画面下部、left/right=縦型サイドメニュ。
  static const Set<String> desktopHeaderButtonPlacements = {
    'top',
    'bottom',
    'left',
    'right',
  };
  String _desktopHeaderButtonPlacement = 'top';
  String get desktopHeaderButtonPlacement => _desktopHeaderButtonPlacement;

  /// 表示するPCカスタムバー。ボタンが0件でも、選択された辺には空バーを
  /// 常設して、別バーからボタンをドロップできるようにする。
  final Set<String> _desktopHeaderEnabledDockPlacements = {'top'};
  Set<String> get desktopHeaderEnabledDockPlacements =>
