  // ── ページ一覧のアイコン (= ユーザー要望: ページごとに変えたり、
  //    種類ごとにまとめて変えたりできるように) ────────────────────────
  //    画面側が持つアイコンの一覧 (kPageIconChoices) の**番号**を覚える。
  //    番号で持つのは、 アイコンを動的に作ると Flutter の絵文字/アイコンの
  //    間引き (tree shaking) に引っかかるため。
  /// ページ id → アイコン番号 (そのページだけの指定)。
  Map<String, int> _pageIconIndex = {};

  /// ページ種別 ('normal' / 'markdown' など) → アイコン番号 (種類まとめて)。
  Map<String, int> _pageTypeIconIndex = {};

  /// ページ id → 色番号 (そのページだけの指定)。
  Map<String, int> _pageIconColorIndex = {};

  /// ページ種別 → 色番号 (種類まとめて)。
  Map<String, int> _pageTypeIconColorIndex = {};

  Map<String, int> get pageIconIndex => _pageIconIndex;
  Map<String, int> get pageTypeIconIndex => _pageTypeIconIndex;

  /// このページに使う色番号。 個別 → 種類 の順。 無ければ null (既定色)。
  int? pageIconColorIndexFor(String pageId, String? pageType) {
    final own = _pageIconColorIndex[pageId];
    if (own != null) return own;
    return _pageTypeIconColorIndex[pageType ?? 'normal'];
  }

  /// そのページだけ色を変える (= ユーザー要望)。 [index] が null で元に戻す。
  Future<void> setPageIconColor(String pageId, int? index) async {
    if (index == null) {
      _pageIconColorIndex.remove(pageId);
    } else {
      _pageIconColorIndex[pageId] = index;
    }
    notifyListeners();
    await _savePageIcons();
  }

  /// 同じ種類のページの色をまとめて変える。 [index] が null で元に戻す。
  Future<void> setPageTypeIconColor(String pageType, int? index) async {
    if (index == null) {
      _pageTypeIconColorIndex.remove(pageType);
    } else {
      _pageTypeIconColorIndex[pageType] = index;
    }
    for (final p in _pages) {
      if ((p.pageType ?? 'normal') == pageType) {
        _pageIconColorIndex.remove(p.id);
      }
    }
    notifyListeners();
    await _savePageIcons();
  }

  /// このページに使うアイコン番号。 個別指定 → 種類の指定 の順で見る。
  /// どちらも無ければ null (= 元からの既定アイコン)。
  int? pageIconIndexFor(String pageId, String? pageType) {
    final own = _pageIconIndex[pageId];
    if (own != null) return own;
    return _pageTypeIconIndex[pageType ?? 'normal'];
  }

  /// そのページだけアイコンを変える。 [index] が null で元に戻す。
  Future<void> setPageIcon(String pageId, int? index) async {
    if (index == null) {
      _pageIconIndex.remove(pageId);
    } else {
      _pageIconIndex[pageId] = index;
    }
    notifyListeners();
    await _savePageIcons();
  }

  /// 同じ種類のページをまとめて変える。 [index] が null で元に戻す。
  /// 個別指定は邪魔になるので、 その種類のページからは外す。
  Future<void> setPageTypeIcon(String pageType, int? index) async {
    if (index == null) {
      _pageTypeIconIndex.remove(pageType);
    } else {
      _pageTypeIconIndex[pageType] = index;
    }
    for (final p in _pages) {
      if ((p.pageType ?? 'normal') == pageType) _pageIconIndex.remove(p.id);
    }
    notifyListeners();
    await _savePageIcons();
  }

  Future<void> _savePageIcons() async {
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setString('pageIconIndex', jsonEncode(_pageIconIndex));
      await prefs.setString(
          'pageTypeIconIndex', jsonEncode(_pageTypeIconIndex));
      await prefs.setString(
          'pageIconColorIndex', jsonEncode(_pageIconColorIndex));
      await prefs.setString(
          'pageTypeIconColorIndex', jsonEncode(_pageTypeIconColorIndex));
    } catch (_) {}
  }

  Future<void> _loadPageIcons() async {
    try {
      final prefs = await _prefsWithRetry();
      Map<String, int> read(String key) {
        final raw = prefs.getString(key);
        if (raw == null || raw.isEmpty) return {};
        final m = jsonDecode(raw);
        if (m is! Map) return {};
        final out = <String, int>{};
        m.forEach((k, v) {
          final i = v is int ? v : int.tryParse('$v');
          if (i != null && i >= 0) out['$k'] = i;
        });
        return out;
      }

      _pageIconIndex = read('pageIconIndex');
      _pageTypeIconIndex = read('pageTypeIconIndex');
      _pageIconColorIndex = read('pageIconColorIndex');
      _pageTypeIconColorIndex = read('pageTypeIconColorIndex');
      notifyListeners();
    } catch (_) {}
  }

