  Future<void> setDesktopSideDockHeight(String placement, double height) async {
    if (!_isDesktopSideDockPlacement(placement)) return;
    final next = height.clamp(176.0, 2400.0).toDouble();
    if ((desktopSideDockHeightAt(placement) - next).abs() < 0.5) return;
    _desktopSideDockHeightByPlacement[placement] = next;
    final prefs = await _prefsWithRetry();
    await prefs.setDouble('desktopSideDockHeight_$placement', next);
    notifyListeners();
  }

  Future<void> setDesktopSideDockPosition(
    String placement, {
    required bool floating,
    double? x,
    double? y,
  }) async {
    if (!_isDesktopSideDockPlacement(placement)) return;
    final nextX =
        (x ?? desktopSideDockXAt(placement)).clamp(0.0, 1.0).toDouble();
    final nextY =
        (y ?? desktopSideDockYAt(placement)).clamp(0.0, 1.0).toDouble();
    if (desktopSideDockFloatingAt(placement) == floating &&
        (desktopSideDockXAt(placement) - nextX).abs() < 0.0005 &&
        (desktopSideDockYAt(placement) - nextY).abs() < 0.0005) {
      return;
    }
    _desktopSideDockFloatingByPlacement[placement] = floating;
    _desktopSideDockXByPlacement[placement] = nextX;
    _desktopSideDockYByPlacement[placement] = nextY;
    final prefs = await _prefsWithRetry();
    await Future.wait([
      prefs.setBool('desktopSideDockFloating_$placement', floating),
      prefs.setDouble('desktopSideDockX_$placement', nextX),
      prefs.setDouble('desktopSideDockY_$placement', nextY),
    ]);
    notifyListeners();
  }

  Future<void> setDesktopBottomDockWidth(double width) async {
    final next = width.clamp(180.0, 1600.0).toDouble();
    if ((_desktopBottomDockWidth - next).abs() < 0.5) return;
    _desktopBottomDockWidth = next;
    final prefs = await _prefsWithRetry();
    await prefs.setDouble('desktopBottomDockWidth', next);
    notifyListeners();
  }

  Future<void> setDesktopHeaderDockCollapsed(
      String placement, bool collapsed) async {
    if (!desktopHeaderButtonPlacements.contains(placement) ||
        desktopHeaderDockCollapsedAt(placement) == collapsed) {
      return;
    }
    _desktopHeaderDockCollapsedByPlacement[placement] = collapsed;
    if (placement == 'bottom') _desktopBottomDockCollapsed = collapsed;
    final prefs = await _prefsWithRetry();
    final writes = <Future<bool>>[
      prefs.setString('desktopHeaderDockCollapsedByPlacement',
          jsonEncode(_desktopHeaderDockCollapsedByPlacement)),
    ];
    if (placement == 'bottom') {
      writes.add(prefs.setBool('desktopBottomDockCollapsed', collapsed));
    }
    await Future.wait(writes);
    notifyListeners();
  }

  Future<void> setDesktopBottomDockCollapsed(bool collapsed) =>
      setDesktopHeaderDockCollapsed('bottom', collapsed);

