  Future<void> setDesktopBottomDockPosition({
    required bool floating,
    double? x,
    double? y,
  }) async {
    final nextX = (x ?? _desktopBottomDockX).clamp(0.0, 1.0).toDouble();
    final nextY = (y ?? _desktopBottomDockY).clamp(0.0, 1.0).toDouble();
