    {'id': 'claude-sonnet-5', 'label': 'Claude Sonnet 5'},
    {'id': 'claude-haiku-4-5', 'label': 'Claude Haiku 4.5 (fast / cheap)'},
  ];

  /// 動的に取得した OpenAI / Claude モデル一覧
  List<Map<String, String>> _dynamicOpenaiModels = [];
  List<Map<String, String>> _dynamicClaudeModels = [];
  DateTime? _lastOpenaiModelsFetch;
  DateTime? _lastClaudeModelsFetch;

  /// UI 用ゲッター: 動的取得 → フォールバック
  List<Map<String, String>> get openaiAvailableModels =>
      _dynamicOpenaiModels.isNotEmpty
          ? List.unmodifiable(_dynamicOpenaiModels)
          : _fallbackOpenaiModels;
  List<Map<String, String>> get claudeAvailableModels =>
      _dynamicClaudeModels.isNotEmpty
          ? List.unmodifiable(_dynamicClaudeModels)
          : _fallbackClaudeModels;

  String _openaiModel = 'gpt-4o-mini';
  String _anthropicModel = 'claude-haiku-4-5';
  String get openaiModel => _openaiModel;
  String get anthropicModel => _anthropicModel;

