  // ─── AI モデル一覧の動的取得 ────────────────────────────────────────────
  //
  // 各 AI プロバイダーは新モデルを頻繁にリリースするため、コードを書き直さ
  // なくても自動でリストが更新されるよう、各社の API から最新モデル一覧を
  // 取得する。失敗した場合 (ネットワーク・認証問題等) は組み込みフォール
  // バックを使うので致命的にはならない。
  //
  // 実行頻度: 1 日 1 回程度を目安に内部で間隔を絞る (毎起動で API を叩くと
  // 無駄な通信になるため)。SharedPreferences にキャッシュしておき、次回
  // 起動時はキャッシュをそのまま表示しつつ裏で更新する形にする。

  /// アプリ起動直後に呼ぶ初期化。SharedPreferences からキャッシュを復元し、
  /// 24 時間以上前なら裏で API を叩いて更新する。
  Future<void> initializeAvailableModels() async {
    try {
      final prefs = await _prefsWithRetry();
      // ── キャッシュ復元 ──
      final flashJson = prefs.getString('cached_flash_models');
      if (flashJson != null && flashJson.isNotEmpty) {
        try {
          _dynamicFlashModels = (jsonDecode(flashJson) as List).cast<String>();
        } catch (_) {}
      }
      final proJson = prefs.getString('cached_pro_models');
      if (proJson != null && proJson.isNotEmpty) {
        try {
          _dynamicProModels = (jsonDecode(proJson) as List).cast<String>();
        } catch (_) {}
      }
      final openaiJson = prefs.getString('cached_openai_models');
      if (openaiJson != null && openaiJson.isNotEmpty) {
        try {
          _dynamicOpenaiModels = (jsonDecode(openaiJson) as List)
              .map((e) => Map<String, String>.from(e as Map))
              .toList();
        } catch (_) {}
      }
      final claudeJson = prefs.getString('cached_claude_models');
      if (claudeJson != null && claudeJson.isNotEmpty) {
        try {
          _dynamicClaudeModels = (jsonDecode(claudeJson) as List)
              .map((e) => Map<String, String>.from(e as Map))
              .toList();
        } catch (_) {}
      }
      // ── 取得時刻も復元 ──
      final geminiTs = prefs.getInt('models_fetch_gemini_ts');
      if (geminiTs != null) {
        _lastGeminiModelsFetch = DateTime.fromMillisecondsSinceEpoch(geminiTs);
      }
      final openaiTs = prefs.getInt('models_fetch_openai_ts');
      if (openaiTs != null) {
        _lastOpenaiModelsFetch = DateTime.fromMillisecondsSinceEpoch(openaiTs);
      }
      final claudeTs = prefs.getInt('models_fetch_claude_ts');
      if (claudeTs != null) {
        _lastClaudeModelsFetch = DateTime.fromMillisecondsSinceEpoch(claudeTs);
      }
      notifyListeners();
      // ── 24 時間以上経っているプロバイダーは裏で更新 ──
      // (await はしない: アプリ起動を阻害したくないので fire-and-forget)
      // 失敗しても問題ないので unawaited 扱い。
      _maybeRefreshGeminiModels();
      _maybeRefreshOpenaiModels();
      _maybeRefreshClaudeModels();
    } catch (e) {
      debugPrint('initializeAvailableModels: $e');
    }
  }

  /// 24h 以上経過していれば Gemini モデル一覧を再取得
  Future<void> _maybeRefreshGeminiModels() async {
    if (_lastGeminiModelsFetch != null &&
        DateTime.now().difference(_lastGeminiModelsFetch!).inHours < 24) {
      return;
    }
    await refreshGeminiModels();
  }

  Future<void> _maybeRefreshOpenaiModels() async {
    if (_lastOpenaiModelsFetch != null &&
        DateTime.now().difference(_lastOpenaiModelsFetch!).inHours < 24) {
      return;
    }
    await refreshOpenaiModels();
  }

  Future<void> _maybeRefreshClaudeModels() async {
    if (_lastClaudeModelsFetch != null &&
        DateTime.now().difference(_lastClaudeModelsFetch!).inHours < 24) {
      return;
    }
    await refreshClaudeModels();
  }

  /// Google Generative Language API の v1beta/models で最新モデルを取得。
  /// API キーが無いと公開モデル一覧が取れないので、キーが設定されている時
  /// だけ実行する。失敗しても黙ってフォールバックを使い続ける。
  Future<void> refreshGeminiModels() async {
    final key = _effectiveGeminiKey();
    if (key == null || key.isEmpty) return;
    try {
      final url =
          'https://generativelanguage.googleapis.com/v1beta/models?key=$key';
      final res =
          await http.get(Uri.parse(url)).timeout(const Duration(seconds: 8));
      if (res.statusCode != 200) return;
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final list = data['models'] as List? ?? const [];

      final flash = <String>[];
      final pro = <String>[];
      for (final m in list) {
        final mm = m as Map<String, dynamic>;
        final name = (mm['name'] as String?) ?? '';
        // name は "models/gemini-2.5-flash" 形式で来る → 末尾だけ取り出す
        final modelId = name.startsWith('models/') ? name.substring(7) : name;
        final methods =
            (mm['supportedGenerationMethods'] as List?)?.cast<String>() ??
                const [];
        // generateContent をサポートする = テキスト生成可能なモデル
        if (!methods.contains('generateContent')) continue;
        // gemini モデルだけに絞る (Embedding / TTS などを除外)
        if (!modelId.startsWith('gemini')) continue;
        // プレビュー版 / 学習用変種は除く
        if (modelId.contains('embedding') || modelId.contains('aqa')) continue;
        if (modelId.contains('flash')) {
          flash.add(modelId);
        } else if (modelId.contains('pro')) {
          pro.add(modelId);
        }
      }
      // 重複除去 + バージョン番号で降順ソート (新しいバージョンを先頭に)
      // 単純な文字列降順で大体うまく行く: gemini-2.5-flash > gemini-2.0-flash
      final flashSet = flash.toSet().toList()..sort((a, b) => b.compareTo(a));
      final proSet = pro.toSet().toList()..sort((a, b) => b.compareTo(a));

      _dynamicFlashModels = flashSet;
      _dynamicProModels = proSet;
      _lastGeminiModelsFetch = DateTime.now();
      // 永続化
      final prefs = await _prefsWithRetry();
      await prefs.setString('cached_flash_models', jsonEncode(flashSet));
      await prefs.setString('cached_pro_models', jsonEncode(proSet));
      await prefs.setInt('models_fetch_gemini_ts',
          _lastGeminiModelsFetch!.millisecondsSinceEpoch);
      notifyListeners();
    } catch (e) {
      debugPrint('refreshGeminiModels: $e');
    }
  }

  /// OpenAI の /v1/models から取得。
  /// 認証ヘッダに API キーが必要なので、キー未設定なら何もしない。
  Future<void> refreshOpenaiModels() async {
    final key = _openaiApiKey;
    if (key == null || key.isEmpty) return;
    try {
      final res = await http.get(
        Uri.parse('https://api.openai.com/v1/models'),
        headers: {'Authorization': 'Bearer $key'},
      ).timeout(const Duration(seconds: 8));
      if (res.statusCode != 200) return;
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final list = (data['data'] as List?) ?? const [];

      // テキスト生成系モデルだけに絞る (チャット完了対応)。
      // ID プレフィックスで雑にフィルタ: gpt-* / o1-* / o3-* / o4-* / chatgpt-*
      // 現実には Embeddings / Whisper 等も同じエンドポイントから返ってくる。
      bool isChatLike(String id) {
        return id.startsWith('gpt-') ||
            id.startsWith('o1') ||
            id.startsWith('o3') ||
            id.startsWith('o4') ||
            id.startsWith('chatgpt');
      }

      final models = <Map<String, String>>[];
      for (final m in list) {
        final mm = m as Map<String, dynamic>;
        final id = (mm['id'] as String?) ?? '';
        if (id.isEmpty || !isChatLike(id)) continue;
        // 日付サフィックス付きのスナップショット (例: gpt-4o-mini-2024-07-18)
        // は隠す: ベース ID だけ表示する方が分かりやすい。
        if (RegExp(r'-\d{4}-\d{2}-\d{2}').hasMatch(id)) continue;
        // ラベルは ID をそのまま使う (人間可読フォーマットを取得する API は無い)
        models.add({'id': id, 'label': id});
      }
      // 新しい世代が先頭に来るよう、 ID 内の最初のバージョン番号で降順
      // ソートする (= ユーザー要望: 4o のような古いモデルが上に並ぶのを
      // やめて、 最新モデルが選ばれやすいように)。
      double ver(String id) {
        final m = RegExp(r'(\d+(?:\.\d+)?)').firstMatch(id);
        return m == null ? 0 : (double.tryParse(m.group(1)!) ?? 0);
      }

      models.sort((a, b) {
        final c = ver(b['id']!).compareTo(ver(a['id']!));
        return c != 0 ? c : a['id']!.compareTo(b['id']!);
      });

      _dynamicOpenaiModels = models;
      _lastOpenaiModelsFetch = DateTime.now();
      final prefs = await _prefsWithRetry();
      await prefs.setString('cached_openai_models', jsonEncode(models));
      await prefs.setInt('models_fetch_openai_ts',
          _lastOpenaiModelsFetch!.millisecondsSinceEpoch);
      notifyListeners();
    } catch (e) {
      debugPrint('refreshOpenaiModels: $e');
    }
  }

  /// Anthropic の /v1/models から取得。
  /// 認証ヘッダ x-api-key が必要なのでキー未設定なら何もしない。
  /// OpenRouter で使えるモデル一覧を取得する (= ユーザー要望: モデルごとに
  /// キーを設定するのではなく、 OpenRouter でまとめて選べるように)。
  /// OpenRouter は数百のモデルを横断して同じキーで呼べるので、 一覧から
  /// 選ぶだけで各社のモデルに切り替えられる。
  List<Map<String, String>> _openrouterModels = [];
  List<Map<String, String>> get openrouterModels =>
      List.unmodifiable(_openrouterModels);
  DateTime? _lastOpenrouterModelsFetch;
  bool _openrouterModelsLoading = false;
  bool get openrouterModelsLoading => _openrouterModelsLoading;

  Future<void> refreshOpenrouterModels({bool force = false}) async {
    if (_openrouterModelsLoading) return;
    if (!force &&
        _openrouterModels.isNotEmpty &&
        _lastOpenrouterModelsFetch != null &&
        DateTime.now().difference(_lastOpenrouterModelsFetch!) <
            const Duration(hours: 24)) {
      return;
    }
    _openrouterModelsLoading = true;
    notifyListeners();
    try {
      // モデル一覧はキー無しでも公開されている (= キー登録前でも下見できる)。
      final res = await http
          .get(Uri.parse('$_openrouterBaseUrl/models'))
          .timeout(const Duration(seconds: 12));
      if (res.statusCode != 200) return;
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final list = (data['data'] as List?) ?? const [];
      final models = <Map<String, String>>[];
      for (final m in list) {
        final mm = m as Map<String, dynamic>;
        final id = (mm['id'] as String?) ?? '';
        if (id.isEmpty) continue;
        final name = (mm['name'] as String?)?.trim();
        // 料金は 1 トークンあたりの USD 文字列で来る。 100 万トークン単位に
        // 直して「だいたいいくらか」 が分かるようにしておく。
        String price = '';
        try {
          final pr = mm['pricing'] as Map<String, dynamic>?;
          final inP = double.tryParse('${pr?['prompt'] ?? ''}') ?? -1;
          final outP = double.tryParse('${pr?['completion'] ?? ''}') ?? -1;
          if (inP == 0 && outP == 0) {
            price = 'free';
          } else if (inP >= 0 && outP >= 0) {
            price = '\$${(inP * 1000000).toStringAsFixed(2)}'
                ' / \$${(outP * 1000000).toStringAsFixed(2)} per 1M';
          }
        } catch (_) {}
        models.add({
          'id': id,
          'label': (name == null || name.isEmpty) ? id : name,
          'price': price,
        });
      }
      models.sort((a, b) => a['label']!.compareTo(b['label']!));
      _openrouterModels = models;
      _lastOpenrouterModelsFetch = DateTime.now();
      final prefs = await _prefsWithRetry();
      await prefs.setString('cached_openrouter_models', jsonEncode(models));
      await prefs.setInt('models_fetch_openrouter_ts',
          _lastOpenrouterModelsFetch!.millisecondsSinceEpoch);
    } catch (e) {
      debugPrint('refreshOpenrouterModels: $e');
    } finally {
      _openrouterModelsLoading = false;
      notifyListeners();
    }
  }

  /// 起動時にキャッシュから読み戻す。
  Future<void> _loadCachedOpenrouterModels() async {
    try {
      final prefs = await _prefsWithRetry();
      final raw = prefs.getString('cached_openrouter_models');
      if (raw == null || raw.isEmpty) return;
      final list = jsonDecode(raw) as List<dynamic>;
      _openrouterModels = [
        for (final e in list)
          (e as Map<String, dynamic>).map((k, v) => MapEntry(k, '$v')),
      ];
      final ts = prefs.getInt('models_fetch_openrouter_ts');
      if (ts != null) {
        _lastOpenrouterModelsFetch =
            DateTime.fromMillisecondsSinceEpoch(ts);
      }
      notifyListeners();
    } catch (_) {}
  }

  Future<void> refreshClaudeModels() async {
    final key = _anthropicApiKey;
    if (key == null || key.isEmpty) return;
    try {
      final res = await http.get(
        Uri.parse('https://api.anthropic.com/v1/models?limit=100'),
        headers: {
          'x-api-key': key,
          'anthropic-version': '2023-06-01',
        },
      ).timeout(const Duration(seconds: 8));
      if (res.statusCode != 200) return;
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final list = (data['data'] as List?) ?? const [];

      final models = <Map<String, String>>[];
      for (final m in list) {
        final mm = m as Map<String, dynamic>;
        final id = (mm['id'] as String?) ?? '';
        // display_name が API 側で用意されていればそれを使う
        // (例: "Claude Sonnet 4.5"). 無ければ ID をそのまま使う。
        final displayName =
            (mm['display_name'] as String?)?.trim().isNotEmpty == true
                ? mm['display_name'] as String
                : id;
        if (id.isEmpty) continue;
        models.add({'id': id, 'label': displayName});
      }
      // ID で降順ソート (新しい "claude-opus-4-7" が先頭に来るように)
      models.sort((a, b) => b['id']!.compareTo(a['id']!));

      _dynamicClaudeModels = models;
      _lastClaudeModelsFetch = DateTime.now();
      final prefs = await _prefsWithRetry();
      await prefs.setString('cached_claude_models', jsonEncode(models));
      await prefs.setInt('models_fetch_claude_ts',
          _lastClaudeModelsFetch!.millisecondsSinceEpoch);
      notifyListeners();
    } catch (e) {
      debugPrint('refreshClaudeModels: $e');
    }
  }

  /// Gemini API キーの実効値。
  /// BYOK (= ユーザー要望): 利用者が設定画面で入力した自分のキーのみを使う。
  /// 開発者のグローバルキーへのフォールバックは廃止 (キーを配布しない方針)。
  String? _effectiveGeminiKey() {
    if (_geminiApiKey != null && _geminiApiKey!.isNotEmpty) {
      return _geminiApiKey;
    }
    return null;
  }

  /// 全プロバイダーのモデル一覧を強制リフレッシュする。
  /// 設定画面の「モデル一覧を更新」ボタンから呼ぶ用。
  /// 24h 制限を無視して即時に API を叩く。
  Future<void> forceRefreshAllAvailableModels() async {
    // 並列実行: それぞれ独立した API 呼び出しなので待ち時間を短縮できる。
    await Future.wait([
      refreshGeminiModels(),
      refreshOpenaiModels(),
      refreshClaudeModels(),
    ]);
  }

  /// AI 設定ダイアログを開いた時に呼ぶ軽い更新 (= ユーザー要望: 開く度に
  /// 定期的に選択肢が最新モデルになるように)。 前回取得から 6 時間以上
  /// 経っているプロバイダーだけ、 裏で取り直す (キー未設定なら各 refresh
  /// が即 return するので通信は起きない)。
  Future<void> refreshModelsOnSettingsOpen() async {
    bool stale(DateTime? t) =>
        t == null || DateTime.now().difference(t).inHours >= 6;
    final jobs = <Future<void>>[];
    if (stale(_lastGeminiModelsFetch)) jobs.add(refreshGeminiModels());
    if (stale(_lastOpenaiModelsFetch)) jobs.add(refreshOpenaiModels());
    if (stale(_lastClaudeModelsFetch)) jobs.add(refreshClaudeModels());
    if (jobs.isEmpty) return;
    await Future.wait(jobs);
  }

  // ── 開発者モード ──────────────────────────────────────────────────────────
  bool _developerMode = false;
  bool get developerMode => _developerMode;
  Timer? _developerModeRestoreTimer;
  int _developerModeRestoreAttempt = 0;
  bool _developerModeRestoreInFlight = false;
  int _developerModeStateGeneration = 0;
  Future<void> _developerModeRevocation = Future<void>.value();

  /// グローバルAPIキー（開発者が全ユーザー向けに設定）
  String? _globalGeminiApiKey;
  String? get globalGeminiApiKey => _globalGeminiApiKey;

  /// 問い合わせ先メールアドレス（開発者が設定）
  String _inquiryEmail = '';
  String get inquiryEmail => _inquiryEmail;

  // ─── Pro プラン (有料機能) ────────────────────────────────────────────
  //
  // 無料プランでは同じ種類のページを 1 ページまで作成可能。2 ページ目以降は
  // Pro プラン加入か有効なクーポンコード適用が必要。仕組み:
  //
  // - `_proSubscribed`        : 通常のサブスク加入済み (永続)
  // - `_appliedCouponCode`    : 現在適用中のクーポンコード
  // - `_couponDiscountPercent`: クーポンの割引率 (0-100)
  // - `_couponExpiry`         : クーポンの有効期限 (UTC)
  //
  // ページ作成時は `canCreatePageType` をチェック。クーポンが期限切れに
  // なっていたら自動的に `_appliedCouponCode` をクリアする。

  /// 無料プランで作成可能な同一種類ページ数。これを超えるとペイウォール表示。
  static const int kFreePageLimit = 1;

  /// プラン月額価格 (USD)。 ペイウォール / プラン紹介画面で表示する用。
  /// 実課金接続時はストア (App Store / Google Play / RevenueCat) 側の
  /// 価格表示を優先するが、 オフライン時の参考表示やマーケティング文言用に
  /// アプリ側でも保持しておく。
  static const String kProMonthlyPriceUsd = r'$5.99';
  static const String kMaxMonthlyPriceUsd = r'$19.99';

  /// プランごとの自動削除猶予期間。
  ///   Free: アップロードから 3 日でファイル単位に削除
  ///   Pro/Max: 契約終了から 30 日で全データ削除
  static const Duration kFreeAutoDeleteGrace = Duration(days: 3);
  static const Duration kPaidAutoDeleteGrace = Duration(days: 30);

  /// 画面分割 (PDF/動画/Web/Office の分割表示) を無料プランで開ける回数の上限。
  /// 無料プランは 2 回まで分割を開けて、3 回目以降は Pro 以上のプランが必要。
  /// Pro/Max/クーポン/開発者モードは無制限。
  static const int kFreeSplitViewLimit = 2;

  bool _proSubscribed = false;
  bool get proSubscribed => _proSubscribed;

  /// 実課金で確定した具体プラン (pro / max)。free = 未加入。
  /// 上の SubscriptionPlan のコメントどおり、購入結果をこの enum に書き込む。
  /// `_proSubscribed` は「Pro 以上に加入しているか」の後方互換フラグとして併存。
  SubscriptionPlan _purchasedPlan = SubscriptionPlan.free;
  SubscriptionPlan get purchasedPlan => _purchasedPlan;
  Future<void> _billingPersistence = Future<void>.value();
  Future<void>? _proStateLoadFuture;

  /// RevenueCat 連携サービス。onPlanChanged で購入結果を provider に反映する。
  /// env.json から public キー等を注入 (シークレットは持たせない)。
  late final BillingService _billing = BillingService(
    apiKeyMobile: const String.fromEnvironment('REVENUECAT_API_KEY_ANDROID',
        defaultValue: ''),
    restApiKey: const String.fromEnvironment('REVENUECAT_API_KEY_REST',
        defaultValue: ''),
    webLinkPro: const String.fromEnvironment('REVENUECAT_WEB_PURCHASE_LINK_PRO',
        defaultValue: ''),
    webLinkMax: const String.fromEnvironment('REVENUECAT_WEB_PURCHASE_LINK_MAX',
        defaultValue: ''),
    // ── Stripe 決済リンク (デスクトップ用) ──
    stripeLinkProMonthly:
        const String.fromEnvironment('STRIPE_LINK_PRO_MONTHLY',
            defaultValue: ''),
    stripeLinkProYearly: const String.fromEnvironment('STRIPE_LINK_PRO_YEARLY',
        defaultValue: ''),
    stripeLinkMaxMonthly:
        const String.fromEnvironment('STRIPE_LINK_MAX_MONTHLY',
            defaultValue: ''),
    stripeLinkMaxYearly: const String.fromEnvironment('STRIPE_LINK_MAX_YEARLY',
        defaultValue: ''),
    stripeTestMode:
        const String.fromEnvironment('STRIPE_TEST_MODE', defaultValue: '') ==
            'true',
    entitlementApiBase: const String.fromEnvironment('ENTITLEMENT_API_BASE',
        defaultValue: ''),
    onPlanChanged: applyBillingPlanByName,
  );
  BillingService get billing => _billing;

  /// Pro / Max の契約が解除された日時 (UTC)。
  /// 課金状態が `_proSubscribed = true → false` に切り替わった瞬間に
  /// `setProSubscription(false)` 経由でセットされる。 この日付から 30 日が
  /// 経過すると、 起動時の `pruneExpiredCloudData()` で
  /// 該当グループの Storage 全データが自動削除される (= 復活猶予期間)。
  DateTime? _subscriptionEndedAt;
  DateTime? get subscriptionEndedAt => _subscriptionEndedAt;

  /// 実課金 (RevenueCat / IAP) からのフックで Pro 状態を切り替えるエントリ。
  /// false に切り替える瞬間に「契約終了タイムスタンプ」を記録するので、
  /// 30 日後の自動削除タイマーが動き出す。 true に戻れば終了時刻はクリア。
  /// 後方互換: bool フックは pro として扱う。
  /// (旧コードの `setProSubscription(true/false)` 呼び出しをそのまま活かす)
  Future<void> setProSubscription(bool subscribed) async {
    await applyBillingPlan(
        subscribed ? SubscriptionPlan.pro : SubscriptionPlan.free);
  }

  /// billing_service からの文字列 ('free'/'pro'/'max') を受けるブリッジ。
  /// BillingService.onPlanChanged に渡している。
  void applyBillingPlanByName(String name) {
    if (_disposed) return;
    final plan = SubscriptionPlan.values.firstWhere(
      (p) => p.name == name,
      orElse: () => SubscriptionPlan.free,
    );
    // ignore: discarded_futures
    applyBillingPlan(plan);
  }

  /// 実課金 (RevenueCat) からのフックで確定プランを適用する正式エントリ。
  /// free に落ちた瞬間に「契約終了タイムスタンプ」を記録するので、30 日後の
  /// 自動削除タイマーが動き出す。pro/max に戻れば終了時刻はクリア。
  Future<void> applyBillingPlan(SubscriptionPlan plan) async {
    final nextPro = plan != SubscriptionPlan.free;
    if (_purchasedPlan == plan && _proSubscribed == nextPro) return;
    _purchasedPlan = plan;
    _proSubscribed = nextPro;
    if (!nextPro) {
      // 解除された → 30 日後の自動削除起算点を保存
      _subscriptionEndedAt = DateTime.now().toUtc();
    } else {
      _subscriptionEndedAt = null;
    }
    notifyListeners();

    // RevenueCat のキャッシュ通知と最新状態通知が短時間に連続することがある。
    // SharedPreferences 書き込みを直列化し、古い通知の完了が新しい状態を
    // 後から上書きしないようにする。
    final endedAtSnapshot = _subscriptionEndedAt;
    final write = _billingPersistence.catchError((Object e) {
      debugPrint('前回の課金状態保存に失敗: $e');
    }).then((_) async {
      final prefs = await _prefsWithRetry();
      await prefs.setBool('pro_subscribed', nextPro);
      await prefs.setString('purchased_plan', plan.name);
      if (endedAtSnapshot != null) {
        await prefs.setInt(
            'subscription_ended_at_ms', endedAtSnapshot.millisecondsSinceEpoch);
      } else {
        await prefs.remove('subscription_ended_at_ms');
      }
    });
    _billingPersistence = write;
    try {
      await write;
    } catch (e) {
      debugPrint('課金状態の保存に失敗: $e');
    }
    if (_disposed) return;
    // lastSeen と所属グループの表示用メタデータを更新する。
    // users.plan はサーバー正本なのでクライアントからは変更しない。
    // ignore: discarded_futures
    _syncPlanToUserDoc();
  }

  /// 現在適用中のクーポンが解放するプラン種別。
  /// 既定は `pro` (互換性: 過去のクーポンは plan フィールドが無いので pro 扱い)。
  /// Max 用クーポンを引き換えると `max` になる。
  SubscriptionPlan _couponPlan = SubscriptionPlan.pro;
  SubscriptionPlan get couponPlan => _couponPlan;

  /// ─── 月次容量制限 (アップロード / ダウンロード) ────────────────────────
  /// プランごとの月間上限:
  ///   free : アップロード 5 MB,   ダウンロード 20 MB
  ///   pro  : アップロード 5 GB,   ダウンロード 20 GB
  ///   max  : アップロード 25 GB,  ダウンロード 100 GB
  ///
  /// バイト数の累積を SharedPreferences に保存し、 月 (yyyy-MM) が
  /// 変わったら自動リセット。 端末ローカル管理なので 100% 厳密ではないが、
  /// 通常利用での暴走防止には十分。
  int _monthlyUploadBytes = 0;
  int _monthlyDownloadBytes = 0;
  String _billingMonthYm = ''; // 'yyyy-MM' 形式
  /// 累積ストレージ使用量 (バイト)。 Firebase Storage に保持しているファイルの
  /// 合計サイズ。 アップロード成功で加算、 ファイル削除で減算する。
  /// 端末ローカル管理 (SharedPreferences) なので 100% 厳密ではないが、
  /// 通常運用では暴走防止に十分。
  int _totalStorageBytes = 0;
  int get monthlyUploadBytes {
    _resetMonthlyIfNeeded();
    return _monthlyUploadBytes;
  }

  int get monthlyDownloadBytes {
    _resetMonthlyIfNeeded();
    return _monthlyDownloadBytes;
  }

  /// 開発者モード時に各上限へ返す「実質無制限」 値 (約 1 PB)。
  static const int kUnlimitedBytes = 1 << 50;

  /// 各上限が「実質無制限 (= 開発者モード)」 かどうか。 UI 表示で使う。
  /// 上限を無視してよい状態か。
  ///
  /// ★ 開発者モードでも、 プランを装っている時 (dev_impersonate_plan) は
  ///   **そのプランの上限に従う** (= ユーザー報告: Free を選んでいるのに
  ///   使用状況が「無制限」 と出る)。 装った状態で見え方を確かめるための
  ///   機能なので、 上限まで開いてしまうと確かめられない。
  ///   Dev 枠 (引き換えコードの dev プラン) は今までどおり無制限。
  bool get _quotaUnlimited => currentPlan == SubscriptionPlan.dev;

  bool get isStorageUnlimited => _quotaUnlimited;

  /// プランごとのアップロード月上限 (バイト)。 0 は無制限の意味でも使えるが、
  /// 現状はすべて有限値。
  int get monthlyUploadLimit {
    if (_quotaUnlimited) return kUnlimitedBytes; // Dev 枠は実質無制限
    switch (currentPlan) {
      // ★ クラウド同期は Max 限定 (uploadToCloud / downloadFromCloud /
      //   fetchCloudPageList などすべてに isMaxUnlocked のゲートがある)。
      //   以前はここに Free 5MB / Pro 5GB という値が入っていたが、 そこへ
      //   到達しないので使われず、 画面には「5MB まで使える」 かのように
      //   出ていた (= 実態と食い違う表示)。 0 にして「使えない」 を表す。
      case SubscriptionPlan.free:
      case SubscriptionPlan.pro:
        return 0;
      case SubscriptionPlan.max:
      case SubscriptionPlan.dev: // Dev は Max と同じ枠
        return 25 * 1024 * 1024 * 1024; // 25 GB
    }
  }

  /// プランごとのダウンロード月上限 (バイト)。
  int get monthlyDownloadLimit {
    if (_quotaUnlimited) return kUnlimitedBytes; // Dev 枠は実質無制限
    switch (currentPlan) {
      // クラウド同期は Max 限定 (monthlyUploadLimit の注記を参照)。
      case SubscriptionPlan.free:
      case SubscriptionPlan.pro:
        return 0;
      case SubscriptionPlan.max:
      case SubscriptionPlan.dev: // Dev は Max と同じ枠
        return 100 * 1024 * 1024 * 1024; // 100 GB
    }
  }

  /// プランごとの累積ストレージ容量上限 (バイト)。
  /// Firebase Storage 上に同時に保持できるファイル合計サイズの上限。
  ///   free / pro : 0 (クラウド同期そのものが Max 限定のため)
  ///   max        : 100 GB
  int get totalStorageLimit {
    if (_quotaUnlimited) return kUnlimitedBytes; // Dev 枠は実質無制限
    switch (currentPlan) {
      // クラウド同期は Max 限定 (monthlyUploadLimit の注記を参照)。
      case SubscriptionPlan.free:
      case SubscriptionPlan.pro:
        return 0;
      case SubscriptionPlan.max:
      case SubscriptionPlan.dev: // Dev は Max と同じ枠
        return 100 * 1024 * 1024 * 1024; // 100 GB
    }
  }

  int get totalStorageBytes => _totalStorageBytes;
  int get totalStorageRemaining {
    final r = totalStorageLimit - _totalStorageBytes;
    return r < 0 ? 0 : r;
  }

  /// `bytes` バイトをストレージに追加して問題ないかチェック。
  bool canUseStorageBytes(int bytes) =>
      _totalStorageBytes + bytes <= totalStorageLimit;

  /// 今月の残りアップロード可能バイト (>= 0)。
  int get monthlyUploadRemaining {
    final r = monthlyUploadLimit - monthlyUploadBytes;
    return r < 0 ? 0 : r;
  }

  /// 今月の残りダウンロード可能バイト。
  int get monthlyDownloadRemaining {
    final r = monthlyDownloadLimit - monthlyDownloadBytes;
    return r < 0 ? 0 : r;
  }

  /// `bytes` バイトのアップロードを開始して問題ないかチェック。
  /// 上限超過なら false。 上限到達ぎりぎり (例: 残り 1MB) の時も、
  /// 部分的に通すのではなく false にして UI 側で上限案内を出させる。
  bool canUseUploadBytes(int bytes) =>
      monthlyUploadBytes + bytes <= monthlyUploadLimit;

  /// `bytes` バイトのダウンロードを開始して問題ないかチェック。
  bool canUseDownloadBytes(int bytes) =>
      monthlyDownloadBytes + bytes <= monthlyDownloadLimit;

  /// 月をまたいだ場合に累積をリセットする。 SharedPreferences に保存する処理は
  /// 副作用無しで呼びたい場面 (ゲッター) でも呼ばれるので、 同期で書込む
  /// 代わりにフラグだけ更新し、次回 `_persistMonthlyUsage` 時に確定させる。
  void _resetMonthlyIfNeeded() {
    final now = DateTime.now();
    final ym = '${now.year.toString().padLeft(4, '0')}-'
        '${now.month.toString().padLeft(2, '0')}';
    if (_billingMonthYm != ym) {
      _billingMonthYm = ym;
      _monthlyUploadBytes = 0;
      _monthlyDownloadBytes = 0;
      // 永続化は async の都合上 fire-and-forget
      // ignore: discarded_futures
      _persistMonthlyUsage();
    }
  }

  Future<void> _persistMonthlyUsage() async {
    final prefs = await _prefsWithRetry();
    await prefs.setString('billingMonthYm', _billingMonthYm);
    await prefs.setInt('monthlyUploadBytes', _monthlyUploadBytes);
    await prefs.setInt('monthlyDownloadBytes', _monthlyDownloadBytes);
    await prefs.setInt('totalStorageBytes', _totalStorageBytes);
  }

  /// アップロード成功時に使用量を加算 (永続化込み)。
  void recordUploadBytes(int bytes) {
    _resetMonthlyIfNeeded();
    if (bytes <= 0) return;
    _monthlyUploadBytes += bytes;
    // 累積ストレージにも加算 (アップロード = Storage に新規ファイル登録)
    _totalStorageBytes += bytes;
    // ignore: discarded_futures
    _persistMonthlyUsage();
    scheduleAccountPush(); // 他の端末にも反映する
    notifyListeners();
  }

  /// ダウンロード成功時に使用量を加算 (永続化込み)。
  void recordDownloadBytes(int bytes) {
    _resetMonthlyIfNeeded();
    if (bytes <= 0) return;
    _monthlyDownloadBytes += bytes;
    // ignore: discarded_futures
    _persistMonthlyUsage();
    scheduleAccountPush();
    notifyListeners();
  }

  /// Storage からファイルを削除した時に累積使用量を減算する。
  /// 自動削除 (期限切れ) や手動削除の両方から呼ばれる。
  void releaseStorageBytes(int bytes) {
    if (bytes <= 0) return;
    _totalStorageBytes -= bytes;
    if (_totalStorageBytes < 0) _totalStorageBytes = 0;
    // ignore: discarded_futures
    _persistMonthlyUsage();
    scheduleAccountPush();
    notifyListeners();
  }

  /// Ctrl+S (クラウドアップロード) で「URL のみ上げる」をユーザーが選んだ
  /// ときに 1 回だけ動画ファイルアップロードをスキップするためのフラグ。
  /// `_uploadPageAttachments` 内でローカル動画ジョブの追加可否を判定し、
  /// アップロード処理の最後でリセットされる (ワンショット動作)。
  /// デフォルトは false (= 従来通り動画ファイルもアップロード)。
  bool skipVideoUploadOnce = false;

  String? _appliedCouponCode;
  String? get appliedCouponCode => _appliedCouponCode;

  int _couponDiscountPercent = 0;
  int get couponDiscountPercent => _couponDiscountPercent;

  DateTime? _couponExpiry;
  DateTime? get couponExpiry => _couponExpiry;

  /// 有効なクーポンが適用されているかどうか (期限内 + 100%引き = Pro 同等)。
  /// 部分割引クーポンは将来の課金導入用に値だけ持っておくが、
  /// 現状のページ制限解放には「100% 割引」(= 完全無料化) のクーポンを使う。
  bool get hasActiveCoupon {
    if (_appliedCouponCode == null) return false;
    if (_couponExpiry != null && DateTime.now().isAfter(_couponExpiry!)) {
      return false;
    }
    // 割引率 100% (= 完全無料化) は Pro 同等扱いでページ作成解放。
    // それ未満は将来の課金時に金額差し引き用。
    return _couponDiscountPercent >= 100;
  }

  /// 開発者モード時に「演じる」プラン。Free/Pro/Max を切り替えて
  /// 各プランでの UI / 機能制限の挙動をテストできる。
  /// デフォルトは `pro` (= 開発者モードに入った瞬間に Pro として扱われる)。
  /// `_developerMode == false` の時は無視され、`_proSubscribed` /
  /// `hasActiveCoupon` で実際の状態を判定する。
  SubscriptionPlan _devImpersonatePlan = SubscriptionPlan.pro;
  SubscriptionPlan get devImpersonatePlan => _devImpersonatePlan;

  /// 開発者モードでの演じるプランを変更し、SharedPreferences に永続化する。
  Future<void> setDevImpersonatePlan(SubscriptionPlan plan) async {
    if (!_developerMode || _disposed) return;
    _devImpersonatePlan = plan;
    final prefs = await _prefsWithRetry();
    await prefs.setString('dev_impersonate_plan', plan.name);
    notifyListeners();
    // 課金 plan は書き換えず、最終アクセス等の非課金メタデータだけ更新する。
    // ignore: discarded_futures
    _syncPlanToUserDoc();
  }

  /// 現在のプラン種別 (UI 表示や機能切り分け用)。
  /// 開発者モード時は `_devImpersonatePlan` を返し、それ以外は実際の購入状態
  /// (proSubscribed → pro / クーポン → couponPlan / それ以外 → free) を返す。
  /// クーポンの種類 (Pro / Max) は `_couponPlan` で識別。
  SubscriptionPlan get currentPlan {
    if (_developerMode) return _devImpersonatePlan;
    // 実課金プラン (pro / max) を最優先で反映
    if (_purchasedPlan != SubscriptionPlan.free) return _purchasedPlan;
    if (hasActiveCoupon) return _couponPlan;
    return SubscriptionPlan.free;
  }

  /// Pro / クーポン / 開発者モード によってページ無制限になっているか。
  /// UI 側のペイウォール出し分けで使う。
  /// 開発者モードは演じプラン (`_devImpersonatePlan`) で切り替わるので、
  /// Free を演じている場合は無料プラン同等の制限が適用される。
  bool get hasUnlimitedPages => currentPlan != SubscriptionPlan.free;

  /// Pro 機能 (= 動画ダウンロード・無制限ページ等) が
  /// 解放されているか。中身は `hasUnlimitedPages` と同じだが、ページ枚数
  /// 以外の文脈で使う場合に意味が分かるよう別名で公開する。
  bool get isProUnlocked => currentPlan != SubscriptionPlan.free;

  int pageTypeCount(String pageType) {
    var count = 0;
    for (final page in _pages) {
      if (page.pageType == pageType) count++;
    }
    return count;
  }

  int get freePageTypesUsed {
    final types = <String>{};
    for (final page in _pages) {
      types.add(page.pageType);
    }
    return types.length;
  }

  /// 指定した種類のページを作成して良いか。
  /// 無料プラン + Pro 未加入 + クーポン無効 の場合、既定で作成済みのページも
  /// 含め、同じ pageType は `kFreePageLimit` 枚までに制限する。
  bool canCreatePageType(String pageType) {
    if (hasUnlimitedPages) return true;
    // ── モバイル無料版: 既定の 4 ページ (マップ / ギャラリー / フリーノート /
    //    ビデオ) が最初から用意され、 それ以外の新規作成は Pro 以上
    //    (= ユーザー要望)。 ──
    if (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) return false;
    // ── フリーノート (ノート自体の新規作成) は Pro 以上限定
    //    (= ユーザー要望: ノート内のページはいくらでも増やせるが、 ノートを
    //    新規に作るには Pro への加入が必要)。 ──
    if (pageType == 'paint') return false;
    return pageTypeCount(pageType) < kFreePageLimit;
  }

  /// Web の自動操作が使えるか (= ユーザー要望: Pro 以上限定)。
  bool get canUseWebAutomation => isProUnlocked;


  /// 通常ページを作成して良いか。既存呼び出し向けの後方互換アクセサ。
  bool get canCreateNewPage => canCreatePageType('normal');

  /// ─── 画面分割の無料利用回数 ───────────────────────────────────────────
  /// 無料プランは画面分割を `kFreeSplitViewLimit` (= 2) 回まで無料で開ける。
  /// 3 回目以降は Pro 以上が必要。SharedPreferences に累積回数を保存する。
  int _splitViewUseCount = 0;
  int get splitViewUseCount => _splitViewUseCount;

  /// 残りの無料分割回数 (>= 0)。Pro 以上かどうかは `canUseSplitView` で判定。
  int get splitViewFreeRemaining {
    final r = kFreeSplitViewLimit - _splitViewUseCount;
    return r < 0 ? 0 : r;
  }

  /// 画面分割を新規に開いて良いか。Pro 以上は常に true、
  /// 無料プランは累積利用回数が上限未満なら true。
  bool get canUseSplitView =>
      isProUnlocked || _splitViewUseCount < kFreeSplitViewLimit;

  /// 画面分割を 1 回開いたことを記録 (無料枠を 1 消費)。Pro 以上では呼ばない。
  /// SharedPreferences に永続化する (fire-and-forget)。
  /// notifyListeners は呼ばない: setState/build 内から呼ばれる可能性があり、
  /// ビルド中の通知を避けるため。残数表示は次回ダイアログ表示時に最新化される。
  void recordSplitViewUse() {
    _splitViewUseCount++;
    // ignore: discarded_futures
    _persistSplitViewUse();
  }

  Future<void> _persistSplitViewUse() async {
    final prefs = await _prefsWithRetry();
    await prefs.setInt('splitViewUseCount', _splitViewUseCount);
  }

  /// ─── 集中ロック / 画面ロックの無料利用 ─────────────────────────────────
  /// = ユーザー要望: 「集中ロックや画面ロックは初回だけ誰でも実行できて、
  ///   2 回目以降は Pro プラン以上限定」。 それぞれ初回 1 回のみ無料。
  static const int kFreeLockLimit = 1;
  int _focusLockUseCount = 0;
  int _appLockUseCount = 0;
  int get focusLockUseCount => _focusLockUseCount;
  int get appLockUseCount => _appLockUseCount;

  /// 集中ロックを今すぐ実行して良いか。 Pro 以上は常に true、 無料は初回のみ。
  bool get canUseFocusLock =>
      isProUnlocked || _focusLockUseCount < kFreeLockLimit;

  /// 画面ロックを今すぐ実行して良いか。 Pro 以上は常に true、 無料は初回のみ。
  bool get canUseAppLock => isProUnlocked || _appLockUseCount < kFreeLockLimit;

  void recordFocusLockUse() {
    _focusLockUseCount++;
    // ignore: discarded_futures
    _persistLockUse();
  }

  void recordAppLockUse() {
    _appLockUseCount++;
    // ignore: discarded_futures
    _persistLockUse();
  }

  Future<void> _persistLockUse() async {
    final prefs = await _prefsWithRetry();
    await prefs.setInt('focusLockUseCount', _focusLockUseCount);
    await prefs.setInt('appLockUseCount', _appLockUseCount);
  }

  /// Max プラン以上が解放されているか (= ユーザー要望: Cloud 同期は Max 限定)。
  /// Max を演じる開発者モード / Max クーポンでも true。
  /// Dev は「Max + 決済なしで AI」 なので、 ここでも解放する。
  bool get isMaxUnlocked =>
      currentPlan == SubscriptionPlan.max || currentPlan == SubscriptionPlan.dev;

  /// Dev プラン (= 決済を通さずに AI を呼べる枠) が有効か。
  /// 開発者モードそのものとは別物 (開発者モードはパスワードで入る管理機能)。
  /// Dev 枠 (= 決済を通さずに AI 代行を使える枠) を持っているか。
  ///
  /// ★ 開発者モード中の `currentPlan` は「演じるプラン」 (`_devImpersonatePlan`、
  ///   既定 pro) を返す。 そのため Dev コードを引き換えて `_purchasedPlan` が
  ///   dev になっていても、 開発者モードに入った途端 `isDevPlan` が false に
  ///   なり、 残高 0 だと `canUseAiRelay` が閉じて AI が
  ///   「Gemini APIキーが設定されていません」 になっていた (= ユーザー報告:
  ///   「Dev モードになったのに API キーが設定されていませんと言われる」)。
  ///   実際に引き換えたプランも見て、 演じるプランで塞がないようにする。
  ///   本当に Dev 枠かはサーバー (entitlement) が判定するので、 ここは
  ///   入口を開けるだけ。
  bool get isDevPlan =>
      currentPlan == SubscriptionPlan.dev ||
      _purchasedPlan == SubscriptionPlan.dev;

  /// Pro / クーポン状態をローカルから復元。
  /// クーポンは期限切れなら自動クリア。
  /// 加えて開発者モード用の演じプラン (Free/Pro/Max) も復元する。
  /// `purchased_plan` は起動直後の表示用キャッシュに過ぎない。Firebase 初期化は
  /// この Future の完了を待ってから RevenueCat.configure/getCustomerInfo を呼び、
  /// SDK に接続できた場合は、検証済みの最新 entitlement で上書きする。
  Future<void> _loadProState() async {
    final prefs = await _prefsWithRetry();
    _proSubscribed = prefs.getBool('pro_subscribed') ?? false;
    // 実課金プラン (pro/max) を復元。旧バージョン互換: 無ければ bool から導出。
    final purchasedPlanStr = prefs.getString('purchased_plan');
    if (purchasedPlanStr != null) {
      _purchasedPlan = SubscriptionPlan.values.firstWhere(
        (p) => p.name == purchasedPlanStr,
        orElse: () => SubscriptionPlan.free,
      );
    } else if (_proSubscribed) {
      _purchasedPlan = SubscriptionPlan.pro;
    }
    _splitViewUseCount = prefs.getInt('splitViewUseCount') ?? 0;
    _focusLockUseCount = prefs.getInt('focusLockUseCount') ?? 0;
    _appLockUseCount = prefs.getInt('appLockUseCount') ?? 0;
    final endedMs = prefs.getInt('subscription_ended_at_ms');
    if (endedMs != null) {
      _subscriptionEndedAt = DateTime.fromMillisecondsSinceEpoch(endedMs);
    }
    _appliedCouponCode = prefs.getString('applied_coupon_code');
    _couponDiscountPercent = prefs.getInt('coupon_discount_percent') ?? 0;
    final expiryMs = prefs.getInt('coupon_expiry_ms');
    if (expiryMs != null) {
      _couponExpiry = DateTime.fromMillisecondsSinceEpoch(expiryMs);
    }
    // 適用中クーポンが解放するプラン (pro / max)
    final couponPlanStr = prefs.getString('coupon_plan');
    if (couponPlanStr != null) {
      _couponPlan = SubscriptionPlan.values.firstWhere(
        (p) => p.name == couponPlanStr,
        orElse: () => SubscriptionPlan.pro,
      );
    }
    // 期限切れクーポンの自動クリア
    if (_couponExpiry != null &&
        DateTime.now().isAfter(_couponExpiry!) &&
        _appliedCouponCode != null) {
      await _clearCoupon();
    }
    // 開発者モードの演じプラン復元
    final planStr = prefs.getString('dev_impersonate_plan');
    if (planStr != null) {
      _devImpersonatePlan = SubscriptionPlan.values.firstWhere(
        (p) => p.name == planStr,
        orElse: () => SubscriptionPlan.pro,
      );
    }
    // 月次容量カウンタ復元 (月またぎなら自動で 0 リセット)
    _billingMonthYm = prefs.getString('billingMonthYm') ?? '';
    _monthlyUploadBytes = prefs.getInt('monthlyUploadBytes') ?? 0;
    _monthlyDownloadBytes = prefs.getInt('monthlyDownloadBytes') ?? 0;
    // 累積ストレージ使用量 (月またぎでもリセットしない)
    _totalStorageBytes = prefs.getInt('totalStorageBytes') ?? 0;
    _resetMonthlyIfNeeded();
    // 起動直後の UI は読み込み前の Free 初期値で一度 build される。
    // 復元後に通知しないと、次の無関係な更新まで購入済みプランや
    // 開発者用の演じプランが Free に離脱したように見えていた。
    notifyListeners();
  }

  Future<void> _clearCoupon() async {
    _appliedCouponCode = null;
    _couponDiscountPercent = 0;
    _couponExpiry = null;
    _couponPlan = SubscriptionPlan.pro;
    final prefs = await _prefsWithRetry();
    await prefs.remove('applied_coupon_code');
    await prefs.remove('coupon_discount_percent');
    await prefs.remove('coupon_expiry_ms');
    await prefs.remove('coupon_plan');
    notifyListeners();
  }

  /// クーポンコードを適用する。
  /// Firestore 上のクーポンドキュメントを取得し、有効なら適用、
  /// 無効なら理由を含むエラーメッセージを返す。
  ///
  /// 戻り値 null = 成功、それ以外 = エラーメッセージ (ローカライズ済み)
  String? _deviceIdCache;

  /// 端末固有ID（クーポンの端末別不正利用防止に使用）。
  /// Windows はマシン GUID（アンインストールしても維持される）。
  /// Android は取得可能なハードウェア情報の合成（ANDROID_ID は
  ///   device_info_plus v11 では取得不可のため、厳密な一意性は保証されない
  ///   ＝ベストエフォート）。iOS/macOS/Linux はベンダー/システム ID。
  Future<String> _deviceId() async {
    if (_deviceIdCache != null) return _deviceIdCache!;
    String id = '';
    try {
      if (!kIsWeb) {
        final info = DeviceInfoPlugin();
        if (Platform.isWindows) {
          id = (await info.windowsInfo).deviceId;
        } else if (Platform.isAndroid) {
          try {
            id = (await const MethodChannel('app/device')
                    .invokeMethod<String>('getAndroidId')) ??
                '';
          } catch (_) {}
          final a = await info.androidInfo;
          if (id.isEmpty) {
            id =
                '${a.brand}_${a.device}_${a.model}_${a.board}_${a.hardware}_${a.id}';
          }
        } else if (Platform.isIOS) {
          id = (await info.iosInfo).identifierForVendor ?? '';
        } else if (Platform.isMacOS) {
          id = (await info.macOsInfo).systemGUID ?? '';
        } else if (Platform.isLinux) {
          id = (await info.linuxInfo).machineId ?? '';
        }
      }
    } catch (_) {}
    // Firestore のドキュメント ID に使えるようにサニタイズ
    id = id.replaceAll(RegExp(r'[^A-Za-z0-9_-]'), '');
    if (id.isEmpty) id = 'unknown';
    if (id.length > 100) id = id.substring(0, 100);
    _deviceIdCache = id;
    return id;
  }

  DateTime _addCouponMonths(DateTime baseUtc, int months) {
    final totalMonths = baseUtc.month - 1 + months;
    final year = baseUtc.year + totalMonths ~/ 12;
    final month = totalMonths % 12 + 1;
    final lastDay = DateTime.utc(year, month + 1, 0).day;
    final day = math.min(baseUtc.day, lastDay);
    return DateTime.utc(
      year,
      month,
      day,
      baseUtc.hour,
      baseUtc.minute,
      baseUtc.second,
      baseUtc.millisecond,
      baseUtc.microsecond,
    );
  }

  Future<String?> applyCoupon(String code,
      {bool retriedAfterConflict = false,
      bool retriedAfterAuthFailure = false}) async {
    final trimmed = code.trim().toUpperCase();
    if (trimmed.isEmpty) return t('coupon.errEmpty');
    // ── クーポンは Google アカウントでログインしてから (= ユーザー要望) ──
    //    ログインしていないと端末ごとに別人扱いになり、 同じコードを
    //    何台でも使い回せてしまう。 ログインできない配布 (認証情報が
    //    入っていないビルド) では、 従来どおり匿名のまま通す。
    if (canUseGoogleSignIn && !_googleSignedIn) {
      return t('coupon.errNeedGoogle');
    }
    // ── まず Dev コードとして代行サーバーに聞く (= ユーザー要望: Dev に
    //    入れるコードを発行できるように)。 入口はクーポン欄ひとつに揃え、
    //    そのコードが Dev かどうかはサーバーが答える。 知らないコードなら
    //    `_devCodeUnknown` が返るので、 従来のクーポン処理へ進む。 ──
    if (!retriedAfterConflict && !retriedAfterAuthFailure) {
      final dev = await redeemDevCode(trimmed);
      if (dev == null) return null; // Dev として引き換え成立
      if (dev != _devCodeUnknown) return dev; // 期限切れ / 使い切り等
    }
    // クーポンは Firestore 検証が前提。 未接続なら一度だけ初期化を試みる
    //   (= ユーザー要望: 接続できないときに「無効」ではなく「接続できなかった」と
    //   分かるように。 ここで繋がればそのまま検証へ進む)。
    if (!_firebaseEnabled || _idToken == null) {
      try {
        await _initFirebase();
      } catch (_) {}
    }
    if (_firebaseEnabled && _idToken != null) {
      try {
        // 起動時に取得した匿名認証トークンは約1時間で失効する。クーポン処理だけ
        // 更新を行っていなかったため、長時間起動後は有効なコードでも Firestore
        // の 401/403 が「ネットワークエラー」として返っていた。
        await _ensureFreshToken();
        final url = '$_firestoreBaseUrl/coupons/$trimmed';
        final res = await http.get(
          Uri.parse(url),
          headers: {'Authorization': 'Bearer $_idToken'},
        );
        if ((res.statusCode == 401 || res.statusCode == 403) &&
            !retriedAfterAuthFailure) {
          await _ensureFreshToken(force: true);
          return applyCoupon(
            trimmed,
            retriedAfterConflict: retriedAfterConflict,
            retriedAfterAuthFailure: true,
          );
        }
        if (res.statusCode == 404) {
          return t('coupon.errNotFound');
        }
        if (res.statusCode != 200) {
          return t('coupon.errNetwork');
        }
        final data = jsonDecode(res.body) as Map<String, dynamic>;
        final updateTime = data['updateTime'] as String?;
        final fields = data['fields'] as Map<String, dynamic>?;
        if (fields == null) return t('coupon.errInvalid');

        final discount = (() {
          // discountPercent は Firestore で integerValue として保存している。
          // 過去のテストデータ等で stringValue に入っているケースに備えて
          // 両方をチェックする。
          final intStr = (fields['discountPercent']
              as Map<String, dynamic>?)?['integerValue'] as String?;
          if (intStr != null) {
            return int.tryParse(intStr) ?? 0;
          }
          final s = _firestoreStr(fields['discountPercent']) ?? '';
          return int.tryParse(s) ?? 0;
        })();
        final expiryStr = _firestoreStr(fields['expiresAt']);
        final maxUsesStr = ((fields['maxUses']
                as Map<String, dynamic>?)?['integerValue'] as String?) ??
            '0';
        final currentUsesStr = ((fields['currentUses']
                as Map<String, dynamic>?)?['integerValue'] as String?) ??
            '0';
        final validMonthsStr = ((fields['validMonthsAfterUse']
                as Map<String, dynamic>?)?['integerValue'] as String?) ??
            '0';
        final maxUses = int.tryParse(maxUsesStr) ?? 0;
        final currentUses = int.tryParse(currentUsesStr) ?? 0;
        final validMonthsAfterUse =
            math.max(0, int.tryParse(validMonthsStr) ?? 0);

        DateTime? expiry;
        if (expiryStr != null && expiryStr.isNotEmpty) {
          expiry = DateTime.tryParse(expiryStr);
        }

        // ── 端末別の利用履歴チェック ──
        // validMonthsAfterUse が設定されているクーポンは、端末ごとの初回使用日
        // から期限を数える。再入力時は同じ期限を復元し、期限を延長しない。
        final devId = await _deviceId();
        bool alreadyRedeemedOnDevice = false;
        DateTime? deviceBenefitExpiry;
        try {
          final redRes = await http.get(
            Uri.parse('$_firestoreBaseUrl/coupons/$trimmed/redemptions/$devId'),
            headers: {'Authorization': 'Bearer $_idToken'},
          );
          if (redRes.statusCode == 200) {
            if (validMonthsAfterUse <= 0) {
              return t('coupon.errDeviceUsed');
            }
            alreadyRedeemedOnDevice = true;
            final redData = jsonDecode(redRes.body) as Map<String, dynamic>;
            final redFields = redData['fields'] as Map<String, dynamic>? ?? {};
            final redemptionUid = _firestoreStr(redFields['uid']);
            final atomicVersion = int.tryParse(((redFields['atomicVersion']
                            as Map<String, dynamic>?)?['integerValue']
                        as String?) ??
                    '') ??
                0;
            final redeemedMonths = int.tryParse(
                    ((redFields['validMonthsAfterUse']
                                as Map<String, dynamic>?)?['integerValue']
                            as String?) ??
                        '') ??
                -1;
            // 旧クライアントが単独作成した履歴や、別 UID が先に置いた文書は
            // 利用枠の原子的確保を証明できないため entitlement に使わない。
            if (redemptionUid != _uid ||
                atomicVersion != 1 ||
                redeemedMonths != validMonthsAfterUse) {
              return t('coupon.errInvalid');
            }
            final benefitField =
                redFields['benefitExpiresAt'] as Map<String, dynamic>?;
            final benefitExpiryStr = (benefitField?['timestampValue'] ??
                    benefitField?['stringValue'])
                ?.toString();
            if (benefitExpiryStr != null && benefitExpiryStr.isNotEmpty) {
              deviceBenefitExpiry = DateTime.tryParse(benefitExpiryStr);
            }
            if (deviceBenefitExpiry == null) return t('coupon.errInvalid');
            if (deviceBenefitExpiry != null &&
                DateTime.now().isAfter(deviceBenefitExpiry!)) {
              return t('coupon.errExpired');
            }
          }
        } catch (_) {/* ネットワーク不調時は従来どおり続行 */}

        if (!alreadyRedeemedOnDevice &&
            expiry != null &&
            DateTime.now().isAfter(expiry)) {
          return t('coupon.errExpired');
        }
        if (!alreadyRedeemedOnDevice && maxUses > 0 && currentUses >= maxUses) {
          return t('coupon.errMaxUsed');
        }

        DateTime? appliedExpiry = expiry;
        if (validMonthsAfterUse > 0) {
          appliedExpiry = alreadyRedeemedOnDevice && deviceBenefitExpiry != null
              ? deviceBenefitExpiry
              : _addCouponMonths(DateTime.now().toUtc(), validMonthsAfterUse);
        }

        // クーポンが解放するプランを Firestore の plan フィールドから決める
        // (互換性: フィールドがなければ pro 扱い)
        final planStr = _firestoreStr(fields['plan']);
        final appliedCouponPlan =
            (planStr == 'max') ? SubscriptionPlan.max : SubscriptionPlan.pro;
        // 使用回数の予約が成功した場合だけ entitlement を確定する。
        if (!alreadyRedeemedOnDevice) {
          if (updateTime == null || updateTime.isEmpty) {
            return t('coupon.errInvalid');
          }
          final redFields = <String, dynamic>{
            'atomicVersion': {'integerValue': '1'},
            'usedAt': {
              'timestampValue': DateTime.now().toUtc().toIso8601String()
            },
            'uid': {'stringValue': _uid ?? ''},
            'validMonthsAfterUse': {
              'integerValue': validMonthsAfterUse.toString()
            },
          };
          if (appliedExpiry != null) {
            redFields['benefitExpiresAt'] = {
              'timestampValue': appliedExpiry.toUtc().toIso8601String()
            };
          }
          final documentRoot =
              'projects/$_firestoreProjectId/databases/(default)/documents';
          final commitRes = await http.post(
            Uri.parse(
                'https://firestore.googleapis.com/v1/projects/$_firestoreProjectId/databases/(default)/documents:commit'),
            headers: {
              'Authorization': 'Bearer $_idToken',
              'Content-Type': 'application/json',
            },
            body: jsonEncode({
              'writes': [
                {
                  'update': {
                    'name': '$documentRoot/coupons/$trimmed',
                    'fields': {
                      'currentUses': {
                        'integerValue': (currentUses + 1).toString()
                      },
                      'lastRedemptionId': {'stringValue': devId},
                    },
                  },
                  'updateMask': {
                    'fieldPaths': ['currentUses', 'lastRedemptionId']
                  },
                  'currentDocument': {'updateTime': updateTime},
                },
                {
                  'update': {
                    'name': '$documentRoot/coupons/$trimmed/redemptions/$devId',
                    'fields': redFields,
                  },
                  'currentDocument': {'exists': false},
                },
              ],
            }),
          );
          if (commitRes.statusCode < 200 || commitRes.statusCode >= 300) {
            if ((commitRes.statusCode == 401 || commitRes.statusCode == 403) &&
                !retriedAfterAuthFailure) {
              await _ensureFreshToken(force: true);
              return applyCoupon(
                trimmed,
                retriedAfterConflict: retriedAfterConflict,
                retriedAfterAuthFailure: true,
              );
            }
            final conflict = commitRes.statusCode == 409 ||
                commitRes.statusCode == 412 ||
                commitRes.body.contains('ABORTED') ||
                commitRes.body.contains('FAILED_PRECONDITION');
            if (conflict && !retriedAfterConflict) {
              return applyCoupon(
                trimmed,
                retriedAfterConflict: true,
                retriedAfterAuthFailure: retriedAfterAuthFailure,
              );
            }
            debugPrint('coupon atomic redemption failed: '
                '${commitRes.statusCode} ${commitRes.body}');
            return commitRes.body.contains('PERMISSION_DENIED')
                ? t('coupon.errNetwork')
                : t('coupon.errMaxUsed');
          }
        }
        // サーバー側の利用枠確保後にのみローカル entitlement を確定する。
        _appliedCouponCode = trimmed;
        _couponDiscountPercent = discount;
        _couponExpiry = appliedExpiry;
        _couponPlan = appliedCouponPlan;
        final prefs = await _prefsWithRetry();
        await prefs.setString('applied_coupon_code', trimmed);
        await prefs.setInt('coupon_discount_percent', discount);
        await prefs.setString('coupon_plan', _couponPlan.name);
        if (appliedExpiry != null) {
          await prefs.setInt(
              'coupon_expiry_ms', appliedExpiry.millisecondsSinceEpoch);
        } else {
          await prefs.remove('coupon_expiry_ms');
        }
        // /users/{uid} のプランフィールドを同期 (失敗してもユーザー体験は損なわない)
        await _syncPlanToUserDoc();
        notifyListeners();
        return null; // success
      } catch (e) {
        debugPrint('applyCoupon error: $e');
        return t('coupon.errNetwork');
      }
    }
    // ここに来るのは Firestore に接続できなかった時だけ (上の try 内は必ず
    //   return する)。 = ユーザー要望: 「無効」ではなく「接続できなかった」と
    //   伝える (サーバー未接続 / env.json 未指定 / オフライン等)。
    return t('coupon.errNetwork');
  }

  // ─── 開発者モード: クーポン管理 ──────────────────────────────────────
  // Firestore の /coupons/{code} ドキュメント構造:
  //   { code, discountPercent, expiresAt (ISO), validMonthsAfterUse,
  //     maxUses, currentUses, createdAt, note }
  // クーポンコードは大文字英数 8 文字。重複しないようランダム生成。

  /// 8 文字のランダム英数字コード生成 (大文字 + 数字、紛らわしい O/0/I/1 除外)
  String _generateCouponCode() {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    final rand = math.Random.secure();
    return List.generate(8, (_) => chars[rand.nextInt(chars.length)]).join();
  }

  /// 開発者モード専用: 新規クーポンを生成して Firestore に保存
  /// 戻り値: 生成されたコード (成功時)
  /// 失敗時は Exception を throw してエラー詳細を呼び出し側に伝える。
  ///
  /// `plan`: クーポンが解放するプラン種別。
  ///   - SubscriptionPlan.pro  (既定): Pro プラン相当 (ページ無制限・同期なし)
  ///   - SubscriptionPlan.max          : Max プラン相当 (クラウド同期あり)
  /// それ以外の値は Pro として扱う。
  ///
  /// 失敗パターン:
  /// - 開発者モード未認証 → "開発者モードが有効になっていません"
  /// - Firebase 未初期化 → "Firebase に接続できていません"
  /// - HTTP エラー → "Firestore: HTTP {code} {body}" (権限不足など)
  Future<String?> createCoupon({
    required int discountPercent,
    DateTime? expiresAt,
    int validMonthsAfterUse = 0,
    int maxUses = 0, // 0 = 無制限
    String note = '',
    SubscriptionPlan plan = SubscriptionPlan.pro,
  }) async {
    if (!_developerMode) {
      throw Exception('開発者モードが有効になっていません');
    }
    // トークン期限切れの可能性があるので、明示的にリフレッシュ
    if (!_firebaseEnabled || _idToken == null) {
      try {
        await _initFirebase();
      } catch (e) {
        throw Exception('Firebase 初期化に失敗しました: $e');
      }
    }
    if (!_firebaseEnabled || _idToken == null) {
      throw Exception('Firebase に接続できていません (オフライン or 設定不足)');
    }
    try {
      await _ensureFreshToken();
    } catch (e) {
      debugPrint('createCoupon: token refresh failed: $e');
      // refresh 失敗してもダメ元で送ってみる
    }
    final code = _generateCouponCode();
    try {
      // plan 値の正規化: max のみ受け入れ、 それ以外は pro として保存
      final planStr = plan == SubscriptionPlan.max ? 'max' : 'pro';
      final fields = <String, dynamic>{
        'code': {'stringValue': code},
        'discountPercent': {'integerValue': discountPercent.toString()},
        'validMonthsAfterUse': {
          'integerValue': math.max(0, validMonthsAfterUse).toString()
        },
        'maxUses': {'integerValue': maxUses.toString()},
        'currentUses': {'integerValue': '0'},
        'createdAt': {
          'timestampValue': DateTime.now().toUtc().toIso8601String()
        },
        'note': {'stringValue': note},
        'plan': {'stringValue': planStr},
      };
      if (expiresAt != null) {
        fields['expiresAt'] = {
          'stringValue': expiresAt.toUtc().toIso8601String()
        };
      }
      final res = await http.patch(
        Uri.parse('$_firestoreBaseUrl/coupons/$code'),
        headers: {
          'Authorization': 'Bearer $_idToken',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({'fields': fields}),
      );
      if (res.statusCode >= 200 && res.statusCode < 300) {
        return code;
      }
      // HTTP エラーは body 込みでログ + 例外
      // 典型例:
      //   403 PERMISSION_DENIED  → Firestore セキュリティルールが書込拒否
      //   401 UNAUTHENTICATED    → IDトークン期限切れ (再起動でリフレッシュ)
      //   400 INVALID_ARGUMENT   → fields の型不一致
      debugPrint('createCoupon failed: ${res.statusCode} ${res.body}');
      String hint = '';
      if (res.statusCode == 403) {
        hint = ' (Firestore セキュリティルールで /coupons への書込が許可されていません)';
      } else if (res.statusCode == 401) {
        hint = ' (認証トークン期限切れ。アプリを再起動してください)';
      }
      throw Exception('Firestore: HTTP ${res.statusCode}$hint');
    } catch (e) {
      debugPrint('createCoupon error: $e');
      // 既に Exception ならそのまま rethrow、それ以外も Exception 化
      if (e is Exception) rethrow;
      throw Exception('createCoupon: $e');
    }
  }

  // ─── Dev プラン (= 決済を通さずに AI を呼べる枠) ────────────────────────
  //
  // なぜ Firestore のクーポンと別なのか:
  //   AI を実際に呼ぶのは代行サーバー (Worker) で、 支払いもそこで起きる。
  //   「この人は払わなくてよい」 を知っていないといけないのは Worker なので、
  //   コードの発行・引き換えも Worker に持たせる。 Firestore のクーポンに
  //   dev を足しても、 Worker が知らなければ残高不足で断られるだけになる。
  //
  // 発行できるのは誰か:
  //   Worker の ADMIN_UIDS に登録した uid だけ (サーバー側で照合)。
  //   アプリの開発者モード (パスワード) は画面の入口に過ぎないので、
  //   Dev プランの利用者がアプリを改造しても発行はできない (= ユーザー要望)。

  /// Dev コードを発行する (開発者モード + サーバー側 uid 照合)。
  /// [months] は引き換えた人が Dev でいられる月数 (0 = 無期限)。
  /// [maxUses] は何人まで引き換えられるか (0 = 無制限)。
  /// 戻り値: 生成されたコード。 失敗時は Exception。
  Future<String> createDevCode({
    int months = 0,
    int maxUses = 0,
    DateTime? expiresAt,
    String note = '',
  }) async {
    if (!_developerMode) {
      throw Exception('開発者モードが有効になっていません');
    }
    final base = relayApiBase;
    if (base.isEmpty) throw Exception(t('relay.notConfigured'));
    await _ensureFreshToken();
    if (_idToken == null) throw Exception(t('relay.needSignIn'));
    final res = await http
        .post(
          Uri.parse('$base/dev/issue'),
          headers: _relayHeaders(json: true),
          body: jsonEncode({
            'months': months,
            'maxUses': maxUses,
            'note': note,
            if (expiresAt != null)
              'expiresAt': expiresAt.toUtc().millisecondsSinceEpoch ~/ 1000,
          }),
        )
        .timeout(const Duration(seconds: 30));
    Map<String, dynamic> j;
    try {
      j = jsonDecode(res.body) as Map<String, dynamic>;
    } catch (_) {
      throw Exception('HTTP ${res.statusCode}');
    }
    if (res.statusCode == 403) {
      // ここが本当の防壁。 パスワードを知っていても uid が違えば発行できない。
      throw Exception(t('dev.notAdminUid'));
    }
    if (res.statusCode != 200) {
      throw Exception('${j['error'] ?? 'HTTP ${res.statusCode}'}');
    }
    final code = '${j['code'] ?? ''}';
    if (code.isEmpty) throw Exception('HTTP ${res.statusCode}');
    return code;
  }

  /// 発行済み Dev コードの一覧 (開発者モード + uid 照合)。
  Future<List<Map<String, dynamic>>> listDevCodes() async {
    if (!_developerMode) return const [];
    final base = relayApiBase;
    if (base.isEmpty) return const [];
    try {
      await _ensureFreshToken();
      final res = await http
          .get(Uri.parse('$base/dev/codes'), headers: _relayHeaders())
          .timeout(const Duration(seconds: 25));
      if (res.statusCode != 200) {
        debugPrint('listDevCodes failed: ${res.statusCode} ${res.body}');
        return const [];
      }
      final j = jsonDecode(res.body) as Map<String, dynamic>;
      final list = j['codes'];
      if (list is! List) return const [];
      return list
          .whereType<Map<String, dynamic>>()
          .map((e) => Map<String, dynamic>.from(e))
          .toList();
    } catch (e) {
      debugPrint('listDevCodes: $e');
      return const [];
    }
  }

  /// Dev コードを失効させる (開発者モード + uid 照合)。
  Future<bool> revokeDevCode(String code) async {
    if (!_developerMode) return false;
    final base = relayApiBase;
    if (base.isEmpty) return false;
    try {
      await _ensureFreshToken();
      final res = await http
          .post(
            Uri.parse('$base/dev/revoke'),
            headers: _relayHeaders(json: true),
            body: jsonEncode({'code': code.trim().toUpperCase()}),
          )
          .timeout(const Duration(seconds: 25));
      return res.statusCode == 200;
    } catch (e) {
      debugPrint('revokeDevCode: $e');
      return false;
    }
  }

  /// Dev コードを引き換える (誰でも呼べる。 正しいコードだけが通る)。
  /// 成功したら null、 失敗したら画面に出す文言を返す。
  /// 「コードが違う」 (= 404) の時だけ `_devCodeUnknown` を返し、
  /// 呼び出し側 (applyCoupon) が従来のクーポン処理へ進めるようにする。
  static const String _devCodeUnknown = '__dev_code_unknown__';

  Future<String?> redeemDevCode(String code) async {
    final base = relayApiBase;
    if (base.isEmpty) return _devCodeUnknown;
    try {
      await _ensureFreshToken();
      if (_idToken == null) return _devCodeUnknown;
      final res = await http
          .post(
            Uri.parse('$base/dev/redeem'),
            headers: _relayHeaders(json: true),
            body: jsonEncode({'code': code.trim().toUpperCase()}),
          )
          .timeout(const Duration(seconds: 30));
      if (res.statusCode == 404) return _devCodeUnknown; // 別種のコードかもしれない
      if (res.statusCode == 410) return t('coupon.errExpired');
      if (res.statusCode == 409) return t('coupon.errMaxUsed');
      if (res.statusCode != 200) return t('coupon.errNetwork');
      // サーバー側で権利が付いたので、 アプリ側の表示もその場で切り替える。
      await applyBillingPlan(SubscriptionPlan.dev);
      await _setServerGrantedPlan('dev');
      // 代行が使えるか確かめ直す (残高 0 でも Dev なら通るようになる)。
      unawaited(probeAiRelay(force: true));
      return null;
    } catch (e) {
      debugPrint('redeemDevCode: $e');
      return _devCodeUnknown;
    }
  }

  /// 開発者モード専用: 既存クーポン一覧を取得
  Future<List<Map<String, dynamic>>> listCoupons() async {
    if (!_developerMode || !_firebaseEnabled || _idToken == null) return [];
    try {
      // トークン更新を保険で実行 (期限切れだと 401 で空配列が返るのを防ぐ)
      await _ensureFreshToken();
      final res = await http.get(
        Uri.parse('$_firestoreBaseUrl/coupons?pageSize=100'),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      if (res.statusCode != 200) {
        debugPrint('listCoupons failed: ${res.statusCode} ${res.body}');
        return [];
      }
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final docs = data['documents'] as List<dynamic>? ?? [];
      final result = <Map<String, dynamic>>[];
      for (final d in docs) {
        final m = d as Map<String, dynamic>;
        final fields = m['fields'] as Map<String, dynamic>? ?? {};
        result.add({
          'code': _firestoreStr(fields['code']) ?? '',
          'discountPercent': int.tryParse(((fields['discountPercent']
                      as Map<String, dynamic>?)?['integerValue'] as String?) ??
                  '0') ??
              0,
          'validMonthsAfterUse': int.tryParse(((fields['validMonthsAfterUse']
                      as Map<String, dynamic>?)?['integerValue'] as String?) ??
                  '0') ??
              0,
          'maxUses': int.tryParse(((fields['maxUses']
                      as Map<String, dynamic>?)?['integerValue'] as String?) ??
                  '0') ??
              0,
          'currentUses': int.tryParse(((fields['currentUses']
                      as Map<String, dynamic>?)?['integerValue'] as String?) ??
                  '0') ??
              0,
          'expiresAt': _firestoreStr(fields['expiresAt']) ?? '',
          'note': _firestoreStr(fields['note']) ?? '',
          'plan': _firestoreStr(fields['plan']) == 'max' ? 'max' : 'pro',
        });
      }
      // 新しい順にソート (expires が空 = 無期限を一番下に)
      result.sort((a, b) {
        final aExp = a['expiresAt'] as String;
        final bExp = b['expiresAt'] as String;
        if (aExp.isEmpty && bExp.isEmpty) return 0;
        if (aExp.isEmpty) return 1;
        if (bExp.isEmpty) return -1;
        return bExp.compareTo(aExp);
      });
      return result;
    } catch (e) {
      debugPrint('listCoupons: $e');
      return [];
    }
  }

  /// 開発者モード専用: クーポンを削除
  Future<bool> deleteCoupon(String code) async {
    if (!_developerMode || !_firebaseEnabled || _idToken == null) return false;
    try {
      final res = await http.delete(
        Uri.parse('$_firestoreBaseUrl/coupons/$code'),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      return res.statusCode >= 200 && res.statusCode < 300;
    } catch (e) {
      debugPrint('deleteCoupon: $e');
      return false;
    }
  }

  /// 開発者モード専用: 既存クーポンの note (= 発券時に付ける任意の名前/メモ)
  /// を後から編集する。Firestore 上の note フィールドだけを書き換える。
  ///
  /// updateMask クエリパラメータで `note` のみ指定することで、他のフィールド
  /// (discountPercent / expiresAt / currentUses 等) を巻き戻さずに済む。
  /// ない場合 PATCH は「指定したフィールドだけ」更新するが、 Firestore REST
  /// の挙動は updateMask があると「マスクに無いフィールドを温存」、 無いと
  /// 「fields 全体で置換」 とドキュメント上は微妙なので、 安全側で常に
  /// updateMask を付ける。
  ///
  /// 戻り値: 成功なら true、失敗なら false。
  Future<bool> updateCouponNote(String code, String newNote) =>
      updateCoupon(code, note: newNote);

  /// 発券済みクーポンの中身を後から書き換える
  /// (= ユーザー要望: 名前だけでなく人数や期限も直せるように)。
  ///
  /// 渡した項目だけを更新する。 null の項目は触らない。
  /// `clearExpiry` を true にすると有効期限を「無期限」 に戻す。
  ///
  /// ※ 使用済み回数 (`currentUses`) はここでは変えない。 発券者が数字を
  ///   いじれてしまうと「何人が使ったか」 の記録として当てにならなくなる。
  Future<bool> updateCoupon(
    String code, {
    String? note,
    int? discountPercent,
    int? maxUses,
    int? validMonthsAfterUse,
    SubscriptionPlan? plan,
    DateTime? expiresAt,
    bool clearExpiry = false,
  }) async {
    if (!_developerMode || !_firebaseEnabled || _idToken == null) return false;
    try {
      await _ensureFreshToken();
      final fields = <String, dynamic>{};
      final masks = <String>[];
      void put(String key, Map<String, dynamic> value) {
        fields[key] = value;
        masks.add(key);
      }

      if (note != null) put('note', {'stringValue': note});
      if (discountPercent != null) {
        put('discountPercent',
            {'integerValue': discountPercent.clamp(0, 100).toString()});
      }
      if (maxUses != null) {
        put('maxUses', {'integerValue': math.max(0, maxUses).toString()});
      }
      if (validMonthsAfterUse != null) {
        put('validMonthsAfterUse', {
          'integerValue': validMonthsAfterUse.clamp(0, 120).toString(),
        });
      }
      if (plan != null) {
        put('plan',
            {'stringValue': plan == SubscriptionPlan.max ? 'max' : 'pro'});
      }
      // 期限は「消す」 と「入れ直す」 の両方があるので分けて扱う。
      if (clearExpiry) {
        put('expiresAt', {'nullValue': null});
      } else if (expiresAt != null) {
        put('expiresAt', {'stringValue': expiresAt.toUtc().toIso8601String()});
      }
      if (masks.isEmpty) return true; // 変更なし

      final query = masks.map((m) => 'updateMask.fieldPaths=$m').join('&');
      final res = await http.patch(
        Uri.parse('$_firestoreBaseUrl/coupons/$code?$query'),
        headers: {
          'Authorization': 'Bearer $_idToken',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({'fields': fields}),
      );
      if (res.statusCode >= 200 && res.statusCode < 300) return true;
      debugPrint('updateCoupon failed: ${res.statusCode} ${res.body}');
      return false;
    } catch (e) {
      debugPrint('updateCoupon: $e');
      return false;
    }
  }

  /// 現在のプラン状態を文字列で返す ('free' / 'pro' / 'max')。
  ///
  /// 開発者モード時は `_devImpersonatePlan` を反映する (FREE/PRO/MAX)。
  /// 「自分は Pro として振る舞っているのに、他のユーザーから DEV として
  /// 見える」というのを避けるため、演じプランをそのまま返す。
  /// 真の開発者権限の有無は `_developerMode` フラグそのもので判定する。
  ///
  /// クーポン適用中も実効プランを返す。`coupon` として保存してしまうと、
  /// Max 限定のクラウド同期メンバー判定から外れるため。
  String currentPlanLabel() {
    if (_developerMode)
      return _devImpersonatePlan.name; // 'free' / 'pro' / 'max'
    return currentPlan.name;
  }

  /// /users/{uid} の非課金メタデータを更新する。
  /// `plan` は Stripe / RevenueCat / ライセンス用 Cloud Functions だけが書く
  /// サーバー正本であり、クライアント値で上書きしない。
  Future<void> _syncPlanToUserDoc() async {
    if (!_firebaseEnabled || _idToken == null || _uid == null) return;
    try {
      await _ensureFreshToken();
      final url = '$_firestoreBaseUrl/users/$_uid';
      final fields = <String, dynamic>{
        'lastSeen': {'stringValue': DateTime.now().toUtc().toIso8601String()},
        'couponCode': {'stringValue': _appliedCouponCode ?? ''},
      };
      await http.patch(
        Uri.parse(
            '$url?updateMask.fieldPaths=lastSeen&updateMask.fieldPaths=couponCode'),
        headers: {
          'Authorization': 'Bearer $_idToken',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({'fields': fields}),
      );
      // 所属グループのメンバードキュメントにも最新の表示名・共有設定を反映する。
      for (final gid in _joinedGroupIds) {
        try {
          await _registerMember(gid);
        } catch (_) {}
      }
    } catch (e) {
      debugPrint('_syncPlanToUserDoc error: $e');
    }
  }

  // ─── 開発者モード: ユーザー一覧 (プラン別) ─────────────────────────────
  String _firestoreAnyString(dynamic val) {
    final s = _firestoreStr(val);
    if (s != null) return s;
    if (val is Map) {
      final timestamp = val['timestampValue'];
      if (timestamp != null) return timestamp.toString();
      final integer = val['integerValue'];
      if (integer != null) return integer.toString();
      final doubleValue = val['doubleValue'];
      if (doubleValue != null) return doubleValue.toString();
      final boolValue = val['booleanValue'];
      if (boolValue != null) return boolValue.toString();
    }
    return '';
  }

  Map<String, dynamic> _userLicenseMapFromDoc(Map<String, dynamic> doc) {
    final fields = doc['fields'] as Map<String, dynamic>? ?? {};
    final docName = (doc['name'] as String?) ?? '';
    final uid =
        docName.contains('/users/') ? docName.split('/users/').last : '';
    final plan = _firestoreAnyString(fields['plan']);
    return {
      'uid': uid,
      'displayName': _firestoreAnyString(fields['displayName']),
      'plan': plan.isEmpty ? 'free' : plan,
      'lastSeen': _firestoreAnyString(fields['lastSeen']),
      'couponCode': _firestoreAnyString(fields['couponCode']),
      'subscriptionStatus': _firestoreAnyString(fields['subscriptionStatus']),
      'planExpiresAt': _firestoreAnyString(fields['planExpiresAt']),
      'planSource': _firestoreAnyString(fields['planSource']),
      'planUpdatedAt': _firestoreAnyString(fields['planUpdatedAt']),
      'stripeCustomerId': _firestoreAnyString(fields['stripeCustomerId']),
      'stripeSubscriptionId':
          _firestoreAnyString(fields['stripeSubscriptionId']),
      'rcStore': _firestoreAnyString(fields['rcStore']),
      'rcAppUserId': _firestoreAnyString(fields['rcAppUserId']),
      // ── 分析用の属性 (= ユーザー要望: 年齢 / 性別 / 国) ──
      'ageYears': _firestoreAnyString(fields['ageYears']),
      'birthYear': _firestoreAnyString(fields['birthYear']),
      'gender': _firestoreAnyString(fields['gender']),
      'country': _firestoreAnyString(fields['country']),
      'locale': _firestoreAnyString(fields['locale']),
      'profileSource': _firestoreAnyString(fields['profileSource']),
    };
  }

  /// /users/{uid} を取得し、ライセンス関連フィールドを返す。
  /// 見つからない場合は null。
  Future<Map<String, dynamic>?> fetchUserLicenseByUid(String uid) async {
    final trimmed = uid.trim();
    if (!_developerMode ||
        !_firebaseEnabled ||
        _idToken == null ||
        trimmed.isEmpty) {
      return null;
    }
    try {
      await _ensureFreshToken();
      final res = await http.get(
        Uri.parse('$_firestoreBaseUrl/users/$trimmed'),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      if (res.statusCode == 404) return null;
      if (res.statusCode != 200) {
        debugPrint(
            'fetchUserLicenseByUid failed: ${res.statusCode} ${res.body}');
        return null;
      }
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      return _userLicenseMapFromDoc(data);
    } catch (e) {
      debugPrint('fetchUserLicenseByUid error: $e');
      return null;
    }
  }

  /// /users コレクションを最大 1000 件まで取得し、
  /// uid / displayName / plan / lastSeen / couponCode 等のリストを返す。
  Future<List<Map<String, dynamic>>> listAllUsers() async {
    if (!_developerMode || !_firebaseEnabled || _idToken == null) return [];
    try {
      await _ensureFreshToken();
      final result = <Map<String, dynamic>>[];
      String? pageToken;
      for (int page = 0; page < 10; page++) {
        final urlBuf = StringBuffer('$_firestoreBaseUrl/users?pageSize=100');
        if (pageToken != null) {
          urlBuf.write('&pageToken=$pageToken');
        }
        final res = await http.get(
          Uri.parse(urlBuf.toString()),
          headers: {'Authorization': 'Bearer $_idToken'},
        );
        if (res.statusCode != 200) break;
        final data = jsonDecode(res.body) as Map<String, dynamic>;
        final docs = data['documents'] as List<dynamic>? ?? [];
        for (final d in docs) {
          final m = d as Map<String, dynamic>;
          result.add(_userLicenseMapFromDoc(m));
        }
        pageToken = data['nextPageToken'] as String?;
        if (pageToken == null || pageToken.isEmpty) break;
      }
      // lastSeen で新しい順にソート
      result.sort((a, b) {
        final aL = a['lastSeen'] as String;
        final bL = b['lastSeen'] as String;
        if (aL.isEmpty && bL.isEmpty) return 0;
        if (aL.isEmpty) return 1;
        if (bL.isEmpty) return -1;
        return bL.compareTo(aL);
      });
      return result;
    } catch (e) {
      debugPrint('listAllUsers error: $e');
      return [];
    }
  }

  /// 開発者モードを有効化（永続化）。
  ///
  /// パスワードはアプリ内に持たず、Cloud Functions 側の Secret Manager で
  /// 照合する。成功時だけローカル状態を有効化する。
  /// 戻り値: null = 成功。 それ以外 = 表示用エラーメッセージ (t() 済み)。
  /// = ユーザー要望: 失敗時に「パスワード違い」か「サーバーに接続できない」かを
  ///   区別して表示する (サーバー照合方式は維持)。
  Future<String?> activateDeveloperMode(String password) async {
    // 直前の解除リクエストがサーバー上で完了してから再認証する。
    // 新しい custom claim が古い revoke に後から消される競合を防ぐ。
    try {
      await _developerModeRevocation;
    } catch (_) {}
    if (_disposed) return t('dev.errConnection');
    final requestGeneration = _developerModeStateGeneration;
    final err = await _verifyDeveloperPasswordOnServer(password);
    if (_disposed || requestGeneration != _developerModeStateGeneration) {
      return t('dev.errConnection');
    }
    if (err == null) {
      final generation = ++_developerModeStateGeneration;
      _developerModeRestoreTimer?.cancel();
      _developerModeRestoreTimer = null;
      _developerModeRestoreAttempt = 0;
      _developerMode = true;
      notifyListeners();
      // Dev モードなら決済なしで代行を使えるよう、 Dev 権利を自動で
      // 自己発行する (= ユーザー要望。 管理者 uid のみ通る)。
      unawaited(maybeDevSelfGrantAiAccess());
      try {
        final prefs = await _prefsWithRetry();
        if (!_disposed && generation == _developerModeStateGeneration) {
          await prefs.setBool('developer_mode', true);
        }
      } catch (e) {
        debugPrint('開発者モード保存に失敗 (認証状態は維持): $e');
      }
      if (_disposed || generation != _developerModeStateGeneration) {
        return null;
      }
      try {
        await _loadDeveloperSettings();
        if (!_disposed && generation == _developerModeStateGeneration) {
          notifyListeners();
        }
      } catch (e) {
        debugPrint('開発者設定の読み込みに失敗 (モードは維持): $e');
      }
      // users.plan はサーバー正本のため変更せず、非課金メタデータだけ同期する。
      if (!_disposed && generation == _developerModeStateGeneration) {
        _syncPlanToUserDoc();
      }
      return null;
    }
    return err;
  }

  Future<void> deactivateDeveloperMode() async {
    final generation = ++_developerModeStateGeneration;
    _developerModeRestoreTimer?.cancel();
    _developerModeRestoreTimer = null;
    _developerModeRestoreAttempt = 0;
    _developerMode = false;
    notifyListeners();
    final previousRevocation = _developerModeRevocation;
    final operation = () async {
      try {
        await previousRevocation;
      } catch (_) {}
      // 自己発行した Dev 枠を先に返上する (= ユーザー要望: 開発者モードから
      // 出たら元のプランが出るように)。 claim を落とす前に呼ぶ。
      try {
        await releaseDevSelfGrant();
      } catch (e) {
        debugPrint('Dev 枠の返上に失敗: $e');
      }
      try {
        final prefs = await _prefsWithRetry();
        if (!_disposed &&
            generation == _developerModeStateGeneration &&
            !_developerMode) {
          await prefs.setBool('developer_mode', false);
        }
      } catch (e) {
        debugPrint('開発者モード解除状態の保存に失敗: $e');
      }
      // サーバー側の custom claim も解除する。新しい認証は
      // `_developerModeRevocation` を await するため、新旧の書き込み順は入れ替わない。
      await _revokeDeveloperModeOnServer();
      if (!_disposed &&
          generation == _developerModeStateGeneration &&
          !_developerMode) {
        await _syncPlanToUserDoc();
      }
    }();
    _developerModeRevocation = operation;
    await operation;
  }

  Future<void> _loadDeveloperModeState() async {
    if (_developerModeRestoreInFlight || _disposed) return;
    _developerModeRestoreInFlight = true;
    final generation = _developerModeStateGeneration;
    try {
      final prefs = await _prefsWithRetry();
      if (_disposed || generation != _developerModeStateGeneration) return;
      final locallyEnabled = prefs.getBool('developer_mode') ?? false;
      if (!locallyEnabled) {
        _developerModeRestoreTimer?.cancel();
        _developerModeRestoreTimer = null;
        _developerModeRestoreAttempt = 0;
        _developerMode = false;
        // 開発者モードでは無いのに Dev 枠が残っている = 以前のログアウトで
        // 返上できていなかった分。 ここで戻さないと、 一度入り直して出る
        // まで Dev 表示のままになる (= ユーザー報告の状態そのもの)。
        unawaited(_releaseDevSelfGrantWhenSignedIn());
        return;
      }

      // このフラグは以前のサーバー検証成功時だけ保存される。更新直後の認証初期化や
      // 一時的なオフラインで開発者モード / 演じるプランから離脱して見えないよう、
      // まず保存済みセッションを復元し、サーバー検証はバックグラウンドで行う。
      // サーバーから明示的な false が返った場合だけ即座に解除・保存値削除する。
      if (!_developerMode) {
        _developerMode = true;
        notifyListeners();
      }
      try {
        await _loadDeveloperSettings();
        if (!_disposed && generation == _developerModeStateGeneration) {
          notifyListeners();
        }
      } catch (e) {
        debugPrint('開発者設定のローカル復元に失敗 (モードは維持): $e');
      }
      final serverEnabled = await _fetchDeveloperModeStatusFromServer();
      // 待機中に手動解除や再認証が行われた場合、古い応答で新しい状態を
      // 上書きしない。保存状態を扱う非同期処理の世代を明示的に分離する。
      if (_disposed || generation != _developerModeStateGeneration) return;
      if (serverEnabled == true) {
        _developerModeRestoreTimer?.cancel();
        _developerModeRestoreTimer = null;
        _developerModeRestoreAttempt = 0;
        _developerMode = true;
        // Dev モードなら決済なしで代行を使えるよう、 Dev 権利を自動で
        // 自己発行する (= ユーザー要望。 管理者 uid のみ通る)。
        unawaited(maybeDevSelfGrantAiAccess());
        notifyListeners();
        try {
          await _loadDeveloperSettings();
          if (!_disposed && generation == _developerModeStateGeneration) {
            notifyListeners();
          }
        } catch (e) {
          debugPrint('開発者設定の再読込に失敗 (モードは維持): $e');
        }
      } else if (serverEnabled == false) {
        _developerMode = false;
        _developerModeRestoreTimer?.cancel();
        _developerModeRestoreTimer = null;
        _developerModeRestoreAttempt = 0;
        // サーバー側で開発者でなくなった場合も、 自己発行した Dev 枠を
        // 抱えたままにしない (手動ログアウトと同じ扱い)。
        unawaited(releaseDevSelfGrant());
        // UI上の失効はディスク書き込みを待たず即時反映する。保存失敗で
        // 開発者モードを再度有効化してはいけない。
        notifyListeners();
        try {
          await prefs.setBool('developer_mode', false);
        } catch (e) {
          debugPrint('開発者モード失効状態の保存に失敗: $e');
        }
      } else {
        // 通信失敗では復元済み状態を維持し、同じ起動中に有限回だけ再検証する。
        _scheduleDeveloperModeRestore();
      }
    } catch (e) {
      debugPrint('開発者モードの保存状態読み込みに失敗: $e');
      if (generation == _developerModeStateGeneration) {
        _scheduleDeveloperModeRestore();
      }
    } finally {
      _developerModeRestoreInFlight = false;
    }
  }

  void _scheduleDeveloperModeRestore() {
    if (_disposed || _developerModeRestoreTimer != null) return;
    // 回線切替や更新直後のプラグイン/認証初期化の遅れを吸収する。
    // 永久に通信し続けないよう最大 6 回で打ち切る。
    const delays = <Duration>[
      Duration(seconds: 2),
      Duration(seconds: 5),
      Duration(seconds: 10),
      Duration(seconds: 20),
      Duration(seconds: 30),
      Duration(seconds: 30),
    ];
    if (_developerModeRestoreAttempt >= delays.length) return;
    final delay = delays[_developerModeRestoreAttempt++];
    _developerModeRestoreTimer = Timer(delay, () {
      _developerModeRestoreTimer = null;
      if (_disposed) return;
      unawaited(_loadDeveloperModeState());
    });
  }

  Future<void> setConnectionElbowSplitRatio(double v) async {
    _connectionElbowSplitRatio = v.clamp(0.1, 0.9).toDouble();
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setDouble(
          'connectionElbowSplitRatio', _connectionElbowSplitRatio);
    } catch (_) {}
    notifyListeners();
  }

  Future<void> setConnectionElbowPointCount(int v) async {
    _connectionElbowPointCount = v.clamp(1, 8).toInt();
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setInt(
          'connectionElbowPointCount', _connectionElbowPointCount);
    } catch (_) {}
    notifyListeners();
  }

  Future<void> saveConnectionDefaultsFrom(NodeConnection conn) async {
    _connectionLineStyle = conn.lineStyle ?? 'curve';
    _connectionElbowSplitRatio =
        conn.elbowSplitRatio.clamp(0.1, 0.9).toDouble();
    _connectionElbowPointCount = conn.elbowPointCount.clamp(1, 8).toInt();
    _connectionStrokeWidth = conn.strokeWidth.clamp(1.0, 8.0).toDouble();
    _connectionShowArrow = conn.showArrow;
    _connectionArrowHeadScale = conn.arrowHeadScale.clamp(0.5, 3.0).toDouble();
    _connectionBidirectional = conn.bidirectional;
    _connectionLineColorValue = conn.lineColorValue;
    _connectionRelationshipType = conn.relationshipType;
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setString('connectionLineStyle', _connectionLineStyle);
      await prefs.setDouble(
          'connectionElbowSplitRatio', _connectionElbowSplitRatio);
      await prefs.setInt(
          'connectionElbowPointCount', _connectionElbowPointCount);
      await prefs.setDouble('connectionStrokeWidth', _connectionStrokeWidth);
      await prefs.setBool('connectionShowArrow', _connectionShowArrow);
      await prefs.setDouble(
          'connectionArrowHeadScale', _connectionArrowHeadScale);
      await prefs.setBool('connectionBidirectional', _connectionBidirectional);
      if (_connectionLineColorValue == null) {
        await prefs.remove('connectionLineColorValue');
      } else {
        await prefs.setInt(
            'connectionLineColorValue', _connectionLineColorValue!);
      }
      await prefs.setString(
          'connectionRelationshipType', _connectionRelationshipType);
    } catch (_) {}
    notifyListeners();
  }

  NodeConnection _newConnection({
    required String fromId,
    required AnchorDirection fromAnchor,
    required String toId,
    required AnchorDirection toAnchor,
    double? strokeWidth,
    bool? showArrow,
    double? arrowHeadScale,
    bool? bidirectional,
    String? label,
  }) =>
      NodeConnection(
        fromId: fromId,
        fromAnchor: fromAnchor,
        toId: toId,
        toAnchor: toAnchor,
        strokeWidth: strokeWidth ?? _connectionStrokeWidth,
        showArrow: showArrow ?? _connectionShowArrow,
        arrowHeadScale: arrowHeadScale ?? _connectionArrowHeadScale,
        bidirectional: bidirectional ?? _connectionBidirectional,
        label: label,
        lineColorValue: _connectionLineColorValue,
        relationshipType: _connectionRelationshipType,
        lineStyle: _connectionLineStyle,
        elbowSplitRatio: _connectionElbowSplitRatio,
        elbowPointCount: _connectionElbowPointCount,
        // 今いる作業レイヤーに置く (= ユーザー要望: レイヤーはノードや
        // リンクにも適用される)。
        layer: activeLayer,
      );

  /// 開発者パスワードをサーバーで照合する。
  /// 戻り値: null = 成功。 それ以外 = 表示用エラーメッセージ (t() 済み)。
  Future<String?> _verifyDeveloperPasswordOnServer(String password) async {
    final trimmed = password.trim();
    if (trimmed.isEmpty) return t('dev.wrongPassword');
    // Firebase 未接続 / 設定不足はパスワード以前の問題なので接続エラーとして扱う。
    if (!await _ensureDeveloperAuthReady()) return t('dev.errConnection');
    final verifiedUid = _uid;

    try {
      final res = await http
          .post(
            Uri.parse('$_functionsBaseUrl/verifyDeveloperPassword'),
            headers: {
              'Authorization': 'Bearer $_idToken',
              'Content-Type': 'application/json',
            },
            body: jsonEncode({'password': trimmed}),
          )
          .timeout(const Duration(seconds: 30));
      if (res.statusCode == 200) {
        final data = jsonDecode(res.body) as Map<String, dynamic>;
        if (data['ok'] == true && data['developer'] == true) {
          // custom claim が入った新しい ID token を取り直しておく。
          await _ensureFreshToken(force: true);
          // refresh token 失効時に別の匿名 UID が作られた場合、
          // 元 UID へ付与した claim は引き継がれない。その状態を
          // 認証成功としてローカル保存しない。
          if (verifiedUid == null || _uid != verifiedUid) {
            return t('dev.errConnection');
          }
          final enabled =
              await _fetchDeveloperModeStatusFromServer(forceRefresh: false);
          return enabled == true ? null : t('dev.errConnection');
        }
        return t('dev.wrongPassword');
      }
      // サーバーが返したエラーコードで「パスワード違い」と「接続/認証エラー」を
      //   切り分ける (= ユーザー要望)。 invalid-password=誤り、
      //   too-many-attempts=ロック、 それ以外 (unauthenticated/internal 等) は接続側。
      String? errCode;
      try {
        errCode =
            (jsonDecode(res.body) as Map<String, dynamic>)['error']?.toString();
      } catch (_) {}
      debugPrint(
          'verifyDeveloperPassword failed: ${res.statusCode} $errCode ${res.body}');
      if (res.statusCode == 401 && errCode == 'invalid-password') {
        return t('dev.wrongPassword');
      }
      if (res.statusCode == 429 || errCode == 'too-many-attempts') {
        return t('dev.errLocked');
      }
      return t('dev.errConnection');
    } catch (e) {
      debugPrint('verifyDeveloperPassword error: $e');
      return t('dev.errConnection');
    }
  }

  Future<bool?> _fetchDeveloperModeStatusFromServer(
      {bool forceRefresh = true}) async {
    if (!await _ensureDeveloperAuthReady()) return null;
    try {
      // custom claim 反映済みの状態を見るため、起動時は保険で更新してから確認。
      if (forceRefresh) await _ensureFreshToken(force: true);
      final res = await http
          .post(
            Uri.parse('$_functionsBaseUrl/developerModeStatus'),
            headers: {
              'Authorization': 'Bearer $_idToken',
              'Content-Type': 'application/json',
            },
            body: '{}',
          )
          .timeout(const Duration(seconds: 20));
      if (res.statusCode == 200) {
        final data = jsonDecode(res.body) as Map<String, dynamic>;
        final developer = data['developer'];
        if (data['ok'] == true && developer is bool) return developer;
        debugPrint('developerModeStatus malformed response: ${res.body}');
        return null;
      }
      debugPrint('developerModeStatus failed: ${res.statusCode} ${res.body}');
    } catch (e) {
      debugPrint('developerModeStatus error: $e');
    }
    return null;
  }

  Future<void> _revokeDeveloperModeOnServer() async {
    if (!await _ensureDeveloperAuthReady()) return;
    try {
      await http
          .post(
            Uri.parse('$_functionsBaseUrl/revokeDeveloperMode'),
            headers: {
              'Authorization': 'Bearer $_idToken',
              'Content-Type': 'application/json',
            },
            body: '{}',
          )
          .timeout(const Duration(seconds: 20));
      await _ensureFreshToken(force: true);
    } catch (e) {
      debugPrint('revokeDeveloperMode error: $e');
    }
  }

  Future<bool> _ensureDeveloperAuthReady() async {
    if (_firestoreProjectId.isEmpty || _authApiKey.isEmpty) {
      debugPrint('Developer auth skipped: Firebase settings are missing');
      return false;
    }
    if (!_firebaseEnabled || _idToken == null) {
      await _initFirebase();
    }
    if (!_firebaseEnabled || _idToken == null) return false;
    await _ensureFreshToken();
    return _idToken != null;
  }

  Future<void> _loadDeveloperSettings() async {
    final prefs = await _prefsWithRetry();
    _globalGeminiApiKey = prefs.getString('global_gemini_api_key') ?? '';
    _inquiryEmail = prefs.getString('inquiry_email') ?? '';
  }

  Future<void> setGlobalGeminiApiKey(String key) async {
    if (!_developerMode || _disposed) return;
    _globalGeminiApiKey = key.trim();
    final prefs = await _prefsWithRetry();
    await prefs.setString('global_gemini_api_key', _globalGeminiApiKey!);
    // Firestoreにも保存（グローバル設定）
    if (_firebaseEnabled && _idToken != null) {
      try {
        final url = '$_firestoreBaseUrl/admin/settings';
        await http.patch(
          Uri.parse('$url?updateMask.fieldPaths=globalGeminiApiKey'),
          headers: {
            'Authorization': 'Bearer $_idToken',
            'Content-Type': 'application/json',
          },
          body: jsonEncode({
            'fields': {
              'globalGeminiApiKey': {'stringValue': _globalGeminiApiKey!},
            },
          }),
        );
      } catch (e) {
        debugPrint('グローバルAPIキー保存エラー: $e');
      }
    }
    notifyListeners();
  }

  Future<void> setInquiryEmail(String email) async {
    if (!_developerMode || _disposed) return;
    _inquiryEmail = email.trim();
    final prefs = await _prefsWithRetry();
    await prefs.setString('inquiry_email', _inquiryEmail);
    // Firestoreにも保存
    if (_firebaseEnabled && _idToken != null) {
      try {
        final url = '$_firestoreBaseUrl/admin/settings';
        await http.patch(
          Uri.parse('$url?updateMask.fieldPaths=inquiryEmail'),
          headers: {
            'Authorization': 'Bearer $_idToken',
            'Content-Type': 'application/json',
          },
          body: jsonEncode({
            'fields': {
              'inquiryEmail': {'stringValue': _inquiryEmail},
            },
          }),
        );
      } catch (e) {
        debugPrint('問い合わせメール保存エラー: $e');
      }
    }
    notifyListeners();
  }

  /// 問い合わせ先メールを全ユーザー向けにFirestoreから取得
  Future<void> loadInquiryEmailFromCloud() async {
    final prefs = await _prefsWithRetry();
    // まずローカルキャッシュをロード
    _inquiryEmail = prefs.getString('inquiry_email') ?? '';
    if (!_firebaseEnabled || _idToken == null) return;
    try {
      final url = '$_firestoreBaseUrl/admin/settings';
      final res = await http.get(
        Uri.parse(url),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      if (res.statusCode == 200) {
        final data = jsonDecode(res.body) as Map<String, dynamic>;
        final fields = data['fields'] as Map<String, dynamic>?;
        if (fields != null) {
          final email = _firestoreStr(fields['inquiryEmail']);
          if (email != null && email.isNotEmpty) {
            _inquiryEmail = email;
            await prefs.setString('inquiry_email', _inquiryEmail);
          }
          // ── グローバル(開発者)キーの自動適用は廃止 (= BYOK / ユーザー要望) ──
          // 以前は admin/settings の globalGeminiApiKey を取得して、 ユーザーが
          // 未設定なら自動で AI キーに使っていたが、 開発者キーを配布しない方針に
          // 変更したため取り込まない。 AI キーは利用者が自分で入力したものだけを使う。
        }
        notifyListeners();
      }
    } catch (e) {
      debugPrint('クラウド設定取得エラー: $e');
    }
  }

  bool get _developerAllGroupDataViewEnabled => false;

  /// 開発者モード：全グループの一覧を取得
  Future<List<Map<String, dynamic>>> fetchAllGroups() async {
    if (!_developerAllGroupDataViewEnabled) {
      debugPrint('fetchAllGroups disabled: all-group data view removed');
      return [];
    }
    if (!_developerMode || !_firebaseEnabled || _idToken == null) return [];
    try {
      final url = '$_firestoreBaseUrl/groups';
      final res = await http.get(
        Uri.parse(url),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      if (res.statusCode != 200) return [];
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final docs = data['documents'] as List<dynamic>? ?? [];
      final result = <Map<String, dynamic>>[];
      for (final doc in docs) {
        final name = doc['name'] as String?;
        final updateTime = doc['updateTime'] as String?;
        final createTime = doc['createTime'] as String?;
        if (name != null) {
          final groupId = name.split('/').last;
          result.add({
            'groupId': groupId,
            'updateTime': updateTime,
            'createTime': createTime,
          });
        }
      }
      return result;
    } catch (e) {
      debugPrint('全グループ取得エラー: $e');
      return [];
    }
  }

  /// 開発者モード：指定グループの全ページを取得
  Future<List<Map<String, dynamic>>> fetchGroupPages(String groupId) async {
    if (!_developerAllGroupDataViewEnabled) {
      debugPrint('fetchGroupPages disabled: all-group data view removed');
      return [];
    }
    if (!_developerMode || !_firebaseEnabled || _idToken == null) return [];
    try {
      final url = '$_firestoreBaseUrl/groups/$groupId/pages';
      final res = await http.get(
        Uri.parse(url),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      if (res.statusCode != 200) return [];
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final docs = data['documents'] as List<dynamic>? ?? [];
      final result = <Map<String, dynamic>>[];
      for (final doc in docs) {
        try {
          final fields = doc['fields'] as Map<String, dynamic>;
          final jsonStr = _firestoreStr(fields['json']);
          final updateTime = doc['updateTime'] as String?;
          if (jsonStr == null) continue;
          final pageData = jsonDecode(jsonStr) as Map<String, dynamic>;
          result.add({
            'pageId': pageData['id'],
            'pageName': pageData['name'],
            'nodeCount': (pageData['nodes'] as List?)?.length ?? 0,
            'updateTime': updateTime,
            'groupId': groupId,
          });
        } catch (_) {}
      }
      return result;
    } catch (e) {
      debugPrint('グループページ取得エラー: $e');
      return [];
    }
  }

  /// 開発者モード：指定グループ・ページを削除
  Future<bool> adminDeletePage(String groupId, String pageId) async {
    if (!_developerMode || !_firebaseEnabled || _idToken == null) return false;
    try {
      final url = '$_firestoreBaseUrl/groups/$groupId/pages/$pageId';
      final res = await http.delete(
        Uri.parse(url),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      return res.statusCode == 200 || res.statusCode == 204;
    } catch (e) {
      debugPrint('管理者削除エラー: $e');
      return false;
    }
  }

  // ── 問い合わせ機能 ────────────────────────────────────────────────────────

  /// ユーザーが問い合わせを送信する
  /// Firestore REST API: inquiries コレクションに問い合わせを保存
  /// ルール allow write: if true なので認証トークン不要
  ///
  /// レート制限: 1 ユーザー (この端末) につき **3 時間で 10 件**まで。
  ///
  /// = ユーザー要望「1 日ではなく 3 時間ごとにリセット」。 1 日単位だと、
  ///   朝に使い切った人は翌日まで報告できず、 報告してほしい不具合ほど
  ///   埋もれてしまう。 直近 3 時間だけを数える形にすれば、 連投は抑えつつ
  ///   待ち時間は最長 3 時間で済む。
  static const int kInquiryDailyLimit = 10;

  /// 数える幅 (この時間ぶんだけ遡って数える)。
  static const Duration kInquiryWindow = Duration(hours: 3);

  /// 直近 3 時間に送信した問い合わせ数を返す。
  /// 幅から外れたタイムスタンプは自動的に捨てる。
  Future<int> _purgeAndCountInquirySendLog() async {
    final prefs = await _prefsWithRetry();
    final raw = prefs.getString('inquiry_send_log') ?? '[]';
    List<dynamic> arr;
    try {
      arr = jsonDecode(raw) as List<dynamic>;
    } catch (_) {
      arr = [];
    }
    final from = DateTime.now().subtract(kInquiryWindow);
    final kept = <String>[];
    for (final ts in arr) {
      if (ts is! String) continue;
      final d = DateTime.tryParse(ts);
      if (d == null) continue;
      // 未来の日付 (時計を戻した等) は数に入れつつ残す。
      if (d.isAfter(from)) kept.add(ts);
    }
    if (kept.length != arr.length) {
      await prefs.setString('inquiry_send_log', jsonEncode(kept));
    }
    return kept.length;
  }

  /// 次に 1 件空くまでの時間 (残りが 0 の時に案内する)。
  /// 分からなければ null。
  Future<Duration?> inquiryNextSlotIn() async {
    try {
      final prefs = await _prefsWithRetry();
      final raw = prefs.getString('inquiry_send_log') ?? '[]';
      final arr = (jsonDecode(raw) as List<dynamic>)
          .whereType<String>()
          .map(DateTime.tryParse)
          .whereType<DateTime>()
          .toList()
        ..sort();
      if (arr.isEmpty) return null;
      final free = arr.first.add(kInquiryWindow).difference(DateTime.now());
      return free.isNegative ? Duration.zero : free;
    } catch (_) {
      return null;
    }
  }

  /// 直近 3 時間の残り送信可能回数。
  /// UI で残量表示に使う。
  /// Dev 枠では無制限 (-1) を返し、UI 側でそれを「∞」として扱う。
  /// ★ 開発者モードでプランを装っている時は、 そのプランの上限に従う
  ///   (= ユーザー報告: Free を選んでいるのに無制限と出る)。
  Future<int> remainingInquirySendCount() async {
    if (_quotaUnlimited) return -1; // -1 = 無制限
    // 迷惑行為として止められている人は 0 件 (送れない)。
    if (await isInquiryBlocked()) return 0;
    final used = await _purgeAndCountInquirySendLog();
    final remaining = kInquiryDailyLimit - used;
    return remaining < 0 ? 0 : remaining;
  }

  // ── 迷惑な送信者を個別に止める (= ユーザー要望: 開発者がスパムと判断した
  //    人には送らせない) ──
  //
  // 止める判断はサーバー (Worker の /inquiry/block) に置く。 端末の設定に
  // 置くと消して回避されるため。
  // ★ Firestore ではなく Worker にしたのは、 Firestore は inquiries しか
  //   書き込みを開けておらず、 他は規則で閉じている (実測で 403)。 規則を
  //   開けると「止められた本人が印を消す」 ことができてしまう。 Worker なら
  //   ADMIN_UIDS の本人だけが書けるので消されない。

  /// 直近に確かめた「止められているか」。 null = 未確認。
  bool? _inquiryBlocked;
  bool get inquiryBlockedCached => _inquiryBlocked ?? false;

  /// 止められた理由 (開発者が書いたもの)。
  String _inquiryBlockReason = '';
  String get inquiryBlockReason => _inquiryBlockReason;

  /// 自分が止められていないか確かめる。
  Future<bool> isInquiryBlocked({bool force = false}) async {
    if (!force && _inquiryBlocked != null) return _inquiryBlocked!;
    final base = relayApiBase;
    if (base.isEmpty) return _inquiryBlocked ?? false;
    try {
      await _ensureFreshToken();
      if (_idToken == null) return _inquiryBlocked ?? false;
      final res = await http
          .get(Uri.parse('$base/inquiry/blocked'), headers: _relayHeaders())
          .timeout(const Duration(seconds: 15));
      if (res.statusCode == 200) {
        final j = jsonDecode(res.body);
        if (j is Map) {
          _inquiryBlocked = j['blocked'] == true;
          _inquiryBlockReason = '${j['reason'] ?? ''}';
        }
      }
    } catch (e) {
      // 確かめられない時は止めない (通信不良で送れなくなるのを避ける)。
      debugPrint('送信停止の確認に失敗 (そのまま送れる扱い): $e');
    }
    return _inquiryBlocked ?? false;
  }

  /// 開発者が、 ある人の問い合わせ送信を止める / 戻す。
  /// [uid] は受信箱に出ている送信者の uid。
  /// 実際に通るのは Worker の ADMIN_UIDS に載っている本人だけ。
  Future<bool> setInquiryBlocked(String uid, bool blocked,
      {String reason = ''}) async {
    final base = relayApiBase;
    if (base.isEmpty || uid.trim().isEmpty) return false;
    try {
      await _ensureFreshToken();
      if (_idToken == null) return false;
      final res = await http
          .post(Uri.parse('$base/inquiry/block'),
              headers: _relayHeaders(json: true),
              body: jsonEncode({
                'uid': uid.trim(),
                'blocked': blocked,
                'reason': reason,
              }))
          .timeout(const Duration(seconds: 20));
      return res.statusCode == 200;
    } catch (e) {
      debugPrint('送信停止の切り替えに失敗: $e');
      return false;
    }
  }

  /// その人が今止められているか (受信箱の表示用)。
  Future<bool> isUidInquiryBlocked(String uid) async {
    final base = relayApiBase;
    if (base.isEmpty || uid.trim().isEmpty) return false;
    try {
      await _ensureFreshToken();
      if (_idToken == null) return false;
      final res = await http
          .get(
              Uri.parse('$base/inquiry/blocked'
                  '?uid=${Uri.encodeComponent(uid.trim())}'),
              headers: _relayHeaders())
          .timeout(const Duration(seconds: 15));
      if (res.statusCode != 200) return false;
      final j = jsonDecode(res.body);
      return (j is Map) && j['blocked'] == true;
    } catch (_) {
      return false;
    }
  }

  Future<String?> sendInquiry(String message) async {
    if (message.trim().isEmpty) return null;
    // ── ユーザー名 (displayName) 必須チェック ──
    // 問い合わせは送信者を識別する必要があるため、displayName 未設定では
    // 送信不可。UI 側でこの例外をキャッチしてユーザー名設定ダイアログを
    // 開くフローに繋げる。
    if ((_displayName ?? '').trim().isEmpty) {
      throw const _DisplayNameRequiredException();
    }

    // ── レート制限チェック (開発者モードは免除) ──
    if (!_developerMode) {
      // 迷惑行為として止められている人は送れない (= ユーザー要望)。
      //   判断はサーバー側にあるので、 送る直前に必ず確かめ直す。
      if (await isInquiryBlocked(force: true)) {
        final why = _inquiryBlockReason.trim();
        throw Exception(why.isEmpty
            ? t('inquiry.blocked')
            : '${t('inquiry.blocked')} ($why)');
      }
      final used = await _purgeAndCountInquirySendLog();
      if (used >= kInquiryDailyLimit) {
        throw Exception(t('inquiry.rateLimit'));
      }
    }

    final prefs = await _prefsWithRetry();
    // UIDはローカル保存されたものを使う（匿名認証の有無に依存しない）
    String uid = _uid ?? prefs.getString('firebase_uid') ?? '';
    if (uid.isEmpty) {
      uid = _uuid.v4(); // 匿名UIDを生成してローカルに保存
      await prefs.setString('firebase_uid', uid);
    }
    final msgId = _uuid.v4();
    final now = DateTime.now().toIso8601String();

    // ローカルにも保存
    final existing = prefs.getString('my_inquiries') ?? '[]';
    final list =
        (jsonDecode(existing) as List<dynamic>).cast<Map<String, dynamic>>();
    list.add({
      'id': msgId,
      'message': message.trim(),
      'timestamp': now,
      'reply': '',
      'replyTimestamp': '',
      'status': 'open',
    });
    await prefs.setString('my_inquiries', jsonEncode(list));

    // Firestore REST API: POST でドキュメント作成
    // 認証トークンを取得してから送信（ルールが request.auth != null の場合に対応）
    try {
      if (!_firebaseEnabled || _idToken == null) await _initFirebase();
      await _ensureFreshToken();
    } catch (_) {}

    final url = '$_firestoreBaseUrl/inquiries?documentId=$msgId';
    try {
      final res = await http
          .post(
            Uri.parse(url),
            headers: {
              'Content-Type': 'application/json',
              if (_idToken != null) 'Authorization': 'Bearer $_idToken',
            },
            body: jsonEncode({
              'fields': {
                'uid': {'stringValue': uid},
                'message': {'stringValue': message.trim()},
                'timestamp': {'stringValue': now},
                'reply': {'stringValue': ''},
                'replyTimestamp': {'stringValue': ''},
                'status': {'stringValue': 'open'},
                // 受信ボックスの優先度ソート用にプランを刻印しておく。
                // Cloud Function で開発者メールへ転送するときにも使える。
                'senderPlan': {'stringValue': currentPlanLabel()},
                'senderName': {'stringValue': _displayName ?? ''},
                // 開発者モードで設定したメールアドレス (admin/settings.inquiryEmail)
                // を「転送先」として刻印しておく。Cloud Function 側で
                // この forwardEmail を読んでメール送信するように繋げる想定。
                // クライアント側は別途 mailto: でも開く (UI 側で対応)。
                'forwardEmail': {'stringValue': _inquiryEmail},
              },
            }),
          )
          .timeout(const Duration(seconds: 15));
      if (res.statusCode == 200 || res.statusCode == 201) {
        debugPrint('問い合わせ送信完了: $msgId');
      } else {
        final code = res.statusCode;
        final body = res.body;
        debugPrint('問い合わせ送信失敗: $code $body');
        throw Exception('送信失敗 (HTTP $code): $body');
      }
    } catch (e) {
      debugPrint('問い合わせ送信エラー: $e');
      rethrow;
    }

    // ── 送信成功 → レート制限ログにタイムスタンプを追加 ──
    try {
      final raw = prefs.getString('inquiry_send_log') ?? '[]';
      final arr = (jsonDecode(raw) as List<dynamic>).cast<String>();
      arr.add(now);
      await prefs.setString('inquiry_send_log', jsonEncode(arr));
    } catch (_) {}

    return msgId;
  }

  /// ユーザー自身の問い合わせを削除（ローカル＋Firestore）

  /// 自分が送った問い合わせ一覧を取得（ローカルキャッシュ＋Firestoreマージ）
  Future<List<Map<String, dynamic>>> fetchMyInquiries() async {
    final prefs = await _prefsWithRetry();
    final existing = prefs.getString('my_inquiries') ?? '[]';
    final localList =
        (jsonDecode(existing) as List<dynamic>).cast<Map<String, dynamic>>();

    // Firebase未初期化なら初期化してトークンを取得
    if (!_firebaseEnabled || _idToken == null) {
      try {
        await _initFirebase();
      } catch (_) {}
    }
    if (!_firebaseEnabled || _idToken == null)
      return localList.reversed.toList();

    try {
      await _ensureFreshToken();
      final updated = <Map<String, dynamic>>[];
      for (final local in localList) {
        final msgId = local['id'] as String;
        final url = '$_firestoreBaseUrl/inquiries/$msgId';
        final res = await http.get(
          Uri.parse(url),
          headers: {'Authorization': 'Bearer $_idToken'},
        );
        if (res.statusCode == 200) {
          final data = jsonDecode(res.body) as Map<String, dynamic>;
          final fields = data['fields'] as Map<String, dynamic>? ?? {};
          updated.add({
            'id': msgId,
            'message': _firestoreStr(fields['message']) ?? local['message'],
            'timestamp':
                _firestoreStr(fields['timestamp']) ?? local['timestamp'],
            'reply': _firestoreStr(fields['reply']) ?? '',
            'replyTimestamp': _firestoreStr(fields['replyTimestamp']) ?? '',
            'status': _firestoreStr(fields['status']) ?? 'open',
          });
        } else {
          updated.add(local);
        }
      }
      await prefs.setString('my_inquiries', jsonEncode(updated));
      return updated.reversed.toList();
    } catch (e) {
      debugPrint('問い合わせ取得エラー: $e');
      return localList.reversed.toList();
    }
  }

  /// 開発者専用：全ユーザーの問い合わせ一覧を取得
  Future<List<Map<String, dynamic>>> fetchAllInquiries() async {
    if (!_developerMode) return [];
    // Firebase未初期化なら初期化してトークンを取得
    if (!_firebaseEnabled || _idToken == null) {
      try {
        await _initFirebase();
      } catch (_) {}
    }
    try {
      await _ensureFreshToken();
    } catch (_) {}

    final url = '$_firestoreBaseUrl/inquiries';
    final res = await http.get(
      Uri.parse(url),
      headers: {
        'Content-Type': 'application/json',
        if (_idToken != null) 'Authorization': 'Bearer $_idToken',
      },
    );
    debugPrint('fetchAllInquiries: HTTP ${res.statusCode}');
    if (res.statusCode == 401 || res.statusCode == 403) {
      // トークンを再取得してリトライ
      try {
        await _ensureFreshToken();
        final retry = await http.get(
          Uri.parse(url),
          headers: {
            'Content-Type': 'application/json',
            if (_idToken != null) 'Authorization': 'Bearer $_idToken',
          },
        );
        debugPrint('fetchAllInquiries retry: HTTP ${retry.statusCode}');
        if (retry.statusCode != 200) {
          throw Exception(
              'Firestore読み取りエラー (HTTP ${retry.statusCode}): ${retry.body}');
        }
        return _parseInquiriesDocs(retry.body);
      } catch (e) {
        throw Exception('問い合わせ取得失敗: $e');
      }
    }
    try {
      if (res.statusCode != 200) {
        throw Exception(
            'Firestore読み取りエラー (HTTP \${res.statusCode}): \${res.body}');
      }
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final docs = data['documents'] as List<dynamic>? ?? [];
      final result = <Map<String, dynamic>>[];
      for (final doc in docs) {
        try {
          final docName = doc['name'] as String;
          final msgId = docName.split('/').last;
          final fields = doc['fields'] as Map<String, dynamic>? ?? {};
          result.add({
            'id': msgId,
            'uid': _firestoreStr(fields['uid']) ?? '',
            'message': _firestoreStr(fields['message']) ?? '',
            'timestamp': _firestoreStr(fields['timestamp']) ?? '',
            'reply': _firestoreStr(fields['reply']) ?? '',
            'replyTimestamp': _firestoreStr(fields['replyTimestamp']) ?? '',
            'status': _firestoreStr(fields['status']) ?? 'open',
            // 送信時に刻印された senderPlan / senderName を読み出す。
            // 旧データは無いので空文字 → 後で /users/{uid}.plan で補完。
            'senderPlan': _firestoreStr(fields['senderPlan']) ?? '',
            'senderName': _firestoreStr(fields['senderName']) ?? '',
          });
        } catch (_) {}
      }
      // ── senderPlan が空の旧レコードに対して /users/{uid}.plan を補完 ──
      // 同じ uid に対して何度もリクエストしないようキャッシュする。
      final uidsNeedingPlan = <String>{
        for (final r in result)
          if ((r['senderPlan'] as String).isEmpty &&
              (r['uid'] as String).isNotEmpty)
            r['uid'] as String,
      };
      if (uidsNeedingPlan.isNotEmpty) {
        final planByUid = await _fetchUserPlansByUids(uidsNeedingPlan);
        for (final r in result) {
          if ((r['senderPlan'] as String).isEmpty) {
            final uid = r['uid'] as String;
            r['senderPlan'] = planByUid[uid] ?? 'free';
          }
        }
      }
      // ── ソート: プラン優先 (Max → developer/coupon → Pro → Free) → 新しい順 ──
      result.sort((a, b) {
        final aR = _planSortRank(a['senderPlan'] as String);
        final bR = _planSortRank(b['senderPlan'] as String);
        if (aR != bR) return aR.compareTo(bR);
        return (b['timestamp'] as String).compareTo(a['timestamp'] as String);
      });
      return result;
    } catch (e) {
      debugPrint('全問い合わせ取得エラー: $e');
      rethrow; // UIでエラーを表示するためrethrow
    }
  }

  /// 受信ボックスのソート優先度。値が小さいほど上に表示される。
  ///   max       : 0 (最優先)
  ///   developer : 1
  ///   pro       : 2
  ///   coupon    : 3
  ///   free      : 4
  ///   その他    : 5
  static int _planSortRank(String plan) {
    switch (plan) {
      case 'max':
        return 0;
      case 'developer':
        return 1;
      case 'pro':
        return 2;
      case 'coupon':
        return 3;
      case 'free':
        return 4;
      default:
        return 5;
    }
  }

  /// /users/{uid} ドキュメントの plan を一括取得 (uid → plan のマップ)。
  /// 旧仕様の問い合わせ (senderPlan が空) を補完するため。
  /// Firestore REST API は単発 GET しかないので並列リクエストする。
  /// 失敗 / 取得不能なものは結果マップに含めない (呼び出し側で 'free' に
  /// フォールバック)。
  Future<Map<String, String>> _fetchUserPlansByUids(Set<String> uids) async {
    final result = <String, String>{};
    if (!_firebaseEnabled || _idToken == null || uids.isEmpty) return result;
    try {
      await _ensureFreshToken();
    } catch (_) {}
    // 並列で取得 (最大同時 8 件くらいに絞る)
    final uidList = uids.toList();
    const chunkSize = 8;
    for (int i = 0; i < uidList.length; i += chunkSize) {
      final chunk = uidList.sublist(
          i, (i + chunkSize > uidList.length) ? uidList.length : i + chunkSize);
      await Future.wait(chunk.map((uid) async {
        try {
          final r = await http.get(
            Uri.parse('$_firestoreBaseUrl/users/$uid'),
            headers: {
              if (_idToken != null) 'Authorization': 'Bearer $_idToken',
            },
          );
          if (r.statusCode == 200) {
            final d = jsonDecode(r.body) as Map<String, dynamic>;
            final fields = d['fields'] as Map<String, dynamic>? ?? {};
            final plan = _firestoreStr(fields['plan']);
            if (plan != null && plan.isNotEmpty) result[uid] = plan;
          }
        } catch (_) {}
      }));
    }
    return result;
  }

  /// Firestore inquiriesドキュメント一覧をパース (401/403 リトライ用)。
  /// senderPlan が空のドキュメントは 'free' 扱いでソートされる
  /// (リトライ系なので /users/{uid}.plan の補完までは行わず素早く返す)。
  List<Map<String, dynamic>> _parseInquiriesDocs(String body) {
    final data = jsonDecode(body) as Map<String, dynamic>;
    final docs = data['documents'] as List<dynamic>? ?? [];
    final result = <Map<String, dynamic>>[];
    for (final doc in docs) {
      try {
        final docName = doc['name'] as String;
        final msgId = docName.split('/').last;
        final fields = doc['fields'] as Map<String, dynamic>? ?? {};
        result.add({
          'id': msgId,
          'uid': _firestoreStr(fields['uid']) ?? '',
          'message': _firestoreStr(fields['message']) ?? '',
          'timestamp': _firestoreStr(fields['timestamp']) ?? '',
          'reply': _firestoreStr(fields['reply']) ?? '',
          'replyTimestamp': _firestoreStr(fields['replyTimestamp']) ?? '',
          'status': _firestoreStr(fields['status']) ?? 'open',
          'senderPlan': _firestoreStr(fields['senderPlan']) ?? '',
          'senderName': _firestoreStr(fields['senderName']) ?? '',
        });
      } catch (_) {}
    }
    result.sort((a, b) {
      final aR = _planSortRank(a['senderPlan'] as String);
      final bR = _planSortRank(b['senderPlan'] as String);
      if (aR != bR) return aR.compareTo(bR);
      return (b['timestamp'] as String).compareTo(a['timestamp'] as String);
    });
    return result;
  }

  /// 開発者専用：問い合わせに返信する
  Future<bool> replyToInquiry(String msgId, String replyText) async {
    if (!_developerMode) return false;
    try {
      if (_firebaseEnabled && _idToken == null) await _ensureFreshToken();
      final now = DateTime.now().toIso8601String();
      final url = '$_firestoreBaseUrl/inquiries/$msgId'
          '?updateMask.fieldPaths=reply'
          '&updateMask.fieldPaths=replyTimestamp'
          '&updateMask.fieldPaths=status';
      final res = await http.patch(
        Uri.parse(url),
        headers: {
          if (_idToken != null) 'Authorization': 'Bearer $_idToken',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({
          'fields': {
            'reply': {'stringValue': replyText.trim()},
            'replyTimestamp': {'stringValue': now},
            'status': {'stringValue': 'replied'},
          },
        }),
      );
      return res.statusCode == 200;
    } catch (e) {
      debugPrint('返信エラー: $e');
      return false;
    }
  }

  /// 開発者専用：問い合わせを削除
  Future<bool> deleteInquiry(String msgId) async {
    if (!_developerMode) return false;
    try {
      if (_firebaseEnabled && _idToken == null) await _ensureFreshToken();
      final url = '$_firestoreBaseUrl/inquiries/$msgId';
      final res = await http.delete(
        Uri.parse(url),
        headers: {
          if (_idToken != null) 'Authorization': 'Bearer $_idToken',
        },
      );
      return res.statusCode == 200 || res.statusCode == 204;
    } catch (e) {
      return false;
    }
  }

  Future<bool> deleteMyInquiry(String msgId) async {
    // ローカルから削除
    final prefs = await _prefsWithRetry();
    final existing = prefs.getString('my_inquiries') ?? '[]';
    final list =
        (jsonDecode(existing) as List<dynamic>).cast<Map<String, dynamic>>();
    list.removeWhere((e) => e['id'] == msgId);
    await prefs.setString('my_inquiries', jsonEncode(list));

    // Firestoreからも削除（ベストエフォート）
    try {
      await _ensureFreshToken();
      final url = '$_firestoreBaseUrl/inquiries/$msgId';
      final res = await http.delete(
        Uri.parse(url),
        headers: {
          if (_idToken != null) 'Authorization': 'Bearer $_idToken',
        },
      );
      debugPrint('Firestore削除: ${res.statusCode}');
    } catch (e) {
      debugPrint('自分の問い合わせ削除エラー: $e');
    }
    return true; // ローカル削除は成功
  }

  // ─── AI キャンセル機構 ────────────────────────────────────────────────
  // AI 生成実行中フラグ。UI は aiInProgress を監視して進行中の場合は「停止」
  // ボタンを出す。cancelAi() が呼ばれると _aiCancelled が立ち、AI メソッド側で
  // 次のチェックポイントで早期 return（ノードには何も反映されない）。
  //
  // 加えて、AI 開始時点での各ページの Undo スタックサイズを記録する
  // (`_aiStartUndoSize`)。これは Ctrl+Z の挙動を「AI 開始後にユーザーが
  // 行った別作業を先に取り消し、それが無くなった時点で AI 自体をキャンセル」
  // とするため。これにより AI はバックグラウンドで動作し続け、別作業と
  // 並行できる。
  bool _aiInProgress = false;
  bool get aiInProgress => _aiInProgress;
  bool _aiCancelled = false;
  bool get aiCancelled => _aiCancelled;

  /// AI 開始時点での各ページの Undo スタックサイズ。
  /// AI 開始後にユーザーが編集すると _undoStacks に新しいスナップショットが
  /// 積まれ、サイズが増える。Ctrl+Z は increment 分を先に取り消し、
  /// すべて取り消し終わってからの追加 Ctrl+Z で AI 自体をキャンセルする。
  final Map<String, int> _aiStartUndoSize = {};

  void _beginAi() {
    _aiInProgress = true;
    _aiCancelled = false;
    // 全ページの現在の Undo スタックサイズをスナップショット
    _aiStartUndoSize.clear();
    for (final entry in _undoStacks.entries) {
      _aiStartUndoSize[entry.key] = entry.value.length;
    }
    notifyListeners();
  }

  void _endAi() {
    _aiInProgress = false;
    _aiStartUndoSize.clear();
    notifyListeners();
  }

  /// 進行中の AI 生成をキャンセル。実行中の HTTP リクエスト自体は止められないが、
  /// 完了後に結果がノードへ反映されるのを防ぐ。
  void cancelAi() {
    if (_aiInProgress) {
      _aiCancelled = true;
      notifyListeners();
    }
  }

  /// AI 開始後にユーザーが Undo 可能な操作を行ったか判定。
  /// true の場合、Ctrl+Z は AI のキャンセルではなく通常の undo を実行すべき
  /// （AI 開始後の別作業を先に取り消す）。
  /// false の場合（AI 開始後に何も操作していない）、Ctrl+Z で AI をキャンセル。
  bool get hasUserActionsAfterAiStart {
    if (!_aiInProgress) return false;
    for (final entry in _undoStacks.entries) {
      final startSize = _aiStartUndoSize[entry.key] ?? 0;
      if (entry.value.length > startSize) return true;
    }
    return false;
  }

  /// ── AI 呼び出し統一ディスパッチャ ──
  /// `aiProvider` の設定に従い Gemini / OpenAI / Claude に振り分ける
  // ─── AI 代行実行 (アプリ側のキーで動かして使用量を計上する) ────────────
  //
  // 自分の API キーを持たないユーザー向け。 本物のキーは Worker だけが持ち、
  // アプリは Worker に投げる。 トークン数は Worker が AI の応答から読んで
  // 積むので、 クライアントを書き換えても水増し / 過少申告はできない。
  //
  // 代行は有料プラン限定 (無料に開くとそのままこちらの持ち出しになる)。
  static const String relayApiBase = String.fromEnvironment(
      'ENTITLEMENT_API_BASE',
      defaultValue: '');

  /// 代行の中継先が実際に応答するか。 null = 未確認。
  /// 接続先 URL が設定されていても、 Worker 側に代行エンドポイントが
  /// デプロイされていない事があるため、 確認できるまでは使わない
  /// (= 確認せずに使うと「AI は使える」 表示のまま全部失敗する)。
  bool? _relayAvailable;
  bool? get relayAvailable => _relayAvailable;

  // ── 前払いクレジット (= ユーザー要望: 先に 10 ドル預けて、 使った分だけ
  //    原価 + 1 割で引かれる。 足りなくなったら都度チャージ) ──
  double _creditBalanceUsd = 0.0;
  double get creditBalanceUsd => _creditBalanceUsd;

  /// 1 回のチャージ額 (= 最低額)。 サーバーの CREDIT_PACK_USD と揃える。
  double _creditPackUsd = 10.0;
  double get creditPackUsd => _creditPackUsd;

  /// 残高が少なくなったか (サーバー判定)。
  bool _creditLow = false;
  bool get creditLow => _creditLow;

  /// トークンが足りなくて断られた時に、 画面側がチャージの案内を出すための
  /// 呼び出し口 (= ユーザー要望: 文言と一緒にチャージの誘導画面も出す)。
  /// 画面が起動時に差し込む。 差さっていなければ何も起きない。
  void Function()? onCreditShort;

  /// トークン切れを画面へ知らせる。 投げる直前に呼ぶ。
  void _notifyCreditShort() {
    final cb = onCreditShort;
    if (cb == null) return;
    // 例外を投げる流れの途中なので、 画面の描画とは切り離して呼ぶ。
    Future.microtask(cb);
  }

  /// 累計チャージ / 累計使用 (表示用 = ユーザー要望: チャージ額と使った分を
  /// 見えるように)。
  double _creditTotalChargedUsd = 0.0;
  double get creditTotalChargedUsd => _creditTotalChargedUsd;
  double _creditTotalSpentUsd = 0.0;
  double get creditTotalSpentUsd => _creditTotalSpentUsd;

  /// 直近のクレジット明細 (表示用)。
  List<dynamic> _creditRecent = const [];
  List<dynamic> get creditRecent => _creditRecent;

  /// 代行実行が使える状態か。
  /// 中継先が応答し、 前払い残高が残っていること。
  ///
  /// ★ BYOK (利用者が自分の API キーを入れる方式) は廃止した
  ///   (= ユーザー要望: こちら側で用意したキーのみを使う)。
  ///   そのため「自分のキーの有無」 は条件に入れない。
  /// ★ Dev プランは残高が 0 でも使える (= 決済を通さない枠)。 実際の
  ///   「引き落とさない」 判定はサーバー側が持っているので、 ここでは
  ///   入口を開けるだけ。 詐称しても Worker が Dev と認めなければ弾かれる。
  bool get canUseAiRelay =>
      relayApiBase.isNotEmpty &&
      _relayAvailable == true &&
      (_creditBalanceUsd > 0 || isDevPlan);

  /// 代行サーバーに送る本人確認ヘッダ (= uid の自己申告をやめ、
  /// Google が署名した ID トークンで本人だと示す)。
  Map<String, String> _relayHeaders({bool json = false}) => {
        if (json) 'content-type': 'application/json',
        if (_idToken != null) 'Authorization': 'Bearer $_idToken',
      };

  // ─── 書いた物をネットに公開する (= ユーザー要望: マークダウンの
  //     プレビュー画面をサーバーに公開したい) ───────────────────────
  //
  // 出来上がった HTML をそのまま Worker に預け、 `/p/<id>` で誰でも読める
  // 静的ページとして配る。 **必ず期限が付く** (最長 30 日)。 期限が来れば
  // サーバー側 (KV の TTL) が勝手に消すので、 消し忘れが残らない。

  /// 公開できる状態か (中継先が設定されていて、 サインインできている)。
  bool get canPublishHtmlPage => relayApiBase.isNotEmpty;

  /// 公開する。 [updateId] を渡すと同じ URL のまま中身を差し替える。
  /// [hours] で時間単位の細かい期限を指定できる (最長 30 日 = 720 時間)。
  /// 返り値は公開 URL と失効時刻 (秒)。 失敗したら例外。
  /// [markdown] を渡すと、 読む人が公開ページから .md を落とせる。
  /// [password] を付けると、 読む前に合言葉を聞く。
  Future<({String id, String url, int expiresAt})> publishHtmlPage(
    String html, {
    String title = '',
    int days = 7,
    int? hours,
    String markdown = '',
    String password = '',
    String? updateId,
  }) async {
    final base = relayApiBase;
    if (base.isEmpty) throw Exception(t('pub.notConfigured'));
    await _ensureFreshToken();
    if (_idToken == null) throw Exception(t('relay.needSignIn'));
    final res = await http
        .post(
          Uri.parse('$base/pub/create'),
          headers: _relayHeaders(json: true),
          body: jsonEncode({
            'html': html,
            'title': title,
            'days': days.clamp(1, 30),
            if (hours != null) 'hours': hours.clamp(1, 30 * 24),
            if (markdown.trim().isNotEmpty) 'md': markdown,
            // 空文字も送る (= 付いていた合言葉を外せるように)。
            'pw': password,
            if (updateId != null && updateId.isNotEmpty) 'id': updateId,
          }),
        )
        .timeout(const Duration(seconds: 40));
    Map<String, dynamic> j;
    try {
      j = jsonDecode(res.body) as Map<String, dynamic>;
    } catch (_) {
      throw Exception('HTTP ${res.statusCode}');
    }
    if (res.statusCode != 200) {
      // 大きすぎる / 数が多すぎるは、 理由が分かる文にして返す。
      final err = '${j['error'] ?? ''}';
      if (err == 'too large') throw Exception(t('pub.tooLarge'));
      if (err == 'too many') {
        throw Exception(
            t('pub.tooMany').replaceFirst('{n}', '${j['max'] ?? 30}'));
      }
      throw Exception(err.isEmpty ? 'HTTP ${res.statusCode}' : err);
    }
    return (
      id: '${j['id'] ?? ''}',
      url: '${j['url'] ?? ''}',
      expiresAt: (j['expiresAt'] as num?)?.toInt() ?? 0,
    );
  }

  /// 今公開しているページの一覧。
  Future<List<Map<String, dynamic>>> listPublishedHtmlPages() async {
    final base = relayApiBase;
    if (base.isEmpty) return const [];
    try {
      await _ensureFreshToken();
      if (_idToken == null) return const [];
      final res = await http
          .get(Uri.parse('$base/pub/list'), headers: _relayHeaders())
          .timeout(const Duration(seconds: 25));
      if (res.statusCode != 200) return const [];
      final j = jsonDecode(res.body);
      if (j is! Map) return const [];
      return [
        for (final e in (j['items'] as List? ?? const []))
          if (e is Map) e.cast<String, dynamic>()
      ];
    } catch (e) {
      debugPrint('公開ページの一覧取得に失敗: $e');
      return const [];
    }
  }

  /// 公開をやめる (すぐ読めなくなる)。
  Future<bool> unpublishHtmlPage(String id) async {
    final base = relayApiBase;
    if (base.isEmpty || id.isEmpty) return false;
    try {
      await _ensureFreshToken();
      if (_idToken == null) return false;
      final res = await http
          .post(Uri.parse('$base/pub/delete'),
              headers: _relayHeaders(json: true),
              body: jsonEncode({'id': id}))
          .timeout(const Duration(seconds: 25));
      return res.statusCode == 200;
    } catch (e) {
      debugPrint('公開の取り消しに失敗: $e');
      return false;
    }
  }

  /// 残高を取り直す。
  Future<void> refreshCreditBalance() async {
    final base = relayApiBase;
    if (base.isEmpty) return;
    await _ensureFreshToken();
    final uid = _uid;
    if (uid == null || uid.isEmpty) return;
    try {
      final res = await http
          .get(Uri.parse('$base/credits/balance'), headers: _relayHeaders())
          .timeout(const Duration(seconds: 20));
      if (res.statusCode != 200) return;
      final j = jsonDecode(res.body) as Map<String, dynamic>;
      _creditBalanceUsd = (j['balanceUsd'] as num?)?.toDouble() ?? 0.0;
      _creditPackUsd = (j['packUsd'] as num?)?.toDouble() ?? 10.0;
      _creditLow = j['low'] == true;
      _creditTotalChargedUsd =
          (j['totalChargedUsd'] as num?)?.toDouble() ?? _creditTotalChargedUsd;
      _creditTotalSpentUsd =
          (j['totalSpentUsd'] as num?)?.toDouble() ?? _creditTotalSpentUsd;
      final recent = j['recent'];
      if (recent is List) _creditRecent = recent;
      notifyListeners();
    } catch (e) {
      debugPrint('残高の取得に失敗: $e');
    }
    // Dev プランは残高でなく「大元の月間枠」 を見るので、 一緒に取り直す
    // (= ユーザー要望: 大元の残りトークン数みたいなのを表示)。
    if (isDevPlan) unawaited(refreshAiMonthlyUsage());
  }

  // ─── Dev 枠: 月間使用量 (= ユーザー要望: 大元の残り表示) ─────────────
  /// 今月すでに使った額 (マークアップ込みの請求額ベース)。
  double _aiMonthlyBilledUsd = 0.0;
  double get aiMonthlyBilledUsd => _aiMonthlyBilledUsd;

  /// サーバーが返した月間上限 (未取得時は 0)。
  double _aiMonthlyCapUsd = 0.0;

  /// Dev 枠の月間上限。 サーバー値が届いていればそれ、 無ければ Worker の
  /// DEV_MONTHLY_CAP_USD と揃えた既定値。
  static const double _kDevMonthlyCapUsdFallback = 200.0;
  double get devMonthlyCapUsd =>
      _aiMonthlyCapUsd > 0 ? _aiMonthlyCapUsd : _kDevMonthlyCapUsdFallback;

  /// Dev 枠の残り (ドル)。
  double get devRemainingUsd =>
      (devMonthlyCapUsd - _aiMonthlyBilledUsd).clamp(0.0, double.infinity);

  /// 今月の AI 使用量 (と上限) を取り直す。
  Future<void> refreshAiMonthlyUsage() async {
    final base = relayApiBase;
    if (base.isEmpty) return;
    await _ensureFreshToken();
    if (_idToken == null) return;
    try {
      final res = await http
          .get(Uri.parse('$base/ai/usage'), headers: _relayHeaders())
          .timeout(const Duration(seconds: 20));
      if (res.statusCode != 200) return;
      final j = jsonDecode(res.body);
      if (j is! Map) return;
      _aiMonthlyBilledUsd = (j['billedUsd'] as num?)?.toDouble() ?? 0.0;
      // dev: true の応答なら capUsd は Dev 枠の値 (Worker 側を更新済み)。
      if (j['dev'] == true) {
        _aiMonthlyCapUsd = (j['capUsd'] as num?)?.toDouble() ?? 0.0;
      }
      notifyListeners();
    } catch (_) {}
  }

  // ─── Dev: 決済なしで代行を使う (= ユーザー要望) ──────────────────────
  /// developer_mode が ON の時、 管理者 uid に限り Dev 権利を自動で
  /// 自己発行して引き換える。 管理者でなければ Worker が 403 で断るので
  /// 何も起きない (= 一般ユーザーが Dev 枠を得ることはできない)。
  bool _devSelfGrantTried = false;
  Future<void> maybeDevSelfGrantAiAccess() async {
    if (_devSelfGrantTried) return;
    _devSelfGrantTried = true;
    if (!_developerMode) return;
    if (_serverGrantedPlan == 'dev') return; // 既に付与済み
    final base = relayApiBase;
    if (base.isEmpty) return;
    try {
      await _ensureFreshToken();
      if (_idToken == null) return;
      final res = await http
          .post(
            Uri.parse('$base/dev/issue'),
            headers: _relayHeaders(json: true),
            body: jsonEncode(
                {'maxUses': 1, 'months': 0, 'note': 'self (dev mode)'}),
          )
          .timeout(const Duration(seconds: 20));
      if (res.statusCode != 200) return; // 管理者でない等
      final code = '${(jsonDecode(res.body) as Map)['code'] ?? ''}';
      if (code.isEmpty) return;
      await redeemDevCode(code);
      unawaited(refreshAiMonthlyUsage());
    } catch (e) {
      debugPrint('dev self grant: $e');
    }
  }

  /// 上で自己発行した Dev 枠を返上して、 本来のプランに戻す。
  ///
  /// 開発者モードを抜けた後も `_purchasedPlan` が dev のまま残っていて、
  /// プラン表示がずっと Dev になっていた (= ユーザー報告: 「開発者モードを
  /// ログアウトしてもプランが Dev のまま」)。 サーバー側の権利も一緒に
  /// 戻さないと、 再起動や別端末でも Dev が復活してしまうため、 Worker の
  /// `/dev/release` を呼んでから手元の状態を合わせる。
  ///
  /// 返上できるのは管理者 uid だけ (= 自己発行できるのと同じ範囲)。
  /// 配布コードで Dev になった利用者には影響しない (403 で何も起きない)。
  /// 起動時用。 匿名ログインが済むまで待ってから返上する。
  /// 起動直後は ID トークンがまだ無く、 その場で呼んでも何も出来ないため。
  Future<void> _releaseDevSelfGrantWhenSignedIn() async {
    const waits = <Duration>[
      Duration(seconds: 2),
      Duration(seconds: 4),
      Duration(seconds: 8),
      Duration(seconds: 15),
      Duration(seconds: 30),
    ];
    for (final w in waits) {
      if (_disposed) return;
      // 待っている間に開発者モードへ入り直した場合は触らない。
      if (_developerMode) return;
      if (_uid != null && _idToken != null) {
        await releaseDevSelfGrant();
        return;
      }
      await Future<void>.delayed(w);
    }
  }

  Future<void> releaseDevSelfGrant() async {
    // 次に開発者モードへ入った時に、 もう一度自己発行できるようにする。
    _devSelfGrantTried = false;
    await _loadServerGrantedPlan();
    if (_purchasedPlan != SubscriptionPlan.dev && _serverGrantedPlan != 'dev') {
      return;
    }
    final base = relayApiBase;
    if (base.isEmpty) return;
    try {
      await _ensureFreshToken();
      if (_idToken == null) return;
      final res = await http
          .post(Uri.parse('$base/dev/release'),
              headers: _relayHeaders(json: true), body: '{}')
          .timeout(const Duration(seconds: 20));
      if (res.statusCode != 200) return; // 管理者でない等
      final plan = '${(jsonDecode(res.body) as Map)['plan'] ?? 'free'}';
      final next = SubscriptionPlan.values.firstWhere(
        (p) => p.name == plan,
        orElse: () => SubscriptionPlan.free,
      );
      await applyBillingPlan(next);
      await _setServerGrantedPlan(
          next == SubscriptionPlan.free ? null : next.name);
      unawaited(probeAiRelay(force: true));
      unawaited(refreshAiMonthlyUsage());
      notifyListeners();
    } catch (e) {
      debugPrint('dev release: $e');
    }
  }

  /// チャージ用の決済ページ URL を作る。 [packs] は 10 ドル単位の個数。
  /// 返った URL を外部ブラウザで開く (アプリ内に決済画面は出さない)。
  Future<String?> createCreditCheckoutUrl({int packs = 1}) async {
    final base = relayApiBase;
    if (base.isEmpty) throw Exception(t('relay.notConfigured'));
    await _ensureFreshToken();
    final uid = _uid;
    if (uid == null || uid.isEmpty) throw Exception(t('relay.needSignIn'));
    final res = await http
        .post(
          Uri.parse('$base/credits/checkout'),
          headers: _relayHeaders(json: true),
          body: jsonEncode({'uid': uid, 'packs': packs}),
        )
        .timeout(const Duration(seconds: 30));
    final j = jsonDecode(res.body) as Map<String, dynamic>;
    if (res.statusCode != 200) {
      throw Exception('${j['error'] ?? 'HTTP ${res.statusCode}'}');
    }
    return j['url'] as String?;
  }

  // ── 契約中のサブスクリプション (= ユーザー要望: アプリの中で契約状況を
  //    見て、 そのまま解約までできるように) ──
  // Stripe の契約は Worker (課金サーバー) が uid → subscriptionId を
  // 知っているので、 そこ経由で照会・解約する。 Google アカウントで
  // ログインしていれば、 どの端末でも同じ uid = 同じ契約が見える。

  /// 契約状況を照会する。 戻り値は Worker の JSON
  /// (`plan`, `subscription: {status, cancelAtPeriodEnd, currentPeriodEnd,
  /// amount, currency, interval}` / 契約が無ければ subscription = null)。
  Future<Map<String, dynamic>> fetchSubscriptionInfo() async {
    const base = relayApiBase;
    if (base.isEmpty) throw Exception(t('relay.notConfigured'));
    await _ensureFreshToken();
    final res = await http
        .get(Uri.parse('$base/billing/subscription'), headers: _relayHeaders())
        .timeout(const Duration(seconds: 30));
    final j = jsonDecode(res.body) as Map<String, dynamic>;
    if (res.statusCode != 200) {
      throw Exception('${j['error'] ?? 'HTTP ${res.statusCode}'}');
    }
    return j;
  }

  /// 解約 (期間終了で止める) / 解約の取り消し。 成功したら最新の契約状況を返す。
  Future<Map<String, dynamic>> setSubscriptionCancel(bool cancel) async {
    const base = relayApiBase;
    if (base.isEmpty) throw Exception(t('relay.notConfigured'));
    await _ensureFreshToken();
    final res = await http
        .post(
          Uri.parse('$base/billing/${cancel ? 'cancel' : 'resume'}'),
          headers: _relayHeaders(json: true),
          body: '{}',
        )
        .timeout(const Duration(seconds: 30));
    final j = jsonDecode(res.body) as Map<String, dynamic>;
    if (res.statusCode != 200) {
      throw Exception('${j['error'] ?? 'HTTP ${res.statusCode}'}');
    }
    return j;
  }

  /// サーバーが代行できるモデルの一覧 (料金つき)。
  List<dynamic> _relayModels = const [];
  List<dynamic> get relayModels => _relayModels;

  Future<void> refreshRelayModels() async {
    final base = relayApiBase;
    if (base.isEmpty) return;
    try {
      final res = await http
          .get(Uri.parse('$base/ai/models'))
          .timeout(const Duration(seconds: 20));
      if (res.statusCode != 200) return;
      final j = jsonDecode(res.body) as Map<String, dynamic>;
      final models = j['models'];
      if (models is List) {
        _relayModels = models;
        notifyListeners();
      }
    } catch (e) {
      debugPrint('代行モデル一覧の取得に失敗: $e');
    }
  }

  /// 代行で使うモデル ID (プロバイダーを問わず、 サーバーが対応するもの)。
  /// 既定は Gemini Flash。 設定で切り替えられる。
  String _relayModel = 'gemini-flash-latest';
  String get relayModel => _relayModel;
  Future<void> setRelayModel(String id) async {
    _relayModel = id;
    notifyListeners();
    try {
      final p = await _prefsWithRetry();
      await p.setString('relayModel', id);
    } catch (_) {}
  }

  // ── 考える深さ (= ユーザー要望: 推論レベルも設定したい) ──
  //
  // 'low' / 'medium' / 'high' の 3 つだけ。 深いほど答えは良くなりやすいが、
  // 考えた分もトークンとして掛かるので料金と時間が伸びる。
  // ★ 以前あった 'auto' (指定しない) は「何が起きるか分からない」 ため廃止
  //   (= ユーザー要望)。 昔の設定が残っていたら 'medium' として扱う。
  String _relayReasoning = 'medium';
  String get relayReasoning => _relayReasoning;
  static const List<String> relayReasoningLevels = ['low', 'medium', 'high'];

  Future<void> setRelayReasoning(String v) async {
    if (!relayReasoningLevels.contains(v)) return;
    _relayReasoning = v;
    notifyListeners();
    try {
      final p = await _prefsWithRetry();
      await p.setString('relayReasoning', v);
    } catch (_) {}
  }

  /// 中継先に代行エンドポイントがあるか一度だけ確かめる。
  /// プランは問わない (= 前払いクレジット方式なので、 残高があれば誰でも使える)。
  Future<void> probeAiRelay({bool force = false}) async {
    if (!force && _relayAvailable != null) return;
    final base = relayApiBase;
    if (base.isEmpty) return;
    await _ensureFreshToken();
    final uid = _uid;
    if (uid == null || uid.isEmpty) return;
    try {
      final res = await http
          .get(Uri.parse('$base/ai/usage'), headers: _relayHeaders())
          .timeout(const Duration(seconds: 12));
      final ok = res.statusCode == 200;
      if (_relayAvailable != ok) {
        _relayAvailable = ok;
        notifyListeners();
      } else {
        _relayAvailable = ok;
      }
      if (ok) {
        try {
          _relayUsage = jsonDecode(res.body) as Map<String, dynamic>;
        } catch (_) {}
        // 代行が使えるなら、 残高とモデル一覧も取っておく。
        unawaited(refreshCreditBalance());
        unawaited(refreshRelayModels());
      }
    } catch (e) {
      debugPrint('代行エンドポイントの確認に失敗: $e');
      _relayAvailable = false;
    }
  }

  /// 今月の代行分の使用量 (Worker 集計)。 表示用。
  Map<String, dynamic>? _relayUsage;
  Map<String, dynamic>? get relayUsage => _relayUsage;

  /// Worker 経由で生成する。 戻り値は本文。 使用量は Worker が計上する。
  /// [images] を渡すと写真も一緒に見せる (= ユーザー要望: カメラで撮った物を
  /// そのまま AI に渡したい)。 対応していないモデルではサーバー側が無視する。
  Future<String> askAiViaRelay(String prompt,
      {int? maxTokens, List<AiInputImage>? images}) async {
    final base = relayApiBase;
    if (base.isEmpty) throw Exception(t('relay.notConfigured'));
    await _ensureFreshToken();
    final uid = _uid;
    if (uid == null || uid.isEmpty) throw Exception(t('relay.needSignIn'));
    final res = await http
        .post(
          Uri.parse('$base/ai/generate'),
          headers: _relayHeaders(json: true),
          body: jsonEncode({
            'uid': uid,
            // ★ 各社へ直接投げる経路 (askGemini 等) と同じように、 返答の言語
            //   指定を先頭に付ける。 代行経路だけこれが抜けていたため、
            //   日本語に設定していても英語で返ってきていた (= ユーザー報告)。
            //   代行は既定の経路なので、 ほぼ全員がこれに当たっていた。
            //   (画像生成 /ai/image は絵の指示文なので付けない)
            'prompt': languageInstructionForAi() + prompt,
            // 代行で使うモデル (Gemini / ChatGPT / Claude)。
            'model': _relayModel,
            // 考える深さ (= ユーザー要望: 推論レベルの設定)。
            'reasoning': _relayReasoning,
            // 構造化 (JSON) の生成は長くなるので、 呼び出し側が上限を指定する。
            //   指定が無ければ代行サーバー側の既定 (4096) を使う。
            if (maxTokens != null) 'maxTokens': maxTokens,
            // 一緒に見せる画像 (カメラで撮った写真など)。
            if (images != null && images.isNotEmpty)
              'images': images.map((e) => e.toJson()).toList(),
          }),
        )
        .timeout(const Duration(seconds: 180));
    Map<String, dynamic> j;
    try {
      j = jsonDecode(res.body) as Map<String, dynamic>;
    } catch (_) {
      throw Exception('HTTP ${res.statusCode}');
    }
    if (res.statusCode == 404) {
      // 中継先に代行エンドポイントが無い (未デプロイ)。 以後は自分のキーを
      //   使う経路に戻す。
      _relayAvailable = false;
      notifyListeners();
      throw Exception(t('relay.notConfigured'));
    }
    if (res.statusCode == 402) {
      // 残高不足。 画面がチャージを促せるよう、 残高を反映してから投げる。
      _creditBalanceUsd = (j['balanceUsd'] as num?)?.toDouble() ?? 0.0;
      _creditLow = true;
      notifyListeners();
      _notifyCreditShort();
      throw Exception(t('credit.insufficient'));
    }
    if (res.statusCode == 429) throw Exception(t('relay.capReached'));
    // 画像が大き過ぎる (= サーバー側の合計サイズ上限)。
    if (res.statusCode == 413) throw Exception(t('ai.imageTooLarge'));
    if (res.statusCode != 200) {
      // 失敗の中身も見せる。 'upstream error' だけだと、 どのモデルが何で
      //   断られたのか分からず調べようがなかった (= 実際に詰まった)。
      final detail = j['detail'];
      var extra = '';
      if (detail != null) {
        var d = detail is Map
            ? '${(detail['error'] is Map ? detail['error']['message'] : null) ?? jsonEncode(detail)}'
            : '$detail';
        if (d.length > 300) d = '${d.substring(0, 300)}…';
        extra = ': $d';
      }
      throw Exception('${j['error'] ?? 'HTTP ${res.statusCode}'}$extra');
    }
    // 残高を最新にする (応答に含まれる)。
    final c = j['credit'];
    if (c is Map<String, dynamic>) {
      _creditBalanceUsd = (c['balanceUsd'] as num?)?.toDouble() ?? 0.0;
      _creditLow = c['low'] == true;
      _creditPackUsd = (c['packUsd'] as num?)?.toDouble() ?? _creditPackUsd;
    }
    // 表示用に今月分を控えておく。
    final monthly = j['monthly'];
    if (monthly is Map<String, dynamic>) {
      _relayUsage = monthly;
      notifyListeners();
    }
    // ローカルの累計にも足す (画面のトークン表示と揃えるため)。
    // 原価は Worker が計算した値をそのまま使う (アプリ側の料金表とずれても
    //   請求根拠は Worker 側なので、 表示を Worker に合わせる)。
    final u = j['usage'];
    if (u is Map<String, dynamic>) {
      recordAppKeyUsage(
        inputTokens: (u['inputTokens'] as num?)?.toInt() ?? 0,
        outputTokens: (u['outputTokens'] as num?)?.toInt() ?? 0,
        costUsd: (u['costUsd'] as num?)?.toDouble(),
      );
    }
    return (j['text'] as String? ?? '').trim();
  }

  /// Worker 経由で画像を 1 枚生成する (= 前払いクレジットから 1 枚分を引く)。
  /// 本物の API キーは Worker だけが持つので、 アプリには埋め込まれない。
  Future<Uint8List> generateAiImageViaRelay(String prompt) async {
    final base = relayApiBase;
    if (base.isEmpty) throw Exception(t('relay.notConfigured'));
    await _ensureFreshToken();
    final uid = _uid;
    if (uid == null || uid.isEmpty) throw Exception(t('relay.needSignIn'));
    final res = await http
        .post(
          Uri.parse('$base/ai/image'),
          headers: _relayHeaders(json: true),
          body: jsonEncode({
            'uid': uid,
            'prompt': prompt,
            if (_imageGenModel != 'auto') 'model': _imageGenModel,
          }),
        )
        .timeout(const Duration(seconds: 180));
    Map<String, dynamic> j;
    try {
      j = jsonDecode(res.body) as Map<String, dynamic>;
    } catch (_) {
      throw Exception('HTTP ${res.statusCode}');
    }
    if (res.statusCode == 402) {
      _creditBalanceUsd = (j['balanceUsd'] as num?)?.toDouble() ?? 0.0;
      _creditLow = true;
      notifyListeners();
      _notifyCreditShort();
      throw Exception(t('credit.insufficient'));
    }
    if (res.statusCode == 429) throw Exception(t('relay.capReached'));
    if (res.statusCode != 200) {
      throw Exception('${j['error'] ?? 'HTTP ${res.statusCode}'}');
    }
    final b64 = j['imageBase64'] as String?;
    if (b64 == null || b64.isEmpty) throw Exception(t('ai.imageFailed'));
    // 残高を最新にする。
    final c = j['credit'];
    if (c is Map<String, dynamic>) {
      _creditBalanceUsd = (c['balanceUsd'] as num?)?.toDouble() ?? 0.0;
      _creditLow = c['low'] == true;
    }
    final monthly = j['monthly'];
    if (monthly is Map<String, dynamic>) _relayUsage = monthly;
    final u = j['usage'];
    if (u is Map<String, dynamic>) {
      // 原価と請求額はそれぞれの入れ物へ。 以前は請求額を原価側へ入れて
      //   いたため、 表示のときにもう一度上乗せされていた。
      _appKeyCostUsd += (u['costUsd'] as num?)?.toDouble() ?? 0.0;
      _appKeyBilledUsd += (u['billedUsd'] as num?)?.toDouble() ?? 0.0;
    }
    notifyListeners();
    return base64Decode(b64);
  }

  /// 今月の代行使用量を取り直す (設定画面などから)。
  Future<void> refreshRelayUsage() async {
    final base = relayApiBase;
    if (base.isEmpty) return;
    await _ensureFreshToken();
    final uid = _uid;
    if (uid == null || uid.isEmpty) return;
    try {
      final res = await http
          .get(Uri.parse('$base/ai/usage'), headers: _relayHeaders())
          .timeout(const Duration(seconds: 20));
      if (res.statusCode == 200) {
        _relayUsage = jsonDecode(res.body) as Map<String, dynamic>;
        notifyListeners();
      }
    } catch (e) {
      debugPrint('代行使用量の取得に失敗: $e');
    }
  }

  Future<String> askAi(String prompt,
      {int? maxTokensOverride,
      Duration? timeoutOverride,
      List<AiInputImage>? images}) async {
    // ★ 常に代行サーバー経由 (= ユーザー要望: こちらが用意したキーのみ)。
    //   残高が無い / 中継先が応答しない時は、 その理由を投げて画面に出す。
    if (canUseAiRelay) return askAiViaRelay(prompt, images: images);
    if (relayApiBase.isEmpty || _relayAvailable != true) {
      throw Exception(t('relay.notConfigured'));
    }
    _notifyCreditShort();
      throw Exception(t('credit.insufficient'));
    switch (_aiProvider) {
      case 'openai':
        return askOpenAi(prompt, maxTokensOverride: maxTokensOverride);
      case 'anthropic':
        return askClaude(prompt, maxTokensOverride: maxTokensOverride);
      case 'grok':
        return askGrok(prompt, maxTokensOverride: maxTokensOverride);
      case 'deepseek':
        return askDeepseek(prompt, maxTokensOverride: maxTokensOverride);
      case 'openrouter':
        return askOpenRouter(prompt, maxTokensOverride: maxTokensOverride);
      case 'gemini':
      default:
        return askGemini(prompt,
            maxTokensOverride: maxTokensOverride,
            timeoutOverride: timeoutOverride);
    }
  }

  // ════════ AI 生成スタジオ (画像 / スライド) = ユーザー要望 ════════

  /// プロンプトから画像を 1 枚生成して PNG/JPEG バイト列を返す。
  /// 画像生成は Gemini の image モデルのみ対応 (= 他プロバイダ選択時も
  /// Gemini キーがあれば動く)。 失敗時は分かりやすい例外を投げる。
  Future<Uint8List> generateAiImage(String prompt) async {
    final p = prompt.trim();
    if (p.isEmpty) throw Exception(t('ai.needPrompt'));
    // ★ 画像もアプリ側で用意したキー (代行サーバー) で動かす
    //   (= ユーザー要望: 利用者が自分でキーを用意しなくてよいように)。
    //   残高があれば代行、 無ければ自分のキー、 どちらも無ければ案内。
    if (canUseAiRelay) {
      return generateAiImageViaRelay(p);
    }
    if (!hasGeminiKey) {
      _notifyCreditShort();
      throw Exception(t('credit.insufficient'));
    }
    final styledPrompt = '''
$p

Art direction:
- polished contemporary editorial style, premium app/portfolio quality
- cohesive color palette, balanced contrast, clean composition
- cinematic lighting or refined vector/3D illustration depending on the subject
- generous negative space, no clutter, no random text, no watermarks
- crisp details, elegant atmosphere, visually suitable for a modern presentation
''';
    // 画像対応モデルを優先順に試す (利用可否はキー/リージョンで変わる)。
    // 選択モデル (auto 以外) があれば先頭に持ってくる (= ユーザー要望: 切替)。
    final base = [
      'gemini-2.5-flash-image',
      'gemini-2.5-flash-image-preview',
      'gemini-2.0-flash-preview-image-generation',
    ];
    final imageModels =
        (_imageGenModel != 'auto' && base.contains(_imageGenModel))
            ? [_imageGenModel, ...base.where((m) => m != _imageGenModel)]
            : base;
    Object? lastErr;
    for (final model in imageModels) {
      final url = 'https://generativelanguage.googleapis.com/v1beta/models/'
          '$model:generateContent?key=$_geminiApiKey';
      try {
        final res = await http
            .post(
              Uri.parse(url),
              headers: {'Content-Type': 'application/json'},
              body: jsonEncode({
                'contents': [
                  {
                    'parts': [
                      {'text': styledPrompt}
                    ]
                  }
                ],
                'generationConfig': {
                  'responseModalities': ['IMAGE', 'TEXT']
                },
              }),
            )
            .timeout(const Duration(seconds: 90));
        if (res.statusCode == 404 || res.statusCode == 400) {
          // このモデルは使えない → 次の候補へ。
          lastErr = Exception('モデル $model 利用不可 (${res.statusCode})');
          continue;
        }
        if (res.statusCode == 403) {
          throw Exception('Gemini APIキーが無効か、画像生成が許可されていません');
        }
        if (res.statusCode == 429) {
          throw Exception('レート制限です。しばらく待ってから再試行してください');
        }
        if (res.statusCode != 200) {
          lastErr = Exception('画像生成エラー: ${res.statusCode}');
          continue;
        }
        final data = jsonDecode(res.body) as Map<String, dynamic>;
        final candidates = data['candidates'] as List<dynamic>?;
        if (candidates == null || candidates.isEmpty) {
          lastErr = Exception('画像が返りませんでした');
          continue;
        }
        final content =
            (candidates.first as Map)['content'] as Map<String, dynamic>?;
        final parts = content?['parts'] as List<dynamic>?;
        if (parts != null) {
          for (final part in parts) {
            final m = part as Map<String, dynamic>;
            final inline =
                (m['inlineData'] ?? m['inline_data']) as Map<String, dynamic>?;
            final b64 = inline?['data'] as String?;
            if (b64 != null && b64.isNotEmpty) {
              return base64Decode(b64);
            }
          }
        }
        lastErr = Exception('応答に画像が含まれていません');
      } on TimeoutException {
        lastErr = Exception('画像生成がタイムアウトしました');
      }
    }
    throw lastErr is Exception
        ? lastErr as Exception
        : Exception('画像生成に失敗しました');
  }

  /// トピックからプレゼン用スライド構成を AI に作らせて返す。
  /// 各スライド = (見出し, 箇条書きリスト)。 pptx 生成に使う (= ユーザー要望)。
  Future<List<({String title, List<String> bullets})>> generateSlideOutline(
      String topic,
      {int slides = 6}) async {
    if (!hasActiveAiKey) {
      throw Exception('スライド生成には AI APIキーが必要です（設定で登録してください）');
    }
    final t = topic.trim();
    if (t.isEmpty) throw Exception('トピックを入力してください');
    final n = slides.clamp(3, 20);
    final prompt = '''次のトピックについて、見た目の良いビジネス/学習用プレゼンを$n枚作成してください。
トピック: $t

出力は次の形式の JSON 配列のみ（前後の説明やマークダウン記号は一切付けない）:
[{"title":"スライドの見出し","bullets":["要点1","要点2","要点3"]}]

ルール:
- 1枚目はタイトル/概要スライド。
- 2枚目以降は「背景 → 重要ポイント → 具体例 → まとめ」の流れが自然になるよう構成する。
- title は短く印象的にし、重複語を避ける。
- 各スライドの bullets は2〜4個、各要点は簡潔だが資料として伝わる一文。
- 箇条書きはデザインしやすい粒度にして、1行が長すぎないようにする。
- 最終スライドは要点整理または次のアクションで締める。
- 全体で$n枚ちょうど。''';
    final raw = await askAiForJson(prompt);
    final list = _parseSlideJson(raw);
    if (list.isEmpty) throw Exception('スライド構成の生成に失敗しました');
    return list;
  }

  List<({String title, List<String> bullets})> _parseSlideJson(String raw) {
    // ```json ... ``` フェンスや前後ノイズを除去して配列部分を取り出す。
    var s = raw.trim();
    final start = s.indexOf('[');
    final end = s.lastIndexOf(']');
    if (start >= 0 && end > start) s = s.substring(start, end + 1);
    final out = <({String title, List<String> bullets})>[];
    try {
      final decoded = jsonDecode(s);
      if (decoded is List) {
        for (final e in decoded) {
          if (e is Map) {
            final title = (e['title'] ?? e['heading'] ?? '').toString();
            final rawB = e['bullets'] ?? e['points'] ?? e['body'];
            final bullets = <String>[];
            if (rawB is List) {
              for (final b in rawB) {
                final bs = b.toString().trim();
                if (bs.isNotEmpty) bullets.add(bs);
              }
            } else if (rawB is String && rawB.trim().isNotEmpty) {
              bullets.add(rawB.trim());
            }
            if (title.isNotEmpty || bullets.isNotEmpty) {
              out.add((title: title, bullets: bullets));
            }
          }
        }
      }
    } catch (_) {/* パース不可なら空 */}
    return out;
  }

  /// ── JSON 構造を期待する AI 呼び出し ──
  ///
  /// 内部で次の事をやる:
  /// - Gemini なら `responseMimeType: application/json` で確実に JSON を返してもらう
  /// - OpenAI なら `response_format: json_object` で同上
  /// - Claude は専用 JSON モードが無いので素直に投げる
  /// - 出力トークン上限を 4096〜8192 に増やして「JSON が途中で切れる」事故を防ぐ
  ///   (旧来 2048 上限で長い解説がよく途中で切れて parse 失敗していた)
  ///
  /// [detailed] が true の時は更に大きいトークンを許可する (詳しい解説向け)。
  Future<String> askAiForJson(String prompt, {bool detailed = false}) async {
    // 表を含む要約は JSON が長くなる。 上限が足りないと途中で切れて
    //   「構造を取得できませんでした」 になるので、 表対応にあわせて広げた。
    final maxTokens = detailed ? 12288 : 6144;
    // ★ askAi と同じく代行サーバー経由にする (= ユーザー要望: こちらが
    //   用意したキーのみ)。 ここだけ各社へ直接投げていたため、 BYOK を
    //   やめた後は 「APIキーが設定されていません」 で PDF 要約・用語解説・
    //   クイズなど構造化を使う機能が丸ごと動かなくなっていた。
    if (canUseAiRelay) {
      return askAiViaRelay(prompt, maxTokens: maxTokens);
    }
    if (relayApiBase.isEmpty || _relayAvailable != true) {
      throw Exception(t('relay.notConfigured'));
    }
    _notifyCreditShort();
      throw Exception(t('credit.insufficient'));
    // ignore: dead_code
    switch (_aiProvider) {
      case 'openai':
        return askOpenAi(prompt, jsonMode: true, maxTokensOverride: maxTokens);
      case 'anthropic':
        return askClaude(prompt, maxTokensOverride: maxTokens);
      case 'grok':
        return askGrok(prompt, jsonMode: true, maxTokensOverride: maxTokens);
      case 'deepseek':
        return askDeepseek(prompt,
            jsonMode: true, maxTokensOverride: maxTokens);
      case 'openrouter':
        return askOpenRouter(prompt,
            jsonMode: true, maxTokensOverride: maxTokens);
      case 'gemini':
      default:
        return askGemini(prompt, jsonMode: true, maxTokensOverride: maxTokens);
    }
  }

  /// AI に JSON 構造を要求し、解釈失敗時は 1 度だけ「JSON だけ返して」と
  /// 再試行してから諦める。最終的に失敗したら、AI が実際に返した文字列の
  /// 冒頭をエラーメッセージに含めて投げる (デバッグしやすくするため)。
  ///
  /// このヘルパは summarize / explain 共通で利用する。
  Future<Map<String, dynamic>> _askAiForJsonStructure(String prompt,
      {bool detailed = false}) async {
    String text;
    try {
      text = await askAiForJson(prompt, detailed: detailed);
    } catch (e) {
      // ネットワーク等のエラーはそのまま投げる (UI 側でメッセージ表示)
      rethrow;
    }
    Map<String, dynamic>? parsed = _extractJsonStructure(text);
    if (parsed != null) return parsed;

    // ── 1 回だけ「JSON のみで再出力して」とリトライ ──
    debugPrint('AI 出力 1 回目で JSON 抽出失敗。retry します。'
        '\n--- raw (head) ---\n${text.substring(0, text.length > 400 ? 400 : text.length)}');
    final retryPrompt = '''
あなたが直前に返した出力は有効な JSON ではありませんでした。
再度、有効な JSON オブジェクト 1 つだけを返してください。
コードフェンス、前置き、後置き、解説文、 // コメント、末尾カンマは
一切付けないでください。
内容が長くなりそうなら、項目数や文字数を減らして構造を簡潔にしてください。

直前の出力 (壊れた JSON):
$text
''';
    try {
      text = await askAiForJson(retryPrompt, detailed: detailed);
    } catch (e) {
      rethrow;
    }
    parsed = _extractJsonStructure(text);
    if (parsed != null) return parsed;

    // ── それでも失敗 → ユーザーに見える範囲で AI の応答を含めて throw ──
    final preview = text.length > 240 ? '${text.substring(0, 240)}…' : text;
    throw Exception('AI 出力から構造を取得できませんでした\n--- AI の応答 (冒頭) ---\n$preview');
  }

  /// http(s) URL かどうかをざっくり検証して返す。空文字や無効なら null。
  /// AI が `link_url` 等に何でも書いてくる可能性があるので、ノードに
  /// 入れる前にここで弾く。
  String? _validatedHttpUrl(dynamic v) {
    if (v == null) return null;
    if (v is! String) return null;
    final s = v.trim();
    if (s.isEmpty) return null;
    if (!s.startsWith('http://') && !s.startsWith('https://')) return null;
    return s;
  }

  /// URL が **実際に開けるか** を軽く確認する。
  ///
  /// AI は YouTube や Wikipedia の URL をそれっぽく作って返すことがある
  /// (ハルシネーション)。クリックすると 404 になる「飛べないリンク」を
  /// ノードに残しても害悪なので、ノード作成前にここで実在チェックする。
  ///
  /// - YouTube は HEAD だと「動画が無い」状態でも 200 を返してくる
  ///   (テンプレ HTML を返すだけ)。代わりに **oembed エンドポイント**
  ///   `https://www.youtube.com/oembed?url=...` を叩く。これは存在する
  ///   動画だけ 200 を返し、無い/非公開なら 401/404 を返す。
  /// - その他の URL は HEAD で statusCode を見る。HEAD を許さない (405) や
  ///   一部サイト (403 Forbidden) には GET でフォールバック。
  /// - 4xx と判定 / タイムアウト / DNS 失敗等は **すべて「実在しない」扱い**
  ///   (ユーザーは「正確に開けるリンクだけ欲しい」と明言している)。
  /// - 5xx は一時障害の可能性が高いので「実在する」として残す。
  Future<bool> _isUrlReachable(String url) async {
    try {
      final lower = url.toLowerCase();
      final isYoutube =
          lower.contains('youtube.com') || lower.contains('youtu.be');
      if (isYoutube) {
        final api = 'https://www.youtube.com/oembed?'
            'url=${Uri.encodeQueryComponent(url)}&format=json';
        final res =
            await http.get(Uri.parse(api)).timeout(const Duration(seconds: 5));
        return res.statusCode == 200;
      }
      // 一般 URL: HEAD → 405/403 なら GET フォールバック
      var res =
          await http.head(Uri.parse(url)).timeout(const Duration(seconds: 5));
      if (res.statusCode == 405 || res.statusCode == 403) {
        res =
            await http.get(Uri.parse(url)).timeout(const Duration(seconds: 7));
      }
      // 4xx は無効、5xx は一時障害扱いで残す
      if (res.statusCode >= 400 && res.statusCode < 500) return false;
      return true;
    } catch (_) {
      // タイムアウト・DNS 失敗 etc → 飛べない URL とみなす
      return false;
    }
  }

  /// AI が返した構造の中の `youtube_url` / `link_url` / `image_url` を
  /// 並列に reachability 確認して、**飛べないものは Map から削除**する。
  /// `_buildPageFromAiStructure` の直前で呼ぶ。
  Future<int> _validateUrlsInStructure(Map<String, dynamic> structure) async {
    // ノードの URL スロットを再帰的に集める
    final slots = <_UrlSlot>[];
    void scan(dynamic n) {
      if (n is Map) {
        for (final f in const [
          'youtube_url',
          'link_url',
          'image_url',
        ]) {
          final v = n[f];
          if (v is String && _validatedHttpUrl(v) != null) {
            slots.add(_UrlSlot(node: n, field: f, url: v.trim()));
          }
        }
        final c = n['children'];
        if (c is List) {
          for (final x in c) scan(x);
        }
        final r = n['roots'];
        if (r is List) {
          for (final x in r) scan(x);
        }
      }
    }

    scan(structure);
    if (slots.isEmpty) return 0;

    // 並列に reachability チェック (各 URL ごとに自前で 5〜7s timeout)
    final results = await Future.wait(
      slots.map((s) async {
        try {
          return await _isUrlReachable(s.url);
        } catch (_) {
          return false;
        }
      }),
    );

    // 飛べない URL は Map から削除
    int stripped = 0;
    for (int i = 0; i < slots.length; i++) {
      if (!results[i]) {
        slots[i].node.remove(slots[i].field);
        stripped++;
        debugPrint('URL validation: 飛べないため削除 ${slots[i].url}');
      }
    }
    return stripped;
  }

  /// AI に JSON 構造マップを生成してもらう共通プロンプトテンプレ。
  /// summarize と explain で同じスキーマを使うことで、後段の
  /// `_buildPageFromAiStructure` が両方の出力に対応できるようにする。
  ///
  /// [introLines] は機能ごとの「役割文」(例: "あなたは資料を構造化要約する..."
  /// "あなたは博識な解説者です..." 等)。
  /// [detail] は 'rough' | 'standard' | 'detailed' で、ノード数や階層の深さを変える。
  /// [userInstruction] はユーザーから入力された追加指示 (省略可)。
  String _buildAiStructurePrompt({
    required String introLines,
    required String detail,
    String userInstruction = '',
    // 資料 (PDF など) を読ませる時だけ true。 ページ番号や図の指定を許可する。
    bool sourceDocument = false,
  }) {
    String detailGuide;
    switch (detail) {
      case 'rough':
        detailGuide = '''
詳細レベル: 「分かり易く (要点のみ、初心者向け)」
- 主要トピックは 3〜5 個
- 階層は最大 2 階層 (深掘りはせず、まず全体像)
- 平易な言葉で、専門用語が出るときは memo で 1 文補足
- memo は 1 文程度に短く
- 表は本当に必要な時だけ 1 つまで
''';
        break;
      case 'detailed':
        detailGuide = '''
詳細レベル: 「詳しい (深掘り)」
- 主要トピックは 6〜10 個
- 階層は 3〜4 階層、可能なら具体例ノードまで含める
- memo は 1〜3 文 (要点 + 具体例)
- 数値・比較・分類は積極的に table にする (3〜6 個程度)
''';
        break;
      default:
        detailGuide = '''
詳細レベル: 「標準」
- 主要トピックは 4〜8 個
- 階層は 2〜3 階層
- memo は 1〜3 文の要点
- 数値・比較・分類があれば table にする (1〜3 個程度)
''';
    }

    final instruction = userInstruction.trim().isNotEmpty
        ? '\nユーザーからの追加指示: ${userInstruction.trim()}'
        : '';

    // 資料を読ませる時だけ使えるフィールド (ページ番号・図の指定)。
    final docFields = sourceDocument
        ? '''

  * "page": 任意・整数 (その内容が載っている資料のページ番号。1 始まり)
  * "figure": 任意・真偽値。 そのページに **図・グラフ・写真・回路図など、
    文章では伝わらない絵**があり、 それを見せた方が理解しやすい時だけ true。
    true にすると、 そのページの見た目をそのまま画像として貼り付けます。'''
        : '';

    // 資料要約のときだけ足す組み立て方の指示 (= ユーザー要望:
    //   階層構造で、 表や図も入った、 要点の整理された要約にしたい)。
    final docGuide = sourceDocument
        ? '''
資料のまとめ方:
- 1 番目のルートは必ず **「要点」** にし、 資料全体で最も大事な事を
  3〜5 個の子ノードに分けて置く (各 1 文)。 ここだけ読めば概要が分かる形。
- 2 番目以降のルートは、 **資料自身の章立て・見出しの順番**をなぞる。
  勝手に並べ替えたり、 独自の切り口に作り替えたりしない。
- 各セクションには、 分かる範囲で "page" を入れる (読み返す時の目印)。
- 数値・比較・分類・手順・用語一覧は、 文章にせず "table" にする。
- 図・グラフ・写真が要点になっているページには "figure": true を付ける
  (目安: 資料全体で 1〜4 か所。 付けすぎない)。
- 資料に書かれていない事を足さない。 推測を書くときは memo に「推測」 と記す。
- **言葉は資料のものをそのまま使う**。 「指標A」 「区分B」 「項目1」 のように
  中身の分からない言い換えに置き換えない。 表の見出しも行の名前も、
  資料に出てくる語 (例: 「通勤・通学」 「市場規模」) をそのまま書くこと。
  元の語が読み取れない時は、 その行を書かずに落とす。
'''
        : '';

    // 注意: 旧版は schema 例を [...] でぼかしていたため、AI が literal で
    // [...] を書いてきて JSON が壊れる事例があった。schema 例は
    // 完全に有効な JSON として書き、「これは構造の参考」とルール文で明示する。
    return '''
$introLines

出力は **必ず JSON オブジェクト 1 つのみ** とし、コードフェンス (\`\`\`)、
前置き、後置き、解説文、 // コメントは一切含めないでください。

JSON の形は次のとおり:
- トップに "title" (文字列、ページ全体のタイトル) を入れる。
- 内容は次の **どちらか** の形で表現する:
  * 単一ツリー型: トップに "children" (ノード配列) を直接付ける。
  * 複数ツリー型: トップに "roots" (ノード配列) を入れ、各要素を独立した
    マインドマップのルートとして扱う。1 つの親に無理にまとめなくて良い。
- 各ノードは次のフィールドを持つ:
  * "title": 必須・文字列
  * "memo": 任意・文字列 (1〜3 文の補足)
  * "children": 任意・同じ形のノード配列
  * "table": 任意・文字列の 2 次元配列 (先頭行が見出し)。
    数値・比較・分類・手順のように「表にした方が分かりやすい」 内容は
    memo に文章で書かず、 この table に入れること。
  * "table_caption": 任意・文字列 (table を付けた時の見出し。20 文字以内)
  * "youtube_url": 任意・文字列 (http(s):// で始まる YouTube 動画 URL)
  * "link_url": 任意・文字列 (Wikipedia など参考 web ページの URL)
  * "image_url": 任意・文字列 (画像の URL、link_url と同じ扱い)$docFields

例 (構造の参考。実際の内容は対象に合わせて差し替えること):
{
  "title": "ページ全体のタイトル",
  "roots": [
    {
      "title": "観点A",
      "memo": "概要",
      "children": [
        {"title": "詳細1", "memo": "短い説明",
         "link_url": "https://ja.wikipedia.org/wiki/Example"},
        {"title": "詳細2",
         "table_caption": "年度別の売上",
         "table": [["年度", "売上", "前年比"],
                   ["2024", "120 億円", "+8%"],
                   ["2025", "138 億円", "+15%"]]}
      ]
    },
    {"title": "観点B", "memo": "別軸の見方"}
  ]
}

$detailGuide
ルール:
- title は短く (15〜25文字目安)。
- **冗長な前置き・繰り返しは禁止**:
  * 子ノードの title に親や全体のテーマ名を再度含めない
    (例: テーマが「都道府県の有名人」で子が「茨城県」なら、
     "都道府県の有名人のうち茨城県の有名人" ではなく単に「茨城県」と書く)。
  * memo に「ここでは…を解説します」「本項では…」のような前置きを入れない。
    内容そのものを 1〜3 文で簡潔に書く。
- youtube_url / link_url / image_url は **書かない方が安全**。本当に実在し、
  かつ自分の記憶で URL を正しく覚えているとほぼ確信できる時にだけ書くこと。
  少しでも不安なら省略してください。**架空の URL は絶対に書かないこと**
  (出力後に実在チェックを行い、飛べないリンクは自動で破棄されます)。
- YouTube URL を書く場合は、有名なチャンネルの代表的な動画など、出力時に
  実在を強く確信できるものに限定すること。
- 1 つにまとめづらいテーマは "roots" 形式で 2〜4 個のツリーに分割可。
- table は 2 次元配列。 各行の列数は揃え、 セルは短く (15 文字以内目安)。
  列は 5 列まで、 行は見出しを含めて 12 行までに収めること。
- 文字列内のダブルクォートは必ず \\ でエスケープすること。
- 末尾カンマや // コメントは絶対に書かないこと。
$docGuide$instruction
''';
  }

  /// AI が返した "table" を、 レイアウトに乗せられる形の子ノードへ展開する
  /// (= ユーザー要望: 要約に表を入れたい)。
  ///
  /// `{"title": "...", "table": [[...]], "children": [...]}` を
  /// `{"title": "...", "children": [..., {"__table": [[...]], "title": "見出し"}]}`
  /// に書き換える。 表そのものは兄弟の一番下に置く (本文の子より下)。
  ///
  /// 併せて `"figure": true` + `"page"` のノードには、 呼び出し側が用意した
  /// ページ画像 ([pageImages] の page → ファイルパス) を画像ノードとして足す。
  void _expandAiExtras(
    Map<String, dynamic> node, {
    Map<int, String> pageImages = const {},
    Map<int, double> pageAspects = const {},
  }) {
    final extras = <Map<String, dynamic>>[];

    // ── 表 ──
    final rows = _normalizeAiTable(node['table']);
    if (rows != null) {
      final caption = '${node['table_caption'] ?? ''}'.trim();
      extras.add(<String, dynamic>{
        'title': caption.isEmpty ? '表' : caption,
        '__table': rows,
      });
    }
    node.remove('table');
    node.remove('table_caption');

    // ── 図 (ページの見た目をそのまま貼る) ──
    final page = (node['page'] as num?)?.toInt();
    final wantsFigure = node['figure'] == true;
    if (wantsFigure && page != null && pageImages.containsKey(page)) {
      extras.add(<String, dynamic>{
        'title': '図 (p.$page)',
        '__imagePath': pageImages[page],
        // 縦横比が分かっていないと場所取りを誤り、 隣のノードが絵に
        //   重なってしまう。 分からない時は A4 縦を仮に使う。
        '__imageAspect': pageAspects[page] ?? 0.71,
      });
    }
    node.remove('figure');

    // ── ページ番号を memo の末尾に控える (読み返す時の目印) ──
    if (page != null && page > 0) {
      final memo = '${node['memo'] ?? ''}'.trim();
      node['memo'] = memo.isEmpty ? 'p.$page' : '$memo\np.$page';
    }
    node.remove('page');

    // ── 子を再帰的に処理してから extras を後ろへ足す ──
    final children = node['children'];
    final list = <dynamic>[];
    if (children is List) {
      for (final c in children) {
        if (c is Map) {
          final m = c.map((k, v) => MapEntry(k.toString(), v));
          _expandAiExtras(m,
              pageImages: pageImages, pageAspects: pageAspects);
          list.add(m);
        }
      }
    }
    list.addAll(extras);
    if (list.isNotEmpty) node['children'] = list;
  }

  /// AI が返した table を `List<List<String>>` に正規化する。
  /// 形が壊れている / 実質空 の場合は null を返して表を作らない。
  List<List<String>>? _normalizeAiTable(dynamic raw) {
    if (raw is! List || raw.isEmpty) return null;
    final rows = <List<String>>[];
    for (final r in raw) {
      if (r is List) {
        rows.add([for (final c in r) '${c ?? ''}'.trim()]);
      } else if (r is Map) {
        // {"列名": "値"} 形式で返してくる事があるので値だけ拾う。
        rows.add([for (final v in r.values) '${v ?? ''}'.trim()]);
      }
    }
    if (rows.isEmpty) return null;
    final cols = rows.fold<int>(0, (m, r) => math.max(m, r.length));
    if (cols == 0) return null;
    // 列数を揃え、 行数・列数に上限を掛ける (巨大な表でマップが壊れないように)。
    const maxCols = 6;
    const maxRows = 14;
    final c = math.min(cols, maxCols);
    final out = <List<String>>[];
    for (final r in rows.take(maxRows)) {
      out.add([for (var i = 0; i < c; i++) i < r.length ? r[i] : '']);
    }
    // 中身が全部空なら表にしない。
    if (out.every((r) => r.every((cell) => cell.isEmpty))) return null;
    return out;
  }

  /// 構造全体から「図を貼りたいページ番号」を集める (最大 [limit] 件)。
  Set<int> _collectAiFigurePages(Map<String, dynamic> structure,
      {int limit = 4}) {
    final pages = <int>{};
    void walk(dynamic n) {
      if (pages.length >= limit) return;
      if (n is List) {
        for (final e in n) {
          walk(e);
        }
        return;
      }
      if (n is! Map) return;
      if (n['figure'] == true) {
        final p = (n['page'] as num?)?.toInt();
        if (p != null && p > 0) pages.add(p);
      }
      walk(n['children']);
      walk(n['roots']);
    }

    walk(structure['roots']);
    walk(structure['children']);
    return pages;
  }

  /// AI 構造 JSON (top: {title, roots? | children?, ...}) からノードを配置する
  /// 共通の後段処理。summarize / explain 両方から呼ばれる。
  ///
  /// 「単一ツリー型」(top.children) も「複数ツリー型」(top.roots) も両対応。
  /// 複数ツリー型の場合、各ツリーは縦に積んで配置 (X は同じ列、Y を順に下げる)。
  /// 1 つでも複数でも同じレイアウト関数 [_placeAiSummaryChildren] を再利用する。
  ///
  /// [structure] は AI が返した JSON。`_extractJsonStructure` の戻り値。
  /// [fallbackTitle] は title が無かった時のページ名 (ファイル名 or 用語名)。
  AiMapResult _buildPageFromAiStructure({
    required Map<String, dynamic> structure,
    required String fallbackTitle,
    required bool addToCurrentPage,
    required Offset rootPosition,
    // ファイル要約モードでは true。AI が返した roots/children を全て
    // [fallbackTitle] (= ファイル名) を頂点とする 1 つのツリーの子としてぶら下げる。
    // ユーザー要望: 「読み込ませたファイルが一番上の親ノードになるように」
    bool wrapWithFileTitle = false,
  }) {
    // ── ルート群を抽出 ──
    // 新フォーマット: top.roots が配列 → そのまま採用
    // 旧/単一: top.children を持つ → 全体を 1 ルートとして扱う
    final rootEntries = <Map<String, dynamic>>[];
    final rootsRaw = structure['roots'];
    if (rootsRaw is List && rootsRaw.isNotEmpty) {
      for (final r in rootsRaw) {
        if (r is Map) {
          rootEntries.add(r.map((k, v) => MapEntry(k.toString(), v)));
        }
      }
    }
    if (rootEntries.isEmpty) {
      // top の title/memo/children/url を「単一ルート」と見立てる
      rootEntries.add(<String, dynamic>{
        'title': structure['title'] ?? fallbackTitle,
        'memo': structure['memo'],
        'children': structure['children'] ?? const [],
        'youtube_url': structure['youtube_url'],
        'link_url': structure['link_url'],
        'image_url': structure['image_url'],
      });
    }

    // ── ファイル要約モード: ファイル名を頂点として全 roots を子として束ねる ──
    // wrap 後は rootEntries が 1 つだけになり、その children が元の roots。
    // 旧構造から fileName をルートに変える効果と、AI が複数 roots を返した時
    // それらが「セクション」のように頂点ファイル名にぶら下がる効果がある。
    if (wrapWithFileTitle) {
      final wrappedChildren =
          rootEntries.map((r) => Map<String, dynamic>.from(r)).toList();
      rootEntries
        ..clear()
        ..add(<String, dynamic>{
          'title': fallbackTitle,
          'memo': null,
          'children': wrappedChildren,
        });
    }

    // ── ページ名: ファイル要約モードは fallbackTitle (= ファイル名) を採用 ──
    // wrap した時に root が fileName になっているので、ページ名もそれに揃える。
    String pageTitle;
    if (wrapWithFileTitle) {
      pageTitle = fallbackTitle;
    } else {
      final topTitle = (structure['title'] as String?)?.trim();
      if (topTitle != null && topTitle.isNotEmpty) {
        pageTitle = topTitle;
      } else {
        final firstT = (rootEntries[0]['title'] as String?)?.trim();
        pageTitle =
            (firstT != null && firstT.isNotEmpty) ? firstT : fallbackTitle;
      }
    }

    if (!addToCurrentPage) {
      addPage(name: pageTitle);
    }
    final pageIdx = _currentPageIndex;

    const minVerticalGap = 40.0;
    const interRootGap = 80.0; // ルートツリー間に追加で空ける
    const rootW = 220.0;
    const rootH = 60.0;

    // 各ルートの占有高さを事前計算
    final rootHeights = rootEntries
        .map((r) => _computeAiSubtreeHeight(r, minVerticalGap))
        .toList();

    // 全体の縦方向合計
    double totalH = 0;
    for (int i = 0; i < rootHeights.length; i++) {
      totalH += rootHeights[i];
      if (i < rootHeights.length - 1) totalH += interRootGap;
    }

    // 中心揃え: 「ルート全体の縦中心」を「rootPosition の縦中心 (= rootPos.dy + rootH/2)」
    // に合わせる。これで単一ルートだった時と複数ルートだった時で、ユーザーから見た
    // 出現位置が大きくぶれない。
    final anchorCenterY = rootPosition.dy + rootH / 2;
    double currentY = anchorCenterY - totalH / 2;

    String? firstRootId;
    Offset firstRootTopLeft = rootPosition;

    for (int i = 0; i < rootEntries.length; i++) {
      final entry = rootEntries[i];
      final subH = rootHeights[i];

      final title = (entry['title'] as String?)?.trim() ?? '';
      if (title.isEmpty) {
        currentY += subH + interRootGap;
        continue;
      }
      final memo = (entry['memo'] as String?)?.trim();
      final ytUrl = _validatedHttpUrl(entry['youtube_url']);
      final linkUrl = _validatedHttpUrl(entry['link_url']) ??
          _validatedHttpUrl(entry['image_url']);
      final children = (entry['children'] as List<dynamic>?) ?? const [];

      // このルートのスロット中心 (孫もここを基準に上下対称化)
      final slotCenterY = currentY + subH / 2;
      final rootTopLeft = Offset(rootPosition.dx, slotCenterY - rootH / 2);

      // contentType: youtube > link > memo > none の優先順
      NodeContentType ct = NodeContentType.none;
      if (ytUrl != null) {
        ct = NodeContentType.youtube;
      } else if (linkUrl != null) {
        ct = NodeContentType.link;
      } else if (memo != null && memo.isNotEmpty) {
        ct = NodeContentType.memo;
      }

      final root = MindMapNode(
        id: _uuid.v4(),
        title: title.length > 30 ? '${title.substring(0, 30)}…' : title,
        position: rootTopLeft,
        width: rootW,
        height: rootH,
        color: const Color(0xFF6C63FF),
        memoText: memo,
        youtubeUrl: ytUrl,
        linkUrl: linkUrl,
        contentType: ct,
      );
      currentPage.nodes[root.id] = root;
      if (firstRootId == null) {
        firstRootId = root.id;
        firstRootTopLeft = rootTopLeft;
      }

      if (children.isNotEmpty) {
        // 複数ルートの場合、ルートごとに違う「色シード」で開始する。
        // 単一ルート (= ファイル要約 wrap モード) の場合は i=0 で始まる。
        // 係数 3 はパレット長 8 と互いに素 (i*3 が散らせる)。
        _placeAiSummaryChildren(
          parent: root,
          childrenJson: children,
          depth: 1,
          siblingsCount: children.length,
          parentSlotCenterY: slotCenterY,
          parentColorIdx: (i * _kAiPaletteStep) % _kAiNodePalette.length,
        );
      }

      currentY += subH + interRootGap;
    }

    _saveToStorage();
    notifyListeners();
    return AiMapResult(
      pageIndex: pageIdx,
      rootId: firstRootId ?? '',
      rootPosition: firstRootTopLeft,
      addedToCurrentPage: addToCurrentPage,
    );
  }

  /// ── ファイル要約 → マインドマップ化 ──
  /// 与えられたファイルの内容を AI で要約し、階層構造を取り出して
  /// マインドマップとして配置する。
  ///
  /// [addToCurrentPage] が true の場合は新規ページを作らず、現在ページに
  /// 追加する。false の場合は新規ページを作って配置する (旧来の動作)。
  /// [rootPosition] はルートノードを置く canvas 座標 (左上)。
  /// 「現在ページに追加」モードで「画面に映っている領域」に置きたい時は
  /// 画面側で viewport 中心の canvas 座標を計算して渡す。
  ///
  /// 対応形式:
  ///   - テキスト系 (.txt/.md/.csv/.json/.log/.py/.dart など): UTF-8 として直接読む
  ///   - PDF/docx/pptx: Gemini に inline_data で渡す or Claude にドキュメント
  ///                    として渡す (両 API ともネイティブ対応)
  ///                    OpenAI は対応外なので一時的に Gemini にフォールバック。
  ///
  /// 戻り値: AiMapResult (どのページの どの canvas 位置に作ったか)。
  /// エラーは throw する (UI 側で SnackBar に表示)。
  Future<AiMapResult> summarizeFileToNewPage({
    required String filePath,
    required String fileName,
    String? userInstruction,
    bool addToCurrentPage = false,
    Offset rootPosition = const Offset(2000, 2000),
    String detail = 'standard', // 'rough' | 'standard' | 'detailed'
    String? pretext, // = ユーザー要望: 抽出済みテキスト (非 Gemini で PDF 等)
    // = ユーザー要望: 図が要点になっているページは、 見た目をそのまま画像で
    //   貼る。 ページ画像の生成は画面側 (printing) に任せ、 ここは 1 始まりの
    //   ページ番号を渡して保存先パスを受け取るだけにする。
    Future<String?> Function(int pageNumber)? renderPage,
  }) async {
    final f = File(filePath);
    if (!await f.exists()) {
      throw Exception('File not found: $filePath');
    }
    // 拡張子で形式を判定
    final dot = fileName.lastIndexOf('.');
    final ext = dot >= 0 ? fileName.substring(dot + 1).toLowerCase() : '';
    const textExts = {
      'txt',
      'md',
      'markdown',
      'csv',
      'tsv',
      'json',
      'log',
      'dart',
      'py',
      'js',
      'ts',
      'java',
      'kt',
      'cpp',
      'c',
      'h',
      'hpp',
      'cs',
      'go',
      'rb',
      'rs',
      'swift',
      'sh',
      'yml',
      'yaml',
      'xml',
      'html',
      'htm',
      'css',
    };
    const binaryDocExts = {'pdf', 'docx', 'pptx'};

    // 統一プロンプトテンプレ + ファイル要約用の役割文
    final structurePrompt = _buildAiStructurePrompt(
      introLines: 'あなたは資料を構造化要約するアシスタントです。\n'
          '渡された資料 ($fileName) の内容を読み、要旨を階層的なマインドマップに変換してください。',
      detail: detail,
      userInstruction: userInstruction ?? '',
      // 資料が元なので、 ページ番号と図の指定を許可する。
      sourceDocument: true,
    );

    // ── AI 呼び出し: バイナリ系は専用経路、テキスト系/その他は本文を結合 ──
    Map<String, dynamic> structure;
    // 追加質問機能 (askAiFollowUpForPage) で再利用するための「資料の文脈」を
    // ここで掴んでおく。テキスト系なら本文 (truncate 済み) を、バイナリ系なら
    // ファイルパスだけを保持する。
    String? capturedTextContent;
    String? capturedBinaryPath;

    if (pretext != null && pretext.trim().isNotEmpty) {
      // = ユーザー要望: 抽出済みテキスト (PDF 等) を選択中プロバイダで要約。
      //   Gemini 以外はバイナリを直接読めないため、 呼び出し側でテキスト抽出。
      var content = pretext;
      const int kMaxChars = 60000;
      if (content.length > kMaxChars) {
        content = '${content.substring(0, kMaxChars)}\n... [truncated]';
      }
      capturedTextContent = content;
      structure = await _askAiForJsonStructure(
          '$structurePrompt\n\n--- 資料の内容 ---\n$content',
          detailed: detail == 'detailed');
    } else if (textExts.contains(ext)) {
      // ── テキスト直接読み込み ──
      String content;
      try {
        content = await f.readAsString();
      } catch (_) {
        // UTF-8 で読めなかった場合 (Shift-JIS など) はバイトから latin1 経由で
        final bytes = await f.readAsBytes();
        content = String.fromCharCodes(bytes);
      }
      // 巨大ファイルは AI コンテキスト制限を超えるので 60,000 文字に制限
      const int kMaxChars = 60000;
      if (content.length > kMaxChars) {
        content = '${content.substring(0, kMaxChars)}\n... [truncated]';
      }
      capturedTextContent = content;
      final fullPrompt = '$structurePrompt\n\n--- 資料の内容 ---\n$content';
      // 構造化 JSON 取得 (失敗時は内部で 1 度自動再試行)
      structure = await _askAiForJsonStructure(fullPrompt,
          detailed: detail == 'detailed');
    } else if (binaryDocExts.contains(ext)) {
      // ── バイナリドキュメント (PDF/docx/pptx) ──
      // バイナリを直接送る経路は各社のキーを直に使うため、 代行 (アプリ側の
      //   キー) だけで動かす今の作りでは使えない。 代行が使える時は、
      //   呼び出し側が抜き出した本文 (pretext) が来ているはずなのでそちらを
      //   使う。 本文が取れなかった時だけ、 従来のバイナリ送信を試す。
      if (canUseAiRelay) {
        throw Exception(t('aiSummary.textExtractFailed'));
      }
      capturedBinaryPath = filePath;
      final aiResponseText = await _askAiWithBinaryDoc(
        filePath: filePath,
        fileName: fileName,
        ext: ext,
        prompt: structurePrompt,
      );
      final parsed = _extractJsonStructure(aiResponseText);
      if (parsed == null) {
        debugPrint('AI 出力 (JSON抽出失敗): $aiResponseText');
        final preview = aiResponseText.length > 240
            ? '${aiResponseText.substring(0, 240)}…'
            : aiResponseText;
        throw Exception('AI 出力から構造を取得できませんでした\n--- AI の応答 (冒頭) ---\n$preview');
      }
      structure = parsed;
    } else {
      // それ以外 (画像など) はテキスト読み込みを試行 → 失敗ならエラー
      try {
        final content = await f.readAsString();
        final truncated = content.length > 60000
            ? '${content.substring(0, 60000)}\n... [truncated]'
            : content;
        capturedTextContent = truncated;
        structure = await _askAiForJsonStructure(
            '$structurePrompt\n\n--- 資料の内容 ---\n$truncated',
            detailed: detail == 'detailed');
      } catch (_) {
        throw Exception('未対応のファイル形式です: .$ext');
      }
    }

    // ── URL 実在チェック (飛べないリンクをノードに残さない) ──
    // AI が hallucinate した YouTube/Wikipedia URL をここで弾く。
    // 並列に reachability 確認 → 飛べないものは structure から削除。
    await _validateUrlsInStructure(structure);

    // ── 図に指定されたページを画像にする (= ユーザー要望: 図も入れたい) ──
    // 生成は重いので、 上限 4 ページまで。 失敗したページは黙って諦める
    // (図が無くても要約自体は成立するため)。
    final pageImages = <int, String>{};
    final pageAspects = <int, double>{};
    if (renderPage != null) {
      for (final p in _collectAiFigurePages(structure)) {
        try {
          final path = await renderPage(p);
          if (path == null || path.isEmpty) continue;
          pageImages[p] = path;
          // 縦横比が分かってから並べる。 後から当てると、 一度は違う高さで
          //   置かれてしまい、 隣のノードが絵に重なる。
          final ar = await _imageAspectOfFile(path);
          if (ar != null) pageAspects[p] = ar;
        } catch (_) {}
      }
    }

    // ── table / figure / page を、 レイアウトに乗る形へ展開する ──
    // `_expandAiExtras` は渡した Map を書き換えるので、 作り直した Map を
    // 元のリストへ入れ直す (そうしないと変換結果が捨てられる)。
    for (final key in const ['roots', 'children']) {
      final list = structure[key];
      if (list is! List) continue;
      for (var i = 0; i < list.length; i++) {
        final e = list[i];
        if (e is! Map) continue;
        final m = e.map((k, v) => MapEntry(k.toString(), v));
        _expandAiExtras(m, pageImages: pageImages, pageAspects: pageAspects);
        list[i] = m;
      }
    }

    // ── 構造をページに展開 (単一ツリー / 複数ツリー両対応) ──
    // ユーザー要望: ファイル要約はファイル名を一番上の親ノードに置き、
    // AI が返したセクション群をその子としてぶら下げる。
    final result = _buildPageFromAiStructure(
      structure: structure,
      fallbackTitle: fileName,
      addToCurrentPage: addToCurrentPage,
      rootPosition: rootPosition,
      wrapWithFileTitle: true,
    );

    // ── 追加質問用の文脈を保存 ──
    // 配置されたページ (新規 or 現在) の id をキーにして資料情報を保持。
    // ユーザーが後で「資料に関する追加質問」をしたら askAiFollowUpForPage が参照する。
    if (result.pageIndex >= 0 && result.pageIndex < _pages.length) {
      final pageId = _pages[result.pageIndex].id;
      _aiPageContexts[pageId] = AiPageContext(
        fileName: fileName,
        textContent: capturedTextContent,
        filePath: capturedBinaryPath,
        ext: ext,
      );
    }
    return result;
  }

  /// ── 用語・概念を AI に解説させてマインドマップ化 ──
  /// summarizeFileToNewPage のテキスト版/対話版。ファイルではなくユーザーが
  /// 入力した用語 (例: "オートエンコーダ" "三段論法") を AI に解説させ、
  /// その階層構造をマインドマップに展開する。
  ///
  /// [addToCurrentPage] が true なら新規ページを作らず現在ページに追加。
  /// [rootPosition] はルートノードを置く canvas 座標。
  /// [detail] は 'rough' | 'standard' | 'detailed' で、解説の深さを変える。
  /// [comprehensive] が true の場合は **網羅モード**: 1 回の AI 出力に
  /// 収まらないテーマ (例: "都道府県毎の有名人") を複数回に分けて生成し、
  /// 最後に 1 ページに統合する。詳細は `_explainConceptComprehensive` 参照。
  /// [onProgress] は網羅モード中の進捗通知 (current, total, currentLabel)。
  /// 戻り値: AiMapResult。
  /// エラーは throw する (UI 側で SnackBar に表示)。
  Future<AiMapResult> explainConceptToNewPage({
    required String term,
    String? userInstruction,
    bool addToCurrentPage = false,
    Offset rootPosition = const Offset(2000, 2000),
    String detail = 'standard',
    bool comprehensive = false,
    void Function(int current, int total, String currentLabel)? onProgress,
  }) async {
    if (term.trim().isEmpty) {
      throw Exception('用語・概念が空です');
    }
    final cleanTerm = term.trim();

    if (comprehensive) {
      // 網羅モード: 単発の AI 呼び出しでは出力トークン上限で全項目を埋め切れない
      // 場合に、計画 → 分割実行 → マージ の 3 段階で完全網羅を狙う。
      return _explainConceptComprehensive(
        term: cleanTerm,
        userInstruction: userInstruction ?? '',
        addToCurrentPage: addToCurrentPage,
        rootPosition: rootPosition,
        detail: detail,
        onProgress: onProgress,
      );
    }

    // 統一プロンプトテンプレ + 用語解説用の役割文
    final structurePrompt = _buildAiStructurePrompt(
      introLines: 'あなたは博識な解説者です。\n'
          'ユーザーから提示された用語・概念「$cleanTerm」を、初学者にも理解できるように\n'
          '階層的なマインドマップに整理して解説してください。\n'
          '内容に応じて「概要」「主な構成要素・仕組み」「応用例」「関連概念」「歴史」'
          '「メリット/デメリット」「よくある誤解」などの観点を適宜含めること。\n'
          '1 つの親に無理にまとめづらいテーマは、複数のルート (roots 形式) に分けて構わない。',
      detail: detail,
      userInstruction: userInstruction ?? '',
    );

    // JSON 構造を取得 (失敗時は内部で 1 度自動再試行 + 詳細エラー)
    final structure = await _askAiForJsonStructure(structurePrompt,
        detailed: detail == 'detailed');

    // URL 実在チェック (飛べないリンクは structure から削除)
    await _validateUrlsInStructure(structure);

    // 構造をページに展開 (単一ツリー / 複数ツリー両対応 + URL/画像対応)
    return _buildPageFromAiStructure(
      structure: structure,
      fallbackTitle: cleanTerm,
      addToCurrentPage: addToCurrentPage,
      rootPosition: rootPosition,
    );
  }

  /// 網羅モードの本体。
  ///
  /// 設計思想:
  /// 「都道府県毎の有名人」「世界の主要都市」「全大統領」のような **対象が
  /// 多く 1 回の AI 出力では出力トークン上限で途中切れする** トピックを、
  /// 計画 (Plan) → 分割実行 (Expand) → 統合 (Merge) の 3 段階で確実に網羅する。
  ///
  /// 1. **Plan フェーズ**:
  ///    AI に「このテーマを網羅するなら、何を子テーマとして列挙すべき?」と
  ///    だけ聞き、平坦な配列で返してもらう。schema は
  ///    `{ "title": "...", "subjects": [ { "name": "..." }, ... ] }` 形式。
  ///    都道府県なら 47 個、国連加盟国なら 193 個といった具合。
  ///
  /// 2. **Expand フェーズ**:
  ///    Plan で得た subjects を batch サイズ (デフォルト 4) で区切り、
  ///    各バッチについて「これらの子テーマ <X1, X2, ...> について
  ///    それぞれ階層的な内容を JSON で返して」と AI に問い合わせる。
  ///    各バッチの応答は roots 配列 (バッチ内で 1 root = 1 subject) として
  ///    返ってくる前提。バッチが小さいことで出力上限切れを避けられる。
  ///
  /// 3. **Merge フェーズ**:
  ///    全バッチの roots を 1 つの親ルート (term) の children として連結し、
  ///    `_buildPageFromAiStructure` で配置する。これによりユーザー視点では
  ///    「1 つの大きなマインドマップ」として見える。
  ///
  /// [onProgress] は (current=完了済 subject 数, total=全 subject 数, label=現在処理中の subject)
  /// で UI へ進捗を通知 (省略可能)。
  Future<AiMapResult> _explainConceptComprehensive({
    required String term,
    required String userInstruction,
    required bool addToCurrentPage,
    required Offset rootPosition,
    required String detail,
    void Function(int current, int total, String currentLabel)? onProgress,
  }) async {
    // 二重起動を防ぐ。直前の生成がまだ in-flight ならエラーで弾く。
    if (_explainInProgress) {
      throw Exception('別の AI 解説生成が進行中です。完了/停止してから再実行してください。');
    }
    _explainInProgress = true;
    _explainCancelRequested = false;
    notifyListeners();

    try {
      final hint = userInstruction.trim().isNotEmpty
          ? '\nユーザーからの追加指示: ${userInstruction.trim()}'
          : '';

      // ── (1) Plan フェーズ: 子テーマを列挙させる ──
      onProgress?.call(0, 0, '計画中…');
      final planPrompt = '''
あなたはマインドマップを設計するアシスタントです。
ユーザーが与えるテーマ「$term」を **網羅的に** 解説するマインドマップを作る
ための、最初の枝分かれ (子テーマ) を列挙してください。

例:
- テーマが「都道府県毎の有名人」なら 47 都道府県すべてを列挙
- テーマが「世界の通貨」なら主要通貨を 30〜80 件
- テーマが「人体の臓器」なら主要臓器を 15〜30 件
- テーマが「日本史の時代区分」なら全時代区分を漏れなく

返却は JSON 1 個のみ。コードフェンス、前置き、後置き等は禁止:
{
  "title": "$term",
  "subjects": [
    {"name": "子テーマ1の名前"},
    {"name": "子テーマ2の名前"}
  ]
}

ルール:
- subjects の各 name は短く (15〜25文字目安)。
- **網羅性最優先**: 知っている限り全部列挙すること。
  「など」「ほか」「主要なもののみ」で省略してはいけない。
- name は対象そのものの呼び名 ("茨城県" "ドル" など) のみで、
  テーマ名 ("$term") を再度含めない (重複表示は禁止)。
- 順序は分かりやすい順 (五十音/北→南/古→新 等) で。
- 数が膨大すぎる場合は 200 件で打ち切り、その旨は出力しない (黙って先頭 200)。$hint
''';

      final plan = await _askAiForJsonStructure(planPrompt, detailed: true);
      final subjectsRaw = plan['subjects'];
      if (subjectsRaw is! List || subjectsRaw.isEmpty) {
        throw Exception('AI が網羅対象を列挙できませんでした (subjects が空)');
      }
      final subjects = <String>[];
      for (final s in subjectsRaw) {
        if (s is Map) {
          final n = (s['name'] as String?)?.trim();
          if (n != null && n.isNotEmpty) subjects.add(n);
        } else if (s is String) {
          if (s.trim().isNotEmpty) subjects.add(s.trim());
        }
      }
      if (subjects.isEmpty) {
        throw Exception('AI が網羅対象を列挙できませんでした (有効な name が無い)');
      }
      debugPrint('網羅モード: ${subjects.length} 件の subject を計画');

      // ── (2) Expand フェーズ: バッチごとに詳細展開 ──
      // batch サイズは detail に応じて調整。詳しいモードはバッチを小さくして
      // 出力切れを避ける。
      final batchSize = detail == 'detailed' ? 3 : (detail == 'rough' ? 6 : 4);

      final allRoots = <Map<String, dynamic>>[];
      int processed = 0;
      final total = subjects.length;

      // キャンセル発生時にどこで止めたかを記録 (これ以降の subject は
      // 再開セッションに保存される)。
      int cancelAtIndex = -1;

      for (int i = 0; i < subjects.length; i += batchSize) {
        // 各バッチの直前で停止リクエストをチェック。
        // 現在のバッチが既に AI 通信を開始していたら最後まで完走させ、
        // 次のバッチの直前でループを抜ける。
        if (_explainCancelRequested) {
          cancelAtIndex = i;
          debugPrint('網羅モード: キャンセル要求を検知。$i 件目以降を保留に。');
          break;
        }

        final batchEnd = (i + batchSize).clamp(0, subjects.length);
        final batch = subjects.sublist(i, batchEnd);
        onProgress?.call(processed, total, batch.first);

        // バッチ用プロンプト: 各 subject を独立した root にして、その下に
        // 詳細を階層展開する。
        final batchPrompt = _buildBatchExpandPrompt(
          masterTheme: term,
          batchSubjects: batch,
          detail: detail,
          userInstruction: userInstruction,
        );

        Map<String, dynamic>? batchStruct;
        try {
          batchStruct = await _askAiForJsonStructure(batchPrompt,
              detailed: detail == 'detailed');
        } catch (e) {
          // 1 バッチ失敗しても他のバッチは続行 (網羅モードの目的は最大限カバー)
          debugPrint('網羅モード: バッチ失敗 [$batch] → スキップ: $e');
          processed = batchEnd;
          continue;
        }

        // 各 subject を root として取り出して allRoots に追加
        // batchStruct.roots がある場合はそれを使用。無ければ subject ごとに
        // 「name に一致する root」を探して追加。
        final batchRoots = batchStruct['roots'];
        if (batchRoots is List) {
          for (final r in batchRoots) {
            if (r is Map) {
              allRoots.add(r.map((k, v) => MapEntry(k.toString(), v)));
            }
          }
        } else {
          // フォールバック: top.children をそのまま使う (1 root しか作れなかった場合)
          if (batchStruct['children'] is List) {
            allRoots.add(<String, dynamic>{
              'title': batchStruct['title'] ?? batch.first,
              'children': batchStruct['children'],
            });
          }
        }
        processed = batchEnd;
        onProgress?.call(processed, total, batch.last);
      }

      // 何 1 つも完了する前にキャンセルされた場合: 配置するものが無いので
      // セッションを保存せずに例外を投げる (ユーザーに「停止しました」とだけ伝える)。
      if (allRoots.isEmpty) {
        if (cancelAtIndex == 0) {
          throw Exception('停止しました (まだ何も生成されていません)');
        }
        throw Exception('AI が網羅展開に失敗しました (全バッチがエラー)');
      }

      // ── (3) Merge フェーズ: 全 root を 1 つの親 (term) 配下にまとめる ──
      // top.title = テーマ全体名、children = 各 subject の root を平坦化したもの
      // (各 subject root の title/memo/youtube_url/link_url/image_url/children を保持)
      final mergedStructure = <String, dynamic>{
        'title': term,
        'children': allRoots,
      };

      // URL 実在チェック (飛べないリンクは削除)
      await _validateUrlsInStructure(mergedStructure);

      final result = _buildPageFromAiStructure(
        structure: mergedStructure,
        fallbackTitle: term,
        addToCurrentPage: addToCurrentPage,
        rootPosition: rootPosition,
      );

      // キャンセルされていた場合は、残りの subject を再開セッションとして保存。
      if (cancelAtIndex >= 0 && cancelAtIndex < subjects.length) {
        final remaining = subjects.sublist(cancelAtIndex);
        if (remaining.isNotEmpty &&
            result.pageIndex >= 0 &&
            result.pageIndex < _pages.length) {
          final page = _pages[result.pageIndex];
          _pausedExplainSession = PausedExplainSession(
            term: term,
            userInstruction: userInstruction,
            detail: detail,
            pageIndex: result.pageIndex,
            pageId: page.id,
            parentRootId: result.rootId,
            remainingSubjects: remaining,
            doneCount: cancelAtIndex,
            totalCount: subjects.length,
          );
          debugPrint('網羅モード: 一時停止セッションを保存 (残 ${remaining.length} 件)');
        }
      } else {
        // 完走した場合は古いセッションをクリア (もし残ってれば)
        _pausedExplainSession = null;
      }

      return result;
    } finally {
      _explainInProgress = false;
      _explainCancelRequested = false;
      notifyListeners();
    }
  }

  /// 一時停止された網羅モード解説を続きから再開する。
  ///
  /// `_pausedExplainSession` が無い場合は throw。
  /// 既存のページの parent root の子としてさらに subject roots を追記する。
  /// 全ての残り subject を完了したらセッションは破棄、再度途中停止された場合は
  /// セッションを更新して保持する。
  ///
  /// 戻り値: AiMapResult (該当ページの index と parent root の id を返す)。
  Future<AiMapResult> resumeExplainConcept({
    void Function(int current, int total, String currentLabel)? onProgress,
  }) async {
    final session = _pausedExplainSession;
    if (session == null) {
      throw Exception('再開できる解説セッションがありません');
    }
    if (_explainInProgress) {
      throw Exception('別の AI 解説生成が進行中です');
    }

    // セッション保存時のページが現存することを確認 (id ベース)
    int pageIdx = -1;
    for (int i = 0; i < _pages.length; i++) {
      if (_pages[i].id == session.pageId) {
        pageIdx = i;
        break;
      }
    }
    if (pageIdx < 0) {
      _pausedExplainSession = null;
      notifyListeners();
      throw Exception('解説の保存先ページが見つかりません (削除された可能性)');
    }
    final page = _pages[pageIdx];
    final parentRoot = page.nodes[session.parentRootId];
    if (parentRoot == null) {
      _pausedExplainSession = null;
      notifyListeners();
      throw Exception('解説の親ノードが見つかりません');
    }

    _explainInProgress = true;
    _explainCancelRequested = false;
    notifyListeners();

    try {
      final remaining = List<String>.from(session.remainingSubjects);
      final batchSize = session.detail == 'detailed'
          ? 3
          : (session.detail == 'rough' ? 6 : 4);

      // 「残り全体」に対する進捗を doneCount/totalCount で表示するため、
      // baseDone = 既に完了済の件数。
      int processedInThisRun = 0;
      int cancelAtInRemaining = -1;
      final newRoots = <Map<String, dynamic>>[];

      for (int i = 0; i < remaining.length; i += batchSize) {
        if (_explainCancelRequested) {
          cancelAtInRemaining = i;
          debugPrint('再開: キャンセル要求を検知。残 ${remaining.length - i} 件をさらに保留に。');
          break;
        }

        final batchEnd = (i + batchSize).clamp(0, remaining.length);
        final batch = remaining.sublist(i, batchEnd);
        onProgress?.call(session.doneCount + processedInThisRun,
            session.totalCount, batch.first);

        final batchPrompt = _buildBatchExpandPrompt(
          masterTheme: session.term,
          batchSubjects: batch,
          detail: session.detail,
          userInstruction: session.userInstruction,
        );

        Map<String, dynamic>? batchStruct;
        try {
          batchStruct = await _askAiForJsonStructure(batchPrompt,
              detailed: session.detail == 'detailed');
        } catch (e) {
          debugPrint('再開: バッチ失敗 [$batch] → スキップ: $e');
          processedInThisRun = batchEnd;
          continue;
        }

        final batchRoots = batchStruct['roots'];
        if (batchRoots is List) {
          for (final r in batchRoots) {
            if (r is Map) {
              newRoots.add(r.map((k, v) => MapEntry(k.toString(), v)));
            }
          }
        } else if (batchStruct['children'] is List) {
          newRoots.add(<String, dynamic>{
            'title': batchStruct['title'] ?? batch.first,
            'children': batchStruct['children'],
          });
        }
        processedInThisRun = batchEnd;
        onProgress?.call(session.doneCount + processedInThisRun,
            session.totalCount, batch.last);
      }

      // URL 実在チェック (新規分のみ)
      if (newRoots.isNotEmpty) {
        // _validateUrlsInStructure は top に children を持つ構造を前提とするので
        // 一時的にラップしてチェック。
        await _validateUrlsInStructure(<String, dynamic>{
          'title': session.term,
          'children': newRoots,
        });

        // 既存の親 root の子として追記
        _appendAiRootsToParent(
          pageIndex: pageIdx,
          parentNodeId: session.parentRootId,
          newRoots: newRoots,
        );
      }

      // セッション更新
      if (cancelAtInRemaining >= 0 && cancelAtInRemaining < remaining.length) {
        final stillRemaining = remaining.sublist(cancelAtInRemaining);
        _pausedExplainSession = session.copyWith(
          pageIndex: pageIdx,
          remainingSubjects: stillRemaining,
          doneCount: session.doneCount + cancelAtInRemaining,
        );
      } else {
        // 全て完了 → セッション破棄
        _pausedExplainSession = null;
      }

      _saveToStorage();
      notifyListeners();

      return AiMapResult(
        pageIndex: pageIdx,
        rootId: session.parentRootId,
        rootPosition: parentRoot.position,
        addedToCurrentPage: pageIdx == _currentPageIndex,
      );
    } finally {
      _explainInProgress = false;
      _explainCancelRequested = false;
      notifyListeners();
    }
  }

  /// 再開時に、新規 subject roots を既存の親ノードの子として追記する。
  ///
  /// 配置方針: 親 root の右側に縦に並んでいる既存の子 subject roots の
  /// 最下端よりさらに下に新しい子を積む。これにより既存ノードと重ならず、
  /// 「ページの下方向に伸びていく」自然な見た目になる。
  void _appendAiRootsToParent({
    required int pageIndex,
    required String parentNodeId,
    required List<Map<String, dynamic>> newRoots,
  }) {
    if (newRoots.isEmpty) return;
    if (pageIndex < 0 || pageIndex >= _pages.length) return;
    final page = _pages[pageIndex];
    final parent = page.nodes[parentNodeId];
    if (parent == null) return;

    // 既存の子ノード (parent から east → west で繋がっているノード) の
    // 縦範囲を計算。
    double bottomMost = parent.position.dy + parent.height;
    final existingChildIds = <String>{};
    for (final c in page.connections) {
      if (c.fromId == parentNodeId &&
          c.fromAnchor == AnchorDirection.east &&
          c.toAnchor == AnchorDirection.west) {
        existingChildIds.add(c.toId);
      }
    }
    for (final cid in existingChildIds) {
      final child = page.nodes[cid];
      if (child == null) continue;
      final childBottom = child.position.dy + child.visualHeight;
      if (childBottom > bottomMost) bottomMost = childBottom;
    }

    // 新規 root の配置位置 (親と同じ x の右側)。Y は既存の最下端の少し下から開始。
    const double horizontalGap = 280.0;
    const double minVerticalGap = 40.0;
    final childX = parent.position.dx + parent.width + horizontalGap;

    // 各新規 root の必要高さを事前計算
    final subtreeHeights = newRoots
        .map((r) => _computeAiSubtreeHeight(r, minVerticalGap))
        .toList();

    // 既存の最下端から開始 (重ならないよう minVerticalGap を空ける)
    double currentY = bottomMost + minVerticalGap;

    // 色パレットは _placeAiSummaryChildren と同じ
    const palette = _kAiNodePalette;

    // 既存の子の数を数えて、新規はその次の色から始める (色の連続性)
    final colorOffset = existingChildIds.length;

    for (int i = 0; i < newRoots.length; i++) {
      final raw = newRoots[i];
      final title = (raw['title'] as String?)?.trim() ?? '';
      if (title.isEmpty) continue;
      final memo = (raw['memo'] as String?)?.trim();
      final grandChildren = (raw['children'] as List<dynamic>?) ?? const [];

      final subH = subtreeHeights[i];
      // ── 高さ: NodeWidget の `node.height + memoExtraH` 仕様に合わせる ──
      // node.height は「タイトル領域だけ」。メモは下に自動で伸びる。
      final w = (title.length * 14.0 + 40).clamp(180.0, 340.0);
      const double h = 50.0;
      double displayH = h;
      if (memo != null && memo.isNotEmpty) {
        const memoFontSize = 11.0;
        final lineCount =
            (memo.length / (w / memoFontSize * 1.2)).ceil().clamp(1, 20);
        displayH += lineCount * (memoFontSize + 3);
      }

      final childSlotCenter = currentY + subH / 2;
      final childPos = Offset(childX, childSlotCenter - displayH / 2);

      // 色: 既存の子に続く順番で coprime 巡回 (_placeAiSummaryChildren 参照)
      final colorIdx =
          ((colorOffset + i) * _kAiPaletteStep + 1) % palette.length;
      final color = palette[colorIdx];

      final ytUrl = _validatedHttpUrl(raw['youtube_url']);
      final linkUrl = _validatedHttpUrl(raw['link_url']) ??
          _validatedHttpUrl(raw['image_url']);
      NodeContentType ct = NodeContentType.none;
      if (ytUrl != null) {
        ct = NodeContentType.youtube;
      } else if (linkUrl != null) {
        ct = NodeContentType.link;
      } else if (memo != null && memo.isNotEmpty) {
        ct = NodeContentType.memo;
      }

      final child = MindMapNode(
        id: _uuid.v4(),
        title: title,
        memoText: memo,
        position: childPos,
        width: w.toDouble(),
        height: h,
        color: color,
        youtubeUrl: ytUrl,
        linkUrl: linkUrl,
        contentType: ct,
      );
      page.nodes[child.id] = child;
      page.connections.add(NodeConnection(
        fromId: parent.id,
        fromAnchor: AnchorDirection.east,
        toId: child.id,
        toAnchor: AnchorDirection.west,
      ));

      // 孫を再帰配置 (= _placeAiSummaryChildren と同じ処理を、
      // ただし currentPage のかわりに対象ページの nodes へ書き出す)。
      // 簡単のためにページが現在ページなら _placeAiSummaryChildren を流用、
      // そうでなければ一時的に _currentPageIndex を切り替える。
      if (grandChildren.isNotEmpty) {
        final savedIdx = _currentPageIndex;
        _currentPageIndex = pageIndex;
        try {
          _placeAiSummaryChildren(
            parent: child,
            childrenJson: grandChildren,
            depth: 1,
            siblingsCount: grandChildren.length,
            parentSlotCenterY: childSlotCenter,
            parentColorIdx: colorIdx,
          );
        } finally {
          _currentPageIndex = savedIdx;
        }
      }

      currentY += subH + minVerticalGap;
    }

    page.lastModifiedAt = DateTime.now();
  }

  /// 網羅モード Expand フェーズ用プロンプト。
  /// 1 バッチ ([batchSubjects] 個) 分の詳細展開を要求する。
  String _buildBatchExpandPrompt({
    required String masterTheme,
    required List<String> batchSubjects,
    required String detail,
    required String userInstruction,
  }) {
    String detailGuide;
    switch (detail) {
      case 'rough':
        detailGuide = '各 subject につき、子要素は 2〜4 個、階層は 1〜2 段、'
            'memo は 1 文程度に短く。';
        break;
      case 'detailed':
        detailGuide = '各 subject につき、子要素は 5〜8 個、階層は 2〜3 段、'
            '具体例ノードまで含める。memo は 1〜3 文。';
        break;
      default:
        detailGuide = '各 subject につき、子要素は 3〜6 個、階層は 1〜2 段、'
            'memo は 1〜2 文の要点。';
    }
    final hint = userInstruction.trim().isNotEmpty
        ? '\nユーザーからの追加指示: ${userInstruction.trim()}'
        : '';
    final subjectList = batchSubjects.map((s) => '- $s').join('\n');

    return '''
あなたは博識な解説者です。テーマ「$masterTheme」のマインドマップ全体のうち、
今回はその一部を担当します。次に挙げる subject (枝) について、それぞれ
階層的なマインドマップを作成してください。

担当する subject (${batchSubjects.length} 件):
$subjectList

返却は JSON 1 個のみ。コードフェンス、前置き、後置き、解説文、 // コメント、
末尾カンマは一切禁止。schema は次のとおり:
{
  "roots": [
    {
      "title": "${batchSubjects.first}",
      "memo": "1〜3 文の概要",
      "children": [
        {"title": "..", "memo": "..", "children": [...]}
      ]
    }
  ]
}

各ノードは title (必須), memo (任意), children (任意, 同形配列),
youtube_url (任意), link_url (任意), image_url (任意) を持てる。

ルール:
- roots は **必ず ${batchSubjects.length} 個** にし、上記の subject に
  1:1 対応させること。順番もリスト順に揃える。
- $detailGuide
- **title は subject 名そのものを使う** (上の例なら「${batchSubjects.first}」)。
  「$masterTheme のうち ◯◯」「$masterTheme の ◯◯」のように
  マスターテーマ名を含めて冗長にしない (重複表示で読みづらくなるため)。
- 子ノード (children) の title も短く 15〜25 文字目安。
  「◯◯ について」「◯◯ の説明」のような飾りは付けず、項目名そのものを書く。
- memo も冗長な前置き ("ここでは…を説明します", "本項では…")
  を入れず、内容そのものを 1〜3 文で簡潔に書く。
- youtube_url / link_url / image_url は本当に実在を確信できる時のみ。
  少しでも不安なら省略 (架空 URL は禁止、出力後に実在チェックされ削除されます)。
- 文字列内のダブルクォートは必ず \\ でエスケープ。$hint
''';
  }

  /// ── AI 追加質問 (要約済み資料に対する Q&A) ──
  ///
  /// `summarizeFileToNewPage` でマップ化したページに対して、ユーザーが
  /// 「この資料の中で〇〇についてもう少し説明して」のような追加質問を
  /// 投げると、当時の資料 (テキスト本文 or バイナリファイル) を再添付して
  /// AI に答えさせる。
  ///
  /// 戻り値: 回答テキスト。同時に `_aiPageContexts[pageId].qaHistory` に
  /// 履歴として追加され、UI 側で会話ログ風に表示できる。
  /// 文脈が無いページに対して呼ぶと throw。
  Future<String> askAiFollowUpForPage(String pageId, String question) async {
    final ctx = _aiPageContexts[pageId];
    if (ctx == null) {
      throw Exception('このページには AI 要約の文脈がありません');
    }
    final cleanQ = question.trim();
    if (cleanQ.isEmpty) {
      throw Exception('質問が空です');
    }

    // ── プロンプト組立 ──
    // テキスト系なら本文を埋め込む (60K 文字に切り詰め済みのものを使う)。
    // これまでの Q&A 履歴も含めて、文脈の継続性を保つ。
    final contentPart = (ctx.textContent != null && ctx.textContent!.isNotEmpty)
        ? '--- 資料の内容 ---\n${ctx.textContent}\n\n'
        : '';

    String historyPart = '';
    if (ctx.qaHistory.isNotEmpty) {
      // 履歴が長くなりすぎるとコンテキスト圧迫するので、直近 6 ターンに制限
      const int kMaxHistoryTurns = 6;
      final recent = ctx.qaHistory.length > kMaxHistoryTurns
          ? ctx.qaHistory.sublist(ctx.qaHistory.length - kMaxHistoryTurns)
          : ctx.qaHistory;
      historyPart = '--- これまでの Q&A 履歴 ---\n';
      for (final e in recent) {
        historyPart += 'Q: ${e.question}\nA: ${e.answer}\n\n';
      }
    }

    final prompt = '''
あなたは資料「${ctx.fileName}」について質問に答えるアシスタントです。
資料の内容を踏まえて、簡潔かつ正確に答えてください。

以下のルールを必ず守ってください:
- 資料に書かれていない事は推測ではなく「資料に明示的な記載はありません」と答えること。
- 「ご質問ありがとうございます」のような前置きは省き、要点から答え始めること。
- 回答は通常 2〜6 文程度に簡潔にまとめる。長くなる場合は箇条書きを使う。
- ユーザーが事実関係について質問していて資料外の一般知識から補足する場合は、
  「資料外の補足:」と明示してから書くこと。

$contentPart$historyPart--- 新しい質問 ---
$cleanQ
''';

    // バイナリ系 (PDF/docx/pptx) は textContent が無いので毎回再添付。
    // ファイルが移動・削除されている場合は、フォールバックでテキストなし問い合わせ。
    String answer;
    final isBinary = ctx.filePath != null &&
        (ctx.ext == 'pdf' || ctx.ext == 'docx' || ctx.ext == 'pptx');
    if (isBinary) {
      final f = File(ctx.filePath!);
      if (await f.exists()) {
        answer = await _askAiWithBinaryDoc(
          filePath: ctx.filePath!,
          fileName: ctx.fileName,
          ext: ctx.ext!,
          prompt: prompt,
        );
      } else {
        debugPrint('追加質問: 資料ファイルが見つからない (${ctx.filePath}) → テキスト無しで問い合わせ');
        answer = await askAi(prompt);
      }
    } else {
      answer = await askAi(prompt);
    }

    // 履歴に追加 (UI が listen している)
    ctx.qaHistory.add(AiQAEntry(
      question: cleanQ,
      answer: answer.trim(),
      ts: DateTime.now(),
    ));
    notifyListeners();
    return answer.trim();
  }

  /// AI 追加質問の特定ターンを履歴から削除 (ユーザーがやり直したい時用)。
  void deleteAiFollowUpEntry(String pageId, int index) {
    final ctx = _aiPageContexts[pageId];
    if (ctx == null) return;
    if (index < 0 || index >= ctx.qaHistory.length) return;
    ctx.qaHistory.removeAt(index);
    notifyListeners();
  }

  /// 画像から文字を OCR 抽出する (= ユーザー要望: 画像の OCR 検索)。
  /// ビジョン対応 AI (Gemini / Claude) に画像を渡し、 認識テキストのみを返す。
  /// 翻訳・要約はさせず原文のまま返す。 AI キー未設定や通信失敗時は例外を投げる。
  Future<String> ocrImageToText(String filePath, String ext) async {
    final name = filePath.split(RegExp(r'[\\/]')).last;
    final text = await _askAiWithBinaryDoc(
      filePath: filePath,
      fileName: name,
      ext: ext,
      prompt: 'この画像に写っている文字をすべて、 見たままの順序でそのまま書き出してください。'
          ' 翻訳・要約・説明・前置き・記号装飾は一切付けず、 認識した文字だけを出力してください。'
          ' 文字が無ければ何も出力しないでください。',
    );
    return text.trim();
  }

  /// AI に PDF/docx/pptx を直接添付して問い合わせる。
  /// Gemini: inline_data で base64 を渡す
  /// Claude: document タイプで base64 を渡す
  /// OpenAI: 直接対応がないので Gemini にフォールバック (要 Gemini キー)
  Future<String> _askAiWithBinaryDoc({
    required String filePath,
    required String fileName,
    required String ext,
    required String prompt,
  }) async {
    // ファイルをそのまま送る経路は各社のキーを直に使う。 アプリ側のキー
    //   (代行サーバー) だけで動かす今の作りでは通らないので、 ここへ来たら
    //   「本文を取り出せなかった」 と正直に伝える。 以前はこの先で
    //   「Gemini APIキーが設定されていません」 という、 利用者には意味の
    //   分からない文言が出ていた。
    if (canUseAiRelay) {
      throw Exception(t('aiSummary.textExtractFailed'));
    }
    final bytes = await File(filePath).readAsBytes();
    final b64 = base64Encode(bytes);
    final lower = ext.toLowerCase();
    // 画像系も Gemini の inline_data でそのまま投げられる。
    // (Claude も documents/images の content type で受けられるが、ここでは
    //  Gemini に統一しておく方が docx/pptx と扱いを揃えられて単純)
    String mimeFor(String e) {
      switch (e) {
        case 'pdf':
          return 'application/pdf';
        case 'docx':
          return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
        case 'pptx':
          return 'application/vnd.openxmlformats-officedocument.presentationml.presentation';
        case 'jpg':
        case 'jpeg':
          return 'image/jpeg';
        case 'png':
          return 'image/png';
        case 'gif':
          return 'image/gif';
        case 'webp':
          return 'image/webp';
        case 'heic':
          return 'image/heic';
        case 'heif':
          return 'image/heif';
        default:
          return 'application/octet-stream';
      }
    }

    final mime = mimeFor(lower);
    final isImage = mime.startsWith('image/');

    final effectivePrompt = languageInstructionForAi() + prompt;

    // どの AI プロバイダーを使うか決定 (現状の設定 → ファイル対応外なら Gemini)
    String useProvider = _aiProvider;
    if (useProvider == 'openai') useProvider = 'gemini';

    if (useProvider == 'anthropic') {
      if (!hasAnthropicKey) {
        throw Exception('Claude APIキーが設定されていません');
      }
      // Claude Messages API: documents 対応 (PDF のみネイティブ)
      // Claude Messages API: PDF は documents で送信、画像は image type で送信。
      // docx/pptx は base64 のままだと処理できないため Gemini にフォールバック。
      if (lower != 'pdf' && !isImage) {
        useProvider = 'gemini';
      } else {
        final contentBlock = isImage
            ? <String, dynamic>{
                'type': 'image',
                'source': {
                  'type': 'base64',
                  'media_type': mime,
                  'data': b64,
                },
              }
            : <String, dynamic>{
                'type': 'document',
                'source': {
                  'type': 'base64',
                  'media_type': mime,
                  'data': b64,
                },
              };
        final res = await http
            .post(
              Uri.parse('https://api.anthropic.com/v1/messages'),
              headers: {
                'Content-Type': 'application/json',
                'x-api-key': _anthropicApiKey!,
                'anthropic-version': '2023-06-01',
              },
              body: jsonEncode({
                'model': _anthropicModel,
                'max_tokens': 4096,
                'messages': [
                  {
                    'role': 'user',
                    'content': [
                      contentBlock,
                      {'type': 'text', 'text': effectivePrompt},
                    ],
                  },
                ],
              }),
            )
            .timeout(const Duration(seconds: 120));
        if (res.statusCode != 200) {
          throw Exception('Claude API エラー: ${res.statusCode} ${res.body}');
        }
        final data =
            jsonDecode(utf8.decode(res.bodyBytes)) as Map<String, dynamic>;
        final content = (data['content'] as List?) ?? const [];
        final buf = StringBuffer();
        for (final c in content) {
          if (c is Map && c['type'] == 'text') {
            buf.write(c['text']);
          }
        }
        return buf.toString();
      }
    }

    if (useProvider == 'gemini') {
      if (!hasGeminiKey) {
        throw Exception('Gemini APIキーが設定されていません');
      }
      // Gemini API: inline_data で各種 mime に対応 (PDF, docx, pptx 含む)
      final model = _geminiModels.first;
      final url =
          'https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$_geminiApiKey';
      final res = await http
          .post(
            Uri.parse(url),
            headers: {'Content-Type': 'application/json'},
            body: jsonEncode({
              'contents': [
                {
                  'parts': [
                    {
                      'inline_data': {
                        'mime_type': mime,
                        'data': b64,
                      },
                    },
                    {'text': effectivePrompt},
                  ],
                },
              ],
              'generationConfig': {
                'temperature': 0.4,
                'maxOutputTokens': 8192,
              },
            }),
          )
          .timeout(const Duration(seconds: 180));
      if (res.statusCode != 200) {
        throw Exception('Gemini API エラー: ${res.statusCode} ${res.body}');
      }
      final data =
          jsonDecode(utf8.decode(res.bodyBytes)) as Map<String, dynamic>;
      final candidates = data['candidates'] as List?;
      if (candidates == null || candidates.isEmpty) {
        throw Exception('Gemini API: レスポンスが空でした');
      }
      final parts =
          ((candidates.first as Map)['content'] as Map?)?['parts'] as List?;
      final buf = StringBuffer();
      for (final part in parts ?? const []) {
        if (part is Map && part['text'] != null) {
          buf.write(part['text']);
        }
      }
      return buf.toString();
    }

    throw Exception('利用可能な AI プロバイダーがありません');
  }

  /// AI 出力テキストから JSON 構造を抽出する。
  /// AI 出力から JSON オブジェクトを取り出す。
  ///
  /// AI は以下のような形式で返してくることがあるので、それぞれに対応する:
  ///   - ` ```json ... ``` ` でラップ
  ///   - JSON の前に「以下が結果です:」のような前置き
  ///   - JSON の後に「以上です」のような後置き
  ///   - 末尾カンマ等の軽微な構文崩れ
  ///   - 文字列内に `{` や `}` を含む (Japanese などで括弧が出る)
  ///   - **トークン上限で途中で切れた JSON** (閉じ括弧が足りない)
  ///   - 全角カンマ・コロン・引用符が混入
  ///
  /// 旧実装は「最初の `{` 〜 最後の `}` を切り出して jsonDecode」だけだった
  /// ため、説明文に `}` が含まれると JSON が壊れて `null` を返していた。
  /// 新実装は次の段階を踏んで成功率を上げる:
  ///   1) ``` フェンスを剥がす
  ///   2) 全体をそのまま jsonDecode
  ///   3) 最初の `{` から **文字列を考慮した括弧バランス** で対応する `}` を
  ///      探して切り出し、parse を試みる
  ///   4) 失敗したら末尾カンマを掃除して再試行
  ///   5) それでも失敗したら、その位置の次から同じ手順で別の JSON を探す
  ///   6) **どこも閉じる `}` が見つからなかった場合 (= 途中で切れた)**:
  ///      最後の `{` から walk して足りない `}` `]` を補って強制的に閉じてみる
  Map<String, dynamic>? _extractJsonStructure(String text) {
    if (text.isEmpty) return null;

    // (1) 先頭/末尾の空白とフェンスを除去。フェンス内に複数あった場合は
    //     最初の 1 つだけ取り出す (実用上問題ない)。
    String s = text.trim();
    final fenceMatch =
        RegExp(r'```(?:json|JSON)?[\s\r\n]*([\s\S]*?)[\s\r\n]*```')
            .firstMatch(s);
    if (fenceMatch != null && (fenceMatch.group(1) ?? '').isNotEmpty) {
      s = fenceMatch.group(1)!.trim();
    }

    // (2) そのまま全体を parse できればそれが最速
    final whole = _tryParseJsonMap(s);
    if (whole != null) return whole;

    // (3) 最初の `{` から括弧バランスで末尾を探す。
    //     文字列リテラル "..." 内の `{` `}` は無視する。
    int searchStart = 0;
    while (true) {
      final firstOpen = s.indexOf('{', searchStart);
      if (firstOpen < 0) break;
      int depth = 0;
      bool inStr = false;
      bool escape = false;
      int? endIdx;
      for (int i = firstOpen; i < s.length; i++) {
        final c = s[i];
        if (escape) {
          escape = false;
          continue;
        }
        if (inStr) {
          if (c == '\\') {
            escape = true;
            continue;
          }
          if (c == '"') inStr = false;
          continue;
        }
        if (c == '"') {
          inStr = true;
          continue;
        }
        if (c == '{') {
          depth++;
        } else if (c == '}') {
          depth--;
          if (depth == 0) {
            endIdx = i;
            break;
          }
        }
      }
      if (endIdx == null) break; // 閉じる括弧が見つからない → (6) の救済へ

      final candidate = s.substring(firstOpen, endIdx + 1);
      final r1 = _tryParseJsonMap(candidate);
      if (r1 != null) return r1;

      // (4) 末尾カンマ救済 (例: "...,}")
      final cleaned = candidate.replaceAllMapped(
          RegExp(r',(\s*[}\]])'), (m) => m.group(1)!);
      final r2 = _tryParseJsonMap(cleaned);
      if (r2 != null) return r2;

      // (5) この `{` で見つかった範囲では parse できなかった
      //     → さらに先に別の JSON 候補があるか探す
      searchStart = endIdx + 1;
    }

    // (6) ── 閉じ括弧が足りない (途中で切れた) ケースの救済 ──
    // トークン上限で出力が途切れた時に発生。最後の `{` まで戻って walk し直し、
    // 「未閉じの `[`/`{` の数だけ閉じ括弧を末尾に足す」「文字列の途中なら
    //   `"` で閉じる」を試す。
    final firstOpenForFix = s.indexOf('{');
    if (firstOpenForFix >= 0) {
      final tail = s.substring(firstOpenForFix);
      final fixed = _attemptCloseTruncatedJson(tail);
      if (fixed != null) {
        // 閉じた候補を末尾カンマ掃除と組み合わせて再 parse 試行
        final r3 = _tryParseJsonMap(fixed);
        if (r3 != null) return r3;
        final cleaned3 =
            fixed.replaceAllMapped(RegExp(r',(\s*[}\]])'), (m) => m.group(1)!);
        final r4 = _tryParseJsonMap(cleaned3);
        if (r4 != null) return r4;
      }
    }

    return null;
  }

  /// 途中で切れた JSON を強制的に閉じる。
  ///
  /// 入力テキストを文字列を考慮しながら walk し、終端時点での
  /// (a) 文字列の途中なら `"` を補う
  /// (b) 開いている `[` `{` の数だけ末尾カンマを掃除して `]` `}` を補う
  /// (c) 末尾の不完全なキー/値 (": null まで打って終わってる等) も穴埋め
  ///
  /// 100% の success ではないが、長い JSON が途中で切れたパターンの大半を
  /// 救える。
  String? _attemptCloseTruncatedJson(String s) {
    if (s.isEmpty || s[0] != '{') return null;
    final stack = <String>[]; // '{' or '['
    bool inStr = false;
    bool escape = false;
    for (int i = 0; i < s.length; i++) {
      final c = s[i];
      if (escape) {
        escape = false;
        continue;
      }
      if (inStr) {
        if (c == '\\') {
          escape = true;
          continue;
        }
        if (c == '"') inStr = false;
        continue;
      }
      if (c == '"') {
        inStr = true;
        continue;
      }
      if (c == '{' || c == '[') {
        stack.add(c);
      } else if (c == '}') {
        if (stack.isNotEmpty && stack.last == '{') stack.removeLast();
      } else if (c == ']') {
        if (stack.isNotEmpty && stack.last == '[') stack.removeLast();
      }
    }

    final buf = StringBuffer(s);
    if (inStr) {
      // 文字列の途中で切れている → `"` で閉じる
      buf.write('"');
    }
    // 末尾の不完全カンマや空属性は除去するため、文字列化してから後処理
    String partial = buf.toString();
    // ": <途中まで> のような形になっている可能性: 直前トークンが
    //   - キーだけ ("foo") → null を割り当てる
    //   - キー + : ("foo":) → null を割り当てる
    // を雑に救済する
    final trimmed = partial.trimRight();
    final lastNonWs = trimmed.isNotEmpty ? trimmed[trimmed.length - 1] : '';
    if (lastNonWs == ':') {
      partial = '${trimmed}null';
    } else if (lastNonWs == ',') {
      partial = trimmed.substring(0, trimmed.length - 1);
    }

    // 開いているスコープを順に閉じる。閉じる前に直前のカンマを掃除しておく。
    while (stack.isNotEmpty) {
      final tr = partial.trimRight();
      final lastCh = tr.isNotEmpty ? tr[tr.length - 1] : '';
      if (lastCh == ',') {
        partial = tr.substring(0, tr.length - 1);
      }
      final open = stack.removeLast();
      final closer = open == '{' ? '}' : ']';
      partial = partial + closer;
    }
    return partial;
  }

  /// jsonDecode して Map<String, dynamic> なら返す。失敗/型違いなら null。
  Map<String, dynamic>? _tryParseJsonMap(String s) {
    try {
      final p = jsonDecode(s);
      if (p is Map<String, dynamic>) return p;
      // jsonDecode は実装によって Map<dynamic, dynamic> を返すこともある
      if (p is Map) return p.map((k, v) => MapEntry(k.toString(), v));
    } catch (_) {}
    return null;
  }

  /// 階層的な AI 要約構造を新規ページのノードに変換して配置する再帰関数。
  ///
  /// 配置方針:
  /// - 親ノードから右側にツリー状に展開
  /// - **各子のサブツリーが必要とする縦方向のスペースを事前計算してから配置**
  ///   することで、同じ列のノードはもちろん、孫世代も他の枝と重ならない。
  ///   (旧実装は固定 120px 間隔だったため、孫が多い枝と少ない枝が混ざると
  ///    隣の枝の孫と重なって読めなくなっていた)
  /// - 色は **兄弟順** に変える (同じ親の下にある複数の子は別の色)。階層を
  ///   またいでも同じ色の繰り返しにならないよう depth でオフセットを足す。
  ///
  /// [parentSlotCenterY] は呼び出し側の再帰で「親が割り当てられた縦スロットの
  /// 中心」を渡すための任意引数。null の場合は parent.position から計算する
  /// (= ルート直下の最初の呼び出し)。
  void _placeAiSummaryChildren({
    required MindMapNode parent,
    required List<dynamic> childrenJson,
    required int depth,
    required int siblingsCount,
    double? parentSlotCenterY,
    // 親ノードの色 index (palette 内のインデックス)。子の色をここから
    // 相対的にずらして決めることで、孫ノードが親グループごとに違う色に
    // なる。ルートからの初回呼び出しは 0 (palette[0] = 水色) を起点にする。
    int parentColorIdx = 0,
  }) {
    if (childrenJson.isEmpty) return;

    // ── ぶら下がる要素が 1 つだけなら、 折れ (節点) を作らずまっすぐ結ぶ
    //    (= ユーザー要望)。 分岐が無いのに直角の角が付くと、 線が回り道を
    //    しているように見えて読みにくい。 曲線を選んでいる人の設定は変えない。
    var placeable = 0;
    for (final c in childrenJson) {
      if (c is! Map) continue;
      final t = '${c['title'] ?? ''}'.trim();
      if (t.isEmpty && c['__table'] == null && c['__imagePath'] == null) {
        continue;
      }
      placeable++;
    }
    final String? singleLineStyle =
        (placeable == 1 && _connectionLineStyle == 'elbow') ? 'straight' : null;

    const palette = _kAiNodePalette;

    const double horizontalGap = 280.0;
    // 兄弟サブツリー間の最低空きスペース。小さすぎると窮屈、大きすぎるとマップが
    // 縦方向に伸びて見渡しづらくなるので 40 で固定。
    const double minVerticalGap = 40.0;

    // ── 各子サブツリーの必要高さを事前計算 ──
    // 高さは「自分のノード高さ」と「孫サブツリー群の合計高さ」の大きい方。
    // この値で兄弟同士の縦スロットを割り当てるので、どの子の枝が大きくても
    // 隣に押し出されて重ならない。
    final subtreeHeights = <double>[];
    for (final c in childrenJson) {
      if (c is! Map) {
        subtreeHeights.add(0.0);
      } else {
        subtreeHeights.add(_computeAiSubtreeHeight(c, minVerticalGap));
      }
    }

    // 兄弟全体を縦に並べた合計高さ (空要素はスキップ)
    double totalH = 0;
    bool first = true;
    for (int i = 0; i < subtreeHeights.length; i++) {
      if (subtreeHeights[i] <= 0) continue;
      if (!first) totalH += minVerticalGap;
      totalH += subtreeHeights[i];
      first = false;
    }

    // 親が「与えられたスロット中心」(または自分のノード中心) を中心に
    // 子群を上下対称に配置する。
    final centerY =
        parentSlotCenterY ?? (parent.position.dy + parent.height / 2);
    double currentY = centerY - totalH / 2;
    bool firstPlaced = true;

    for (int i = 0; i < childrenJson.length; i++) {
      final raw = childrenJson[i];
      if (raw is! Map) continue;
      final title = (raw['title'] as String?)?.trim() ?? '';
      if (title.isEmpty) continue;
      final memo = (raw['memo'] as String?)?.trim();
      final grandChildren = (raw['children'] as List<dynamic>?) ?? const [];

      if (!firstPlaced) currentY += minVerticalGap;
      firstPlaced = false;

      final subH = subtreeHeights[i];

      // ── 表 / 画像の特別ノード (= _expandAiExtras が足したもの) ──
      final tableRows = raw['__table'];
      final imagePath = raw['__imagePath'] as String?;
      if (tableRows is List || imagePath != null) {
        final special = _placeAiExtraNode(
          parent: parent,
          raw: raw.map((k, v) => MapEntry(k.toString(), v)),
          slotCenterY: currentY + subH / 2,
          horizontalGap: horizontalGap,
        );
        if (special != null) {
          currentPage.connections.add(NodeConnection(
            fromId: parent.id,
            fromAnchor: AnchorDirection.east,
            toId: special.id,
            toAnchor: AnchorDirection.west,
            lineStyle: singleLineStyle ??
                _straightIfAligned(centerY, currentY + subH / 2),
          ));
        }
        currentY += subH;
        continue;
      }
      // ── ノード幅・高さの計算 ──
      // 重要: NodeWidget は `bodyH = node.height + memoExtraH` で描画する。
      // つまり node.height は「タイトル領域だけ」を指し、メモ分は自動的に
      // 下に伸ばされる。height にメモ分も足すと二重に余白が確保され、
      // ノードに大きな空白が残る (ユーザー報告のメモ欄余白問題の原因)。
      // → height は 50.0 固定。レイアウトの縦スロット計算用に「実表示高さ」
      //   displayH を別に出して subH と比較する。
      final w = (title.length * 14.0 + 40).clamp(180.0, 340.0);
      const double h = 50.0;
      double displayH = h;
      if (memo != null && memo.isNotEmpty) {
        // NodeWidget と同じ式: lineCount = len / (w / memoFontSize * 1.2)
        const memoFontSize = 11.0; // defaultMemoFontSize 想定
        final lineCount =
            (memo.length / (w / memoFontSize * 1.2)).ceil().clamp(1, 20);
        displayH += lineCount * (memoFontSize + 3);
      }

      // 子のスロット中心 (孫もこの中心に合わせて再帰配置される)
      final childSlotCenter = currentY + subH / 2;

      // 子ノード自身は親の右側にあり、自分のスロット中心に縦中心 (= 表示高ベース) を置く
      final childPos = Offset(
        parent.position.dx + parent.width + horizontalGap,
        childSlotCenter - displayH / 2,
      );

      // 兄弟順 + 親色を起点に色を選ぶ。
      // 旧実装 `palette[(i * 3 + depth) % len]` は depth しか考慮せず、
      // どの親の子であろうと孫の i=0,1,2 が必ず同じ 3 色になっていた
      // (ユーザー報告: 孫ノードがほぼ同じ色)。親の colorIdx を起点に
      // することで、各親グループの孫が散らばった色になる。
      // 係数 3 はパレット長 8 と互いに素なので、兄弟 8 つまで全色違い。
      final colorIdx =
          (parentColorIdx + i * _kAiPaletteStep + 1) % palette.length;
      final color = palette[colorIdx];

      // 任意フィールド: youtube_url / link_url / image_url。
      // image_url は専用フィールドが無いので link_url 相当にフォールバック。
      // contentType は youtube > link > memo > none の優先で決める。
      final ytUrl = _validatedHttpUrl(raw['youtube_url']);
      final linkUrl = _validatedHttpUrl(raw['link_url']) ??
          _validatedHttpUrl(raw['image_url']);
      NodeContentType ct = NodeContentType.none;
      if (ytUrl != null) {
        ct = NodeContentType.youtube;
      } else if (linkUrl != null) {
        ct = NodeContentType.link;
      } else if (memo != null && memo.isNotEmpty) {
        ct = NodeContentType.memo;
      }

      final child = MindMapNode(
        id: _uuid.v4(),
        title: title,
        memoText: memo,
        position: childPos,
        width: w.toDouble(),
        height: h,
        color: color,
        youtubeUrl: ytUrl,
        linkUrl: linkUrl,
        contentType: ct,
      );
      currentPage.nodes[child.id] = child;
      // 親 → 子 接続 (east → west)
      currentPage.connections.add(NodeConnection(
        fromId: parent.id,
        fromAnchor: AnchorDirection.east,
        toId: child.id,
        toAnchor: AnchorDirection.west,
        // 親とちょうど同じ高さに来る子 (= 枝が奇数本の時の真ん中) は
        //   まっすぐ結ぶ (= ユーザー要望)。 曲がる必要が無いのに直角の角が
        //   付くと、 線が回り道しているように見える。
        lineStyle:
            singleLineStyle ?? _straightIfAligned(centerY, childSlotCenter),
      ));

      // 再帰で孫を配置 (childSlotCenter を渡して、孫もこの中心を基準に上下対称化)
      // colorIdx を parentColorIdx として伝えると、孫の色がこのノードの色を
      // 起点に散らされる (= 親グループごとに違う色相になる)。
      if (grandChildren.isNotEmpty) {
        _placeAiSummaryChildren(
          parent: child,
          childrenJson: grandChildren,
          depth: depth + 1,
          siblingsCount: grandChildren.length,
          parentSlotCenterY: childSlotCenter,
          parentColorIdx: colorIdx,
        );
      }

      // 次の兄弟スロットへ進む (gap は次ループ冒頭で加算)
      currentY += subH;
    }
  }

  /// 親と子がちょうど同じ高さに並ぶ時だけ 'straight' を返す
  /// (= ユーザー要望: 枝が奇数本で真ん中の子が親と水平に並ぶ場合は直線に)。
  /// それ以外は null を返し、 既定の線種 (直角) に任せる。
  /// 曲線を選んでいる人の設定は変えない。
  String? _straightIfAligned(double parentCenterY, double childCenterY) {
    if (_connectionLineStyle != 'elbow') return null;
    // 端数で 1px ずれることがあるので少しだけ余裕を持たせる。
    return (parentCenterY - childCenterY).abs() < 1.5 ? 'straight' : null;
  }

  /// 表ノード / 画像ノードを 1 つ置く (= ユーザー要望: 要約に表と図も入れる)。
  /// 置けなかった時は null。
  MindMapNode? _placeAiExtraNode({
    required MindMapNode parent,
    required Map<String, dynamic> raw,
    required double slotCenterY,
    required double horizontalGap,
  }) {
    final x = parent.position.dx + parent.width + horizontalGap;

    // ── 表 ──
    final rowsRaw = raw['__table'];
    if (rowsRaw is List && rowsRaw.isNotEmpty) {
      final rows = <List<String>>[
        for (final r in rowsRaw)
          if (r is List) [for (final c in r) '${c ?? ''}']
      ];
      if (rows.isEmpty) return null;
      final cols = rows.fold<int>(0, (m, r) => math.max(m, r.length));
      if (cols == 0) return null;
      final cells = [
        for (final r in rows)
          [for (var i = 0; i < cols; i++) i < r.length ? r[i] : '']
      ];
      // 中身の長さに応じて列幅を決める (短い表が間延びしないように)。
      var maxLen = 1;
      for (final r in cells) {
        for (final c in r) {
          if (c.length > maxLen) maxLen = c.length;
        }
      }
      final colW = (maxLen * 11.0 + 26).clamp(74.0, 190.0).toDouble();
      final table = TableData(
        cells: cells,
        headerRow: true,
        defaultColWidth: colW,
      );
      final w = (table.totalWidth + 28.0).clamp(120.0, 1400.0).toDouble();
      final node = MindMapNode(
        id: _uuid.v4(),
        title: (raw['title'] as String?)?.trim() ?? '',
        position: Offset(x, slotCenterY - _aiTableNodeHeight(cells.length) / 2),
        width: w,
        height: 14.0,
        color: const Color(0xFF26C6DA),
        contentType: NodeContentType.table,
        tableData: table,
      );
      currentPage.nodes[node.id] = node;
      return node;
    }

    // ── 画像 (資料のページをそのまま貼る) ──
    final path = raw['__imagePath'] as String?;
    if (path != null && path.isNotEmpty) {
      final ar = (raw['__imageAspect'] as num?)?.toDouble() ?? 0.71;
      final h = _aiImageNodeHeight(ar);
      final node = MindMapNode(
        id: _uuid.v4(),
        title: (raw['title'] as String?)?.trim() ?? '',
        position: Offset(x, slotCenterY - h / 2),
        width: _kAiImageNodeWidth,
        height: 50.0,
        color: const Color(0xFF9CCC65),
        contentType: NodeContentType.attachment,
      );
      node.attachmentPath = path;
      node.attachmentName = _baseName(path);
      // 縦横比は分かっているので最初から入れておく (置いた直後の 1 回目の
      //   描画から正しい大きさになり、 隣のノードと重ならない)。
      node.attachmentAspectRatio = ar;
      currentPage.nodes[node.id] = node;
      // 念のため実寸からも整える (縦横比が渡ってこなかった時のため)。
      unawaited(_applyImageAspectRatio(currentPage.id, node.id, path));
      return node;
    }
    return null;
  }

  /// 表ノードの見た目の高さ (レイアウトのスロット計算用)。
  double _aiTableNodeHeight(int rowCount) =>
      36.0 * rowCount.clamp(1, 14) + 34.0;

  /// 資料のページを貼る画像ノードの幅。
  static const double _kAiImageNodeWidth = 300.0;

  /// 画像ノードの見た目の高さ (タイトル帯 + 絵)。 縦横比 = 幅 / 高さ。
  double _aiImageNodeHeight(double aspect) {
    final ar = aspect <= 0 ? 0.71 : aspect;
    return _kAiImageNodeWidth / ar + 56.0;
  }

  /// AI 要約 JSON ノードのサブツリーが占める縦方向の高さを再帰計算する。
  /// = max(自ノードの高さ, 孫サブツリーの合計高さ + 孫間の隙間)
  ///
  /// `_placeAiSummaryChildren` で兄弟スロットを割り当てる前にこの値を取り、
  /// 兄弟同士が重ならないようにするために使う。
  double _computeAiSubtreeHeight(Map node, double minVerticalGap) {
    // 表 / 画像の特別ノードは高さの出し方が違う (子は持たない)。
    final tableRows = node['__table'];
    if (tableRows is List && tableRows.isNotEmpty) {
      return _aiTableNodeHeight(tableRows.length);
    }
    if ((node['__imagePath'] as String?)?.isNotEmpty ?? false) {
      return _aiImageNodeHeight(
          (node['__imageAspect'] as num?)?.toDouble() ?? 0.71);
    }
    // 配置側 _placeAiSummaryChildren と同じ「実表示高さ」を見積もる。
    // NodeWidget は node.height + memoExtraH で描画するので、ここでも同じ式で。
    // ここがズレるとレイアウトが詰まる/間延びする。
    final memo = (node['memo'] as String?)?.trim();
    final title = (node['title'] as String?)?.trim() ?? '';
    final w = (title.length * 14.0 + 40).clamp(180.0, 340.0);
    double selfH = 50.0; // タイトル領域 (= node.height)
    if (memo != null && memo.isNotEmpty) {
      const memoFontSize = 11.0;
      final lineCount =
          (memo.length / (w / memoFontSize * 1.2)).ceil().clamp(1, 20);
      selfH += lineCount * (memoFontSize + 3);
    }
    final children = (node['children'] as List<dynamic>?) ?? const [];
    if (children.isEmpty) return selfH;

    double childrenH = 0;
    bool firstC = true;
    for (final c in children) {
      if (c is! Map) continue;
      if (!firstC) childrenH += minVerticalGap;
      childrenH += _computeAiSubtreeHeight(c, minVerticalGap);
      firstC = false;
    }
    return childrenH > selfH ? childrenH : selfH;
  }

  /// OpenAI Chat Completions API
  Future<String> askOpenAi(String prompt,
      {int retryCount = 0,
      bool jsonMode = false,
      int? maxTokensOverride}) async {
    if (!hasOpenaiKey) throw Exception('OpenAI APIキーが設定されていません');
    final effectivePrompt = languageInstructionForAi() + prompt;
    final model = _openaiModel;
    final isReasoning = model.startsWith('o'); // o4-mini 等は reasoning 系
    debugPrint('OpenAI リクエスト: model=$model, retry=$retryCount, '
        'lang=$_appLanguage, jsonMode=$jsonMode');

    // reasoning モデルは max_completion_tokens / temperature 制限あり
    final body = <String, dynamic>{
      'model': model,
      'messages': [
        {'role': 'user', 'content': effectivePrompt},
      ],
    };
    if (isReasoning) {
      body['max_completion_tokens'] = maxTokensOverride ?? 4096;
    } else {
      body['temperature'] = 0.7;
      body['max_tokens'] = maxTokensOverride ?? 2048;
    }
    // OpenAI Chat Completions の JSON mode。これを付けると応答が必ず
    // 有効な JSON オブジェクトになる (構造化出力でパース失敗を激減できる)。
    // ただしプロンプトに "JSON" の語が含まれている必要がある (OpenAI の要件)。
    if (jsonMode) {
      body['response_format'] = {'type': 'json_object'};
    }

    final http.Response res;
    try {
      res = await http
          .post(
            Uri.parse('https://api.openai.com/v1/chat/completions'),
            headers: {
              'Content-Type': 'application/json',
              'Authorization': 'Bearer $_openaiApiKey',
            },
            body: jsonEncode(body),
          )
          .timeout(Duration(seconds: isReasoning ? 120 : 60));
    } on TimeoutException {
      throw Exception('OpenAI API: 接続がタイムアウトしました。ネットワークを確認してください');
    }

    if (res.statusCode == 429) {
      if (retryCount < 3) {
        final wait = Duration(seconds: 3 + retryCount * 5);
        debugPrint(
            'OpenAI 429 → ${wait.inSeconds}秒後にリトライ (${retryCount + 1}/3)');
        await Future.delayed(wait);
        return askOpenAi(prompt,
            retryCount: retryCount + 1,
            jsonMode: jsonMode,
            maxTokensOverride: maxTokensOverride);
      }
      throw Exception('OpenAI API: レート制限に達しました');
    }
    if (res.statusCode == 401) {
      throw Exception('OpenAI API: APIキーが無効です');
    }
    if (res.statusCode == 404) {
      throw Exception('OpenAI API: モデル「$model」が見つかりません。設定でモデルを変更してください');
    }
    if (res.statusCode != 200) {
      debugPrint('OpenAI API エラー: ${res.statusCode} ${res.body}');
      String detail = '';
      try {
        final errData = jsonDecode(res.body) as Map<String, dynamic>;
        detail = errData['error']?['message'] as String? ?? '';
      } catch (_) {}
      if (res.statusCode >= 500 && retryCount < 2) {
        await Future.delayed(Duration(seconds: 2 + retryCount * 3));
        return askOpenAi(prompt,
            retryCount: retryCount + 1,
            jsonMode: jsonMode,
            maxTokensOverride: maxTokensOverride);
      }
      throw Exception(
          'OpenAI API エラー: ${res.statusCode}${detail.isEmpty ? '' : '\n$detail'}');
    }

    final data = jsonDecode(utf8.decode(res.bodyBytes)) as Map<String, dynamic>;
    final choices = data['choices'] as List<dynamic>?;
    if (choices == null || choices.isEmpty) {
      throw Exception('OpenAI: 回答がありません');
    }

    // 使用量記録
    final usage = data['usage'] as Map<String, dynamic>?;
    if (usage != null) {
      lastInputTokens = (usage['prompt_tokens'] as num?)?.toInt() ?? 0;
      lastOutputTokens = (usage['completion_tokens'] as num?)?.toInt() ?? 0;
      totalInputTokens += lastInputTokens;
      totalOutputTokens += lastOutputTokens;
      // コスト計算（概算）: $0.15/1M input, $0.60/1M output for gpt-4o-mini
      lastCostUsd =
          (lastInputTokens * 0.15 + lastOutputTokens * 0.60) / 1000000;
      totalCostUsd += lastCostUsd;
      _saveUsageTotals();
    }

    final msg = choices[0]['message'] as Map<String, dynamic>?;
    final content = msg?['content'] as String? ?? '';
    if (content.trim().isEmpty) {
      throw Exception('OpenAI: 空の応答が返されました');
    }
    return content.trim();
  }

  /// OpenAI 互換 Chat Completions API への共通リクエスト。
  /// Grok (x.ai) と DeepSeek はどちらも OpenAI 互換なので、 エンドポイント /
  /// API キー / モデルだけ差し替えて使う。
  Future<String> _askOpenAiCompatible({
    required String prompt,
    required String endpoint,
    required String apiKey,
    required String model,
    required String label,
    int retryCount = 0,
    bool jsonMode = false,
    int? maxTokensOverride,
  }) async {
    if (apiKey.isEmpty) throw Exception('$label APIキーが設定されていません');
    final effectivePrompt = languageInstructionForAi() + prompt;
    debugPrint('$label リクエスト: model=$model, retry=$retryCount, '
        'lang=$_appLanguage, jsonMode=$jsonMode');
    final body = <String, dynamic>{
      'model': model,
      'messages': [
        {'role': 'user', 'content': effectivePrompt},
      ],
      'temperature': 0.7,
      'max_tokens': maxTokensOverride ?? 2048,
    };
    if (jsonMode) {
      body['response_format'] = {'type': 'json_object'};
    }

    final http.Response res;
    try {
      res = await http
          .post(
            Uri.parse(endpoint),
            headers: {
              'Content-Type': 'application/json',
              'Authorization': 'Bearer $apiKey',
            },
            body: jsonEncode(body),
          )
          .timeout(const Duration(seconds: 90));
    } on TimeoutException {
      throw Exception('$label API: 接続がタイムアウトしました。ネットワークを確認してください');
    }

    if (res.statusCode == 429) {
      if (retryCount < 3) {
        await Future.delayed(Duration(seconds: 3 + retryCount * 5));
        return _askOpenAiCompatible(
            prompt: prompt,
            endpoint: endpoint,
            apiKey: apiKey,
            model: model,
            label: label,
            retryCount: retryCount + 1,
            jsonMode: jsonMode,
            maxTokensOverride: maxTokensOverride);
      }
      throw Exception('$label API: レート制限に達しました');
    }
    if (res.statusCode == 401) {
      throw Exception('$label API: APIキーが無効です');
    }
    if (res.statusCode == 404) {
      throw Exception('$label API: モデル「$model」が見つかりません。設定でモデル名を変更してください');
    }
    if (res.statusCode != 200) {
      debugPrint('$label API エラー: ${res.statusCode} ${res.body}');
      String detail = '';
      try {
        final errData = jsonDecode(res.body) as Map<String, dynamic>;
        detail = errData['error']?['message'] as String? ?? '';
      } catch (_) {}
      if (res.statusCode >= 500 && retryCount < 2) {
        await Future.delayed(Duration(seconds: 2 + retryCount * 3));
        return _askOpenAiCompatible(
            prompt: prompt,
            endpoint: endpoint,
            apiKey: apiKey,
            model: model,
            label: label,
            retryCount: retryCount + 1,
            jsonMode: jsonMode,
            maxTokensOverride: maxTokensOverride);
      }
      throw Exception(
          '$label API エラー: ${res.statusCode}${detail.isEmpty ? '' : '\n$detail'}');
    }

    final data = jsonDecode(utf8.decode(res.bodyBytes)) as Map<String, dynamic>;
    final choices = data['choices'] as List<dynamic>?;
    if (choices == null || choices.isEmpty) {
      throw Exception('$label: 回答がありません');
    }
    final usage = data['usage'] as Map<String, dynamic>?;
    if (usage != null) {
      lastInputTokens = (usage['prompt_tokens'] as num?)?.toInt() ?? 0;
      lastOutputTokens = (usage['completion_tokens'] as num?)?.toInt() ?? 0;
      totalInputTokens += lastInputTokens;
      totalOutputTokens += lastOutputTokens;
      _saveUsageTotals();
    }
    final msg = choices[0]['message'] as Map<String, dynamic>?;
    final content = msg?['content'] as String? ?? '';
    if (content.trim().isEmpty) {
      throw Exception('$label: 空の応答が返されました');
    }
    return content.trim();
  }

