  /// [maxTokensOverride] が null でなければ max_tokens をそれで上書きする。
  /// (Claude には専用の "JSON mode" は無いが、出力を大きく取れば JSON が
  ///  途中で切れて parse 失敗する事故を抑えられる)
  Future<String> askClaude(String prompt,
      {int retryCount = 0, int? maxTokensOverride}) async {
    if (!hasAnthropicKey) throw Exception('Claude APIキーが設定されていません');
    final effectivePrompt = languageInstructionForAi() + prompt;
    final model = _anthropicModel;
    debugPrint(
        'Claude リクエスト: model=$model, retry=$retryCount, lang=$_appLanguage');

    final http.Response res;
    try {
      res = await http
          .post(
            Uri.parse('https://api.anthropic.com/v1/messages'),
            headers: {
              'Content-Type': 'application/json',
              'x-api-key': _anthropicApiKey ?? '',
              'anthropic-version': '2023-06-01',
            },
            body: jsonEncode({
              'model': model,
              'max_tokens': maxTokensOverride ?? 4096,
              'messages': [
                {'role': 'user', 'content': effectivePrompt},
              ],
            }),
          )
          .timeout(const Duration(seconds: 90));
    } on TimeoutException {
      throw Exception('Claude API: 接続がタイムアウトしました。ネットワークを確認してください');
    }

    if (res.statusCode == 429) {
      if (retryCount < 3) {
        final wait = Duration(seconds: 3 + retryCount * 5);
        debugPrint(
            'Claude 429 → ${wait.inSeconds}秒後にリトライ (${retryCount + 1}/3)');
        await Future.delayed(wait);
        return askClaude(prompt,
            retryCount: retryCount + 1, maxTokensOverride: maxTokensOverride);
      }
      throw Exception('Claude API: レート制限に達しました');
    }
    if (res.statusCode == 401) {
      throw Exception('Claude API: APIキーが無効です');
    }
    if (res.statusCode == 404) {
      throw Exception('Claude API: モデル「$model」が見つかりません。設定でモデルを変更してください');
    }
    if (res.statusCode != 200) {
      debugPrint('Claude API エラー: ${res.statusCode} ${res.body}');
      String detail = '';
      try {
        final errData = jsonDecode(res.body) as Map<String, dynamic>;
        detail = errData['error']?['message'] as String? ?? '';
      } catch (_) {}
      if (res.statusCode >= 500 && retryCount < 2) {
        await Future.delayed(Duration(seconds: 2 + retryCount * 3));
        return askClaude(prompt,
            retryCount: retryCount + 1, maxTokensOverride: maxTokensOverride);
      }
      throw Exception(
          'Claude API エラー: ${res.statusCode}${detail.isEmpty ? '' : '\n$detail'}');
    }

    final data = jsonDecode(utf8.decode(res.bodyBytes)) as Map<String, dynamic>;
    final contentList = data['content'] as List<dynamic>?;
    if (contentList == null || contentList.isEmpty) {
      throw Exception('Claude: 回答がありません');
    }

    // 使用量記録
    final usage = data['usage'] as Map<String, dynamic>?;
    if (usage != null) {
      lastInputTokens = (usage['input_tokens'] as num?)?.toInt() ?? 0;
      lastOutputTokens = (usage['output_tokens'] as num?)?.toInt() ?? 0;
      totalInputTokens += lastInputTokens;
      totalOutputTokens += lastOutputTokens;
      // コスト計算（概算、Haiku 4.5 基準）: $1.0/1M input, $5.0/1M output
      lastCostUsd = (lastInputTokens * 1.0 + lastOutputTokens * 5.0) / 1000000;
      totalCostUsd += lastCostUsd;
      _saveUsageTotals();
    }

    // content は [{type: 'text', text: '...'}, ...] のリスト
    final textParts = contentList
        .whereType<Map<String, dynamic>>()
        .where((c) => c['type'] == 'text')
        .map((c) => c['text'] as String? ?? '')
        .join('\n')
        .trim();
    if (textParts.isEmpty) {
      throw Exception('Claude: 空の応答が返されました');
    }
    return textParts;
  }

  /// Gemini API にプロンプトを送信してテキスト回答を取得
  ///
  /// [jsonMode] が true の場合、`responseMimeType: 'application/json'` を付けて
  /// JSON だけを返すよう Gemini 側に強制する。これは AI 要約や用語解説のように
  /// 構造化出力を期待する用途に使う。
  /// [maxTokensOverride] は出力トークンの上限を上書き。null なら従来通り
  /// (Pro=8192 / Flash=2048)。長い JSON が途中で切れて parse 失敗する事故を
  /// 避けるため、構造化出力では大きめに指定する。
  Future<String> askGemini(String prompt,
      {int retryCount = 0,
      int modelIndex = 0,
      bool jsonMode = false,
      int? maxTokensOverride,
      Duration? timeoutOverride}) async {
    if (!hasGeminiKey) throw Exception('Gemini APIキーが設定されていません');

    // 言語指示を先頭に付与（AI出力を appLanguage に合わせる）
    final effectivePrompt = languageInstructionForAi() + prompt;

    final models = _geminiModels;
    final model = modelIndex < models.length ? models[modelIndex] : models.last;
    final url = 'https://generativelanguage.googleapis.com/v1beta/models/'
        '$model:generateContent?key=$_geminiApiKey';

    debugPrint('Gemini API リクエスト: model=$model, tier=$aiModelTier, '
        'retry=$retryCount, lang=$_appLanguage, jsonMode=$jsonMode');

    // Pro(思考モデル)は maxOutputTokens を大きく取る
    final isProTier = aiModelTier == 'pro';
    final maxTokens = maxTokensOverride ?? (isProTier ? 8192 : 2048);

    // generationConfig: jsonMode の時は responseMimeType を付けて
    // 「JSON 以外の応答が返らない」モードに切り替える
    final generationConfig = <String, dynamic>{
      'temperature': 0.7,
      'maxOutputTokens': maxTokens,
    };
    if (jsonMode) {
      generationConfig['responseMimeType'] = 'application/json';
    }

    final http.Response res;
    try {
      res = await http
          .post(
            Uri.parse(url),
            headers: {'Content-Type': 'application/json'},
            body: jsonEncode({
              'contents': [
                {
                  'parts': [
                    {'text': effectivePrompt}
                  ]
                }
              ],
              'generationConfig': generationConfig,
            }),
          )
          .timeout(timeoutOverride ?? Duration(seconds: isProTier ? 120 : 60));
    } on TimeoutException {
      if (modelIndex + 1 < models.length) {
        debugPrint('Gemini タイムアウト ($model) → 次のモデルへフォールバック');
        return askGemini(prompt,
            retryCount: retryCount,
            modelIndex: modelIndex + 1,
            jsonMode: jsonMode,
            maxTokensOverride: maxTokensOverride,
            timeoutOverride: timeoutOverride);
      }
      throw Exception('Gemini API: 接続がタイムアウトしました。ネットワークを確認してください');
    }

    if (res.statusCode == 404) {
      debugPrint('Gemini 404 ($model) → 次のモデルへフォールバック');
      if (modelIndex + 1 < models.length) {
        return askGemini(prompt,
            retryCount: retryCount,
            modelIndex: modelIndex + 1,
            jsonMode: jsonMode,
            maxTokensOverride: maxTokensOverride,
            timeoutOverride: timeoutOverride);
      }
      throw Exception('Gemini API: 利用可能なモデルが見つかりません。APIキーを確認してください');
    }
    if (res.statusCode == 429) {
      if (retryCount < 3) {
        final wait = Duration(seconds: 3 + retryCount * 5);
        debugPrint(
            'Gemini 429 → ${wait.inSeconds}秒後にリトライ (${retryCount + 1}/3)');
        await Future.delayed(wait);
        return askGemini(prompt,
            retryCount: retryCount + 1,
            modelIndex: modelIndex,
            jsonMode: jsonMode,
            maxTokensOverride: maxTokensOverride,
            timeoutOverride: timeoutOverride);
      }
      throw Exception('APIのレート制限です。しばらく待ってから再試行してください');
    }
    if (res.statusCode == 403) {
      throw Exception(
          'Gemini API: APIキーが無効か、Generative Language APIが有効化されていません');
    }
    if (res.statusCode != 200) {
      debugPrint('Gemini API エラー: ${res.statusCode} ${res.body}');
      if (res.statusCode == 400) {
        String detail = '';
        try {
          final errData = jsonDecode(res.body) as Map<String, dynamic>;
          final errMsg = errData['error']?['message'] as String?;
          if (errMsg != null) detail = '\n詳細: $errMsg';
        } catch (_) {}
        throw Exception('Gemini API: リクエスト形式エラー (400)$detail');
      }
      if (res.statusCode >= 500 && retryCount < 2) {
        await Future.delayed(Duration(seconds: 2 + retryCount * 3));
        return askGemini(prompt,
            retryCount: retryCount + 1,
            modelIndex: modelIndex,
            jsonMode: jsonMode,
            maxTokensOverride: maxTokensOverride,
            timeoutOverride: timeoutOverride);
      }
      throw Exception('Gemini API エラー: ${res.statusCode}');
    }

    final data = jsonDecode(res.body) as Map<String, dynamic>;
    final candidates = data['candidates'] as List<dynamic>?;
    if (candidates == null || candidates.isEmpty) {
      throw Exception('Gemini: 回答がありません');
    }

    // ── 使用量を記録 ──
    final usage = data['usageMetadata'] as Map<String, dynamic>?;
    int inT = 0, outT = 0;
    if (usage != null) {
      inT = (usage['promptTokenCount'] as num?)?.toInt() ?? 0;
      outT = (usage['candidatesTokenCount'] as num?)?.toInt() ?? 0;
    } else {
      inT = (prompt.length * 0.5).round();
    }
    final cost = calcCostUsd(aiModelTier, inT, outT);
    lastInputTokens = inT;
    lastOutputTokens = outT;
    lastCostUsd = cost;
    totalInputTokens += inT;
    totalOutputTokens += outT;
    totalCostUsd += cost;
    _saveUsageTotals();

    // Pro版: finishReasonとcontentのnullチェック
    final firstCandidate = candidates[0] as Map<String, dynamic>?;
    if (firstCandidate == null) throw Exception('Gemini: 候補がありません');

    final finishReason = firstCandidate['finishReason'] as String?;
    if (finishReason == 'SAFETY') {
      throw Exception('Gemini: 安全フィルターにより応答がブロックされました。プロンプトを変更してください');
    }
    if (finishReason == 'RECITATION') {
      throw Exception('Gemini: 著作権保護のため応答がブロックされました');
    }

    final content = firstCandidate['content'] as Map<String, dynamic>?;
    if (content == null) {
      throw Exception('Gemini: 応答コンテンツがありません（finishReason: $finishReason）');
    }
    final parts = content['parts'] as List<dynamic>?;
    if (parts == null || parts.isEmpty) {
      if (finishReason == 'MAX_TOKENS') {
        throw Exception('Gemini Pro: トークン上限に達しました。Flash モデルをお試しください');
      }
      throw Exception('Gemini: 回答がありません (finishReason: $finishReason)');
    }

    // 思考ログ (thought: true) を除外
    final answerParts = parts.where((p) {
      final map = p as Map<String, dynamic>;
      return (map['thought'] as bool? ?? false) == false;
    }).toList();

    final answer = answerParts
        .map((p) => (p as Map<String, dynamic>)['text'] as String? ?? '')
        .join('\n')
        .trim();

    if (answer.isEmpty) {
      if (aiModelTier == 'pro' && modelIndex == 0) {
        debugPrint('Gemini Pro: 回答が空 → Flash にフォールバック');
        final savedTier = aiModelTier;
        aiModelTier = 'flash';
        try {
          return await askGemini(prompt,
              retryCount: 0,
              modelIndex: 0,
              jsonMode: jsonMode,
              maxTokensOverride: maxTokensOverride,
              timeoutOverride: timeoutOverride);
        } finally {
          aiModelTier = savedTier;
        }
      }
      throw Exception(
          'Gemini Pro: 思考トークンが枯渇し回答を生成できませんでした。\nFlash モデルに切り替えてください');
    }
    return answer;
  }

  /// ノードに紐づく添付画像/ファイルを考慮して AI に問い合わせる共通ヘルパ。
  ///
  /// 動作:
  ///  - ノードに `attachmentPath` があり、かつ実ファイルが存在する場合は
  ///    `_askAiWithBinaryDoc` (画像/PDF/docx/pptx をバイナリのまま AI に
  ///    送り込める経路) を使い、AI が中身を見た上で答えるようにする。
  ///  - ない場合は単純に [askAi] を呼ぶ (従来どおり)。
  ///
  /// [prompt] には「対象ノードの題材文 + ユーザーの質問」を全て埋め込んだ
  /// 完成済みの本文を渡す。添付ファイルの説明 (「対象ノードには画像が添付
  /// されています…」のような前置き) はこのヘルパが自動で付与する。
  Future<String> _askAiAboutNode(MindMapNode node, String prompt) async {
    final ap = node.attachmentPath;
    if (ap == null || ap.isEmpty) {
      return askAi(prompt);
    }
    // 拡張子で対応可否を判定
    final dotIdx = ap.lastIndexOf('.');
    if (dotIdx < 0) return askAi(prompt);
    final ext = ap.substring(dotIdx + 1).toLowerCase();
    const supported = <String>{
      'pdf',
      'docx',
      'pptx',
      'jpg',
      'jpeg',
      'png',
      'gif',
      'webp',
      'heic',
      'heif',
    };
    if (!supported.contains(ext)) {
      return askAi(prompt);
    }
    // ファイル実在確認 (パスが残っていてもファイルが消えているケースに備える)
    try {
      final f = File(ap);
      if (!await f.exists()) {
        debugPrint('AI: 添付ファイルが見つからない (${ap}) → 添付なしで問い合わせ');
        return askAi(prompt);
      }
    } catch (_) {
      return askAi(prompt);
    }
    // 添付がある旨を AI に明示するための前置きを付ける。
    // 画像かドキュメントかでメッセージを変えると AI が回答方針を立てやすい。
    final isImage = const {'jpg', 'jpeg', 'png', 'gif', 'webp', 'heic', 'heif'}
        .contains(ext);
    final fileName = node.attachmentName ?? ap.split(RegExp(r'[/\\]')).last;
    // 旧バージョンは "画像の内容も踏まえて回答してください" とだけ書いていたが、
    // それだと AI が画像を「説明する」モードに入ってしまい、ユーザーが
    // 「1+1 の画像を貼って答えを 2 と返してほしい」と思っているのに
    // "丸い角のボタンが描かれています…" と書き出すケースが発生した。
    //
    // 解決策: 添付物に問題/質問/課題が書かれている時は「直接解いて答えを
    // 返す」ことを最優先指示として明示する。具体例 (1+1→2 / 英文→訳 /
    // コード→修正版) を出して挙動を強制する。
    final attachmentHint = isImage
        ? '【最重要指示】このノードには画像が添付されています。\n'
            '・画像内に問題・課題・数式・質問・指示が書かれている場合は、'
            '画像を「説明」せず、その問題を直接解いて答えだけを返してください。\n'
            '  例) 画像が「1+1」→ 答えは「2」 / '
            '画像が英文の問題 → その訳と解答 / '
            '画像がコードのバグ → 修正したコード\n'
            '・画像が単に図解・参考資料・グラフの場合のみ、'
            'その情報を踏まえて以下の指示に答えてください。\n\n'
        : '【最重要指示】このノードにはファイル「$fileName」が添付されています。\n'
            '・ファイル内に問題・課題・質問・指示が書かれている場合は、'
            'ファイルを「説明」せず、その問題を直接解いて答えだけを返してください。\n'
            '・ファイルが単に参考資料の場合のみ、'
            'その情報を踏まえて以下の指示に答えてください。\n\n';
    try {
      return await _askAiWithBinaryDoc(
        filePath: ap,
        fileName: fileName,
        ext: ext,
        prompt: attachmentHint + prompt,
      );
    } catch (e) {
      // 添付経路で失敗したらテキストのみで再試行 (添付が原因でユーザーが
      // 何の回答も得られないのは避けたい)
      debugPrint('AI: 添付付き問い合わせ失敗 → テキストのみで再試行: $e');
      return askAi(prompt);
    }
  }

  /// 画面側から「ノードの添付 (画像/PDF/docx/pptx) を見た上で」 AI に質問する
  /// 公開ラッパ (= ユーザー要望: 画像/ファイルノードの AI ボタンで、 文字が
  /// 空でも中の画像/ファイルを API の AI に渡して回答を得る)。 添付が無い/未対応
  /// なら通常のテキスト問い合わせ [askAi] にフォールバックする。
  Future<String> askAiAboutNodeMedia(MindMapNode node, String prompt) =>
      _askAiAboutNode(node, prompt);

  /// AI: ノードに説明文を追加（同一ノードのメモとして展開）
  Future<void> aiExplainNode(String nodeId) async {
    final node = currentPage.nodes[nodeId];
    if (node == null) return;
    _beginAi();
    try {
      final raw = await _askAiAboutNode(
          node,
          '「${node.title}」について3〜5文で簡潔に説明してください。\n'
          '【重要】\n'
          '・「はい」「承知しました」「もちろん」などの冒頭の挨拶は一切不要です\n'
          '・説明文だけを直接書いてください\n'
          '・各文は句点（。）で終わらせてください\n'
          '・改行は文の区切り（句点の直後）だけに入れてください');
      if (_aiCancelled) return; // キャンセル済み → 結果を反映しない
      // 文末（。）で改行を整える
      final answer = _formatExplanationText(raw);
      _pushUndo();
      // 幅を 300 (自動拡張の上限) に広げてメモとして展開
      currentPage.nodes[nodeId] = node.copyWith(
        memoText: answer,
        contentType: NodeContentType.memo,
        width: 300.0,
      );
      _saveToStorage();
      notifyListeners();
    } finally {
      _endAi();
    }
  }

  /// 説明文を句点ごとに改行して読みやすく整形
  static String _formatExplanationText(String raw) {
    // 連続空白・余計な改行を除去
    var text = raw
        .replaceAll(RegExp(r'[ \t]+'), ' ')
        .replaceAll(RegExp(r'\n{2,}'), '\n')
        .trim();
    // 句点の直後に改行を挿入（すでに改行がある場合は重複しない）
    text = text.replaceAllMapped(
      RegExp(r'。(?!\n)'),
      (m) => '。\n',
    );
    // 最後の余分な改行を除去
    return text.trimRight();
  }

  /// AI: タイトルから子ノードを複数作成（設定に基づく深さ・数）
  Future<void> aiGenerateChildren(String nodeId) async {
    final node = currentPage.nodes[nodeId];
    if (node == null) return;
    _beginAi();
    try {
      final cMin = aiChildMin.clamp(1, 50);
      final cMax = aiChildMax.clamp(cMin, 50);

      final answer = await _askAiAboutNode(
          node,
          '「${node.title}」を構成する具体的な要素・項目・対象を$cMin〜$cMax個列挙してください。\n'
          '\n'
          '【ルール】\n'
          '- 抽象的な分類名（例: "歴史", "種類", "特徴"）ではなく、具体的な固有名詞・実例・アイテム名を出すこと\n'
          '- 例: 「日本の城」→「姫路城」「松本城」「熊本城」（×「天守閣の構造」「立地」）\n'
          '- 例: 「Flutterパッケージ」→「provider」「riverpod」「dio」（×「状態管理」「HTTP通信」）\n'
          '- 例: 「JavaScriptフレームワーク」→「React」「Vue」「Svelte」「Angular」\n'
          '- 各項目は20文字以内\n'
          '- 1行ずつ箇条書き、先頭の記号や番号は付けない\n'
          '- 説明や補足は一切不要、項目名だけ\n'
          '- 重複や類似項目は避け、可能な限り多様性を持たせる');
      if (_aiCancelled) return; // キャンセル済み → ノードを作らずに終了
      final lines = answer
          .split('\n')
          .map((l) => l.replaceAll(RegExp(r'^[\-\*・●▶\d.、\s]+'), '').trim())
          .where((l) => l.isNotEmpty && l.length < 40)
          .toList();
      if (lines.isEmpty) return;

      // 子ノードの仮データを作成
      final childTempNodes = <MindMapNode>[];
      for (final title in lines) {
        childTempNodes.add(MindMapNode(
          id: _uuid.v4(),
          title: title,
          position: Offset.zero,
          color: _childColor(),
        ));
      }

      // ── 孫ノード生成が必要な場合は先にすべてのタイトルを取得 ──
      // childIndex → 孫ノード仮データリスト
      final Map<int, List<MindMapNode>> grandchildMap = {};
      if (aiDepth >= 2) {
        final gMin = aiGrandchildMin.clamp(1, 50);
        final gMax = aiGrandchildMax.clamp(gMin, 50);
        for (int i = 0; i < childTempNodes.length; i++) {
          try {
            final gcAnswer = await askAi(
                '「${childTempNodes[i].title}」を構成する具体的な要素・項目・対象を$gMin〜$gMax個列挙してください。\n'
                '\n'
                '【ルール】\n'
                '- 抽象的な分類名ではなく、具体的な固有名詞・実例・アイテム名を出すこと\n'
                '- 各項目は20文字以内\n'
                '- 1行ずつ箇条書き、先頭の記号や番号は付けない\n'
                '- 説明や補足は一切不要、項目名だけ\n'
                '- 重複や類似項目は避け、可能な限り多様性を持たせる');
            if (_aiCancelled) return; // キャンセル済み → 以降のノード生成をスキップ
            final gcLines = gcAnswer
                .split('\n')
                .map((l) =>
                    l.replaceAll(RegExp(r'^[\-\*・●▶\d.、\s]+'), '').trim())
                .where((l) => l.isNotEmpty && l.length < 40)
                .toList();
            if (gcLines.isNotEmpty) {
              grandchildMap[i] = gcLines
                  .map((t) => MindMapNode(
                        id: _uuid.v4(),
                        title: t,
                        position: Offset.zero,
                        color: _childColor(),
                      ))
                  .toList();
            }
          } catch (e) {
            debugPrint('孫ノード取得エラー (${childTempNodes[i].title}): $e');
          }
        }
      }

      // ── 各子ノードに必要な縦スペースを計算（子自身 vs 孫グループ） ──
      const gap = 16.0;
      final slotHeights = <double>[]; // 子ノードごとの占有高さ
      for (int i = 0; i < childTempNodes.length; i++) {
        final childH = childTempNodes[i].visualHeight;
        final gcNodes = grandchildMap[i];
        if (gcNodes != null && gcNodes.isNotEmpty) {
          double gcTotalH = 0;
          for (final gc in gcNodes) {
            gcTotalH += gc.visualHeight;
          }
          gcTotalH += gap * (gcNodes.length - 1);
          // この子ノードが占有するスロット = 子自身か孫グループの大きい方
          slotHeights.add(gcTotalH > childH ? gcTotalH : childH);
        } else {
          slotHeights.add(childH);
        }
      }

      // 全スロットの合計高さ
      double totalH = 0;
      for (final h in slotHeights) {
        totalH += h;
      }
      totalH += gap * (slotHeights.length - 1);

      // ── 配置 ──
      _pushUndo();
      final childX = node.position.dx + node.width + 80;
      final parentCenterY = node.position.dy + node.visualHeight / 2;
      double slotY = (parentCenterY - totalH / 2).clamp(0.0, 20000.0);
      // 親がグループ所属なら、生成した子孫も同じグループに入れる
      final List<String> newDescendantIds = [];

      for (int i = 0; i < childTempNodes.length; i++) {
        final slotH = slotHeights[i];
        // 子ノードはスロットの縦中央に配置
        final childVH = childTempNodes[i].visualHeight;
        final childY = slotY + (slotH - childVH) / 2;
        final childPos = Offset(childX, childY.clamp(0.0, 20000.0));
        final child = childTempNodes[i].copyWith(position: childPos);
        currentPage.nodes[child.id] = child;
        newDescendantIds.add(child.id);
        currentPage.connections.add(NodeConnection(
          fromId: nodeId,
          fromAnchor: AnchorDirection.east,
          toId: child.id,
          toAnchor: AnchorDirection.west,
        ));

        // 孫ノードを配置（スロットの縦中央にグループ全体を配置）
        final gcNodes = grandchildMap[i];
        if (gcNodes != null && gcNodes.isNotEmpty) {
          double gcTotalH = 0;
          for (final gc in gcNodes) {
            gcTotalH += gc.visualHeight;
          }
          gcTotalH += gap * (gcNodes.length - 1);

          final gcX = childPos.dx + child.width + 80;
          final gcStartY = (slotY + (slotH - gcTotalH) / 2).clamp(0.0, 20000.0);
          double gcY = gcStartY;
          for (final gcTemp in gcNodes) {
            final gc = gcTemp.copyWith(position: Offset(gcX, gcY));
            currentPage.nodes[gc.id] = gc;
            newDescendantIds.add(gc.id);
            currentPage.connections.add(NodeConnection(
              fromId: child.id,
              fromAnchor: AnchorDirection.east,
              toId: gc.id,
              toAnchor: AnchorDirection.west,
            ));
            gcY += gc.visualHeight + gap;
          }
        }

        slotY += slotH + gap;
      }
      // 親のグループに子孫ノードも追加
      if (newDescendantIds.isNotEmpty) {
        addChildrenToParentGroups(nodeId, newDescendantIds);
      }
      _saveToStorage();
      notifyListeners();
    } finally {
      _endAi();
    }
  }

  /// AI: カスタムプロンプトの回答を子ノードとして追加
  Future<void> aiCustomPrompt(String nodeId, String userPrompt) async {
    final node = currentPage.nodes[nodeId];
    if (node == null) return;
    _beginAi();
    try {
      final ctx = '対象: 「${node.title}」\n\nユーザーの質問: $userPrompt\n\n'
          '【重要】「はい」「承知しました」「もちろん」などの冒頭の挨拶は不要です。'
          '回答だけを直接書いてください。';
      final answer = await _askAiAboutNode(node, ctx);
      if (_aiCancelled) return; // キャンセル済み → 結果を反映しない
      _pushUndo();
      // 同一ノードのメモとして追記（既存メモがあれば改行で連結）
      final existing = (node.memoText ?? '').trim();
      final newMemo =
          existing.isEmpty ? answer : '$existing\n\n【$userPrompt】\n$answer';
      currentPage.nodes[nodeId] = node.copyWith(
        memoText: newMemo,
        contentType: NodeContentType.memo,
      );
      _saveToStorage();
      notifyListeners();
    } finally {
      _endAi();
    }
  }

  /// 親ノードの真下に付箋ノードを置く位置を返す（重なり回避付き）
  Offset _findBelowPosition(MindMapNode parent, {double childWidth = 240.0}) {
    const gap = 16.0;
    // 親ノードの中央X、真下Y を基準に
    final baseX = parent.position.dx + (parent.width - childWidth) / 2;
    double baseY = parent.position.dy + parent.visualHeight + gap;

    // 既に真下に付箋があれば、さらに下にずらす
    for (final c in currentPage.connections) {
      if (c.fromId == parent.id && c.fromAnchor == AnchorDirection.south) {
        final existing = currentPage.nodes[c.toId];
        if (existing != null) {
          final bottom = existing.position.dy + existing.visualHeight + gap;
          if (bottom > baseY) baseY = bottom;
        }
      }
    }

    // 他ノードとの重なりを回避（最大10回）
    Offset candidate = Offset(baseX, baseY);
    for (int i = 0; i < 10; i++) {
      bool overlap = false;
      for (final n in currentPage.nodes.values) {
        if (n.id == parent.id) continue;
        if (_nodesOverlap(candidate, childWidth, 42.0, n, gap)) {
          overlap = true;
          candidate = Offset(candidate.dx,
              (n.position.dy + n.visualHeight + gap).clamp(0.0, 20000.0));
          break;
        }
      }
      if (!overlap) break;
    }
    return candidate;
  }

  /// 親ノードの右側に空きスペースを探して子ノードの位置を返す
  Offset _findChildPosition(MindMapNode parent,
      {double childWidth = 200.0, double childHeight = 42.0}) {
    const gap = 20.0;
    final baseX = parent.position.dx + parent.width + 80;
    double baseY = parent.position.dy;
    // 既存の子ノードの最下部を求める（visualHeightを考慮）
    for (final c in currentPage.connections) {
      if (c.fromId == parent.id) {
        final child = currentPage.nodes[c.toId];
        if (child != null) {
          final bottom = child.position.dy + child.visualHeight + gap;
          if (bottom > baseY) baseY = bottom;
        }
      }
    }
    // 他のノードとの重なりを回避
    Offset candidate = Offset(baseX, baseY);
    for (int i = 0; i < 30; i++) {
      bool overlap = false;
      for (final n in currentPage.nodes.values) {
        if (_nodesOverlap(candidate, childWidth, childHeight, n, gap)) {
          overlap = true;
          candidate = Offset(
              candidate.dx,
              (n.position.dy + n.visualHeight + gap)
                  .clamp(gap, 20000.0 - childHeight - gap));
          break;
        }
      }
      if (!overlap) break;
    }
    return candidate;
  }

  // YouTube再生位置記憶 (videoId → seconds)
  final Map<String, double> _videoPositions = {};
  String? _lastWatchedVideoId;

  // モバイル「YouTubeを開く」で最後に表示していた URL を記憶しておき、
  // 次回開いた時に同じ画面から再開できるようにする。
  // 一度もブラウズしたことがない場合は null。
  String? _lastYoutubeBrowseUrl;
  String? get lastYoutubeBrowseUrl => _lastYoutubeBrowseUrl;

  List<MindMapPage> get pages => List.unmodifiable(_pages);
  int get currentPageIndex => _currentPageIndex;
  MindMapPage get currentPage => _pages[_currentPageIndex];
  Map<String, MindMapNode> get nodes => Map.unmodifiable(currentPage.nodes);
  List<NodeConnection> get connections =>
      List.unmodifiable(currentPage.connections);

  /// 現在ページの装飾図形リスト (= 直線/矢印/長方形/楕円)。
  ///
  /// ユーザー要望「直線や矢印線、 長方形等の図形を挿入できるようにして」 への
  /// 対応で導入された [MapDecoration] を読み取り専用で公開。
  List<MapDecoration> get decorations =>
      List.unmodifiable(currentPage.decorations);
  String? get selectedNodeId => _selectedNodeId;
  MindMapNode? get selectedNode =>
      _selectedNodeId != null ? currentPage.nodes[_selectedNodeId] : null;

  // ── 装飾図形の操作メソッド ──
  // すべての変更で notifyListeners + currentPage.lastModifiedAt を更新して
  // UI 即時反映 + 永続化トリガー。 _saveToStorage は呼び出し側で適宜。

  /// 新規装飾を追加。 [id] は呼び出し側が一意な値を渡す (= timestamp 等)。
  void addMapDecoration(MapDecoration deco) {
    _pushUndo(); // Ctrl+Z で図形作成前に戻せるようにする
    currentPage.decorations.add(deco);
    currentPage.lastModifiedAt = DateTime.now();
    _saveToStorage();
    notifyListeners();
  }

  /// 装飾を ID で削除。
  void removeMapDecoration(String id) {
    _pushUndo();
    currentPage.decorations.removeWhere((d) => d.id == id);
    currentPage.lastModifiedAt = DateTime.now();
    _saveToStorage();
    notifyListeners();
  }

  /// 装飾の位置や形を更新 (= ドラッグ移動・端点移動・色/太さ/種類の変更など)。
  void updateMapDecoration(MapDecoration updated) {
    final idx = currentPage.decorations.indexWhere((d) => d.id == updated.id);
    if (idx < 0) return;
    _pushUndo();
    currentPage.decorations[idx] = updated;
    currentPage.lastModifiedAt = DateTime.now();
    _saveToStorage();
    notifyListeners();
  }

  /// 装飾のレイヤー (1〜5) を変更する (= ユーザー要望: マインドマップにも
  /// 5 段階のレイヤー機能)。 4〜5 はノードより手前に描かれる。
  // ─── ページ毎の「今いるレイヤー」 (= ユーザー要望: オブジェクト毎に
  //     レイヤーを変えるのではなく、 ページ毎にレイヤーを移動して、
  //     そのレイヤーに対してオブジェクトを配置する) ─────────────────────
  //
  // 図形 (MapDecoration) の layer は 1〜5。 3 が既定で、 4 以上はノードより
  // 手前に描かれる。 ここで選んだ層に新しい図形が置かれる。
  final Map<String, int> _activeLayerByPage = {};
  static const String _kActiveLayerKey = 'activeLayerByPage_v1';

  /// [pageId] (省略時は今のページ) で作業中のレイヤー番号 (1〜5)。
  int activeLayerOf([String? pageId]) {
    final id = pageId ?? currentPage.id;
    return (_activeLayerByPage[id] ?? 3).clamp(1, 5);
  }

  /// 今のページの作業レイヤー。
  int get activeLayer => activeLayerOf();

  /// 作業レイヤーを変える (ページ毎に覚える)。
  Future<void> setActiveLayer(int layer, {String? pageId}) async {
    final id = pageId ?? currentPage.id;
    final v = layer.clamp(1, 5);
    if (activeLayerOf(id) == v) return;
    _activeLayerByPage[id] = v;
    notifyListeners();
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setString(_kActiveLayerKey, jsonEncode(_activeLayerByPage));
    } catch (_) {}
  }

  Future<void> _loadActiveLayers() async {
    try {
      final prefs = await _prefsWithRetry();
      final raw = prefs.getString(_kActiveLayerKey);
      if (raw == null || raw.isEmpty) return;
      final j = jsonDecode(raw);
      if (j is! Map) return;
      _activeLayerByPage.clear();
      for (final e in j.entries) {
        final v = (e.value as num?)?.toInt();
        if (v != null) _activeLayerByPage['${e.key}'] = v.clamp(1, 5);
      }
      notifyListeners();
    } catch (_) {}
  }

  /// そのレイヤーに図形がいくつあるか (レイヤー選択メニューの表示用)。
  int decorationCountOnLayer(int layer) {
    var n = 0;
    for (final d in currentPage.decorations) {
      if (d.layer == layer) n++;
    }
    return n;
  }

  /// そのレイヤーにノードがいくつあるか。
  int nodeCountOnLayer(int layer) {
    var n = 0;
    for (final e in currentPage.nodes.values) {
      if (e.layer == layer) n++;
    }
    return n;
  }

  /// そのレイヤーにリンク (接続線) がいくつあるか。
  int connectionCountOnLayer(int layer) {
    var n = 0;
    for (final c in currentPage.connections) {
      if (c.layer == layer) n++;
    }
    return n;
  }

  /// ノードのレイヤーを変える (= ユーザー要望: レイヤーはノードにも適用)。
  void setNodeLayer(String id, int layer) {
    final node = currentPage.nodes[id];
    if (node == null) return;
    final v = layer.clamp(1, 5);
    if (node.layer == v) return;
    _pushUndo();
    currentPage.nodes[id] = node.copyWith(layer: v);
    currentPage.lastModifiedAt = DateTime.now();
    _saveToStorage();
    notifyListeners();
  }

  /// 選んだノード群と、 それにぶら下がる接続線をまとめてレイヤー移動する。
  void setNodesLayer(Iterable<String> ids, int layer) {
    final v = layer.clamp(1, 5);
    final set = ids.toSet();
    if (set.isEmpty) return;
    _pushUndo();
    for (final id in set) {
      final node = currentPage.nodes[id];
      if (node == null) continue;
      currentPage.nodes[id] = node.copyWith(layer: v);
    }
    // 両端とも選ばれている線も一緒に動かす (見た目が分断されないように)。
    for (var i = 0; i < currentPage.connections.length; i++) {
      final c = currentPage.connections[i];
      if (set.contains(c.fromId) && set.contains(c.toId)) {
        currentPage.connections[i] = c.copyWith(layer: v);
      }
    }
    currentPage.lastModifiedAt = DateTime.now();
    _saveToStorage();
    notifyListeners();
  }

  /// 接続線のレイヤーを変える。
  void setConnectionLayer(String fromId, String toId, int layer) {
    final v = layer.clamp(1, 5);
    var changed = false;
    for (var i = 0; i < currentPage.connections.length; i++) {
      final c = currentPage.connections[i];
      if (c.fromId == fromId && c.toId == toId && c.layer != v) {
        if (!changed) _pushUndo();
        currentPage.connections[i] = c.copyWith(layer: v);
        changed = true;
      }
    }
    if (!changed) return;
    currentPage.lastModifiedAt = DateTime.now();
    _saveToStorage();
    notifyListeners();
  }

  void setDecorationLayer(String id, int layer) {
    final idx = currentPage.decorations.indexWhere((d) => d.id == id);
    if (idx < 0) return;
    final v = layer.clamp(1, 5);
    if (currentPage.decorations[idx].layer == v) return;
    _pushUndo();
    currentPage.decorations[idx].layer = v;
    currentPage.lastModifiedAt = DateTime.now();
    _saveToStorage();
    notifyListeners();
  }

  // ── 装飾図形のハンドルドラッグ (移動 / リサイズ) ──
  // ドラッグ中は毎フレーム dragDecorationBy が呼ばれるため、 undo / save は
  // フレーム毎には行わない。 開始時に 1 度だけ undo スナップショットを積み
  // (beginDecorationDrag)、 終了時に 1 度だけ保存する (endDecorationDrag)。

  /// ハンドルドラッグ開始: 直前の状態を undo に積む (Ctrl+Z 1 回で戻せる)。
  void beginDecorationDrag() {
    _pushUndo();
  }

  /// ドラッグ中の差分適用 (start / end をデルタ分ずらす)。 save も undo もしない。
  void dragDecorationBy(String id,
      {Offset startDelta = Offset.zero, Offset endDelta = Offset.zero}) {
    final idx = currentPage.decorations.indexWhere((d) => d.id == id);
    if (idx < 0) return;
    final d = currentPage.decorations[idx];
    d.start = d.start + startDelta;
    d.end = d.end + endDelta;
    notifyListeners();
  }

  /// 装飾線の片端をノード端子へ接続、または端子から解除する。
  /// ドラッグ中に使うため undo / 保存はここでは行わず、呼び出し側が
  /// [beginDecorationDrag] / [endDecorationDrag] で操作全体をまとめる。
  void setDecorationEndpointAttachment(
    String id, {
    required bool isStart,
    String? nodeId,
    AnchorDirection? anchor,
    Offset? point,
  }) {
    final idx = currentPage.decorations.indexWhere((d) => d.id == id);
    if (idx < 0) return;
    final d = currentPage.decorations[idx];
    if (isStart) {
      if (point != null) d.start = point;
      d.startNodeId = nodeId;
      d.startNodeAnchor = anchor;
    } else {
      if (point != null) d.end = point;
      d.endNodeId = nodeId;
      d.endNodeAnchor = anchor;
    }
    notifyListeners();
  }

  /// ハンドルドラッグ終了: 1 度だけ保存。
  void endDecorationDrag() {
    currentPage.lastModifiedAt = DateTime.now();
    _saveToStorage();
    notifyListeners();
  }

  /// 図形内テキストの位置 (正規化アンカー) をドラッグ中に更新。 save / undo はしない
  /// (= ドラッグ開始時 beginDecorationDrag、 終了時 endDecorationDrag でまとめる)。
  void dragDecorationTextAnchor(String id, double ax, double ay) {
    final idx = currentPage.decorations.indexWhere((d) => d.id == id);
    if (idx < 0) return;
    final d = currentPage.decorations[idx];
    d.textAnchorX = ax.clamp(0.0, 1.0);
    d.textAnchorY = ay.clamp(0.0, 1.0);
    notifyListeners();
  }

  MindMapProvider() {
    // ★ 最優先: 言語/初回起動/下部ボタンを確実に読んで initialLoadDone を
    //   完了させる (= ユーザー報告の再発防止: 言語ピッカーが出ない / 英語固定 /
    //   下部ボタンが空)。 他のロードがハングしても起動フローが進む。
    _loadEssentialUiState();
    unawaited(_loadGoogleSession());
    // 分析用の属性 (国 / 言語 / 年齢 / 性別) を読み直す (= ユーザー要望)。
    unawaited(_loadAnalyticsProfile());
    _loadFromStorage().then((_) {
      // ロード完了後に最後に開いたページを復元
      // (= 起動時に前回作業していたマップが自動で開く)
      _restoreLastOpenedPage();
      _generateAllMissingThumbnails();
      // 他インスタンス (= もう 1 つ立ち上げたアプリ) の編集を取り込む監視を
      //   開始する (= ユーザー要望)。 基準が確定してからでないと初回ロードと
      //   競合するので、 ここで始める。
      _startCrossInstanceWatch();
    }).catchError((Object e, StackTrace st) {
      // ★ 起動ハング対策: ロードが reject されても永久ローディングにしない。
      debugPrint('起動ロードチェーンでエラー (復旧): $e\n$st');
      if (_pages.isEmpty) {
        try {
          _addDefaultPage(force: true);
        } catch (_) {}
        _currentPageIndex = 0;
      }
      notifyListeners();
    });
    // ★ 最終安全網: 何らかの理由 (プラグイン応答なし等) で 8 秒経っても
    //   ページが 1 枚も無い＝ローディングのままなら、 強制的にデフォルトページを
    //   作って UI を出す。 これで「ずっと読み込み中」が物理的に起こり得なくなる。
    _startupSafetyTimer = Timer(const Duration(seconds: 8), () {
      if (_disposed) return;
      if (_pages.isEmpty) {
        debugPrint('起動安全網: 8秒経過してもページ空 → デフォルトページを強制作成');
        try {
          _addDefaultPage(force: true);
        } catch (_) {}
        _currentPageIndex = 0;
        notifyListeners();
      }
    });
    _loadFontSettings();
    _loadGeneratedIds();
    _loadShelfCells();
    _loadHeaderAndBookshelfSettings();
    _loadFlashcards();
    _loadVideoPositions();
    _loadMcpServerSetting();
    // ignore: discarded_futures
    loadFlashcardTopicPrompt();
    // ページ毎の作業レイヤー (= ユーザー要望: レイヤーを移動して配置する)。
    _loadActiveLayers();
    _loadPublishedPages();
    _loadCachedOpenrouterModels();
    _loadApproxLocation();
    // 名前を自動で付けたページの控え (= ユーザー要望: 自分で決めた名前は
    //   AI に上書きさせない)。
    _loadAutoNamedPages();
    // ★ initialLoadDone は _loadGeminiApiKey の末尾で complete される。 万一
    //   この関数が途中で例外を投げても、 initialLoadDone を必ず完了させる
    //   (= 初回の言語ピッカーが永久に出ない不具合を防ぐ。 ユーザー報告)。
    _loadGeminiApiKey()
        .catchError((Object e) => debugPrint('初期ロードで例外 (続行): $e'))
        .whenComplete(() {
      if (!_initialLoadCompleter.isCompleted) {
        _initialLoadCompleter.complete();
        notifyListeners();
      }
    });
    _loadAiSettings();
    _loadChannelFilterSettings();
    _loadChannelQueues();
    _loadAutoSyncPageIds();
    _loadNamedGroups();
    // 課金 SDK の初期通知より先に、前回保存した状態を必ず読み終える。
    // 開発者モードも同じ SharedPreferences の演じプランに依存
    // するため、両方を並列起動せず必ずプラン復元の後に検証する。
    // これで更新後の高速起動時に初期値が保存値を見かけ上
    // 上書きするレースも避ける。
    _proStateLoadFuture = _loadProState().catchError(
      (Object e, StackTrace st) => debugPrint('プラン状態の復元に失敗 (起動は続行): $e\n$st'),
    );
    unawaited(_proStateLoadFuture!
        .then((_) => _loadDeveloperModeState())
        .catchError((Object e, StackTrace st) =>
            debugPrint('開発者モードの復元に失敗 (起動は続行): $e\n$st')));
    _loadJoinedGroups();
    _loadColorSettings();
    loadDisplayName();
    _loadCalendarGroupSharing();
    _loadCalendarViewingUid();
    // 非表示ページ / お気に入りページ の永続化状態を復元
    _loadHiddenPages();
    _loadFavoritePages();
    // PDF ページレベルの非表示リスト
    _loadHiddenPdfPages();
    // Web ページ用メモ (= Qiita 等の URL に紐づくメモ)
    _loadWebPageMemos();
    // Qiita ブロック投稿者リストを復元
    _loadQiitaBlocked();
    // Google検索ダイアログの永続化状態 (ドラフトメモ + 保存済みメモ) を復元
    loadGoogleSearchMemoState();
    // クイズ重複回避の設定と過去質問履歴を復元 (PDF → AI 一問一答)
    _loadQuizSettings();
    // AI モデル一覧の初期化 (キャッシュ復元 + 24h 経過なら裏で再取得)。
    // API キーの読み込みが完了してから呼ばないと、認証が必要な OpenAI /
    // Claude の models エンドポイントが叩けないので、_loadAiSettings の
    // 直後に呼ぶ。失敗しても問題ないので fire-and-forget。
    initializeAvailableModels();
    _initFirebase().then((_) => loadInquiryEmailFromCloud());
  }

  // ── Firebase REST API 実装 ──────────────────────────────────────────────────

  // ── Firebase 同期メソッド ─────────────────────────────────────────────────

  /// 起動時にFirebase匿名認証を行う（グループ参加は別途）
  /// Firebase初期化時の失敗理由（UIで表示できるよう保持）
  String? _firebaseInitError;
  String? get firebaseInitError => _firebaseInitError;

  /// Firebaseの設定が揃っているか（実際に通信できるかは別）
  bool get isFirebaseConfigured =>
      _firestoreProjectId.isNotEmpty && _authApiKey.isNotEmpty;

  Future<void> _initFirebase() {
    final inFlight = _firebaseInitInFlight;
    if (inFlight != null) return inFlight;

    final init = _doInitFirebase();
    _firebaseInitInFlight = init;
    return init.whenComplete(() {
      if (identical(_firebaseInitInFlight, init)) {
        _firebaseInitInFlight = null;
      }
    });
  }

  Future<void> _doInitFirebase() async {
    if (_firestoreProjectId.isEmpty || _authApiKey.isEmpty) {
      final missing = <String>[];
      if (_firestoreProjectId.isEmpty) missing.add('FIREBASE_PROJECT_ID');
      if (_authApiKey.isEmpty)
        missing.add(
            'FIREBASE_API_KEY_REST / FIREBASE_API_KEY_WINDOWS / FIREBASE_API_KEY_ANDROID');
      _firebaseInitError = t('sync.firebaseConfigMissing')
          .replaceFirst('{fields}', missing.join(', '));
      debugPrint('Firebase未設定 → オフラインモード ($_firebaseInitError)');
      return;
    }
    // ── ① 認証 (ここの成否だけが _firebaseEnabled を決める) ──
    try {
      await _signInAnonymously();
      _firebaseEnabled = true;
      _firebaseInitError = null;
      // ★ 認証できたら必ず代行 (アプリ側キー) が使えるか確かめる。
      //   以前は syncEntitlementFromServer() の「有料プランだった時」 だけ
      //   だったため、 前払いクレジットを買っただけの利用者は
      //   canUseAiRelay が false のままで AI が一切使えなかった
      //   (= ユーザー報告: チャージしたのに AI が動かない)。
      //   クレジットはプランと無関係なので、 起動時に毎回確かめる。
      unawaited(probeAiRelay(force: true));
      // 既にログイン済みの端末でも、 アイコンがまだ Google の物でなければ
      //   取りに行く (= ユーザー要望: ログインした時のアイコンは Google 垢の
      //   アイコンに。 ログインし直さなくても反映されるように)。
      if (_googleSignedIn && (_googleAvatarPath ?? '').isEmpty) {
        unawaited(refreshGoogleAvatar());
      }
    } catch (e) {
      _firebaseEnabled = false;
      _firebaseInitError =
          t('sync.anonymousAuthFailed').replaceFirst('{err}', '$e');
      debugPrint('Firebase init failed (offline): $e');
      return; // 認証失敗時はここで終了
    }
    // ── ② 認証成功後の処理 (= ハートビート/課金/期限削除) ──
    // 重要: ここでの失敗 (ネットワーク・タイムアウト等) で Firebase 自体を
    // 無効化してはいけない。 以前は _registerMember のタイムアウトが
    // catch に落ちて「匿名認証に失敗しました」 と誤表示し、 同期全体が無効化
    // (同期グループも消えたように見える) されていた (= ユーザー報告)。
    // 認証は成功しているので、 これらは失敗しても無視して同期は有効のまま。
    try {
      // RevenueCat 初期化 (モバイルのみ。 Windows 等は no-op)。
      if (_uid != null) {
        final proStateLoad = _proStateLoadFuture;
        if (proStateLoad != null) await proStateLoad;
        await _billing.configure(appUserId: _uid!);
      }
      _syncPlanToUserDoc();
      // 保存済みグループIDがあれば復元（自動同期はしない）
      final prefs = await _prefsWithRetry();
      final savedGroup = prefs.getString('syncGroupId');
      if (savedGroup != null && savedGroup.isNotEmpty) {
        // グループは registerMember より先に復元しておく
        // (ハートビートが失敗してもグループ所属は維持される)。
        _syncGroupId = savedGroup;
        await _registerMember(savedGroup);
        final lastPruneMs = prefs.getInt('lastPruneAtMs') ?? 0;
        final now = DateTime.now().millisecondsSinceEpoch;
        if (now - lastPruneMs > Duration(hours: 24).inMilliseconds) {
          await prefs.setInt('lastPruneAtMs', now);
          // ignore: discarded_futures
          pruneExpiredCloudData();
        }
      }
    } catch (e) {
      // 認証は成功済み → 同期は有効のまま。 ハートビート等の失敗は無視。
      debugPrint('Firebase post-auth step failed (sync still enabled): $e');
    }
  }

  /// Firebase再初期化（同期グループ参加前に自動リトライ）
  Future<void> retryFirebaseInit() async {
    if (_firebaseEnabled) return;
    await _initFirebase();
    notifyListeners();
  }

  // ─── Google アカウントでのログイン (= ユーザー要望) ────────────────────
  //
  // 同じ Google アカウントでログインした端末は、 Firebase の利用者 ID (uid)
  // が同じになる。 有料プランもクラウド使用量も uid で数えているので、
  // ログインするだけで端末をまたいで共有される。
  // (匿名のままだと端末ごとに別人扱いになり、 プランが引き継げなかった。
  //  以前あった「ライセンスの引き継ぎコード」 はこれで不要になったので廃止。)

  bool _googleSignedIn = false;
  bool get googleSignedIn => _googleSignedIn;
  String _googleEmail = '';
  String get googleEmail => _googleEmail;

  /// この端末で Google ログインを出せるか。
  bool get canUseGoogleSignIn =>
      _firebaseEnabled && GoogleAuth.isConfigured && GoogleAuth.isSupported;

  Future<void> _loadGoogleSession() async {
    try {
      final prefs = await _prefsWithRetry();
      _googleSignedIn = prefs.getBool('google_signed_in') ?? false;
      _googleEmail = prefs.getString('google_email') ?? '';
      _googleAvatarPath = prefs.getString('google_avatar_path');
      notifyListeners();
    } catch (_) {}
  }

  /// Google アカウントでログインし直す。 成功したらメールアドレスを返す。
  /// 利用者が途中でやめた場合は null。
  Future<String?> signInWithGoogle({VoidCallback? onWaiting}) async {
    if (!canUseGoogleSignIn) {
      throw Exception(t('account.notConfigured'));
    }
    final signIn = await GoogleAuth.signIn(onWaiting: onWaiting);
    if (signIn == null) return null;
    final googleIdToken = signIn.idToken;

    // Google の証明書を Firebase の利用者に引き換える。 同じ Google
    //   アカウントなら、 どの端末でも同じ uid が返る。
    final res = await http
        .post(
          Uri.parse(
              'https://identitytoolkit.googleapis.com/v1/accounts:signInWithIdp?key=$_authApiKey'),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode({
            'postBody': 'id_token=$googleIdToken&providerId=google.com',
            'requestUri': 'http://127.0.0.1',
            'returnIdpCredential': true,
            'returnSecureToken': true,
          }),
        )
        .timeout(const Duration(seconds: 60));
    if (res.statusCode != 200) {
      throw Exception(t('account.signInFailed')
          .replaceFirst('{err}', '${res.statusCode} ${res.body}'));
    }
    final data = jsonDecode(res.body) as Map<String, dynamic>;
    final idToken = data['idToken'] as String?;
    final uid = data['localId'] as String?;
    final refresh = data['refreshToken'] as String?;
    if (idToken == null || uid == null || refresh == null) {
      throw Exception(t('sync.authResponseInvalid'));
    }
    final expiresIn = int.tryParse('${data['expiresIn'] ?? 3600}') ?? 3600;
    _idToken = idToken;
    _uid = uid;
    _idTokenExpiry = DateTime.now().add(Duration(seconds: expiresIn));
    _googleSignedIn = true;
    _googleEmail = (data['email'] as String?) ?? '';
    // 表示名は Google の名前をそのまま使う (= ユーザー要望: 自分で
    //   ユーザー名を決める機能は無くす)。
    final gName = (data['displayName'] as String?) ?? '';
    if (gName.isNotEmpty) _displayName = gName;
    // アイコンも Google アカウントの物に合わせる (= ユーザー要望)。
    await _applyGoogleAvatar((data['photoUrl'] as String?) ?? '');

    final prefs = await _prefsWithRetry();
    await prefs.setString('firebase_refresh_token', refresh);
    await prefs.setString('firebase_uid', uid);
    await prefs.setBool('google_signed_in', true);
    await prefs.setString('google_email', _googleEmail);
    if (gName.isNotEmpty) await prefs.setString('displayName', gName);

    // ── 分析用の属性 (= ユーザー要望: 年齢・性別・国) ──
    //    ふだんのログインで必ず取れるのは「国 / 言語」 だけ。 Google が
    //    ID トークンと一緒に返す locale と、 端末の地域設定から拾う。
    //    生年月日と性別は追加の許可が要るので `fetchGoogleProfileDetails`。
    try {
      final raw = data['rawUserInfo'];
      if (raw is String && raw.isNotEmpty) {
        final info = jsonDecode(raw);
        if (info is Map) {
          final loc = '${info['locale'] ?? ''}'.trim();
          if (loc.isNotEmpty) _analyticsLocale = loc;
        }
      }
    } catch (_) {}
    await _captureDeviceRegion();
    await _saveAnalyticsProfile();

    notifyListeners();
    // このアカウントの状態 (プラン / 使用量) を取り込む。
    await pullAccountState();
    await pushAccountState();
    unawaited(probeAiRelay());
    unawaited(refreshCreditBalance());
    return _googleEmail.isEmpty ? uid : _googleEmail;
  }

  // ─── 分析用の属性 (年齢 / 性別 / 国) ────────────────────────────────────
  // = ユーザー要望: Google アカウントから年齢・性別・国を取って分析に使いたい。
  //
  // 取れるもの / 取れないものは Google 側の都合で決まる:
  //   - 国 …… アカウントに住所が入っていれば People API から。 ふつうは
  //            入っていないので、 端末の地域設定 (ja_JP → JP) で補う。
  //   - 言語 … ログイン時に Google が返す locale。 追加の許可は要らない。
  //   - 生年月日 / 性別 …… People API + 機密スコープ。 本人が設定していて、
  //            かつ同意した時だけ返る (未設定なら空で返る)。 一般公開には
  //            Google の OAuth 審査が要る。
  String _analyticsGender = '';
  int _analyticsBirthYear = 0;
  int _analyticsBirthMonth = 0;
  int _analyticsBirthDay = 0;
  String _analyticsCountry = '';
  String _analyticsLocale = '';
  String _analyticsSource = '';
  int _analyticsUpdatedAtMs = 0;

  String get analyticsGender => _analyticsGender;
  String get analyticsCountry => _analyticsCountry;
  String get analyticsLocale => _analyticsLocale;
  String get analyticsSource => _analyticsSource;
  int get analyticsBirthYear => _analyticsBirthYear;
  DateTime? get analyticsUpdatedAt => _analyticsUpdatedAtMs == 0
      ? null
      : DateTime.fromMillisecondsSinceEpoch(_analyticsUpdatedAtMs);

  /// 生年月日から数えた今の年齢。 年が分からない時は null。
  int? get analyticsAge {
    if (_analyticsBirthYear <= 0) return null;
    final now = DateTime.now();
    var age = now.year - _analyticsBirthYear;
    if (_analyticsBirthMonth > 0) {
      final hadBirthday = now.month > _analyticsBirthMonth ||
          (now.month == _analyticsBirthMonth &&
              (_analyticsBirthDay <= 0 || now.day >= _analyticsBirthDay));
      if (!hadBirthday) age -= 1;
    }
    return age < 0 || age > 130 ? null : age;
  }

  Future<void> _loadAnalyticsProfile() async {
    try {
      final prefs = await _prefsWithRetry();
      _analyticsGender = prefs.getString('analytics_gender') ?? '';
      _analyticsBirthYear = prefs.getInt('analytics_birth_year') ?? 0;
      _analyticsBirthMonth = prefs.getInt('analytics_birth_month') ?? 0;
      _analyticsBirthDay = prefs.getInt('analytics_birth_day') ?? 0;
      _analyticsCountry = prefs.getString('analytics_country') ?? '';
      _analyticsLocale = prefs.getString('analytics_locale') ?? '';
      _analyticsSource = prefs.getString('analytics_source') ?? '';
      _analyticsUpdatedAtMs = prefs.getInt('analytics_updated_at') ?? 0;
    } catch (_) {}
    // 端末の地域はいつでも取れるので、 未設定なら埋めておく。
    if (_analyticsCountry.isEmpty) {
      await _captureDeviceRegion();
      await _saveAnalyticsProfile();
    }
    notifyListeners();
  }

  Future<void> _saveAnalyticsProfile() async {
    _analyticsUpdatedAtMs = DateTime.now().millisecondsSinceEpoch;
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setString('analytics_gender', _analyticsGender);
      await prefs.setInt('analytics_birth_year', _analyticsBirthYear);
      await prefs.setInt('analytics_birth_month', _analyticsBirthMonth);
      await prefs.setInt('analytics_birth_day', _analyticsBirthDay);
      await prefs.setString('analytics_country', _analyticsCountry);
      await prefs.setString('analytics_locale', _analyticsLocale);
      await prefs.setString('analytics_source', _analyticsSource);
      await prefs.setInt('analytics_updated_at', _analyticsUpdatedAtMs);
    } catch (_) {}
  }

  /// 端末の地域設定から国 / 言語を拾う (許可も通信も要らない)。
  /// 例: `ja_JP` → 言語 ja / 国 JP。
  Future<void> _captureDeviceRegion() async {
    try {
      final name = Platform.localeName; // ja_JP.UTF-8 のこともある
      final base = name.split('.').first.replaceAll('-', '_');
      final parts = base.split('_');
      if (parts.isNotEmpty && parts.first.isNotEmpty) {
        if (_analyticsLocale.isEmpty) _analyticsLocale = parts.first;
      }
      if (parts.length >= 2 && parts[1].length == 2) {
        if (_analyticsCountry.isEmpty) {
          _analyticsCountry = parts[1].toUpperCase();
          if (_analyticsSource.isEmpty) _analyticsSource = 'device';
        }
      }
    } catch (_) {}
  }

  // 旧 `fetchGoogleProfileDetails` (Google に生年月日 / 性別 / 住所の国を
  //   聞きに行く) は廃止 (= ユーザー要望: 自分自身のアカウント情報を取りに
  //   行っても意味が無い)。 機密スコープ (user.birthday.read /
  //   user.gender.read / user.addresses.read) の要求ごとやめたので、
  //   Google の OAuth 審査も不要になった。 国 / 言語は端末の設定とログイン
  //   情報から入る (`_captureDeviceRegion`)。

  /// Google アカウントの写真をアイコンにする (= ユーザー要望: ログインした時の
  /// アイコンは Google 垢のアイコンに)。
  ///
  /// 画像アバターは「ファイルの場所」 で持っているので、 一度落として端末に
  /// 置いてから設定する。 落とせなかった時は今のアイコンをそのまま残す。
  Future<void> _applyGoogleAvatar(String photoUrl) async {
    final url = photoUrl.trim();
    if (url.isEmpty) return;
    try {
      // s96-c のような大きさ指定が付いていることがあるので、 少し大きめに。
      final sized = url.contains('=s')
          ? url.replaceFirst(RegExp(r'=s\d+(-c)?$'), '=s256-c')
          : url;
      final res = await http
          .get(Uri.parse(sized))
          .timeout(const Duration(seconds: 20));
      if (res.statusCode != 200 || res.bodyBytes.isEmpty) return;
      final dir = await getApplicationSupportDirectory();
      final file =
          File('${dir.path}${Platform.pathSeparator}google_avatar.png');
      await file.writeAsBytes(res.bodyBytes, flush: true);
      // 同じ場所に上書きすると Flutter の画像キャッシュが古い絵を出すので、
      //   読み直させるために一度キャッシュから外す。
      try {
        await FileImage(file).evict();
      } catch (_) {}
      _googleAvatarPath = file.path;
      try {
        final prefs = await _prefsWithRetry();
        await prefs.setString('google_avatar_path', file.path);
      } catch (_) {}
      await setUserAvatarImage(file.path);
    } catch (e) {
      debugPrint('Google アイコンの取得に失敗: $e');
    }
  }

  /// Google から落としてきたアイコンの置き場所 (ログアウト時に外すため)。
  String? _googleAvatarPath;

  /// ログイン済みの端末で、 Google アカウントの今の写真をアイコンに反映する。
  /// (ログインし直さなくても切り替わるように。 写真が無いアカウントなら何もしない)
  Future<void> refreshGoogleAvatar() async {
    if (!_googleSignedIn) return;
    try {
      await _ensureFreshToken();
      if (_idToken == null) return;
      final res = await http
          .post(
            Uri.parse(
                'https://identitytoolkit.googleapis.com/v1/accounts:lookup?key=$_authApiKey'),
            headers: {'Content-Type': 'application/json'},
            body: jsonEncode({'idToken': _idToken}),
          )
          .timeout(const Duration(seconds: 30));
      if (res.statusCode != 200) return;
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final users = data['users'];
      if (users is! List || users.isEmpty) return;
      final me = users.first;
      if (me is! Map) return;
      await _applyGoogleAvatar('${me['photoUrl'] ?? ''}');
    } catch (e) {
      debugPrint('Google アイコンの更新に失敗: $e');
    }
  }

  /// ログアウトして、 この端末だけの匿名利用に戻す。
  Future<void> signOutGoogle() async {
    _googleSignedIn = false;
    _googleEmail = '';
    _idToken = null;
    _uid = null;
    _idTokenExpiry = null;
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setBool('google_signed_in', false);
      await prefs.remove('google_email');
      await prefs.remove('firebase_refresh_token');
      await prefs.remove('firebase_uid');
      // Google のアイコンを使っていたなら外す (= 別人のアイコンが残らないよう)。
      final gAvatar = _googleAvatarPath ?? prefs.getString('google_avatar_path');
      if (gAvatar != null && gAvatar.isNotEmpty) {
        if (_userAvatarImagePath == gAvatar) {
          await setUserAvatarImage(null);
        }
        _googleAvatarPath = null;
        await prefs.remove('google_avatar_path');
      }
    } catch (_) {}
    notifyListeners();
    try {
      await _ensureFreshToken(force: true);
    } catch (e) {
      debugPrint('匿名に戻せませんでした: $e');
    }
  }

  // ─── アカウントごとの状態 (プラン / 使用量) の共有 ──────────────────────
  // どちらも uid で数えているので、 users/{uid} に置いて端末間で読み書きする。

  Timer? _accountPushTimer;

  /// 端末で変わった状態をアカウントへ書き戻す (まとめて 1 回)。
  void scheduleAccountPush() {
    if (!_googleSignedIn) return;
    _accountPushTimer?.cancel();
    _accountPushTimer = Timer(const Duration(seconds: 3), () {
      unawaited(pushAccountState());
    });
  }

  Future<void> pushAccountState() async {
    if (!_firebaseEnabled || !_googleSignedIn) return;
    if (_uid == null) return;
    try {
      await _ensureFreshToken();
      final fields = <String, dynamic>{
        'plan': {'stringValue': _purchasedPlan.name},
        'proSubscribed': {'booleanValue': _proSubscribed},
        'subscriptionEndedAtMs': {
          'integerValue':
              '${_subscriptionEndedAt?.millisecondsSinceEpoch ?? 0}'
        },
        'billingMonthYm': {'stringValue': _billingMonthYm},
        'monthlyUploadBytes': {'integerValue': '$_monthlyUploadBytes'},
        'monthlyDownloadBytes': {'integerValue': '$_monthlyDownloadBytes'},
        'totalStorageBytes': {'integerValue': '$_totalStorageBytes'},
        'displayName': {'stringValue': _displayName ?? ''},
        // ── 分析用の属性 (= ユーザー要望: 年齢 / 性別 / 国を見たい) ──
        //    取れていない項目は空のまま送る (集計側で「不明」 として数える)。
        'country': {'stringValue': _analyticsCountry},
        'locale': {'stringValue': _analyticsLocale},
        'gender': {'stringValue': _analyticsGender},
        'birthYear': {'integerValue': '$_analyticsBirthYear'},
        'ageYears': {'integerValue': '${analyticsAge ?? 0}'},
        'profileSource': {'stringValue': _analyticsSource},
        'updatedAt': {'stringValue': DateTime.now().toUtc().toIso8601String()},
      };
      final mask = fields.keys
          .map((k) => 'updateMask.fieldPaths=$k')
          .join('&');
      await http
          .patch(
            Uri.parse('$_firestoreBaseUrl/users/$_uid?$mask'),
            headers: {
              'Authorization': 'Bearer $_idToken',
              'Content-Type': 'application/json',
            },
            body: jsonEncode({'fields': fields}),
          )
          .timeout(const Duration(seconds: 30));
    } catch (e) {
      debugPrint('pushAccountState failed: $e');
    }
  }

  /// アカウント側の状態を取り込む。
  /// プランは「上の方」 を、 使用量は「多い方」 を採る
  /// (別の端末で使った分を取りこぼさないため)。
  Future<void> pullAccountState() async {
    if (!_firebaseEnabled || !_googleSignedIn) return;
    if (_uid == null) return;
    try {
      await _ensureFreshToken();
      final res = await http.get(
        Uri.parse('$_firestoreBaseUrl/users/$_uid'),
        headers: {'Authorization': 'Bearer $_idToken'},
      ).timeout(const Duration(seconds: 30));
      if (res.statusCode != 200) return; // 初回はまだ無い
      final doc = jsonDecode(res.body) as Map<String, dynamic>;
      final f = doc['fields'] as Map<String, dynamic>? ?? {};
      int intOf(String k) =>
          int.tryParse('${(f[k] as Map?)?['integerValue'] ?? 0}') ?? 0;
      String strOf(String k) => _firestoreStr(f[k]) ?? '';

      final prefs = await _prefsWithRetry();

      // ── プラン (上位を優先) ──
      const rank = {'free': 0, 'pro': 1, 'max': 2};
      final remote = strOf('plan');
      if (rank.containsKey(remote) &&
          (rank[remote] ?? 0) > (rank[_purchasedPlan.name] ?? 0)) {
        _purchasedPlan = SubscriptionPlan.values
            .firstWhere((e) => e.name == remote,
                orElse: () => SubscriptionPlan.free);
        _proSubscribed = remote != 'free';
        await prefs.setString('purchased_plan', remote);
        await prefs.setBool('pro_subscribed', _proSubscribed);
        // 解約日時は上位プランを取り込んだ時点で無効にする。
        _subscriptionEndedAt = null;
        await prefs.remove('subscription_ended_at_ms');
      }

      // ── 使用量 (同じ月なら多い方) ──
      final remoteYm = strOf('billingMonthYm');
      if (remoteYm.isNotEmpty && remoteYm == _billingMonthYm) {
        _monthlyUploadBytes =
            math.max(_monthlyUploadBytes, intOf('monthlyUploadBytes'));
        _monthlyDownloadBytes =
            math.max(_monthlyDownloadBytes, intOf('monthlyDownloadBytes'));
      }
      // 保存済みファイルの総量は月に関係なくアカウント共通。
      _totalStorageBytes =
          math.max(_totalStorageBytes, intOf('totalStorageBytes'));
      await _persistMonthlyUsage();

      // ── 表示名 (Google 側を正とする) ──
      final name = strOf('displayName');
      if (name.isNotEmpty && name != _displayName) {
        _displayName = name;
        await prefs.setString('displayName', name);
      }
      notifyListeners();
    } catch (e) {
      debugPrint('pullAccountState failed: $e');
    }
  }

  Future<void> _signInAnonymously() async {
    // 保存済みリフレッシュトークンがあればそれを使う
    final prefs = await _prefsWithRetry();
    final savedRefresh = prefs.getString('firebase_refresh_token');
    if (savedRefresh != null && savedRefresh.isNotEmpty) {
      final ok = await _refreshIdToken(savedRefresh);
      if (ok) return;
    }
    // Google でログイン中なら、 勝手に別人 (匿名) を作らない。
    //   ここで匿名を作ると uid が変わり、 プランも使用量も見失う。
    if (_googleSignedIn) {
      throw Exception(t('account.reSignInNeeded'));
    }
    // なければ新規匿名ユーザー作成
    final res = await http
        .post(
          Uri.parse('$_authUrl?key=$_authApiKey'),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode({'returnSecureToken': true}),
          // 新規匿名ユーザー作成。 短すぎると認証失敗→同期無効化になるため余裕を。
        )
        .timeout(const Duration(seconds: 60));
    if (res.statusCode == 200) {
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final idToken = data['idToken'] as String?;
      final uid = data['localId'] as String?;
      final refresh = data['refreshToken'] as String?;
      if (idToken == null ||
          idToken.isEmpty ||
          uid == null ||
          uid.isEmpty ||
          refresh == null ||
          refresh.isEmpty) {
        throw FormatException(t('sync.authResponseInvalid'));
      }
      final expiresIn = int.tryParse('${data['expiresIn'] ?? 3600}') ?? 3600;
      // 完全なレスポンスを検証してから現在の認証情報を差し替える。
      _idToken = idToken;
      _uid = uid;
      _idTokenExpiry = DateTime.now().add(Duration(seconds: expiresIn));
      await prefs.setString('firebase_refresh_token', refresh);
      await prefs.setString('firebase_uid', uid);
    } else {
      throw Exception(t('sync.authRequestFailed')
          .replaceFirst('{err}', '${res.statusCode} ${res.body}'));
    }
  }

  /// リフレッシュトークンで新しいIDトークンを取得
  Future<bool> _refreshIdToken(String refreshToken) async {
    final res = await http
        .post(
          Uri.parse(
              'https://securetoken.googleapis.com/v1/token?key=$_authApiKey'),
          headers: {'Content-Type': 'application/x-www-form-urlencoded'},
          body: 'grant_type=refresh_token&refresh_token=$refreshToken',
          // 認証は少し遅いことがあるので余裕を持たせる (短すぎると「匿名認証に
          // 失敗しました」 で同期全体が無効化される = ユーザー報告)。
        )
        .timeout(const Duration(seconds: 45));
    if (res.statusCode == 200) {
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final idToken = data['id_token'] as String?;
      final uid = data['user_id'] as String?;
      final newRefresh = data['refresh_token'] as String?;
      if (idToken == null || idToken.isEmpty || uid == null || uid.isEmpty) {
        throw FormatException(t('sync.tokenResponseInvalid'));
      }
      final expiresIn = int.tryParse('${data['expires_in'] ?? 3600}') ?? 3600;
      _idToken = idToken;
      _uid = uid;
      _idTokenExpiry = DateTime.now().add(Duration(seconds: expiresIn));
      if (newRefresh != null && newRefresh.isNotEmpty) {
        final prefs = await _prefsWithRetry();
        await prefs.setString('firebase_refresh_token', newRefresh);
      }
      return true;
    }

    // 新しい匿名 UID を作ってよいのは、保存済み refresh token が無効だと
    // Firebase から明示された場合だけ。一時的な 5xx・設定不備・通信例外で
    // UID を作り直すと、同期グループと購入者 ID の紐付けを失う。
    var errorText = res.body.toUpperCase();
    try {
      final body = jsonDecode(res.body) as Map<String, dynamic>;
      final error = body['error'];
      if (error is Map<String, dynamic>) {
        errorText =
            '${error['message'] ?? ''} ${error['status'] ?? ''}'.toUpperCase();
      }
    } catch (_) {}
    const invalidMarkers = <String>[
      'INVALID_REFRESH_TOKEN',
      'INVALID_GRANT',
      'TOKEN_EXPIRED',
      'USER_DISABLED',
      'USER_NOT_FOUND',
    ];
    if (res.statusCode == 400 &&
        invalidMarkers.any((marker) => errorText.contains(marker))) {
      debugPrint('保存済み Firebase refresh token は無効です');
      return false;
    }
    throw Exception(t('sync.tokenRefreshFailed')
        .replaceFirst('{err}', 'HTTP ${res.statusCode} ${res.body}'));
  }

  /// トークンをリフレッシュしてリトライ可能にする
  Future<void> _ensureFreshToken({bool force = false}) async {
    // トークンがまだ十分に有効なら更新をスキップして高速化する
    // (= ユーザー報告: Ctrl+D の読み込みが毎回のトークン更新往復で遅い)。
    // force=true (401/403 リトライ時) は必ず再取得する。
    if (!force &&
        _idToken != null &&
        _idTokenExpiry != null &&
        DateTime.now()
            .isBefore(_idTokenExpiry!.subtract(const Duration(minutes: 5)))) {
      return;
    }
    final existing = _tokenRefreshInFlight;
    if (existing != null) {
      await existing;
      // force は custom claim 更新後にも使うため、先行更新が終わった後でも
      // もう一度取得して最新 claim を保証する。
      if (!force) return;
    }

    final refresh = _signInAnonymously();
    _tokenRefreshInFlight = refresh;
    try {
      await refresh;
    } finally {
      if (identical(_tokenRefreshInFlight, refresh)) {
        _tokenRefreshInFlight = null;
      }
    }
  }

  // ── グループ管理 ──────────────────────────────────────────────────────────

  /// 一度に参加できる同期グループの最大数
  static const int maxJoinedGroups = 5;

  /// 新しいグループを作成してホストになる
  /// 戻り値: 他のユーザーに共有する8桁のグループコード
  Future<String> createGroup() async {
    if (!isMaxUnlocked) {
      throw Exception(t('paywall.maxRequiredCloudSync'));
    }
    if (!_firebaseEnabled) {
      await _initFirebase(); // 1回リトライ
    }
    if (!_firebaseEnabled) {
      throw Exception(_firebaseInitError ?? t('sync.firebaseNotConfigured'));
    }
    if (_joinedGroupIds.length >= maxJoinedGroups) {
      throw Exception(
          t('sync.groupLimit').replaceFirst('{n}', '$maxJoinedGroups'));
    }
    // 8桁英数字のグループコードを生成
    final code = _uuid.v4().replaceAll('-', '').substring(0, 8).toUpperCase();
    await _writeGroupMeta(code);
    await joinGroup(code);
    return code;
  }

  /// グループコードを入力して参加（グループIDを保存 + メンバー登録）
  /// 同じコードで再度参加しても重複しない
  Future<void> joinGroup(String groupCode) async {
    if (!isMaxUnlocked) {
      throw Exception(t('paywall.maxRequiredCloudSync'));
    }
    if (!_firebaseEnabled) {
      await _initFirebase(); // 1回リトライ
    }
    if (!_firebaseEnabled) {
      throw Exception(_firebaseInitError ?? t('sync.firebaseNotConfigured'));
    }
    final code = groupCode.trim().toUpperCase();
    if (!RegExp(r'^[A-Z0-9]{8}$').hasMatch(code)) {
      throw Exception(t('sync.invalidGroupCode'));
    }
    // 既に参加中のグループでなければ上限チェック
    if (!_joinedGroupIds.contains(code) &&
        _joinedGroupIds.length >= maxJoinedGroups) {
      throw Exception(
          t('sync.groupLimit').replaceFirst('{n}', '$maxJoinedGroups'));
    }
    if (!await _groupExists(code)) {
      throw Exception(t('sync.groupNotFound'));
    }
    if (!await _registerMember(code)) {
      throw Exception(t('sync.groupJoinFailed'));
    }

    // サーバー側の参加登録が成功してからローカル状態を確定する。
    _syncGroupId = code;
    if (!_joinedGroupIds.contains(code)) {
      _joinedGroupIds.add(code);
    }
    final prefs = await _prefsWithRetry();
    await prefs.setString('syncGroupId', code);
    await _saveJoinedGroups();
    notifyListeners();
  }

  /// アクティブな同期グループを切替（参加済みのものから選択）
  Future<void> setActiveGroup(String? groupCode) async {
    if (groupCode != null && !isMaxUnlocked) {
      throw Exception(t('paywall.maxRequiredCloudSync'));
    }
    if (groupCode != null && !_joinedGroupIds.contains(groupCode)) return;
    _syncGroupId = groupCode;
    final prefs = await _prefsWithRetry();
    if (groupCode == null) {
      await prefs.remove('syncGroupId');
    } else {
      await prefs.setString('syncGroupId', groupCode);
    }
    notifyListeners();
  }

  /// 特定のグループから離脱（複数所属対応）
  Future<void> leaveSpecificGroup(String groupCode) async {
    final code = groupCode.trim().toUpperCase();
    _joinedGroupIds.remove(code);
    // ページ紐付けからも削除
    _pageGroupBindings.removeWhere((_, gid) => gid == code);
    if (_syncGroupId == code) {
      _syncGroupId = _joinedGroupIds.isNotEmpty ? _joinedGroupIds.first : null;
    }
    final prefs = await _prefsWithRetry();
    if (_syncGroupId == null) {
      await prefs.remove('syncGroupId');
    } else {
      await prefs.setString('syncGroupId', _syncGroupId!);
    }
    await _saveJoinedGroups();
    await prefs.setString('pageGroupBindings', jsonEncode(_pageGroupBindings));
    notifyListeners();
    if (_firebaseEnabled) {
      await _unregisterMember(code);
      await _cleanupGroupIfEmpty(code);
    }
  }

  /// グループから離脱（ローカル専用に戻る）— 互換維持
  Future<void> leaveGroup() async {
    _syncTimer?.cancel();
    final leavingGroupId = _syncGroupId;
    if (leavingGroupId != null) {
      await leaveSpecificGroup(leavingGroupId);
    } else {
      _syncGroupId = null;
      final prefs = await _prefsWithRetry();
      await prefs.remove('syncGroupId');
      notifyListeners();
    }
  }

  // ── グループメンバー管理 ──────────────────────────────────────────────────

  Future<bool> _groupExists(String groupCode) async {
    if (_idToken == null) return false;
    try {
      await _ensureFreshToken();
      final res = await http.get(
        Uri.parse('$_firestoreBaseUrl/groups/$groupCode'),
        headers: {'Authorization': 'Bearer $_idToken'},
      ).timeout(const Duration(seconds: 20));
      return res.statusCode == 200;
    } catch (e) {
      debugPrint('グループ存在確認エラー: $e');
      return false;
    }
  }

  /// メンバーとしてFirestoreに登録（タイムスタンプ付き）
  Future<bool> _registerMember(String groupCode) async {
    if (_idToken == null || _uid == null) return false;
    try {
      await _ensureFreshToken();
      final url = '$_firestoreBaseUrl/groups/$groupCode/members/$_uid';
      final res = await http
          .patch(
            Uri.parse(
                '$url?updateMask.fieldPaths=lastSeen&updateMask.fieldPaths=uid&updateMask.fieldPaths=displayName&updateMask.fieldPaths=allowCalendarSharing'),
            headers: {
              'Authorization': 'Bearer $_idToken',
              'Content-Type': 'application/json',
            },
            body: jsonEncode({
              'fields': {
                'uid': {'stringValue': _uid!},
                'displayName': {
                  'stringValue': _displayName ?? t('msg.anonymous')
                },
                'lastSeen': {'stringValue': DateTime.now().toIso8601String()},
                'allowCalendarSharing': {
                  'booleanValue': _calendarGroupSharingEnabled,
                },
              },
            }),
          )
          .timeout(const Duration(seconds: 20)); // ハング防止 (= ユーザー報告)
      if (res.statusCode < 200 || res.statusCode >= 300) {
        debugPrint('メンバー登録失敗: ${res.statusCode} ${res.body}');
        return false;
      }
      debugPrint('グループ $groupCode にメンバー登録完了: $_uid');
      return true;
    } catch (e) {
      debugPrint('メンバー登録エラー: $e');
      return false;
    }
  }

  /// メンバー登録を削除
  Future<void> _unregisterMember(String groupCode) async {
    if (_idToken == null || _uid == null) return;
    try {
      final url = '$_firestoreBaseUrl/groups/$groupCode/members/$_uid';
      await http.delete(
        Uri.parse(url),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      debugPrint('グループ $groupCode からメンバー解除: $_uid');
    } catch (e) {
      debugPrint('メンバー解除エラー: $e');
    }
  }

  /// メンバーがいるか確認し、0人ならグループ全データを削除
  Future<void> _cleanupGroupIfEmpty(String groupCode) async {
    if (_idToken == null) return;
    try {
      // メンバー一覧を取得
      final membersUrl = '$_firestoreBaseUrl/groups/$groupCode/members';
      final res = await http.get(
        Uri.parse(membersUrl),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      if (res.statusCode != 200) return;
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final docs = data['documents'] as List<dynamic>? ?? [];

      // 7日以上アクセスのないメンバーは無効とみなす
      final now = DateTime.now();
      int activeMembers = 0;
      final staleIds = <String>[];
      for (final doc in docs) {
        try {
          final fields = doc['fields'] as Map<String, dynamic>;
          final lastSeenStr = _firestoreStr(fields['lastSeen']);
          if (lastSeenStr != null) {
            final lastSeen = DateTime.tryParse(lastSeenStr);
            if (lastSeen != null && now.difference(lastSeen).inDays <= 7) {
              activeMembers++;
              continue;
            }
          }
          // 古いメンバーのドキュメントパスを抽出
          final docName = doc['name'] as String?;
          if (docName != null) staleIds.add(docName);
        } catch (_) {}
      }

      // 古いメンバーを削除
      for (final docPath in staleIds) {
        try {
          final deleteUrl = 'https://firestore.googleapis.com/v1/$docPath';
          await http.delete(
            Uri.parse(deleteUrl),
            headers: {'Authorization': 'Bearer $_idToken'},
          );
        } catch (_) {}
      }

      debugPrint('グループ $groupCode: アクティブメンバー=$activeMembers');

      if (activeMembers > 0) return;

      // ── メンバー0人 → グループ全データ削除 ──
      debugPrint('グループ $groupCode: メンバー0人 → データ削除開始');

      // 1. pages サブコレクション削除
      await _deleteSubcollection(groupCode, 'pages');

      // 2. members サブコレクション削除（残りがあれば）
      await _deleteSubcollection(groupCode, 'members');

      // 3. per-user カレンダーも削除。Firestore は親ドキュメントを消しても
      // サブコレクションを自動削除しないため、残すと予定データが孤児化する。
      await _deleteSubcollection(groupCode, 'calendar');

      // 4. Storage の添付ファイル削除
      await _deleteGroupStorage(groupCode);

      // 5. グループドキュメント自体を削除
      try {
        final groupDocUrl = '$_firestoreBaseUrl/groups/$groupCode';
        await http.delete(
          Uri.parse(groupDocUrl),
          headers: {'Authorization': 'Bearer $_idToken'},
        );
      } catch (_) {}

      debugPrint('グループ $groupCode: データ削除完了');
    } catch (e) {
      debugPrint('グループクリーンアップエラー: $e');
    }
  }

  /// Firestoreサブコレクション内の全ドキュメントを削除
  Future<void> _deleteSubcollection(String groupCode, String collection) async {
    if (_idToken == null) return;
    try {
      final url = '$_firestoreBaseUrl/groups/$groupCode/$collection';
      final res = await http.get(
        Uri.parse(url),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      if (res.statusCode != 200) return;
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final docs = data['documents'] as List<dynamic>? ?? [];
      for (final doc in docs) {
        final docName = doc['name'] as String?;
        if (docName == null) continue;
        try {
          final deleteUrl = 'https://firestore.googleapis.com/v1/$docName';
          await http.delete(
            Uri.parse(deleteUrl),
            headers: {'Authorization': 'Bearer $_idToken'},
          );
        } catch (_) {}
      }
    } catch (e) {
      debugPrint('サブコレクション $collection 削除エラー: $e');
    }
  }

  /// 期限切れクラウドデータの自動削除。
  ///
  /// プランに応じて:
  ///   - Free  : アップロードから **7 日経過** したファイルを削除
  ///   - Pro/Max : 契約終了 (`_subscriptionEndedAt`) から **30 日経過**
  ///              していたら、 該当グループの全データを削除
  ///   - Pro/Max 契約中 (`_subscriptionEndedAt == null`) : 何もしない
  ///
  /// 起動時に呼び出される想定 (バックグラウンド処理、 失敗しても無視)。
  /// 削除した分は `releaseStorageBytes()` で累積使用量から差し引く。
  Future<void> pruneExpiredCloudData() async {
    if (!_firebaseEnabled || _syncGroupId == null || _idToken == null) return;
    final now = DateTime.now().toUtc();

    if (currentPlan == SubscriptionPlan.free) {
      // Free: 7 日より古いファイルを個別に削除
      final cutoff = now.subtract(kFreeAutoDeleteGrace);
      await _pruneFilesOlderThan(cutoff);
    } else {
      // Pro/Max: 契約終了から 30 日経過なら全データ削除
      final endedAt = _subscriptionEndedAt;
      if (endedAt == null) return; // 契約中なので保持
      final deleteAt = endedAt.add(kPaidAutoDeleteGrace);
      if (now.isBefore(deleteAt)) return; // まだ猶予期間中
      try {
        await _deleteGroupStorage(_syncGroupId!);
        // 全削除したので累積使用量を 0 にリセット
        _totalStorageBytes = 0;
        // ignore: discarded_futures
        _persistMonthlyUsage();
        notifyListeners();
      } catch (e) {
        debugPrint('pruneExpiredCloudData (full) error: $e');
      }
    }
  }

  /// `cutoff` より古い `updated` メタデータを持つファイルを Storage から削除。
  Future<void> _pruneFilesOlderThan(DateTime cutoff) async {
    if (_idToken == null || _syncGroupId == null) return;
    try {
      final prefix = Uri.encodeComponent('groups/$_syncGroupId/');
      final listUrl = '$_storageUploadUrl?prefix=$prefix';
      final res = await http.get(
        Uri.parse(listUrl),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      if (res.statusCode != 200) return;
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final items = data['items'] as List<dynamic>? ?? [];
      int releasedBytes = 0;
      for (final item in items) {
        final m = item as Map<String, dynamic>;
        final name = m['name'] as String?;
        final updatedStr = m['updated'] as String?; // ISO8601
        final sizeStr = m['size'] as String?;
        if (name == null || updatedStr == null) continue;
        final updated = DateTime.tryParse(updatedStr);
        if (updated == null) continue;
        if (updated.isAfter(cutoff)) continue; // 期限内 → 保持
        // 期限切れ → 削除
        try {
          final encoded = Uri.encodeComponent(name);
          final deleteUrl = '$_storageUploadUrl/$encoded';
          final dr = await http.delete(
            Uri.parse(deleteUrl),
            headers: {'Authorization': 'Bearer $_idToken'},
          );
          if (dr.statusCode >= 200 && dr.statusCode < 300) {
            releasedBytes += int.tryParse(sizeStr ?? '0') ?? 0;
            debugPrint('Auto-prune: $name (uploaded $updatedStr)');
          }
        } catch (_) {}
      }
      if (releasedBytes > 0) {
        releaseStorageBytes(releasedBytes);
      }
    } catch (e) {
      debugPrint('_pruneFilesOlderThan error: $e');
    }
  }

  /// Firebase Storage のグループフォルダ内ファイルを削除
  Future<void> _deleteGroupStorage(String groupCode) async {
    if (_idToken == null) return;
    try {
      // Storage REST API: prefix でリストしてから各オブジェクトを削除
      final prefix = Uri.encodeComponent('groups/$groupCode/');
      final listUrl = '$_storageUploadUrl?prefix=$prefix';
      final res = await http.get(
        Uri.parse(listUrl),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      if (res.statusCode != 200) return;
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final items = data['items'] as List<dynamic>? ?? [];
      for (final item in items) {
        final name = item['name'] as String?;
        if (name == null) continue;
        try {
          final encoded = Uri.encodeComponent(name);
          final deleteUrl = '$_storageUploadUrl/$encoded';
          await http.delete(
            Uri.parse(deleteUrl),
            headers: {'Authorization': 'Bearer $_idToken'},
          );
          debugPrint('Storage削除: $name');
        } catch (_) {}
      }
    } catch (e) {
      debugPrint('Storageクリーンアップエラー: $e');
    }
  }

  /// グループのメタ情報をFirestoreに書き込む
  Future<void> _writeGroupMeta(String groupCode) async {
    if (_idToken == null || _uid == null) {
      throw Exception(t('sync.firebaseDisconnected'));
    }
    await _ensureFreshToken();
    final url = '$_firestoreBaseUrl/groups/$groupCode';
    final res = await http.patch(
      Uri.parse(
          '$url?currentDocument.exists=false&updateMask.fieldPaths=createdAt&updateMask.fieldPaths=host'),
      headers: {
        'Authorization': 'Bearer $_idToken',
        'Content-Type': 'application/json',
      },
      body: jsonEncode({
        'fields': {
          'createdAt': {'stringValue': DateTime.now().toIso8601String()},
          'host': {'stringValue': _uid ?? ''},
        },
      }),
    );
    if (res.statusCode < 200 || res.statusCode >= 300) {
      throw Exception(t('sync.groupCreateFailed')
          .replaceFirst('{err}', 'HTTP ${res.statusCode} ${res.body}'));
    }
  }

  // ── Firestoreデータ読み書き ───────────────────────────────────────────────

  /// グループの全ページをFirestoreから取得してローカルに反映
  Future<void> _fetchGroupPages() async {
    if (!_firebaseEnabled || _syncGroupId == null || _idToken == null) return;
    try {
      final url = '$_firestoreBaseUrl/groups/$_syncGroupId/pages';
      final res = await http.get(
        Uri.parse(url),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      if (res.statusCode == 200) {
        final data = jsonDecode(res.body) as Map<String, dynamic>;
        final docs = data['documents'] as List<dynamic>? ?? [];
        bool changed = false;
        for (final doc in docs) {
          try {
            final fields = doc['fields'] as Map<String, dynamic>;
            final jsonStr = _firestoreStr(fields['json']);
            if (jsonStr == null) continue;
            final pageData = jsonDecode(jsonStr) as Map<String, dynamic>;
            final page = MindMapPage.fromJson(pageData);
            // ── 再アップロード制限フィールドをクラウドから取り込む ──
            // ユーザー要望「他ユーザーによる再アップロードを制限できる機能」
            //   の一部。 クラウド側 (= 制限を掛けたユーザーの最新状態) を
            //   ローカルに反映することで、 他のメンバーが UI 上でロック状態
            //   を正しく認識できる (= 制限解除されたらすぐに反映される)。
            final restrictedFld =
                fields['uploadRestricted'] as Map<String, dynamic>?;
            if (restrictedFld != null) {
              page.uploadRestricted = restrictedFld['booleanValue'] == true;
            }
            final restrictedByFld =
                fields['restrictedByUid'] as Map<String, dynamic>?;
            if (restrictedByFld != null) {
              page.restrictedByUid = restrictedByFld['stringValue'] as String?;
            }
            // 添付ファイル・画像をStorageからダウンロード
            await _downloadPageAttachments(page);
            final idx = _pages.indexWhere((p) => p.id == page.id);
            if (idx < 0) {
              _pages.add(page);
              changed = true;
            } else if (!_firestoreSyncing) {
              _pages[idx].nodes
                ..clear()
                ..addAll(page.nodes);
              _pages[idx].connections
                ..clear()
                ..addAll(page.connections);
              // 制限フラグはローカルにも反映 (= UI で表示できるよう)
              _pages[idx].uploadRestricted = page.uploadRestricted;
              _pages[idx].restrictedByUid = page.restrictedByUid;
              changed = true;
            }
            // 付箋（namedGroups）を復元
            final ngJson = _firestoreStr(fields['namedGroupsJson']);
            if (ngJson != null && ngJson.isNotEmpty) {
              _applyNamedGroupsJson(page.id, ngJson);
              changed = true;
            }
            // フリーノートの中身も復元 (= ユーザー要望)。
            final paintJson = _firestoreStr(fields['paintJson']);
            if (paintJson != null && paintJson.isNotEmpty) {
              await restorePaintJsonFromCloud(page.id, paintJson);
              changed = true;
            }
          } catch (_) {}
        }
        if (changed) {
          await _saveToStorageLocal();
          await _saveNamedGroups(); // 付箋情報も永続化
          notifyListeners();
        }
      } else if (res.statusCode == 401) {
        await _signInAnonymously();
      }
    } catch (e) {
      debugPrint('Firestore fetch error: $e');
    }
  }

  String? _firestoreStr(dynamic val) {
    if (val == null) return null;
    if (val is Map) return val['stringValue'] as String?;
    return null;
  }

  /// ページをFirestoreのグループに保存
  Future<void> _savePageToFirestore(String pageId,
      {bool retried = false,
      void Function(double progress)? onPageProgress}) async {
    if (!_firebaseEnabled || _syncGroupId == null || _idToken == null) return;
    final idx = _pages.indexWhere((p) => p.id == pageId);
    if (idx < 0) return;
    _firestoreSyncing = true;
    try {
      // ── 他ユーザーによる再アップロード制限のチェック ──
      // ユーザー要望「クラウドに新しいマップをアップロードする時に他ユーザー
      //   による再アップロードを制限できる機能を作って」 への対応。
      //
      // Firestore から既存ドキュメントを GET し、 uploadRestricted == true で
      // restrictedByUid が現在のユーザー (_uid) と異なる場合は拒否する。
      // 自分が制限を掛けている場合は、 自分は引き続き上書き可能。
      // 初回アップロード (= 404) ならスキップ。
      try {
        final getUrl = '$_firestoreBaseUrl/groups/$_syncGroupId/pages/$pageId';
        final getRes = await http.get(
          Uri.parse(getUrl),
          headers: {'Authorization': 'Bearer $_idToken'},
        ).timeout(const Duration(seconds: 25)); // ハング防止 (= ユーザー報告)
        if (getRes.statusCode == 200) {
          final data = jsonDecode(getRes.body) as Map<String, dynamic>;
          final remoteFields = data['fields'] as Map<String, dynamic>? ?? {};
          final restrictedFld =
              remoteFields['uploadRestricted'] as Map<String, dynamic>?;
          final remoteRestricted =
              restrictedFld != null && restrictedFld['booleanValue'] == true;
          final restrictedByFld =
              remoteFields['restrictedByUid'] as Map<String, dynamic>?;
          final remoteRestrictedBy = restrictedByFld != null
              ? restrictedByFld['stringValue'] as String?
              : null;
          if (remoteRestricted &&
              remoteRestrictedBy != null &&
              remoteRestrictedBy.isNotEmpty &&
              remoteRestrictedBy != _uid) {
            // ローカル状態にも反映 (= UI で制限を表示できるよう)
            _pages[idx].uploadRestricted = true;
            _pages[idx].restrictedByUid = remoteRestrictedBy;
            notifyListeners();
            throw _UploadRestrictedException(t('upload.restrictedByOther'));
          }
        }
        // 404 (ドキュメント未作成) はスルー (= 初回アップロード)
      } on _UploadRestrictedException {
        rethrow;
      } catch (e) {
        // それ以外のエラーは無視して通常アップロードを試みる
        debugPrint('uploadRestricted pre-check skipped: $e');
      }

      // ── 添付ファイル (画像/PDF/動画) を Firebase Storage にアップロード ──
      // 旧実装はここで `_uploadPageAttachments(pageId)` を await せず
      // fire-and-forget していたため、ファイル本体が 90% 程度送信中でも
      // メタデータの PATCH が先に完了し、UI 上「アップロード完了」と
      // 表示されてしまうバグがあった (大きな動画ファイルで顕著)。
      //
      // 修正: await を追加してファイル送信が完全に終わってから
      // メタデータ JSON を Firestore に PATCH するように変更。
      // ただし _uploadPageAttachments の中で attachmentStorageUrl が
      // 書き換わるので、その値が反映された後で pageJson をシリアライズする。
      //
      // さらに onPageProgress を介して、添付ファイル送信進捗を呼び出し元
      // (uploadToCloud) に伝える。これによりプログレスバーが実際の
      // バイト送信状況に追従し、巨大な動画でも 90% で固まる現象を防ぐ。
      // ファイルアップロードに進捗の 95% 分を割り当て、メタデータ PATCH に
      // 残り 5% を割り当てる (経験的にメタデータは数百ミリ秒で終わる)。
      //
      // ── アップロード内容を「押した時点」 のスナップショットに固定 ──
      // (= ユーザー要望: アップロード中に編集を続けても、 クラウドに上がる
      //    のはアップロードを押した時点のデータだけ)。 添付転送は分単位で
      //    かかることがあり、 旧実装は転送完了後のライブ状態を送っていた
      //    ため、 転送中の編集が中途半端に混ざっていた。
      final snapshot = MindMapPage.fromJson(
          jsonDecode(jsonEncode(_pages[idx].toJson())) as Map<String, dynamic>);
      await _uploadPageAttachments(pageId, onPageProgress: (p) {
        onPageProgress?.call(p * 0.95);
      });

      // 添付転送で確定した Storage URL はスナップショットにも反映する
      // (ライブ側ノードは _uploadPageAttachments 内で書き換え済み)。
      final liveIdx = _pages.indexWhere((p) => p.id == pageId);
      if (liveIdx >= 0) {
        for (final entry in snapshot.nodes.entries) {
          final live = _pages[liveIdx].nodes[entry.key];
          if (live == null) continue;
          if ((live.attachmentStorageUrl ?? '').isNotEmpty) {
            entry.value.attachmentStorageUrl = live.attachmentStorageUrl;
          }
          if ((live.videoStorageUrl ?? '').isNotEmpty) {
            entry.value.videoStorageUrl = live.videoStorageUrl;
          }
        }
      }

      onPageProgress?.call(0.95);
      final pageJson = jsonEncode(snapshot.toJson());
      // 付箋（namedGroups）も同期
      final namedGroupsJson = _serializeNamedGroupsForPage(pageId);
      // フリーノートは中身が prefs 側にあるので別フィールドで送る
      // (= ユーザー報告: フリーページの画像が転送できていない)。
      final paintJson = _pages[idx].pageType == 'paint'
          ? await preparePaintJsonForUpload(pageId)
          : null;
      final url = '$_firestoreBaseUrl/groups/$_syncGroupId/pages/$pageId';
      // ── 無料プランは 1 週間で自動削除 ──
      // クラウドストレージのコスト・データ滞留対策として、無料プランの
      // ユーザーがアップロードしたページは 7 日後に自動削除されるよう
      // `expiresAt` フィールドを Firestore に書き込む。
      // Firestore Console 側で TTL ポリシーを `expiresAt` フィールドに
      // 対して有効化しておくと、Google Cloud が自動で削除してくれる。
      // (TTL 設定: Firestore Console → TTL → Add Policy → Collection
      //  group: pages, Timestamp field: expiresAt)
      // Pro / クーポンユーザーの場合は `expiresAt` を null で書き込んで
      // 既存の期限を解除する (= 永久保存)。
      final fields = <String, dynamic>{
        'json': {'stringValue': pageJson},
        'namedGroupsJson': {'stringValue': namedGroupsJson},
        if (paintJson != null) 'paintJson': {'stringValue': paintJson},
      };
      final updateMaskParts = <String>[
        'json',
        'namedGroupsJson',
        // 値がある時だけマスクに入れる (マスクだけ付けると削除扱いになる)。
        if (paintJson != null) 'paintJson',
        'expiresAt',
        // 再アップロード制限フィールドも更新対象に追加
        'uploadRestricted',
        'restrictedByUid',
      ];
      // ── 再アップロード制限フィールドの書き込み ──
      // ローカル状態 (= MindMapPage.uploadRestricted) を Firestore に反映。
      // ユーザーが UI で制限を ON にした → アップロード時に Firestore に
      //   uploadRestricted: true, restrictedByUid: <self> が書かれる
      //   → 他のユーザーが上書きしようとすると上の pre-check で拒否される。
      // ユーザーが OFF に戻した → uploadRestricted: false が書かれる
      //   → 制限解除されて誰でも上書き可能に戻る。
      final localRestricted = _pages[idx].uploadRestricted;
      fields['uploadRestricted'] = {'booleanValue': localRestricted};
      if (localRestricted) {
        // 自分が制限を掛ける場合、 自分の UID を書く
        // (= 既存のローカル restrictedByUid があってもアップロード時は自分の
        //   UID で上書きする = 自分が「正当な所有者」 として認識される)
        _pages[idx].restrictedByUid = _uid;
        fields['restrictedByUid'] = {'stringValue': _uid ?? ''};
      } else {
        // 制限解除: restrictedByUid をクリア
        _pages[idx].restrictedByUid = null;
        fields['restrictedByUid'] = {'nullValue': null};
      }
      if (isProUnlocked) {
        // Pro: expiresAt を null にして TTL 削除対象から外す
        fields['expiresAt'] = {'nullValue': null};
      } else {
        // Free: 7 日後に自動削除
        final expiry = DateTime.now()
            .add(const Duration(days: 7))
            .toUtc()
            .toIso8601String();
        fields['expiresAt'] = {'timestampValue': expiry};
      }
      final maskQuery =
          updateMaskParts.map((f) => 'updateMask.fieldPaths=$f').join('&');
      final res = await http
          .patch(
            Uri.parse('$url?$maskQuery'),
            headers: {
              'Authorization': 'Bearer $_idToken',
              'Content-Type': 'application/json',
            },
            body: jsonEncode({'fields': fields}),
          )
          .timeout(const Duration(seconds: 30)); // ハング防止 (= ユーザー報告)
      if ((res.statusCode == 401 || res.statusCode == 403) && !retried) {
        await _ensureFreshToken(force: true);
        _firestoreSyncing = false;
        return _savePageToFirestore(pageId,
            retried: true, onPageProgress: onPageProgress);
      }
      if (res.statusCode == 200) {
        // アップロード成功: 日時を記録
        // ── サーバーの updateTime を記録する (= 時計ズレ対策) ──
        // 旧実装は端末時計 (DateTime.now) を記録していたが、 Ctrl+R の
        // 「クラウドの方が新しいか」 判定はサーバーの updateTime と比較する。
        // 端末時計が数十秒〜数分ズレていると、 他端末のアップロードが
        // 「最新です」 と誤判定されてダウンロードされない / 自分の
        // アップロード直後に古いクラウド版を再ダウンロードして上書きする
        // 不具合になっていた (= ユーザー報告「アップロードとダウンロードが
        // 上手く行っていない」)。 PATCH 応答はドキュメント本体を返すので、
        // その updateTime (= サーバー時刻) をそのまま記録して基準を揃える。
        String uploadedAtIso = DateTime.now().toUtc().toIso8601String();
        try {
          final resData = jsonDecode(res.body) as Map<String, dynamic>;
          final serverUpdateTime = resData['updateTime'] as String?;
          if (serverUpdateTime != null && serverUpdateTime.isNotEmpty) {
            uploadedAtIso = serverUpdateTime;
          }
        } catch (_) {}
        final prefs = await _prefsWithRetry();
        await prefs.setString('page_uploaded_$pageId', uploadedAtIso);
        // ── 差分アップロード用にページ内容のハッシュも記録 (= ユーザー要望:
        //    Ctrl+S で差分だけアップロード)。 次回 Ctrl+S 時にこのハッシュと
        //    現在内容を比較し、 変わっていなければアップロードをスキップする。
        // 記録するのは「実際にクラウドへ上げたスナップショット」 のハッシュ。
        // ライブ状態のハッシュを記録すると、 アップロード中に行った編集が
        // 「アップロード済み」 と誤判定されて次回スキップされてしまう。
        try {
          await prefs.setString(
              'page_uploaded_hash_$pageId', pageJson.hashCode.toString());
        } catch (_) {}
        // ── 3-way マージ用の同期基準 (= 今クラウドに置いた内容) を保存 ──
        // ダウンロード時に「前回同期から自分が変えた部分」 を割り出して
        // クラウド版へ上乗せするために使う (= ユーザー要望: ダウンロードは
        // 現在の編集内容の差分を加える形で)。
        await _storeSyncedBaseJson(pageId, pageJson);
        onPageProgress?.call(1.0);
      } else {
        // ── 200 以外 = ページ保存失敗 ──
        // (= ユーザー報告:「アップロードしました」 と出るのに実際は上がって
        //   いない)。 握りつぶさず失敗フラグを立て、 UI に「完了しませんでした」
        //   を出させて false success を防ぐ。
        debugPrint('Firestore save non-200: ${res.statusCode} ${res.body}');
        _lastSyncAttachmentFailed = true;
      }
    } on _UploadRestrictedException {
      rethrow;
    } catch (e) {
      // タイムアウト/通信エラー等。 ここで握りつぶすと「完了」 と誤表示される
      // ため、 失敗フラグを立てる (= ユーザー報告)。
      debugPrint('Firestore save error: $e');
      _lastSyncAttachmentFailed = true;
    } finally {
      _firestoreSyncing = false;
    }
  }

  /// 最後にクラウドと同期した時点のページ JSON を保存する (3-way マージ用基準)。
  Future<void> _storeSyncedBaseJson(String pageId, String json) async {
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setString('page_synced_json_$pageId', json);
    } catch (_) {}
  }

  /// クラウドからダウンロードしたページに、 ローカルの編集差分を上乗せする
  /// (= ユーザー要望: ダウンロード側は現在の編集内容の差分を加える形で
  ///    取り込む)。
  ///
  /// [baseJson] は前回同期時点のページ JSON (= ローカルとクラウドの共通祖先)。
  /// 基準が無い場合は従来どおりクラウド版をそのまま返す (= 全置換)。
  /// ノード/接続単位の 3-way マージで、 衝突時はローカルの編集を優先する。
  MindMapPage _mergeLocalEditsIntoCloudPage(MindMapPage cloudPage,
      {String? baseJson}) {
    final idx = _pages.indexWhere((p) => p.id == cloudPage.id);
    if (idx < 0) return cloudPage; // ローカルに存在しない → そのまま取り込み
    if (baseJson == null || baseJson.isEmpty) return cloudPage;
    MindMapPage base;
    try {
      base = MindMapPage.fromJson(jsonDecode(baseJson) as Map<String, dynamic>);
    } catch (_) {
      return cloudPage;
    }
    final current = _pages[idx];

    String nodeSig(MindMapNode n) => jsonEncode(n.toJson());
    final baseSigs = <String, String>{
      for (final e in base.nodes.entries) e.key: nodeSig(e.value)
    };
    // ローカルで追加/変更されたノード → ローカル優先で上乗せ
    for (final e in current.nodes.entries) {
      final b = baseSigs[e.key];
      if (b == null || b != nodeSig(e.value)) {
        cloudPage.nodes[e.key] = e.value;
      }
    }
    // ローカルで削除されたノード (基準に有り、 現在に無い) → クラウド版からも削除
    for (final id in base.nodes.keys) {
      if (!current.nodes.containsKey(id)) {
        cloudPage.nodes.remove(id);
      }
    }
    // 接続: ローカルの追加/変更/削除を反映
    String ck(NodeConnection c) => '${c.fromId}->${c.toId}';
    final baseConn = <String, String>{
      for (final c in base.connections) ck(c): jsonEncode(c.toJson())
    };
    final curConn = <String, NodeConnection>{
      for (final c in current.connections) ck(c): c
    };
    for (final e in curConn.entries) {
      final b = baseConn[e.key];
      if (b == null || b != jsonEncode(e.value.toJson())) {
        cloudPage.connections.removeWhere((c) => ck(c) == e.key);
        cloudPage.connections.add(e.value);
      }
    }
    for (final key in baseConn.keys) {
      if (!curConn.containsKey(key)) {
        cloudPage.connections.removeWhere((c) => ck(c) == key);
      }
    }
    // 両端が存在しない接続は掃除
    cloudPage.connections.removeWhere((c) =>
        !cloudPage.nodes.containsKey(c.fromId) ||
        !cloudPage.nodes.containsKey(c.toId));
    // 図形 / ページ名 / 背景: ローカルで変えていればローカル優先
    try {
      final baseDeco =
          jsonEncode(base.decorations.map((d) => d.toJson()).toList());
      final curDeco =
          jsonEncode(current.decorations.map((d) => d.toJson()).toList());
      if (baseDeco != curDeco) {
        cloudPage.decorations
          ..clear()
          ..addAll(current.decorations);
      }
    } catch (_) {}
    if (current.name != base.name) cloudPage.name = current.name;
    if (current.backgroundImagePath != base.backgroundImagePath) {
      cloudPage.backgroundImagePath = current.backgroundImagePath;
    }
    if (current.backgroundOpacityPercent != base.backgroundOpacityPercent) {
      cloudPage.backgroundOpacityPercent = current.backgroundOpacityPercent;
    }
    if (current.backgroundFit != base.backgroundFit) {
      cloudPage.backgroundFit = current.backgroundFit;
    }
    if (current.backgroundHueDegrees != base.backgroundHueDegrees) {
      cloudPage.backgroundHueDegrees = current.backgroundHueDegrees;
    }
    if (current.backgroundSaturationPercent !=
        base.backgroundSaturationPercent) {
      cloudPage.backgroundSaturationPercent =
          current.backgroundSaturationPercent;
    }
    if (current.backgroundBrightnessPercent !=
        base.backgroundBrightnessPercent) {
      cloudPage.backgroundBrightnessPercent =
          current.backgroundBrightnessPercent;
    }
    return cloudPage;
  }

  /// ページの再アップロード制限を切り替える (= ユーザー要望「クラウドに
  ///   新しいマップをアップロードする時に他ユーザーによる再アップロードを
  ///   制限できる機能」 の公開 API)。
  ///
  /// [restricted] が true なら、 次回アップロード時に自分の UID をロックとして
  /// 書き込み、 他ユーザーからの上書きを拒否する。 false なら制限を解除。
  ///
  /// ローカル状態を即座に変更して notifyListeners する。 Firestore への反映
  /// は次のアップロード時 (= ユーザーがアップロードボタンを押した時) に発生。
  /// 「制限の変更だけを即時クラウドに反映したい」 場合は [syncImmediately] を
  /// true にすると、 そのページを単独で _savePageToFirestore する。
  /// ─── マップ背景画像 (= ユーザー要望「マップの背景画像を自由に
  ///   カスタマイズ」) ────────────────────────────────────────────────
  /// 指定ページの背景画像パスをセットして永続化する。 `path` が null なら
  /// 背景画像を解除 (= グリッドのみに戻す)。
  Future<void> setPageBackgroundImage(String pageId, String? path,
      {bool applyToAll = false}) async {
    final targets = applyToAll
        ? _pages
        : _pages.where((page) => page.id == pageId).toList();
    if (targets.isEmpty) return;
    _pushUndo();
    final now = DateTime.now();
    for (final page in targets) {
      page.backgroundImagePath = path;
      page.lastModifiedAt = now;
    }
    notifyListeners();
    await _saveToStorageLocal();
    _triggerAutoSync();
  }

  /// 指定ページの背景画像の不透明度 (0〜100) をセットして永続化する。
  Future<void> setPageBackgroundOpacity(String pageId, int percent,
      {bool applyToAll = false}) async {
    final targets = applyToAll
        ? _pages
        : _pages.where((page) => page.id == pageId).toList();
    if (targets.isEmpty) return;
    final clamped = percent.clamp(0, 100).toInt();
    if (targets.every((p) => p.backgroundOpacityPercent == clamped)) return;
    final now = DateTime.now();
    for (final page in targets) {
      page.backgroundOpacityPercent = clamped;
      page.lastModifiedAt = now;
    }
    notifyListeners();
    await _saveToStorageLocal();
    _triggerAutoSync();
  }

  /// 指定ページの背景画像の表示モード ('cover' / 'contain' / 'tile') を
  /// セットして永続化する。
  Future<void> setPageBackgroundFit(String pageId, String fit,
      {bool applyToAll = false}) async {
    if (fit != 'cover' && fit != 'contain' && fit != 'tile') return;
    final targets = applyToAll
        ? _pages
        : _pages.where((page) => page.id == pageId).toList();
    if (targets.isEmpty || targets.every((p) => p.backgroundFit == fit)) return;
    final now = DateTime.now();
    for (final page in targets) {
      page.backgroundFit = fit;
      page.lastModifiedAt = now;
    }
    notifyListeners();
    await _saveToStorageLocal();
    _triggerAutoSync();
  }

  /// 組み込み背景テンプレートの色相・彩度・明度をまとめて更新する。
  Future<void> setPageBackgroundTone(
    String pageId, {
    required int hueDegrees,
    required int saturationPercent,
    required int brightnessPercent,
    bool applyToAll = false,
  }) async {
    final targets = applyToAll
        ? _pages
        : _pages.where((page) => page.id == pageId).toList();
    if (targets.isEmpty) return;
    final hue = hueDegrees.clamp(-180, 180).toInt();
    final saturation = saturationPercent.clamp(0, 200).toInt();
    final brightness = brightnessPercent.clamp(50, 150).toInt();
    if (targets.every((page) =>
        page.backgroundHueDegrees == hue &&
        page.backgroundSaturationPercent == saturation &&
        page.backgroundBrightnessPercent == brightness)) {
      return;
    }
    final now = DateTime.now();
    for (final page in targets) {
      page.backgroundHueDegrees = hue;
      page.backgroundSaturationPercent = saturation;
      page.backgroundBrightnessPercent = brightness;
      page.lastModifiedAt = now;
    }
    notifyListeners();
    await _saveToStorageLocal();
    _triggerAutoSync();
  }

  /// 現在の背景一式を既存の全ページへコピーする。以後ダイアログ内で
  /// [applyToAll] を使うと、その場での変更も全ページへ同期される。
  Future<void> applyPageBackgroundToAll(String sourcePageId) async {
    final sourceIndex = _pages.indexWhere((page) => page.id == sourcePageId);
    if (sourceIndex < 0 || _pages.isEmpty) return;
    final source = _pages[sourceIndex];
    final now = DateTime.now();
    for (final page in _pages) {
      page.backgroundImagePath = source.backgroundImagePath;
      page.backgroundOpacityPercent = source.backgroundOpacityPercent;
      page.backgroundFit = source.backgroundFit;
      page.backgroundHueDegrees = source.backgroundHueDegrees;
      page.backgroundSaturationPercent = source.backgroundSaturationPercent;
      page.backgroundBrightnessPercent = source.backgroundBrightnessPercent;
      page.lastModifiedAt = now;
    }
    notifyListeners();
    await _saveToStorageLocal();
    _triggerAutoSync();
  }

  Future<void> setPageUploadRestricted(String pageId, bool restricted,
      {bool syncImmediately = false}) async {
    final idx = _pages.indexWhere((p) => p.id == pageId);
    if (idx < 0) return;
    // 他ユーザーが制限している場合は変更不可
    if (_pages[idx].uploadRestricted &&
        _pages[idx].restrictedByUid != null &&
        _pages[idx].restrictedByUid!.isNotEmpty &&
        _pages[idx].restrictedByUid != _uid) {
      throw _UploadRestrictedException(t('upload.lockedByOtherCannotUnlock'));
    }
    _pages[idx].uploadRestricted = restricted;
    if (restricted) {
      _pages[idx].restrictedByUid = _uid;
    } else {
      _pages[idx].restrictedByUid = null;
    }
    notifyListeners();
    // ローカルにも保存 (= アプリ再起動後も保持されるよう)
    try {
      await _saveToStorageLocal();
    } catch (_) {}
    if (syncImmediately &&
        _firebaseEnabled &&
        _syncGroupId != null &&
        _idToken != null) {
      // クラウドに即反映 (= 他ユーザーがすぐに制限を認識できるよう)
      await _savePageToFirestore(pageId);
    }
  }

  /// 指定ページが他のユーザーによってアップロード制限されているか。
  /// 自分が制限を掛けている場合は false (= 自分は上書き可能)。
  bool isPageRestrictedByOthers(String pageId) {
    final idx = _pages.indexWhere((p) => p.id == pageId);
    if (idx < 0) return false;
    final p = _pages[idx];
    if (!p.uploadRestricted) return false;
    if (p.restrictedByUid == null || p.restrictedByUid!.isEmpty) return false;
    return p.restrictedByUid != _uid;
  }

  // 注: 以前ここに `_deletePageFromFirestore` があり、 ローカルのページ削除
  //     から呼ばれていたが、 「手元から消しただけでクラウドのデータまで
  //     消える」 問題 (= ユーザー報告) の原因だったので削除した。 クラウド
  //     からの削除は `deleteCloudPages` (クラウドのマップ一覧の削除操作)
  //     だけが行う。

  // ── Firebase Storage: 添付ファイル・画像の同期 ─────────────────────────────

  /// ファイルをFirebase Storageにアップロード（dart:io HttpClientでストリーミング送信）
  ///
  /// プランごとの月間アップロード容量上限 (free 5MB / pro 5GB / max 25GB) を
  /// 超過する場合は ``MapLimitException`` 系の `Exception` を投げて中断する
  /// (上位 UI 側でユーザー向けエラーメッセージを表示する責務)。
  Future<String?> uploadAttachmentToStorage(String localPath, String fileName,
      {void Function(double progress)? onProgress,
      bool retried = false}) async {
    if (!_firebaseEnabled || _syncGroupId == null || _idToken == null)
      return null;
    try {
      final file = File(localPath);
      if (!await file.exists()) {
        debugPrint('Storage upload: file not found: $localPath');
        return null;
      }
      final fileLength = await file.length();
      if (fileLength == 0) {
        debugPrint('Storage upload: file is empty: $localPath');
        return null;
      }

      // ── 月間アップロード容量チェック ──
      // 上限を超える場合は早期リターン (UI 側でエラー表示)。
      // recordUploadBytes は成功時のみ呼ぶので、 ここで先にチェックする
      // ことで「上限超過時に部分転送だけ走って失敗」を防ぐ。
      if (!canUseUploadBytes(fileLength)) {
        final limitGb =
            (monthlyUploadLimit / 1024 / 1024 / 1024).toStringAsFixed(1);
        _lastSyncLimitMessage =
            t('sync.monthlyUploadLimit').replaceFirst('{limit}', limitGb);
        throw Exception(_lastSyncLimitMessage);
      }
      // ── 累積ストレージ容量チェック ──
      // Max: 100 GB を超える場合は不要ファイルを削除してから
      // やり直してもらう。
      if (!canUseStorageBytes(fileLength)) {
        final limitGb =
            (totalStorageLimit / 1024 / 1024 / 1024).toStringAsFixed(1);
        final usedGb =
            (_totalStorageBytes / 1024 / 1024 / 1024).toStringAsFixed(2);
        _lastSyncLimitMessage = t('sync.storageLimit')
            .replaceFirst('{limit}', limitGb)
            .replaceFirst('{used}', usedGb);
        throw Exception(_lastSyncLimitMessage);
      }

      final ext = fileName.split('.').last.toLowerCase();
      String ct = 'application/octet-stream';
      if (ext == 'jpg' || ext == 'jpeg')
        ct = 'image/jpeg';
      else if (ext == 'png')
        ct = 'image/png';
      else if (ext == 'pdf')
        ct = 'application/pdf';
      else if (ext == 'mp4')
        ct = 'video/mp4';
      else if (ext == 'mov')
        ct = 'video/quicktime';
      else if (ext == 'm4v') ct = 'video/x-m4v';

      final storagePath = 'groups/$_syncGroupId/attachments/$fileName';
      final encoded = Uri.encodeComponent(storagePath);
      final uploadUrl = '$_storageUploadUrl/$encoded?uploadType=media';

      debugPrint(
          'Storage upload start: $fileName (${(fileLength / 1024 / 1024).toStringAsFixed(1)}MB)');

      // dart:io HttpClient でストリーミング送信（メモリに全体を載せない）
      final client = HttpClient();
      // 接続確立のタイムアウト。 旧 10 分は長すぎて、 通信不良時に「0% の
      // まま 10 分間固まる」 原因になっていた (= ユーザー報告)。 60 秒に短縮。
      client.connectionTimeout = const Duration(seconds: 60);
      Timer? stallTimer;
      try {
        final request = await client.postUrl(Uri.parse(uploadUrl));
        request.headers.set('Authorization', 'Bearer $_idToken');
        request.headers.set('Content-Type', ct);
        request.contentLength = fileLength;

        // ── ファイルをストリーム送信 ──
        // 注意: 以前は `await for ... request.add(chunk)` と書いていたが、
        // request.add() は内部バッファに足すだけで非同期送信を待たない。
        // そのため bytesSent はすぐに 100% に達し、実際の送信完了より
        // 早く「アップロード完了」と表示されてしまう問題があった
        // (PDF 等のサイズが大きいファイルで、完了表示後にダウンロードすると
        //  ファイルが壊れて読めない症状)。
        //
        // 修正: addStream() を使い、実際にバッファが流された分だけ進捗を
        // 報告する。さらに request.close() 後に response を受け取るまで
        // 「ファイル本体の送信が完了した」とは見なさない。
        int bytesSent = 0;
        // ── ストール検知 (= ユーザー報告: アップロードが 0% のまま進まない) ──
        // 一定時間バイト送信が進まなければ通信ハングとみなして接続を強制切断し、
        // 下の catch でエラー (null) として返す。 これで永久に固まらない。
        int lastSentSnapshot = 0;
        int stalledTicks = 0;
        stallTimer = Timer.periodic(const Duration(seconds: 15), (t) {
          if (bytesSent > lastSentSnapshot) {
            lastSentSnapshot = bytesSent;
            stalledTicks = 0;
          } else {
            stalledTicks++;
            if (stalledTicks >= 6) {
              // 約 90 秒間まったく進まなければハングと判断して打ち切る。
              t.cancel();
              try {
                client.close(force: true);
              } catch (_) {}
            }
          }
        });
        final progressStream = file.openRead().transform<List<int>>(
          StreamTransformer.fromHandlers(
            handleData: (chunk, sink) {
              sink.add(chunk);
              bytesSent += chunk.length;
              // 進捗は 0.0 〜 0.85 の範囲で報告
              // (残り 0.85 〜 1.0 はサーバー処理 + レスポンス受信の時間に充てる)
              final progress = (bytesSent / fileLength * 0.85).clamp(0.0, 0.85);
              onProgress?.call(progress);
            },
          ),
        );
        await request.addStream(progressStream);

        // ── サーバーへの送信完了 → レスポンス受信 ──
        // ここに来た時点でもまだサーバーは内容を処理中の可能性がある。
        // close() を await することでサーバーが 200 を返すまで待つ。
        onProgress?.call(0.90);
        final response = await request.close();
        final responseBody = await response
            .transform(
              const Utf8Decoder(allowMalformed: true),
            )
            .join();

        // サーバーが正常応答を返した時点で初めて 100% にする
        if (response.statusCode == 200) {
          // 月間アップロード使用量を記録 (永続化込み)
          recordUploadBytes(fileLength);
          // レスポンスからdownloadTokensを取得（公開URLアクセス用）
          String? finalUrl;
          try {
            final resJson = jsonDecode(responseBody) as Map<String, dynamic>;
            // ── サーバー応答の整合性確認 ──
            // size フィールドが返っていれば、 我々が送ったバイト数と一致するか
            // チェック。 PDF などで「途中まで送れたが Storage 側がトリミングして
            // 受領した」 ようなレアケースを検出して null 返却に倒す。
            final remoteSize = (resJson['size'] is String)
                ? int.tryParse(resJson['size'] as String)
                : (resJson['size'] as num?)?.toInt();
            if (remoteSize != null &&
                remoteSize > 0 &&
                remoteSize != fileLength) {
              debugPrint(
                  'Storage upload size mismatch: $fileName local=$fileLength remote=$remoteSize');
              return null;
            }
            final token = resJson['downloadTokens'] as String?;
            if (token != null && token.isNotEmpty) {
              finalUrl = '$_storageUploadUrl/$encoded?alt=media&token=$token';
            }
          } catch (_) {}
          finalUrl ??= '$_storageUploadUrl/$encoded?alt=media';
          // 100% は「URL を返す直前」 に出す。 これより前で 100% を出すと
          // 呼び出し元が attachmentStorageUrl の確定前に
          // 「アップロード完了」 と判定する余地が生まれる。
          onProgress?.call(1.0);
          debugPrint('Storage upload OK: $fileName ($fileLength bytes)');
          return finalUrl;
        } else if ((response.statusCode == 401 || response.statusCode == 403) &&
            !retried) {
          // ── トークン失効は強制リフレッシュして 1 回だけリトライ ──
          // 大きなファイルを連続アップロードしていると途中で ID トークンが
          // 失効し、 以降が全件失敗する (= ユーザー報告「アップロードが
          // 上手く行っていない」 の一因)。
          debugPrint(
              'Storage upload auth error ${response.statusCode} → retry');
          await _ensureFreshToken(force: true);
          return uploadAttachmentToStorage(localPath, fileName,
              onProgress: onProgress, retried: true);
        } else {
          debugPrint(
              'Storage upload failed: ${response.statusCode} $responseBody');
          return null;
        }
      } finally {
        stallTimer?.cancel();
        client.close();
      }
    } catch (e) {
      debugPrint('Storage upload error: $e');
      return null;
    }
  }

  /// Firebase Storageからファイルをダウンロードしてローカルに保存
  ///
  /// プランごとの月間ダウンロード容量上限を超過する場合は Exception を投げる。
  /// チェック順序: メタデータでサイズを先取り → 上限内なら本体取得 → 成功時に
  /// 使用量記録。
  ///
  /// ── 整合性検証 ──
  /// PDF などのバイナリで「ファイル名だけダウンロードされて中が開けない」
  /// 不具合 (ユーザー報告) を防ぐため、 受信本体のサイズと Content-Length
  /// ヘッダー / レスポンスメタの size が食い違う場合は破損とみなして
  /// ローカルの部分書き込みを削除し null を返す。 これによりダウンロード
  /// 完了表示の後で開けないファイルが残るのを防ぐ。
  Future<String?> downloadAttachmentFromStorage(
      String fileName, String nodeId) async {
    if (!_firebaseEnabled || _syncGroupId == null || _idToken == null)
      return null;
    try {
      final storagePath = 'groups/$_syncGroupId/attachments/$fileName';
      final encoded = Uri.encodeComponent(storagePath);
      final downloadUrl = '$_storageUploadUrl/$encoded?alt=media';

      // タイムアウト無しだと通信不良時に「0% のまま固まる」 ので 4 分で打ち切る
      // (= ユーザー報告)。 大きな PDF/動画でも 4 分あれば足りる想定。
      final res = await http.get(
        Uri.parse(downloadUrl),
        headers: {'Authorization': 'Bearer $_idToken'},
      ).timeout(const Duration(minutes: 4));
      if (res.statusCode == 200) {
        // ── 月間ダウンロード容量チェック ──
        final size = res.bodyBytes.length;
        if (!canUseDownloadBytes(size)) {
          final limitGb =
              (monthlyDownloadLimit / 1024 / 1024 / 1024).toStringAsFixed(1);
          _lastSyncLimitMessage =
              t('sync.monthlyDownloadLimit').replaceFirst('{limit}', limitGb);
          throw Exception(_lastSyncLimitMessage);
        }

        // ── Content-Length 整合性チェック ──
        // ヘッダーが付いていない (Firebase Storage の単純 GET では大抵
        // 付いている) ケースでは検証をスキップ。 付いていてサイズが
        // 一致しない場合は途中切断と判断して null を返す。
        final clHeader = res.headers['content-length'];
        if (clHeader != null) {
          final expected = int.tryParse(clHeader);
          if (expected != null && expected > 0 && expected != size) {
            debugPrint(
                'Storage download size mismatch: $fileName expected=$expected got=$size');
            return null;
          }
        }
        // 完全に空のレスポンスは PDF として開けない → 破損扱い
        if (size == 0) {
          debugPrint('Storage download: empty body for $fileName');
          return null;
        }

        final appDir = await getApplicationDocumentsDirectory();
        final attachDir = Directory('${appDir.path}/attachments');
        if (!await attachDir.exists()) {
          await attachDir.create(recursive: true);
        }
        final localFileName = _cloudLocalFileName(nodeId, fileName);
        final localPath = '${attachDir.path}/$localFileName';
        // ── 書き込みは一旦 .part に行い、 完了後 rename ──
        // 書き込み途中で別の処理がローカルパスを参照しても、 「壊れた本体」
        // を掴ませない。 完成した時点で原子的に rename することで
        // 「中身が空 / 途中まで」状態が UI に露出するのを防ぐ。
        final tempFile = File('$localPath.part');
        await tempFile.writeAsBytes(res.bodyBytes, flush: true);

        // 書き出したファイルサイズと受信バイト数が一致するか最終確認
        final writtenLen = await tempFile.length();
        if (writtenLen != size) {
          debugPrint(
              'Storage download write mismatch: $fileName received=$size written=$writtenLen');
          try {
            await tempFile.delete();
          } catch (_) {}
          return null;
        }
        // 旧ファイルがあれば削除してから rename (Windows 対策)
        final finalFile = File(localPath);
        if (await finalFile.exists()) {
          try {
            await finalFile.delete();
          } catch (_) {}
        }
        await tempFile.rename(localPath);

        // 月間ダウンロード使用量を記録
        recordDownloadBytes(size);
        debugPrint('Storage download OK: $fileName → $localPath ($size bytes)');
        return localPath;
      } else {
        debugPrint('Storage download: ${res.statusCode} ($fileName)');
        return null;
      }
    } catch (e) {
      debugPrint('Storage download error: $e');
      return null;
    }
  }

  /// ページ内の添付ファイル・ローカル動画をすべてStorageにアップロード
  /// アップロード完了後、ノードのパスをStorage URLに書き換えてFirestoreに再保存
  String _cloudSafeFileName(String name) {
    final raw = name.trim().isEmpty ? 'attachment' : name.trim();
    final sanitized = raw
        .split('/')
        .last
        .split('\\')
        .last
        .replaceAll(RegExp(r'[<>:"/\\|?*\x00-\x1F]'), '_');
    return sanitized.isEmpty ? 'attachment' : sanitized;
  }

  String _cloudStorageFileName(String pageId, String nodeId, String name) {
    final safe = _cloudSafeFileName(name);
    return '${pageId}_${nodeId}_$safe';
  }

  String _cloudLocalFileName(String nodeId, String fileName) {
    final safe = _cloudSafeFileName(fileName);
    return safe.startsWith('${nodeId}_') ? safe : '${nodeId}_$safe';
  }

  Future<void> _uploadPageAttachments(String pageId,
      {void Function(double progress)? onPageProgress}) async {
    if (!_firebaseEnabled || _syncGroupId == null) return;
    final idx = _pages.indexWhere((p) => p.id == pageId);
    if (idx < 0) return;

    bool anyUpdated = false;

    // ── 進捗計算用に、まず「アップロード対象のファイル」を列挙する ──
    // 1 ページ内に複数の添付があると、ファイル A の進捗が 100% で報告された後、
    // ファイル B の送信が始まるが、A の進捗値だけを上に通知すると B の送信中は
    // 「99% でずっと止まっている」ように見える。
    // → 事前にファイルのバイト数合計を取り、累計バイト数 / 合計バイト数 で
    //   ページ全体の進捗を計算する。
    final List<_AttachmentToUpload> jobs = [];
    for (final nodeId in _pages[idx].nodes.keys.toList()) {
      final node = _pages[idx].nodes[nodeId];
      if (node == null) continue;
      // 画像/PDF添付
      if ((node.attachmentPath ?? '').isNotEmpty &&
          !node.attachmentPath!.startsWith('http') &&
          (node.attachmentStorageUrl ?? '').isEmpty) {
        final name = node.attachmentName ??
            node.attachmentPath!.split('/').last.split('\\').last;
        int size = 0;
        try {
          final f = File(node.attachmentPath!);
          if (await f.exists()) size = await f.length();
        } catch (_) {}
        jobs.add(_AttachmentToUpload(
            nodeId: nodeId,
            kind: _AttachmentKind.image,
            localPath: node.attachmentPath!,
            name: _cloudStorageFileName(pageId, nodeId, name),
            sizeBytes: size));
      }
      // ローカル動画ファイル
      // skipVideoUploadOnce が立っていれば動画ファイルはアップロード
      // しない (= URL のみアップロードモード)。Ctrl+S 時の選択で立つ。
      if ((node.youtubeUrl ?? '').isNotEmpty &&
          !node.youtubeUrl!.startsWith('http') &&
          !node.youtubeUrl!.startsWith('https') &&
          (node.videoStorageUrl ?? '').isEmpty &&
          !skipVideoUploadOnce) {
        final name = node.youtubeUrl!.split('/').last.split('\\').last;
        int size = 0;
        try {
          final f = File(node.youtubeUrl!);
          if (await f.exists()) size = await f.length();
        } catch (_) {}
        jobs.add(_AttachmentToUpload(
            nodeId: nodeId,
            kind: _AttachmentKind.video,
            localPath: node.youtubeUrl!,
            name: _cloudStorageFileName(pageId, nodeId, name),
            sizeBytes: size));
      }
    }

    // skipVideoUploadOnce はワンショット。動画ジョブ収集が終わったら
    // 直ちにリセットしておく (アップロード処理の途中で別ページの
    // 同期が走った場合に予期せず影響しないように)。
    skipVideoUploadOnce = false;

    // 添付なし → 即 100% を通知して終わる
    if (jobs.isEmpty) {
      onPageProgress?.call(1.0);
      return;
    }

    // 進捗計算: 全ジョブの合計バイト数を分母、各ジョブの寄与は
    // (累計済み + 現在送信中バイト) / 合計バイト
    int totalBytes = jobs.fold(0, (s, j) => s + j.sizeBytes);
    if (totalBytes <= 0) totalBytes = jobs.length; // 全ファイルが 0 byte の保険
    int completedBytes = 0;

    for (final job in jobs) {
      final node = _pages[idx].nodes[job.nodeId];
      if (node == null) {
        completedBytes += job.sizeBytes;
        continue;
      }
      _uploading[job.nodeId] = true;
      _uploadProgress[job.nodeId] = 0.0;
      notifyListeners();

      final storageUrl = await uploadAttachmentToStorage(
        job.localPath,
        job.name,
        onProgress: (p) {
          // p は単一ファイル内の 0.0〜1.0 進捗
          _uploadProgress[job.nodeId] = p;
          // ページ全体: 完了済みバイト + 現在ファイルの進捗バイト
          final size = job.sizeBytes > 0 ? job.sizeBytes : 1;
          final pageProgress =
              ((completedBytes + p * size) / totalBytes).clamp(0.0, 1.0);
          onPageProgress?.call(pageProgress);
          notifyListeners();
        },
      );

      _uploading.remove(job.nodeId);
      _uploadProgress.remove(job.nodeId);
      completedBytes += job.sizeBytes;

      if (storageUrl != null) {
        if (job.kind == _AttachmentKind.image) {
          node.attachmentStorageUrl = storageUrl;
        } else {
          node.videoStorageUrl = storageUrl;
        }
        anyUpdated = true;
      } else {
        // 添付の送信に失敗 → このページは「文字情報だけ」 がクラウドに
        //   残る状態になりかねないので、失敗フラグを立てて画面側で
        //   「完了」 ではなくエラーを出す (= 再同期を促す)。
        _lastSyncAttachmentFailed = true;
        lastUploadError = (job.kind == _AttachmentKind.image
                ? t('sync.fileUploadFailed')
                : t('sync.videoUploadFailed'))
            .replaceFirst('{name}', job.name);
      }
      // ジョブ終了時点でこのジョブ分は完全に転送済みなので、
      // 進捗を「completedBytes / totalBytes」に揃える
      onPageProgress?.call((completedBytes / totalBytes).clamp(0.0, 1.0));
      notifyListeners();
    }

    // URLが更新されたらFirestoreに再保存（ループ防止のため直接PATCH）
    if (anyUpdated) {
      await _saveToStorageLocal();
      await _resyncPageToFirestore(pageId);
    }
    onPageProgress?.call(1.0);
  }

  /// ページの namedGroups 全データを JSON 文字列にシリアライズ
  String _serializeNamedGroupsForPage(String pageId) {
    final groups = _namedGroups[pageId] ?? {};
    final colors = _groupColors[pageId] ?? {};
    final fontSizes = _groupFontSizes[pageId] ?? {};
    final fontFamilies = _groupFontFamilies[pageId] ?? {};
    return jsonEncode({
      'groups': groups.map((k, v) => MapEntry(k, v.toList())),
      'colors': colors,
      'fontSizes': fontSizes.map((k, v) => MapEntry(k, v)),
      'fontFamilies': fontFamilies,
    });
  }

  /// シリアライズされた namedGroups JSON をページに適用
  void _applyNamedGroupsJson(String pageId, String jsonStr) {
    try {
      final data = jsonDecode(jsonStr) as Map<String, dynamic>;
      // groups
      final gRaw = data['groups'] as Map<String, dynamic>? ?? {};
      final groups = <String, Set<String>>{};
      for (final e in gRaw.entries) {
        groups[e.key] = Set<String>.from(e.value as List);
      }
      _namedGroups[pageId] = groups;
      // colors
      final cRaw = data['colors'] as Map<String, dynamic>? ?? {};
      _groupColors[pageId] =
          cRaw.map((k, v) => MapEntry(k, (v as num).toInt()));
      // fontSizes
      final fsRaw = data['fontSizes'] as Map<String, dynamic>? ?? {};
      _groupFontSizes[pageId] =
          fsRaw.map((k, v) => MapEntry(k, (v as num).toDouble()));
      // fontFamilies
      final ffRaw = data['fontFamilies'] as Map<String, dynamic>? ?? {};
      _groupFontFamilies[pageId] =
          ffRaw.map((k, v) => MapEntry(k, v as String));
    } catch (e) {
      debugPrint('namedGroups デシリアライズエラー: $e');
    }
  }

  /// Firestoreにページを直接再保存（_uploadPageAttachmentsからのループ防止用）
  Future<void> _resyncPageToFirestore(String pageId) async {
    if (!_firebaseEnabled || _syncGroupId == null || _idToken == null) return;
    final idx = _pages.indexWhere((p) => p.id == pageId);
    if (idx < 0) return;
    try {
      final pageJson = jsonEncode(_pages[idx].toJson());
      final url = '$_firestoreBaseUrl/groups/$_syncGroupId/pages/$pageId';
      await http.patch(
        Uri.parse('$url?updateMask.fieldPaths=json'),
        headers: {
          'Authorization': 'Bearer $_idToken',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({
          'fields': {
            'json': {'stringValue': pageJson}
          },
        }),
      );
      debugPrint('Resync to Firestore OK (after upload): $pageId');
    } catch (e) {
      debugPrint('Resync to Firestore error: $e');
    }
  }

  String _cloudPageItemId(String pageId) => 'page:$pageId';
  String _cloudAttachmentItemId(String pageId, String nodeId) =>
      'attachment:$pageId:$nodeId';
  String _cloudVideoItemId(String pageId, String nodeId) =>
      'video:$pageId:$nodeId';

  String _storageAttachmentFileNameFromUrl(String url, {String? fallback}) {
    try {
      String raw;
      final objectMarker = url.indexOf('/o/');
      if (objectMarker >= 0) {
        raw = url.substring(objectMarker + 3).split('?').first;
      } else {
        raw = url.split('?').first.split('/').last;
      }
      var decoded = Uri.decodeComponent(raw).replaceAll('\\', '/');
      const attachmentMarker = '/attachments/';
      final markerIndex = decoded.lastIndexOf(attachmentMarker);
      if (markerIndex >= 0) {
        decoded = decoded.substring(markerIndex + attachmentMarker.length);
      }
      if (decoded.contains('/')) decoded = decoded.split('/').last;
      if (decoded.trim().isNotEmpty) return decoded.trim();
    } catch (_) {}
    final fb = (fallback ?? '').trim();
    if (fb.isNotEmpty) return fb.split('/').last.split('\\').last;
    return 'attachment_${DateTime.now().millisecondsSinceEpoch}';
  }

  String _downloadNodeTitle(MindMapNode node) {
    final title = node.title.trim();
    if (title.isNotEmpty) return title;
    final name = (node.attachmentName ?? '').trim();
    if (name.isNotEmpty) return name;
    return t('sync.untitledItem');
  }

  void _prepareCloudDownloadItems(List<MindMapPage> pages) {
    _cloudDownloadItems.clear();
    for (final page in pages) {
      _cloudDownloadItems[_cloudPageItemId(page.id)] = CloudDownloadItem(
        id: _cloudPageItemId(page.id),
        pageId: page.id,
        nodeId: '',
        label: t('sync.pageMainLabel').replaceFirst('{name}', page.name),
        fileName: '',
        kind: 'page',
      );
      for (final node in page.nodes.values) {
        final attachmentUrl = (node.attachmentStorageUrl ?? '').trim();
        final attachmentPath = (node.attachmentPath ?? '').trim();
        final attachmentName = (node.attachmentName ?? '').trim();
        if (attachmentUrl.isNotEmpty ||
            (attachmentPath.isNotEmpty &&
                attachmentName.isNotEmpty &&
                !attachmentPath.startsWith('data:'))) {
          final fileName = attachmentUrl.isNotEmpty
              ? _storageAttachmentFileNameFromUrl(attachmentUrl,
                  fallback: attachmentName)
              : _storageAttachmentFileNameFromUrl(attachmentPath,
                  fallback: attachmentName);
          _cloudDownloadItems[_cloudAttachmentItemId(page.id, node.id)] =
              CloudDownloadItem(
            id: _cloudAttachmentItemId(page.id, node.id),
            pageId: page.id,
            nodeId: node.id,
            label: '${page.name} / ${_downloadNodeTitle(node)}',
            fileName: fileName,
            kind: 'attachment',
          );
        }

        final videoUrl = (node.videoStorageUrl ?? '').trim();
        final youtubeUrl = (node.youtubeUrl ?? '').trim();
        if (videoUrl.isNotEmpty ||
            (youtubeUrl.isNotEmpty &&
                !youtubeUrl.startsWith('http://') &&
                !youtubeUrl.startsWith('https://'))) {
          final fileName = videoUrl.isNotEmpty
              ? _storageAttachmentFileNameFromUrl(videoUrl)
              : _storageAttachmentFileNameFromUrl(youtubeUrl);
          _cloudDownloadItems[_cloudVideoItemId(page.id, node.id)] =
              CloudDownloadItem(
            id: _cloudVideoItemId(page.id, node.id),
            pageId: page.id,
            nodeId: node.id,
            label: '${page.name} / ${_downloadNodeTitle(node)}',
            fileName: fileName,
            kind: 'video',
          );
        }
      }
    }
  }

  double _cloudDownloadOverallProgress() {
    if (_cloudDownloadItems.isEmpty) return _syncProgress;
    double total = 0;
    for (final item in _cloudDownloadItems.values) {
      total += item.progress.clamp(0.0, 1.0).toDouble();
    }
    return (total / _cloudDownloadItems.length).clamp(0.0, 1.0).toDouble();
  }

  void _markCloudDownloadItem(String id, CloudDownloadItemStatus status,
      {double? progress, String? error}) {
    final item = _cloudDownloadItems[id];
    if (item == null) return;
    item.status = status;
    if (progress != null) {
      item.progress = progress.clamp(0.0, 1.0).toDouble();
    }
    item.error = error;
    _syncProgress = _cloudDownloadOverallProgress();
  }

  MindMapPage _upsertDownloadedPage(MindMapPage page) {
    final idx = _pages.indexWhere((p) => p.id == page.id);
    if (idx < 0) {
      // ── ドロワーに必ず表示されるようフォルダー所属を正規化 ──
      // (= ユーザー報告: ページをダウンロードしたのに開いている一覧に
      //    表示されない)。 クラウド側の folderId がローカルに存在しない
      //    フォルダーを指していると、 どのフォルダーにもルートにも列挙
      //    されない「見えないページ」 になっていた。 未知のフォルダーは
      //    ルート (= 一覧の見える場所) に置く。
      if (page.folderId != null &&
          !_folders.any((f) => f.id == page.folderId)) {
        page.folderId = null;
      }
      _pages.add(page);
      return page;
    }
    // 既存ページの更新: ローカルでの整理 (所属フォルダー) は維持する
    // (= 別端末のフォルダー構成で自分のドロワーが並び替わらないように)。
    page.folderId = _pages[idx].folderId;
    _pages[idx] = page;
    return _pages[idx];
  }

  Future<bool> _downloadNodeAttachmentItem(
    MindMapPage page,
    MindMapNode node,
    CloudDownloadItem item, {
    bool force = false,
  }) async {
    if (!force && item.skip) {
      _markCloudDownloadItem(item.id, CloudDownloadItemStatus.skipped,
          progress: 1.0);
      notifyListeners();
      return true;
    }

    if (!force) {
      final localPath = item.kind == 'video'
          ? (node.youtubeUrl ?? '')
          : (node.attachmentPath ?? '');
      if (localPath.isNotEmpty &&
          !localPath.startsWith('http://') &&
          !localPath.startsWith('https://') &&
          !localPath.startsWith('data:') &&
          File(localPath).existsSync()) {
        _markCloudDownloadItem(item.id, CloudDownloadItemStatus.completed,
            progress: 1.0);
        notifyListeners();
        return true;
      }
    }

    _uploading[node.id] = true;
    _uploadProgress[node.id] = 0.0;
    _markCloudDownloadItem(item.id, CloudDownloadItemStatus.downloading,
        progress: 0.0);
    notifyListeners();

    final downloaded = await _downloadAttachmentWithProgress(
      item.fileName,
      node.id,
      detailItemId: item.id,
    );

    _uploading.remove(node.id);
    _uploadProgress.remove(node.id);

    if (downloaded != null) {
      if (item.kind == 'video') {
        node.youtubeUrl = downloaded;
      } else {
        node.attachmentPath = downloaded;
      }
      _markCloudDownloadItem(item.id, CloudDownloadItemStatus.completed,
          progress: 1.0);
      notifyListeners();
      return true;
    }

    _lastSyncAttachmentFailed = true;
    _markCloudDownloadItem(
      item.id,
      CloudDownloadItemStatus.failed,
      error: t('sync.itemDownloadFailed').replaceFirst('{name}', item.fileName),
    );
    notifyListeners();
    return false;
  }

  Future<void> retryCloudDownloadItem(String itemId) async {
    final item = _cloudDownloadItems[itemId];
    if (item == null || !item.canRetry || _isUploading || _isDownloading) {
      return;
    }
    final pageIndex = _pages.indexWhere((p) => p.id == item.pageId);
    if (pageIndex < 0) return;
    final page = _pages[pageIndex];
    final node = page.nodes[item.nodeId];
    if (node == null) return;

    _isDownloading = true;
    _downloadStartedAt = DateTime.now();
    _syncCancelRequested = false;
    _syncStatusText = t('sync.retryingItem').replaceFirst('{name}', item.label);
    _syncProgress = item.progress;
    item.skip = false;
    notifyListeners();
    try {
      await _downloadNodeAttachmentItem(page, node, item, force: true);
      await _saveToStorageLocal();
    } finally {
      _isDownloading = false;
      _syncProgress = 0.0;
      _syncStatusText = '';
      notifyListeners();
    }
  }

  /// リモートからフェッチしたページの添付ファイルをローカルにダウンロード
  Future<void> _downloadPageAttachments(MindMapPage page) async {
    if (!_firebaseEnabled || _syncGroupId == null) return;
    final hasPreparedItems =
        _cloudDownloadItems.containsKey(_cloudPageItemId(page.id)) ||
            page.nodes.values.any((node) =>
                _cloudDownloadItems
                    .containsKey(_cloudAttachmentItemId(page.id, node.id)) ||
                _cloudDownloadItems
                    .containsKey(_cloudVideoItemId(page.id, node.id)));
    if (!hasPreparedItems) {
      _prepareCloudDownloadItems([page]);
    }
    for (final node in page.nodes.values) {
      final attachmentItem =
          _cloudDownloadItems[_cloudAttachmentItemId(page.id, node.id)];
      if (attachmentItem != null) {
        await _downloadNodeAttachmentItem(page, node, attachmentItem);
      }

      final videoItem =
          _cloudDownloadItems[_cloudVideoItemId(page.id, node.id)];
      if (videoItem != null) {
        await _downloadNodeAttachmentItem(page, node, videoItem);
      }
    }
  }

  /// 進捗付きダウンロード
  ///
  /// 整合性検証: Content-Length と受信バイト数を最後に突き合わせ、 食い違う
  /// 場合は破損とみなして部分書き込みを破棄する (downloadAttachmentFromStorage
  /// と同じ方針)。 これにより「進捗 100% 表示後にファイルが開けない」現象を
  /// 防ぐ。
  Future<String?> _downloadAttachmentWithProgress(
      String fileName, String nodeId,
      {String? detailItemId, bool retried = false}) async {
    if (!_firebaseEnabled || _syncGroupId == null || _idToken == null)
      return null;
    try {
      final storagePath = 'groups/$_syncGroupId/attachments/$fileName';
      final encoded = Uri.encodeComponent(storagePath);
      final downloadUrl = '$_storageUploadUrl/$encoded?alt=media';

      final request = http.Request('GET', Uri.parse(downloadUrl));
      request.headers['Authorization'] = 'Bearer $_idToken';
      final streamedRes = await request.send();

      // ── トークン失効 (401/403) は強制リフレッシュして 1 回だけリトライ ──
      // 多数の添付を連続ダウンロードしていると途中で ID トークンが失効し、
      // 以降が全件失敗する (= ユーザー報告「ダウンロードが上手く行って
      // いない」 の一因)。
      if ((streamedRes.statusCode == 401 || streamedRes.statusCode == 403) &&
          !retried) {
        try {
          await streamedRes.stream.drain<void>();
        } catch (_) {}
        await _ensureFreshToken(force: true);
        return _downloadAttachmentWithProgress(fileName, nodeId,
            detailItemId: detailItemId, retried: true);
      }

      if (streamedRes.statusCode == 200) {
        final contentLength = streamedRes.contentLength ?? 0;
        if (contentLength > 0 && !canUseDownloadBytes(contentLength)) {
          final limitGb =
              (monthlyDownloadLimit / 1024 / 1024 / 1024).toStringAsFixed(1);
          _lastSyncLimitMessage =
              t('sync.monthlyDownloadLimit').replaceFirst('{limit}', limitGb);
          await streamedRes.stream.drain<void>();
          return null;
        }
        final appDir = await getApplicationDocumentsDirectory();
        final attachDir = Directory('${appDir.path}/attachments');
        if (!await attachDir.exists()) {
          await attachDir.create(recursive: true);
        }
        final localFileName = _cloudLocalFileName(nodeId, fileName);
        final localPath = '${attachDir.path}/$localFileName';
        // 一旦 .part に書く (途中ファイルが UI から参照されないように)
        final tempPath = '$localPath.part';
        final sink = File(tempPath).openWrite();
        int received = 0;
        bool sinkOk = true;

        try {
          await for (final chunk in streamedRes.stream) {
            sink.add(chunk);
            received += chunk.length;
            // 進捗報告は実際のバイト数のみで進める。 95% 以上には乗せず、
            // 残りはサーバー応答クローズ + flush + rename の確定後に
            // 100% へ進める (Upload 側と同じ思想)。
            if (contentLength > 0) {
              final progress =
                  (received / contentLength * 0.95).clamp(0.0, 0.95).toDouble();
              _uploadProgress[nodeId] = progress;
              if (detailItemId != null) {
                final item = _cloudDownloadItems[detailItemId];
                if (item != null) {
                  item.status = CloudDownloadItemStatus.downloading;
                  item.progress = progress;
                  _syncProgress = _cloudDownloadOverallProgress();
                }
              }
              _notifyCloudDownloadProgress();
            }
          }
        } catch (e) {
          debugPrint('Storage download stream error: $e');
          sinkOk = false;
        } finally {
          // flush で OS バッファまで吐き出してから close。
          // close は flush も内部で行うが、 念のため明示する
          // (古い実装で「close は呼んだが書き込み中のチャンクが残る」
          //  ように見える挙動があったため)。
          try {
            await sink.flush();
          } catch (_) {}
          await sink.close();
        }

        if (!sinkOk) {
          try {
            await File(tempPath).delete();
          } catch (_) {}
          return null;
        }

        // ── サイズ検証 ──
        final tempFile = File(tempPath);
        final writtenLen = await tempFile.length();
        if (writtenLen == 0) {
          debugPrint('Storage download: empty file for $fileName');
          try {
            await tempFile.delete();
          } catch (_) {}
          return null;
        }
        if (contentLength > 0 && writtenLen != contentLength) {
          debugPrint(
              'Storage download size mismatch: $fileName expected=$contentLength written=$writtenLen');
          try {
            await tempFile.delete();
          } catch (_) {}
          return null;
        }

        // 旧ファイルを置き換え (Windows では既存ファイルがあると
        // rename が失敗するので先に削除)
        final finalFile = File(localPath);
        if (await finalFile.exists()) {
          try {
            await finalFile.delete();
          } catch (_) {}
        }
        await tempFile.rename(localPath);

        recordDownloadBytes(writtenLen);
        _uploadProgress[nodeId] = 1.0;
        if (detailItemId != null) {
          final item = _cloudDownloadItems[detailItemId];
          if (item != null) {
            item.progress = 1.0;
            _syncProgress = _cloudDownloadOverallProgress();
          }
        }
        _notifyCloudDownloadProgress(force: true);

        debugPrint(
            'Storage download OK: $fileName → $localPath ($writtenLen bytes)');
        return localPath;
      } else {
        debugPrint('Storage download: ${streamedRes.statusCode} ($fileName)');
        return null;
      }
    } catch (e) {
      debugPrint('Storage download error: $e');
      return null;
    }
  }

  /// 手動: 選択したページをクラウドにアップロード
  bool _isUploading = false;
  bool get isUploading => _isUploading;
  // ── 連打ガードのフラグが「死んだまま」 残って永久ブロックするのを防ぐ ──
  // (= ユーザー報告: 連打無効化を入れた辺りから Ctrl+S/D が効かなくなった)。
  // フラグを立てた時刻を記録し、 一定時間 (3 分) 経っても解除されていなければ
  // 前の処理は死んだものとみなして新しい操作を許可する。
  DateTime? _uploadStartedAt;
  DateTime? _downloadStartedAt;
  static const Duration _kSyncStaleAfter = Duration(minutes: 3);

  /// 進行中とされる同期が「生きている (= まだタイムアウト範囲内)」 か。
  /// どちらも生きていなければ stale とみなしてガードを解除してよい。
  bool _syncFlagsAreStale() {
    final now = DateTime.now();
    final upAlive = _isUploading &&
        _uploadStartedAt != null &&
        now.difference(_uploadStartedAt!) <= _kSyncStaleAfter;
    final downAlive = _isDownloading &&
        _downloadStartedAt != null &&
        now.difference(_downloadStartedAt!) <= _kSyncStaleAfter;
    return !(upAlive || downAlive);
  }

  // ── Esc で同期 (アップロード/ダウンロード) を中断する (= ユーザー要望) ──
  // ループ各ページの先頭でこのフラグを見て break する。
  bool _syncCancelRequested = false;
  bool get isSyncing => _isUploading || _isDownloading;
  void cancelSync() {
    if (_isUploading || _isDownloading) {
      _syncCancelRequested = true;
      _syncStatusText = t('sync.cancelling');
      notifyListeners();
    }
  }

  double _syncProgress = 0.0;
  double get syncProgress => _syncProgress;
  String _syncStatusText = '';
  String get syncStatusText => _syncStatusText;

  Future<void> uploadToCloud(List<String> pageIds) async {
    if (!isMaxUnlocked) {
      throw Exception(t('paywall.maxRequiredCloudSync'));
    }
    // ── 連打/二重実行ガード (= ユーザー要望: Ctrl+S を連打しても、 最初の
    //    アップロードが完了するまで以降を無視する) ──
    if (_isUploading || _isDownloading) {
      // 生きている同期がある間だけブロック。 死んだフラグ (stale) なら解除して続行。
      if (!_syncFlagsAreStale()) return;
      _isUploading = false;
      _isDownloading = false;
    }
    if ((!_firebaseEnabled || _idToken == null) && _syncGroupId != null) {
      try {
        await _initFirebase();
      } catch (_) {}
    }
    if (!_firebaseEnabled || _syncGroupId == null) {
      throw Exception(t('sync.joinGroupFirst'));
    }
    // await の前にフラグを立てて再入を防ぐ。
    _isUploading = true;
    _uploadStartedAt = DateTime.now();
    _syncCancelRequested = false;
    _syncProgress = 0.0;
    _lastSyncAttachmentFailed = false; // この同期での添付転送失敗を初期化
    _lastSyncLimitMessage = null; // 上限到達メッセージも初期化
    notifyListeners();
    try {
      // ── ネットワークが固まると 0% から進まなくなる対策 (= ユーザー要望:
      //    Ctrl+S で転送が 0% から永遠に変わらない) ──
      // タイムアウトを付けて、 ハングではなくエラーで finally に抜けて進捗を
      // リセットする (= バーが永久に 0% で止まらない)。
      await _ensureFreshToken().timeout(const Duration(seconds: 25));
      // メンバーのハートビート更新は「おまけ」 なので、 失敗しても
      // アップロード本体は続行する (= ハートビートのタイムアウトで
      // アップロードが止まらないように) (= ユーザー報告)。
      try {
        await _registerMember(_syncGroupId!)
            .timeout(const Duration(seconds: 25));
      } catch (e) {
        debugPrint('registerMember failed (continuing upload): $e');
      }
      for (int i = 0; i < pageIds.length; i++) {
        if (_syncCancelRequested) break; // Esc でキャンセル
        final pageId = pageIds[i];
        final idx = _pages.indexWhere((p) => p.id == pageId);
        if (idx < 0) continue;
        _syncStatusText = t('sync.uploadingPageProgress')
            .replaceFirst('{name}', _pages[idx].name)
            .replaceFirst('{current}', '${i + 1}')
            .replaceFirst('{total}', '${pageIds.length}');
        // 各ページに「全体の進捗の 1/pageIds.length 分」を割り当てる。
        // ページ内の添付ファイル送信進捗 (0.0〜1.0) を、その配分内に
        // マッピングして反映する。これによりバーが「90% で長時間止まって
        // から突然 100% & Complete」になる問題を解消し、巨大な動画ファイル
        // でも実際のバイト送信進捗に追従するようになる。
        final pageBase = i / pageIds.length;
        final pageSlice = 1.0 / pageIds.length;
        _syncProgress = pageBase;
        notifyListeners();
        await _savePageToFirestore(pageId, onPageProgress: (p) {
          // p は 0.0〜1.0 のページ内進捗。全体に変換して syncProgress を更新。
          _syncProgress = (pageBase + p * pageSlice).clamp(0.0, 1.0);
          notifyListeners();
        });
      }
      _syncProgress = 1.0;
      _syncStatusText = '';
      notifyListeners();
    } finally {
      _isUploading = false;
      _syncProgress = 0.0;
      _syncStatusText = '';
      notifyListeners();
    }
  }

  /// 手動: 現在のページをクラウドにアップロード
  Future<void> syncCurrentPageToCloud() async {
    if (!isMaxUnlocked) {
      throw Exception(t('paywall.maxRequiredCloudSync'));
    }
    if ((!_firebaseEnabled || _idToken == null) && _syncGroupId != null) {
      try {
        await _initFirebase();
      } catch (_) {}
    }
    if (!_firebaseEnabled || _syncGroupId == null) {
      throw Exception(t('sync.joinGroupFirst'));
    }
    await _ensureFreshToken();
    await _savePageToFirestore(currentPage.id);
  }

  /// Ctrl+R: クラウドと比較して新しければ現在ページをダウンロード
  /// 戻り値: 'downloaded' | 'up_to_date' | 'not_synced' | 'error:...'
  /// 現在のマップが前回アップロード時から内容が変わっているか (= 差分があるか)。
  /// ページ内容のハッシュを前回アップロード時のものと比較する (= ユーザー要望:
  /// Ctrl+S で差分だけアップロード。 変わっていなければアップロードをスキップ)。
  Future<bool> isCurrentPageUploadNeeded() async {
    try {
      final pageId = currentPage.id;
      final h = jsonEncode(currentPage.toJson()).hashCode.toString();
      final prefs = await _prefsWithRetry();
      final stored = prefs.getString('page_uploaded_hash_$pageId');
      if (stored == null) return true; // 未記録 → アップロードが必要
      if (stored != h) return true; // 変わっていれば必要
      if (!_firebaseEnabled || _syncGroupId == null) return true;
      try {
        if (_idToken == null) {
          try {
            await _initFirebase();
          } catch (_) {}
        }
        await _ensureFreshToken().timeout(const Duration(seconds: 20));
        final url = '$_firestoreBaseUrl/groups/$_syncGroupId/pages/$pageId';
        final res = await http.get(
          Uri.parse(url),
          headers: {'Authorization': 'Bearer $_idToken'},
        ).timeout(const Duration(seconds: 20));
        if (res.statusCode == 200) return false;
        if (res.statusCode == 404) return true;
        if (res.statusCode == 401 || res.statusCode == 403) {
          await _ensureFreshToken(force: true)
              .timeout(const Duration(seconds: 20));
          final retry = await http.get(
            Uri.parse(url),
            headers: {'Authorization': 'Bearer $_idToken'},
          ).timeout(const Duration(seconds: 20));
          return retry.statusCode != 200;
        }
        return true;
      } catch (_) {
        return true;
      }
    } catch (_) {
      return true; // 不明なときは安全側でアップロード
    }
  }

  Future<String> autoSyncCurrentPage() async {
    if (!isMaxUnlocked || _syncGroupId == null) return 'not_synced';
    try {
      if (!_firebaseEnabled || _idToken == null) {
        try {
          await _initFirebase();
        } catch (_) {}
      }
      if (!_firebaseEnabled || _idToken == null) return 'not_synced';
      await _ensureFreshToken();
      final pageId = currentPage.id;
      final url = '$_firestoreBaseUrl/groups/$_syncGroupId/pages/$pageId';
      final res = await http.get(
        Uri.parse(url),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      if (res.statusCode != 200) return 'not_synced';
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      // Firestoreドキュメントの最終更新時刻 = 最後にアップロードされた時刻
      final cloudUpdateTimeStr = data['updateTime'] as String?;
      if (cloudUpdateTimeStr == null) return 'up_to_date';
      final cloudUpdateTime = DateTime.tryParse(cloudUpdateTimeStr);
      if (cloudUpdateTime == null) return 'up_to_date';
      // ローカルの最終アップロード日時
      final prefs = await _prefsWithRetry();
      final localUploadedStr = prefs.getString('page_uploaded_$pageId');
      final localUploadedAt =
          localUploadedStr != null ? DateTime.tryParse(localUploadedStr) : null;
      // クラウドの方が新しい場合のみダウンロード
      if (localUploadedAt == null || cloudUpdateTime.isAfter(localUploadedAt)) {
        final fields = data['fields'] as Map<String, dynamic>? ?? {};
        final jsonStr = _firestoreStr(fields['json']);
        if (jsonStr == null) return 'up_to_date';
        final cloudPage =
            MindMapPage.fromJson(jsonDecode(jsonStr) as Map<String, dynamic>);
        if (_isUploading || _isDownloading) {
          if (!_syncFlagsAreStale()) return 'sync_in_progress';
          _isUploading = false;
          _isDownloading = false;
        }
        _isDownloading = true;
        _downloadStartedAt = DateTime.now();
        _syncCancelRequested = false;
        _syncProgress = 0.0;
        _syncStatusText =
            t('sync.downloadingPage').replaceFirst('{name}', cloudPage.name);
        _lastSyncAttachmentFailed = false;
        _lastSyncLimitMessage = null;
        _prepareCloudDownloadItems([cloudPage]);
        notifyListeners();
        try {
          // undo履歴に積む（Ctrl+Zで戻れるように）
          _undoStacks.putIfAbsent(pageId, () => []);
          _redoStacks.putIfAbsent(pageId, () => []);
          final groups = _namedGroups[pageId] ?? {};
          _undoStacks[pageId]!.add(_PageSnapshot.from(currentPage, groups));
          if (_undoStacks[pageId]!.length > _maxHistory) {
            _undoStacks[pageId]!.removeAt(0);
          }
          _redoStacks[pageId]!.clear();

          _markCloudDownloadItem(
              _cloudPageItemId(pageId), CloudDownloadItemStatus.downloading,
              progress: 0.0);
          // ── ローカルの編集差分を上乗せしてから取り込む ──
          // (= ユーザー要望: ダウンロード側は現在の編集内容の差分を加える
          //    形で取り込む。 前回同期時点を基準にした 3-way マージ)。
          final merged = _mergeLocalEditsIntoCloudPage(cloudPage,
              baseJson: prefs.getString('page_synced_json_$pageId'));
          final localPage = _upsertDownloadedPage(merged);
          _markCloudDownloadItem(
              _cloudPageItemId(pageId), CloudDownloadItemStatus.completed,
              progress: 1.0);

          final ngJson = _firestoreStr(fields['namedGroupsJson']);
          if (ngJson != null && ngJson.isNotEmpty) {
            _applyNamedGroupsJson(pageId, ngJson);
          }
          notifyListeners();

          await _downloadPageAttachments(localPage);
          await _saveToStorageLocal();
          await _saveNamedGroups();
          // アップロード日時をクラウドのupdateTimeに合わせる
          await prefs.setString('page_uploaded_$pageId', cloudUpdateTimeStr);
          // 次回マージの基準は「今クラウドにある内容」 (= 取得した素の JSON)。
          // ローカル差分を上乗せした merged ではない点に注意 (上乗せ分は
          // まだクラウドに無い = 次回も「ローカルの変更」 として扱う)。
          await _storeSyncedBaseJson(pageId, jsonStr);
          notifyListeners();
          return 'downloaded';
        } finally {
          _isDownloading = false;
          _syncProgress = 0.0;
          _syncStatusText = '';
          notifyListeners();
        }
      }
      return 'up_to_date';
    } catch (e) {
      return 'error:$e';
    }
  }

  /// 画面を強制再描画（互換用）
  void refresh() => notifyListeners();

  /// 手動: クラウドからページ一覧を取得（ダウンロードせずにリスト返却）
  Future<List<MindMapPage>> fetchCloudPageList({bool retried = false}) async {
    if (!isMaxUnlocked) {
      throw Exception(t('paywall.maxRequiredCloudSync'));
    }
    if ((!_firebaseEnabled || _idToken == null) && _syncGroupId != null) {
      try {
        await _initFirebase();
      } catch (_) {}
    }
    if (!_firebaseEnabled || _syncGroupId == null) {
      throw Exception(t('sync.joinGroupFirst'));
    }
    await _ensureFreshToken();
    final url = '$_firestoreBaseUrl/groups/$_syncGroupId/pages';
    // タイムアウト無しだと「読み込み中」 のまま固まる (= ユーザー報告)。
    final res = await http.get(
      Uri.parse(url),
      headers: {'Authorization': 'Bearer $_idToken'},
    ).timeout(const Duration(seconds: 60),
        onTimeout: () => throw Exception(t('sync.cloudListTimeout')));
    if ((res.statusCode == 401 || res.statusCode == 403) && !retried) {
      // トークンをリフレッシュしてリトライ (401/403 は必ず再取得)
      await _ensureFreshToken(force: true);
      return fetchCloudPageList(retried: true);
    }
    if (res.statusCode != 200) {
      if (res.statusCode == 403) {
        throw Exception(t('sync.cloudPermissionError')
            .replaceFirst('{project}', _firestoreProjectId));
      }
      throw Exception(t('sync.cloudFetchFailed')
          .replaceFirst('{status}', '${res.statusCode}'));
    }
    final data = jsonDecode(res.body) as Map<String, dynamic>;
    final docs = data['documents'] as List<dynamic>? ?? [];
    final result = <MindMapPage>[];
    _cloudPageGroupsCache.clear();
    _cloudPagePaintCache.clear();
    _cloudPageUpdatedAt.clear();
    final now = DateTime.now().toUtc();
    for (final doc in docs) {
      try {
        final fields = doc['fields'] as Map<String, dynamic>;
        // ── 期限切れチェック (無料プランで 7 日経過) ──
        // Firestore TTL ポリシーが完全に動くまでのフェイルセーフ。
        // expiresAt が過去ならクライアント側でも無視 + 即削除を試みる。
        final expiresAtStr = _firestoreStr(fields['expiresAt']);
        if (expiresAtStr != null && expiresAtStr.isNotEmpty) {
          final expiresAt = DateTime.tryParse(expiresAtStr);
          if (expiresAt != null && expiresAt.isBefore(now)) {
            // 期限切れドキュメントは結果に含めない + バックエンドからも削除
            try {
              final docName = doc['name'] as String?;
              if (docName != null && docName.isNotEmpty) {
                // doc['name'] は "projects/.../documents/groups/.../pages/PAGE_ID"
                // 形式。Firestore REST API で DELETE する。
                final deleteUrl =
                    'https://firestore.googleapis.com/v1/$docName';
                http.delete(
                  Uri.parse(deleteUrl),
                  headers: {'Authorization': 'Bearer $_idToken'},
                ).catchError((_) {
                  // 削除失敗は無視 (TTL ポリシーで後ほど消える)
                  return http.Response('', 0);
                });
              }
            } catch (_) {}
            continue;
          }
        }
        final jsonStr = _firestoreStr(fields['json']);
        if (jsonStr == null) continue;
        final pageData = jsonDecode(jsonStr) as Map<String, dynamic>;
        final page = MindMapPage.fromJson(pageData);
        // namedGroups を一時キャッシュ
        final ngJson = _firestoreStr(fields['namedGroupsJson']);
        if (ngJson != null && ngJson.isNotEmpty) {
          _cloudPageGroupsCache[page.id] = ngJson;
        }
        // フリーノートの中身 (= ユーザー報告への対応)。
        final paintJson = _firestoreStr(fields['paintJson']);
        if (paintJson != null && paintJson.isNotEmpty) {
          _cloudPagePaintCache[page.id] = paintJson;
        }
        // アップロード日時 (= ユーザー要望: 一覧に出す + 新しい順に並べる)。
        // Firestore の updateTime (サーバー側の最終書き込み時刻) を使う。
        final ut = DateTime.tryParse('${doc['updateTime'] ?? ''}');
        if (ut != null) _cloudPageUpdatedAt[page.id] = ut.toLocal();
        result.add(page);
      } catch (_) {}
    }
    // 新しいものが上 (= ユーザー要望)。 時刻が取れなかった分は末尾。
    result.sort((a, b) {
      final ta = _cloudPageUpdatedAt[a.id];
      final tb = _cloudPageUpdatedAt[b.id];
      if (ta == null && tb == null) return 0;
      if (ta == null) return 1;
      if (tb == null) return -1;
      return tb.compareTo(ta);
    });
    return result;
  }

  /// クラウド一覧の各ページのアップロード日時 (fetchCloudPageList が埋める)。
  final Map<String, DateTime> _cloudPageUpdatedAt = {};
  DateTime? cloudPageUpdatedAt(String pageId) => _cloudPageUpdatedAt[pageId];

  /// 手動: 選択したクラウドページをダウンロード（ローカルに追加or上書き）
  bool _isDownloading = false;
  bool get isDownloading => _isDownloading;

  Future<void> downloadFromCloud(
      List<MindMapPage> cloudPages, List<String> selectedIds) async {
    if (!isMaxUnlocked) {
      throw Exception(t('paywall.maxRequiredCloudSync'));
    }
    // ── 連打/二重実行ガード (= ユーザー要望: Ctrl+D を連打しても、 最初の
    //    ダウンロードが完了するまで以降を無視する) ──
    if (_isUploading || _isDownloading) {
      // 生きている同期がある間だけブロック。 死んだフラグ (stale) なら解除して続行。
      if (!_syncFlagsAreStale()) return;
      _isUploading = false;
      _isDownloading = false;
    }
    if ((!_firebaseEnabled || _idToken == null) && _syncGroupId != null) {
      try {
        await _initFirebase();
      } catch (_) {}
    }
    if (!_firebaseEnabled || _syncGroupId == null) {
      throw Exception(t('sync.joinGroupFirst'));
    }
    // await の前にフラグを立てて再入を防ぐ。
    _isDownloading = true;
    _downloadStartedAt = DateTime.now();
    _syncCancelRequested = false;
    _syncProgress = 0.0;
    _lastSyncAttachmentFailed = false; // この同期での添付転送失敗を初期化
    _lastSyncLimitMessage = null; // 上限到達メッセージも初期化
    notifyListeners();
    try {
      // ── トークンを事前リフレッシュ ──
      // 一覧取得 (fetchCloudPageList) から選択ダイアログを挟んで時間が
      // 経っていると ID トークンが失効し、 添付ダウンロードが全件 401 で
      // 失敗する (= ユーザー報告「ダウンロードが上手く行っていない」 の
      // 一因)。 失敗しても本体は続行 (各リクエスト側の 401 リトライに任せる)。
      try {
        await _ensureFreshToken().timeout(const Duration(seconds: 25));
      } catch (e) {
        debugPrint('ensureFreshToken failed (continuing download): $e');
      }
      // メンバーのハートビート更新は「おまけ」 なので、 失敗しても
      // ダウンロード本体は続行する (= ユーザー報告: ハートビート失敗で
      // ダウンロードが止まらないように)。
      try {
        await _registerMember(_syncGroupId!)
            .timeout(const Duration(seconds: 25));
      } catch (e) {
        debugPrint('registerMember failed (continuing download): $e');
      }
      // ── ダウンロード前に上書き対象ページをUndo履歴に積む ──
      for (final pageId in selectedIds) {
        final idx = _pages.indexWhere((p) => p.id == pageId);
        if (idx >= 0) {
          final page = _pages[idx];
          _undoStacks.putIfAbsent(pageId, () => []);
          _redoStacks.putIfAbsent(pageId, () => []);
          final groups = _namedGroups[pageId] ?? {};
          _undoStacks[pageId]!.add(_PageSnapshot.from(page, groups));
          if (_undoStacks[pageId]!.length > _maxHistory) {
            _undoStacks[pageId]!.removeAt(0);
          }
          _redoStacks[pageId]!.clear();
        }
      }
      final selected =
          cloudPages.where((p) => selectedIds.contains(p.id)).toList();
      _prepareCloudDownloadItems(selected);
      notifyListeners();
      for (int i = 0; i < selected.length; i++) {
        if (_syncCancelRequested) break; // Esc でキャンセル
        final page = selected[i];
        _syncStatusText = t('sync.downloadingPageProgress')
            .replaceFirst('{name}', page.name)
            .replaceFirst('{current}', '${i + 1}')
            .replaceFirst('{total}', '${selected.length}');
        final pageItemId = _cloudPageItemId(page.id);
        final pageItem = _cloudDownloadItems[pageItemId];
        if (pageItem?.skip == true) {
          // ページ本体を除外した場合、そのページに属する添付・動画も取得されない。
          // 子項目を待機中のまま残さず、まとめて除外済みにして詳細表示と
          // 全体進捗を完了状態へ揃える。
          for (final item in _cloudDownloadItems.values
              .where((item) => item.pageId == page.id)) {
            item.skip = true;
            _markCloudDownloadItem(item.id, CloudDownloadItemStatus.skipped,
                progress: 1.0);
          }
          notifyListeners();
          continue;
        }
        _markCloudDownloadItem(pageItemId, CloudDownloadItemStatus.downloading,
            progress: 0.0);
        // ── ローカルの編集差分を上乗せしてから取り込む ──
        // (= ユーザー要望: ダウンロード側は現在の編集内容の差分を加える形で
        //    取り込む。 前回同期時点を基準にした 3-way マージ)。 マージ前の
        //    素のクラウド JSON を次回マージの基準として保存する。
        String? cloudJsonForBase;
        try {
          cloudJsonForBase = jsonEncode(page.toJson());
        } catch (_) {}
        String? baseJson;
        try {
          final prefs = await _prefsWithRetry();
          baseJson = prefs.getString('page_synced_json_${page.id}');
        } catch (_) {}
        final merged = _mergeLocalEditsIntoCloudPage(page, baseJson: baseJson);
        final localPage = _upsertDownloadedPage(merged);
        if (cloudJsonForBase != null) {
          await _storeSyncedBaseJson(page.id, cloudJsonForBase);
        }
        final cachedNg = _cloudPageGroupsCache[page.id];
        if (cachedNg != null && cachedNg.isNotEmpty) {
          _applyNamedGroupsJson(page.id, cachedNg);
        }
        // フリーノートの中身と貼り付け画像を復元する (= ユーザー要望)。
        final cachedPaint = _cloudPagePaintCache[page.id];
        if (cachedPaint != null && cachedPaint.isNotEmpty) {
          await restorePaintJsonFromCloud(page.id, cachedPaint);
        }
        _markCloudDownloadItem(pageItemId, CloudDownloadItemStatus.completed,
            progress: 1.0);
        notifyListeners();
        // 添付ファイルをローカルに反映済みのページへ順番に埋めていく。
        await _downloadPageAttachments(localPage);
      }
      _syncProgress = 1.0;
      _syncStatusText = '';
      await _saveToStorageLocal();
      await _saveNamedGroups(); // 付箋情報も永続化
      notifyListeners();
    } finally {
      _isDownloading = false;
      _syncProgress = 0.0;
      _syncStatusText = '';
      notifyListeners();
    }
  }

  /// クラウド上の指定ページを削除
  Future<void> deleteCloudPages(List<String> pageIds) async {
    if (!_firebaseEnabled || _syncGroupId == null) {
      throw Exception(t('sync.joinGroupFirst'));
    }
    await _ensureFreshToken();
    for (final pageId in pageIds) {
      final url = '$_firestoreBaseUrl/groups/$_syncGroupId/pages/$pageId';
      final res = await http.delete(
        Uri.parse(url),
        headers: {'Authorization': 'Bearer $_idToken'},
      );
      if (res.statusCode != 200 && res.statusCode != 204) {
        debugPrint('クラウド削除エラー (pageId=$pageId): ${res.statusCode}');
      }
    }
  }

  // ─── 位置情報 (WebView 用) ────────────────────────────────────────────
  // (= ユーザー報告: Google マップ / Earth で現在地が表示されない)。
  // Windows の WebView2 はホスト側の位置情報プロバイダに繋がっていないこと
  // が多く、 navigator.geolocation が永久に応答しない。 そこで IP から
  // おおよその座標 (都市レベル) を取り、 それを navigator.geolocation の
  // 代わりに流し込む。 精度は粗いが「現在地が全く出ない」 よりは実用的。

  double? _approxLat;
  double? _approxLon;
  DateTime? _approxGeoAt;

  double? get approxLatitude => _approxLat;
  double? get approxLongitude => _approxLon;

  Future<void> _loadApproxLocation() async {
    try {
      final prefs = await _prefsWithRetry();
      final lat = prefs.getDouble('approx_geo_lat');
      final lon = prefs.getDouble('approx_geo_lon');
      final ts = prefs.getInt('approx_geo_ts');
      if (lat != null && lon != null) {
        _approxLat = lat;
        _approxLon = lon;
        if (ts != null) {
          _approxGeoAt = DateTime.fromMillisecondsSinceEpoch(ts);
        }
      }
    } catch (_) {}
  }

  /// おおよその現在地を取得する (24 時間キャッシュ)。
  Future<void> ensureApproxLocation({bool force = false}) async {
    if (!force &&
        _approxLat != null &&
        _approxGeoAt != null &&
        DateTime.now().difference(_approxGeoAt!) < const Duration(hours: 24)) {
      return;
    }
    try {
      final res = await http
          .get(Uri.parse('http://ip-api.com/json/?fields=status,lat,lon'))
          .timeout(const Duration(seconds: 8));
      if (res.statusCode != 200) return;
      final j = jsonDecode(res.body) as Map<String, dynamic>;
      if (j['status'] != 'success') return;
      final lat = (j['lat'] as num?)?.toDouble();
      final lon = (j['lon'] as num?)?.toDouble();
      if (lat == null || lon == null) return;
      _approxLat = lat;
      _approxLon = lon;
      _approxGeoAt = DateTime.now();
      final prefs = await _prefsWithRetry();
      await prefs.setDouble('approx_geo_lat', lat);
      await prefs.setDouble('approx_geo_lon', lon);
      await prefs.setInt('approx_geo_ts', _approxGeoAt!.millisecondsSinceEpoch);
      notifyListeners();
    } catch (e) {
      debugPrint('おおよその現在地の取得に失敗: $e');
    }
  }

  /// WebView に流し込む navigator.geolocation の差し替え JS。
  /// 座標が未取得なら null (= 何もしない)。
  String? geolocationShimJs() {
    final lat = _approxLat;
    final lon = _approxLon;
    if (lat == null || lon == null) return null;
    return '(function(){'
        'try{'
        'var pos={coords:{latitude:$lat,longitude:$lon,accuracy:5000,'
        'altitude:null,altitudeAccuracy:null,heading:null,speed:null},'
        'timestamp:Date.now()};'
        'var g={'
        'getCurrentPosition:function(ok){try{ok(pos);}catch(e){}},'
        'watchPosition:function(ok){try{ok(pos);}catch(e){}return 1;},'
        'clearWatch:function(){}'
        '};'
        'try{Object.defineProperty(navigator,"geolocation",'
        '{value:g,configurable:true});}catch(e){navigator.geolocation=g;}'
        '}catch(e){}'
        '})();';
  }

  // ─── ページの Web 公開 ────────────────────────────────────────────────
  // (= ユーザー要望: ページをサーバーに公開して、 スプレッドシートのように
  //  皆で見られるように)。 自己完結 HTML をクラウドに置き、 その URL を
  //  共有すればブラウザで誰でも閲覧できる。
  //
  // 保存先は既にアクセス権が通っている `groups/public/attachments/` 配下に
  // する (専用パスだと Storage ルール側の許可が別途必要になるため)。

  /// 公開済みページ: pageId → {code, url, title, updatedAt}
  final Map<String, Map<String, String>> _publishedPages = {};

  /// 公開済みページの一覧 (読み取り用)。
  Map<String, Map<String, String>> get publishedPages =>
      Map.unmodifiable(_publishedPages);

  String? publishedUrlFor(String pageId) {
    final u = _publishedPages[pageId]?['url'];
    return (u == null || u.isEmpty) ? null : u;
  }

  /// 公開コードを確保する (まだ公開していなければ発番だけ行う)。
  /// 公開用 HTML に共同編集の接続先を埋め込むため、 アップロードより先に
  /// コードが要る。
  String ensurePublishCode(String pageId) {
    final cur = _publishedPages[pageId]?['code'];
    if (cur != null && cur.isNotEmpty) return cur;
    final code = _uuid.v4().replaceAll('-', '').substring(0, 10);
    _publishedPages[pageId] = {
      'code': code,
      'url': '',
      'title': '',
      'updatedAt': '',
    };
    return code;
  }

  String? publishedCodeFor(String pageId) => _publishedPages[pageId]?['code'];

  DateTime? publishedAtFor(String pageId) {
    final v = _publishedPages[pageId]?['updatedAt'];
    return v == null ? null : DateTime.tryParse(v);
  }

  Future<void> _loadPublishedPages() async {
    try {
      final prefs = await _prefsWithRetry();
      final raw = prefs.getString('published_pages_v1');
      if (raw == null || raw.isEmpty) return;
      final map = jsonDecode(raw) as Map<String, dynamic>;
      _publishedPages.clear();
      map.forEach((k, v) {
        if (v is Map) {
          _publishedPages[k] = v.map((a, b) => MapEntry('$a', '$b'));
        }
      });
      notifyListeners();
    } catch (e) {
      debugPrint('_loadPublishedPages 失敗: $e');
    }
  }

  Future<void> _savePublishedPages() async {
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setString('published_pages_v1', jsonEncode(_publishedPages));
    } catch (e) {
      debugPrint('_savePublishedPages 失敗: $e');
    }
  }

  String _publishStoragePath(String code) =>
      'groups/public/attachments/page_$code.html';

  /// ページを Web に公開し、 共有 URL を返す。 既に公開済みなら同じ URL の
  /// まま中身を差し替える (= リンクを配り直さずに更新できる)。
  Future<String> publishPageToWeb({
    required String pageId,
    required String title,
    required String html,
  }) async {
    // ── 公開はストレージ費用が掛かるので Pro 以上に限定する ──
    // 1 ページの HTML はおおむね数十 KB〜数百 KB。 Storage の保管が
    // 1GB あたり月 $0.026、 配信が 1GB あたり $0.12 なので、 数百ページ
    // 公開しても月あたり数円〜数十円で収まる。 とはいえ無料に開くと
    // ファイル置き場として踏み台にされ得るため Pro 以上とする。
    // ── 共有はリアルタイム共同編集専用にしたので Max 限定 ──
    // (= ユーザー要望: 紛らわしいので共同編集だけにして Max の特典に)。
    if (!isMaxUnlocked) {
      throw Exception(t('paywall.maxRequiredLive'));
    }
    if (!_firebaseEnabled) {
      await _initFirebase(); // 1 回リトライ
    }
    if (!_firebaseEnabled) {
      throw Exception(_firebaseInitError ?? t('sync.firebaseNotConfigured'));
    }
    await _ensureFreshToken();
    if (_idToken == null) {
      throw Exception(t('sync.firebaseDisconnected'));
    }
    final bytes = utf8.encode(html);
    // 公開分も月間アップロード量として数える (他のクラウド機能と同じ扱い)。
    if (!canUseUploadBytes(bytes.length)) {
      final limitGb =
          (monthlyUploadLimit / 1024 / 1024 / 1024).toStringAsFixed(1);
      throw Exception(
          t('sync.monthlyUploadLimit').replaceFirst('{limit}', limitGb));
    }
    final code = _publishedPages[pageId]?['code'] ??
        _uuid.v4().replaceAll('-', '').substring(0, 10);
    final encoded = Uri.encodeComponent(_publishStoragePath(code));
    final res = await http.post(
      Uri.parse('$_storageUploadUrl?uploadType=media&name=$encoded'),
      headers: {
        'Authorization': 'Bearer $_idToken',
        'Content-Type': 'text/html; charset=utf-8',
      },
      body: bytes,
    );
    if (res.statusCode < 200 || res.statusCode >= 300) {
      throw Exception('HTTP ${res.statusCode} ${res.body}');
    }
    recordUploadBytes(bytes.length);
    String? token;
    try {
      final j = jsonDecode(res.body) as Map<String, dynamic>;
      token = j['downloadTokens'] as String?;
    } catch (_) {}
    final url = (token != null && token.isNotEmpty)
        ? '$_storageUploadUrl/$encoded?alt=media&token=$token'
        : '$_storageUploadUrl/$encoded?alt=media';
    final prev = _publishedPages[pageId] ?? const <String, String>{};
    _publishedPages[pageId] = {
      'code': code,
      'url': url,
      'title': title,
      // 権限 / パスワードは公開し直しても引き継ぐ。
      'permission': prev['permission'] ?? 'edit',
      'pwHash': prev['pwHash'] ?? '',
      'updatedAt': DateTime.now().toUtc().toIso8601String(),
    };
    await _savePublishedPages();
    // 管理用の記録 (公開者・対象ページが後から分かるように)。 失敗しても
    // 公開自体は成立しているので握り潰す。
    try {
      await http.patch(
        Uri.parse('$_firestoreBaseUrl/published/$code'
            '?updateMask.fieldPaths=ownerUid'
            '&updateMask.fieldPaths=pageId'
            '&updateMask.fieldPaths=title'
            '&updateMask.fieldPaths=url'
            '&updateMask.fieldPaths=permission'
            '&updateMask.fieldPaths=pwHash'
            '&updateMask.fieldPaths=updatedAt'),
        headers: {
          'Authorization': 'Bearer $_idToken',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({
          'fields': {
            'ownerUid': {'stringValue': _uid ?? ''},
            'pageId': {'stringValue': pageId},
            'title': {'stringValue': title},
            'url': {'stringValue': url},
            'permission': {
              'stringValue': _publishedPages[pageId]?['permission'] ?? 'edit'
            },
            'pwHash': {
              'stringValue': _publishedPages[pageId]?['pwHash'] ?? ''
            },
            'updatedAt': {
              'stringValue': DateTime.now().toUtc().toIso8601String()
            },
          },
        }),
      );
    } catch (e) {
      debugPrint('公開メタ情報の保存に失敗 (続行): $e');
    }
    notifyListeners();
    return url;
  }

  /// 共有パスワードのハッシュ (= 平文はどこにも保存しない)。
  /// コードを混ぜて、 同じパスワードでも公開ごとに違う値になるようにする。
  static String hashSharePassword(String code, String password) {
    if (password.isEmpty) return '';
    return crypto.sha256
        .convert(utf8.encode('hn1:$code:$password'))
        .toString();
  }

  /// このページの共有権限 ('edit' = 編集可 / 'view' = 閲覧のみ)。
  String publishPermissionFor(String pageId) =>
      _publishedPages[pageId]?['permission'] ?? 'edit';

  /// 共有の権限を設定する (次の公開/更新から反映)。
  /// ★ パスワードは廃止した (= ユーザー要望: 共有コードそのものが
  ///   パスワード代わりなので、 二重に持たせない)。
  void setPublishAccess(String pageId, {required String permission}) {
    ensurePublishCode(pageId);
    final rec = _publishedPages[pageId]!;
    rec['permission'] = permission == 'view' ? 'view' : 'edit';
    // 古い設定に残っているパスワードは捨てる (掛かったままにしない)。
    rec['pwHash'] = '';
    // ignore: discarded_futures
    _savePublishedPages();
    notifyListeners();
  }

  /// 参加中セッションの権限 ('edit' / 'view')。 閲覧のみの時は送信しない。
  String _livePermission = 'edit';
  String get livePermission => _livePermission;
  bool get liveCanEdit => _livePermission != 'view';

  /// 共有コードで既存のセッションに参加する (= ユーザー要望: ブラウザの
  /// HTML ではなく、 アプリ内の普段どおりの画面で共同編集したい)。
  ///
  /// サーバー上の内容からページを作り (既にあれば再利用)、 そのページで
  /// 共同編集を開始する。 パスワードが掛かっていれば照合する。
  /// 共有コードだけで参加する (= ユーザー要望: リンクを知らなくても、
  /// コードを入れるだけで入れるように)。 Max プランを持っている人同士が
  /// サーバー越しにアプリの中で一緒に編集する機能。
  Future<String> joinLiveSessionByCode(String code) async {
    final trimmed = code.trim();
    if (trimmed.isEmpty) throw Exception(t('live.joinCodeEmpty'));
    if (!isMaxUnlocked) {
      throw Exception(t('paywall.maxRequiredLive'));
    }
    if (!_firebaseEnabled) {
      await _initFirebase();
    }
    if (!_firebaseEnabled) {
      throw Exception(_firebaseInitError ?? t('sync.firebaseNotConfigured'));
    }
    await _ensureFreshToken();
    if (_idToken == null) throw Exception(t('sync.firebaseDisconnected'));

    // ── 公開設定 (権限 / パスワード) を確認 ──
    var permission = 'edit';
    var title = '';
    final metaRes = await http.get(
      Uri.parse('$_firestoreBaseUrl/published/$trimmed'),
      headers: {'Authorization': 'Bearer $_idToken'},
    );
    if (metaRes.statusCode == 200) {
      try {
        final f = (jsonDecode(metaRes.body)
                as Map<String, dynamic>)['fields'] as Map<String, dynamic>? ??
            {};
        String str(String k) =>
            ((f[k] as Map<String, dynamic>?)?['stringValue'] as String?) ?? '';
        permission = str('permission') == 'view' ? 'view' : 'edit';
        title = str('title');
        // パスワードは見ない (= ユーザー要望: 共有コードだけで入れる)。
      } on Exception {
        rethrow;
      } catch (_) {}
    } else if (metaRes.statusCode == 404) {
      throw Exception(t('live.notFound'));
    }

    // ── 本体を取得 ──
    final res = await http.get(
      Uri.parse('$_firestoreBaseUrl/published/$trimmed/doc/main'),
      headers: {'Authorization': 'Bearer $_idToken'},
    );
    if (res.statusCode == 404) throw Exception(t('live.notFound'));
    if (res.statusCode != 200) throw Exception('HTTP ${res.statusCode}');
    {
      // 期限切れのセッションには入れない (= ユーザー要望: 3 時間で終了)。
      try {
        final f0 = (jsonDecode(res.body)
                as Map<String, dynamic>)['fields'] as Map<String, dynamic>? ??
            {};
        final a =
            (f0['lastActiveAt'] as Map<String, dynamic>?)?['integerValue'];
        final last = int.tryParse('$a') ?? 0;
        if (last > 0 &&
            DateTime.now()
                    .difference(DateTime.fromMillisecondsSinceEpoch(last)) >
                kLiveIdleTimeout) {
          throw Exception(t('live.expired'));
        }
      } on Exception {
        rethrow;
      } catch (_) {}
    }
    final fields = (jsonDecode(res.body)
            as Map<String, dynamic>)['fields'] as Map<String, dynamic>? ??
        {};
    String? fstr(String k) =>
        (fields[k] as Map<String, dynamic>?)?['stringValue'] as String?;
    if (title.isEmpty) title = fstr('title') ?? t('live.sharedPage');

    // 同じコードで既に作ったページがあれば再利用する (二重に増やさない)。
    String? pageId;
    _publishedPages.forEach((pid, rec) {
      if (rec['code'] == trimmed) pageId = pid;
    });
    if (pageId != null && !_pages.any((p) => p.id == pageId)) pageId = null;

    final page = pageId != null
        ? _pages.firstWhere((p) => p.id == pageId)
        : MindMapPage(id: _uuid.v4(), name: title);
    page.nodes.clear();
    fields.forEach((k, v) {
      if (!k.startsWith('n_')) return;
      final raw = (v as Map<String, dynamic>)['stringValue'] as String?;
      if (raw == null || raw.isEmpty) return;
      try {
        final n = MindMapNode.fromJson(jsonDecode(raw) as Map<String, dynamic>);
        page.nodes[n.id] = n;
      } catch (_) {}
    });
    page.connections.clear();
    final connRaw = fstr('connections');
    if (connRaw != null && connRaw.isNotEmpty) {
      try {
        for (final e in jsonDecode(connRaw) as List<dynamic>) {
          page.connections
              .add(NodeConnection.fromJson(e as Map<String, dynamic>));
        }
      } catch (_) {}
    }
    page.decorations.clear();
    final decoRaw = fstr('decorations');
    if (decoRaw != null && decoRaw.isNotEmpty) {
      try {
        for (final e in jsonDecode(decoRaw) as List<dynamic>) {
          page.decorations
              .add(MapDecoration.fromJson(e as Map<String, dynamic>));
        }
      } catch (_) {}
    }
    if (pageId == null) {
      _pages.add(page);
      pageId = page.id;
    }
    _publishedPages[pageId!] = {
      'code': trimmed,
      'url': _publishedPages[pageId]?['url'] ?? '',
      'title': title,
      'permission': permission,
      'pwHash': _publishedPages[pageId]?['pwHash'] ?? '',
      'updatedAt': DateTime.now().toUtc().toIso8601String(),
    };
    await _savePublishedPages();
    _currentPageIndex = _pages.indexWhere((p) => p.id == pageId);
    if (_currentPageIndex < 0) _currentPageIndex = _pages.length - 1;
    _selectedNodeId = null;
    await _saveToStorageLocal();
    // 参加者は初期 push をしない (相手の内容を自分のもので上書きしないため)。
    await startLiveSession(
        pageId: pageId!, code: trimmed, permission: permission,
        pushInitial: false);
    notifyListeners();
    return pageId!;
  }

  /// 誰も居なくなって時間が経ったセッションを終了する。
  ///
  /// サーバー上の共有データ (本体・参加者・公開 HTML・メタ情報) は消すが、
  /// **手元のページはそのまま残す**。 参加していた人のアプリにも各自の
  /// コピーが残るので、 中身が失われることはない。 再開したい時は改めて
  /// 共有し直す (新しい共有コードが発行される)。
  Future<void> _expireLiveSession() async {
    final pageId = _livePageId;
    _liveLastError = t('live.expired');
    await stopLiveSession();
    if (pageId != null) {
      await unpublishPage(pageId);
    }
    notifyListeners();
  }

  /// 共同編集の共有を登録する (= ユーザー要望: 共同編集はあくまでアプリ内の
  /// 機能なので、 ブラウザで閲覧できる HTML はもう作らない)。
  ///
  /// 以前の publishPageToWeb は閲覧用の HTML を Storage へ上げてリンクを
  /// 発行していたが、 これはコードを確保して管理用の記録 (published/{code})
  /// だけを書く。 参加はアプリで共有コードを入れる形に一本化。
  Future<String> registerLivePage({
    required String pageId,
    required String title,
    String permission = 'edit',
  }) async {
    if (!isMaxUnlocked) {
      throw Exception(t('paywall.maxRequiredLive'));
    }
    if (!_firebaseEnabled) {
      await _initFirebase();
    }
    if (!_firebaseEnabled) {
      throw Exception(_firebaseInitError ?? t('sync.firebaseNotConfigured'));
    }
    await _ensureFreshToken();
    if (_idToken == null) {
      throw Exception(t('sync.firebaseDisconnected'));
    }
    final code = ensurePublishCode(pageId);
    final prev = _publishedPages[pageId] ?? const <String, String>{};
    final now = DateTime.now().toUtc().toIso8601String();
    _publishedPages[pageId] = {
      'code': code,
      'url': '', // ブラウザ向けリンクは作らない
      'title': title,
      'permission': permission,
      'pwHash': prev['pwHash'] ?? '',
      'updatedAt': now,
    };
    await _savePublishedPages();
    // 管理用の記録。 失敗しても共有自体 (セッション) は成立するので握り潰す。
    try {
      await http.patch(
        Uri.parse('$_firestoreBaseUrl/published/$code'
            '?updateMask.fieldPaths=ownerUid'
            '&updateMask.fieldPaths=pageId'
            '&updateMask.fieldPaths=title'
            '&updateMask.fieldPaths=permission'
            '&updateMask.fieldPaths=updatedAt'),
        headers: {
          'Authorization': 'Bearer $_idToken',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({
          'fields': {
            'ownerUid': {'stringValue': _uid ?? ''},
            'pageId': {'stringValue': pageId},
            'title': {'stringValue': title},
            'permission': {'stringValue': permission},
            'updatedAt': {'stringValue': now},
          },
        }),
      );
    } catch (e) {
      debugPrint('共同編集の記録に失敗: $e');
    }
    notifyListeners();
    return code;
  }

  /// 公開を停止する (共有 URL を無効化)。
  Future<void> unpublishPage(String pageId) async {
    final rec = _publishedPages[pageId];
    if (rec == null) return;
    final code = rec['code'] ?? '';
    if (_firebaseEnabled && code.isNotEmpty) {
      try {
        await _ensureFreshToken();
        final encoded = Uri.encodeComponent(_publishStoragePath(code));
        await http.delete(
          Uri.parse('$_storageUploadUrl/$encoded'),
          headers: {'Authorization': 'Bearer $_idToken'},
        );
        await http.delete(
          Uri.parse('$_firestoreBaseUrl/published/$code'),
          headers: {'Authorization': 'Bearer $_idToken'},
        );
      } catch (e) {
        debugPrint('公開停止でエラー (ローカル記録は削除): $e');
      }
    }
    _publishedPages.remove(pageId);
    await _savePublishedPages();
    notifyListeners();
  }

  // ─── リアルタイム共同編集 ─────────────────────────────────────────────
  // (= ユーザー要望: Web に公開したページを複数人で同時編集し、 編集内容が
  //  即時に反映されるように。 競合を防ぐため編集中の要素は他のユーザーから
  //  ロックされ、 誰が操作しているかも表示する)。
  //
  // 仕組み: Firestore の REST API を短い間隔でポーリングする。
  //   published/{code}/doc/main    … 本体。 ノード 1 件を 1 フィールドで持つ
  //   published/{code}/peers/{cid} … 参加者 (名前 / 色 / 編集中ノード / 生存)
  //
  // ノードをフィールド分割しているのは updateMask を使って「自分が触った
  // ノードだけ」 を書き換えるため。 ページ全体を書き戻すと、 同時に別の
  // ノードを編集していた人の変更を巻き戻してしまう。
  //
  // ロック: 各参加者は「今編集しているノード」 を peers ドキュメントに書く。
  // 他の参加者がロックしているノードは、 こちらからは編集させない
  // (UI 側で入力を止め、 push 対象からも外す)。

  /// 誰も居なくなってからセッションを畳むまでの時間 (= ユーザー要望:
  /// 編集中のユーザーが誰も居なくなって 3 時間でセッション終了)。
  static const Duration kLiveIdleTimeout = Duration(hours: 3);

  static const Duration _kLiveTick = Duration(milliseconds: 1200);
  static const Duration _kLivePresenceTick = Duration(seconds: 3);

  /// 参加者に割り当てる色 (見分けやすい 8 色)。
  static const List<int> kLivePeerColors = [
    0xFF4FC3F7,
    0xFFFFB347,
    0xFF43B97F,
    0xFFBA68C8,
    0xFFE57373,
    0xFF26C6DA,
    0xFFFFD54F,
    0xFF9575CD,
  ];

  String? _liveCode;
  String? _livePageId;
  String _liveClientId = '';
  int _liveMyColorRgb = kLivePeerColors.first;
  Timer? _liveTimer;
  Timer? _livePresenceTimer;

  /// 最後に取り込んだサーバー側の版 (= 変化検出用のタイムスタンプ)。
  int _liveRev = -1;
  bool _liveBusy = false;
  bool _livePresenceBusy = false;

  /// 直近でサーバーへ送った内容 (nodeId → JSON 文字列)。 差分検出に使う。
  final Map<String, String> _liveLastPushed = {};
  String _liveLastPushedConns = '';
  String _liveLastPushedDeco = '';
  final List<LivePeer> _livePeers = [];
  String? _liveEditingNodeId;
  String? _liveLastError;

  bool get liveActive => _liveCode != null;
  String? get liveCode => _liveCode;
  String? get livePageId => _livePageId;
  int get liveMyColorRgb => _liveMyColorRgb;
  String get liveClientId => _liveClientId;
  String? get liveLastError => _liveLastError;

  /// 今このセッションに居る他の参加者 (離席したものは除く)。
  List<LivePeer> get livePeers =>
      List.unmodifiable(_livePeers.where((p) => !p.isStale));

  /// [nodeId] を他の参加者が編集中なら、 その参加者を返す (= ロック中)。
  LivePeer? liveLockOwnerOf(String nodeId) {
    if (_liveCode == null || nodeId.isEmpty) return null;
    for (final p in _livePeers) {
      if (p.isStale) continue;
      if (p.clientId == _liveClientId) continue;
      if (p.lockNodeId == nodeId) return p;
    }
    return null;
  }

  /// [nodeId] が他の参加者にロックされていて編集できないか。
  bool isNodeLockedByOthers(String nodeId) => liveLockOwnerOf(nodeId) != null;

  /// 自分が今編集しているノードを宣言する (= 他の人からはロックされる)。
  void liveSetEditingNode(String? nodeId) {
    if (_liveCode == null) return;
    if (_liveEditingNodeId == nodeId) return;
    _liveEditingNodeId = nodeId;
    // すぐ相手に伝わるよう、 ハートビートを待たずに 1 回送る。
    // ignore: discarded_futures
    _livePushPresence();
    notifyListeners();
  }

  /// Firestore のフィールド名に使えるようノード ID を正規化する
  /// (UUID のハイフン等はフィールドパスで扱いにくいため)。
  static String _liveFieldForNode(String nodeId) =>
      'n_${nodeId.replaceAll(RegExp(r'[^A-Za-z0-9_]'), '_')}';

  /// 公開中のページでリアルタイム共同編集を開始する。
  Future<void> startLiveSession({
    required String pageId,
    required String code,
    String permission = 'edit',
    bool pushInitial = true,
  }) async {
    // ── リアルタイム共同編集は Max 限定 ──
    // 1.2 秒ごとの版チェック + 3 秒ごとの参加者取得で、 参加者 1 人あたり
    // 1 時間に約 4,200 回の読み取りになる。 Firestore の読み取りは
    // 10 万回あたり \$0.06 なので、 1 人が月 100 時間つなぐと \$0.25 前後、
    // 数人が常時つなぐと無視できない額になる。 クラウド同期と同じ扱いで
    // 上位プラン限定にする。
    if (!isMaxUnlocked) {
      throw Exception(t('paywall.maxRequiredLive'));
    }
    await stopLiveSession();
    if (!_firebaseEnabled) {
      await _initFirebase();
    }
    if (!_firebaseEnabled) {
      throw Exception(_firebaseInitError ?? t('sync.firebaseNotConfigured'));
    }
    await _ensureFreshToken();
    _liveCode = code;
    _livePageId = pageId;
    _liveClientId = _uuid.v4().replaceAll('-', '').substring(0, 12);
    _liveMyColorRgb =
        kLivePeerColors[_liveClientId.hashCode.abs() % kLivePeerColors.length];
    _liveRev = -1;
    _liveLastPushed.clear();
    _liveLastPushedConns = '';
    _liveLastPushedDeco = '';
    _livePeers.clear();
    _liveEditingNodeId = null;
    _liveLastError = null;
    _livePermission = permission == 'view' ? 'view' : 'edit';
    // 最初に今のページ内容を丸ごと送って土台を作る (相手が居なくても安全)。
    // 参加側は送らない (= 相手の内容を自分のもので上書きしない)。
    if (pushInitial && liveCanEdit) await _livePush(force: true);
    await _livePushPresence();
    _liveTimer = Timer.periodic(_kLiveTick, (_) => _liveTick());
    _livePresenceTimer =
        Timer.periodic(_kLivePresenceTick, (_) => _livePresenceTick());
    notifyListeners();
  }

  /// 共同編集を終了する (自分の参加者情報も消す)。
  Future<void> stopLiveSession() async {
    _liveTimer?.cancel();
    _liveTimer = null;
    _livePresenceTimer?.cancel();
    _livePresenceTimer = null;
    final code = _liveCode;
    final cid = _liveClientId;
    _liveCode = null;
    _livePageId = null;
    _liveEditingNodeId = null;
    _livePeers.clear();
    _liveLastPushed.clear();
    if (code != null && cid.isNotEmpty && _idToken != null) {
      try {
        await http.delete(
          Uri.parse('$_firestoreBaseUrl/published/$code/peers/$cid'),
          headers: {'Authorization': 'Bearer $_idToken'},
        );
      } catch (_) {}
    }
    notifyListeners();
  }

  Future<void> _liveTick() async {
    if (_liveBusy || _liveCode == null || _disposed) return;
    _liveBusy = true;
    try {
      await _ensureFreshToken();
      await _livePull();
      await _livePush();
    } catch (e) {
      _liveLastError = '$e';
      debugPrint('共同編集 tick でエラー: $e');
    } finally {
      _liveBusy = false;
    }
  }

  Future<void> _livePresenceTick() async {
    if (_livePresenceBusy || _liveCode == null || _disposed) return;
    _livePresenceBusy = true;
    try {
      await _livePushPresence();
      await _liveTouchActivity();
      await _livePullPeers();
    } catch (e) {
      debugPrint('共同編集 presence でエラー: $e');
    } finally {
      _livePresenceBusy = false;
    }
  }

  MindMapPage? get _livePage {
    final id = _livePageId;
    if (id == null) return null;
    final i = _pages.indexWhere((p) => p.id == id);
    return i < 0 ? null : _pages[i];
  }

  /// サーバー側の変更を取り込む。
  Future<void> _livePull() async {
    final code = _liveCode;
    final page = _livePage;
    if (code == null || page == null || _idToken == null) return;
    final base = '$_firestoreBaseUrl/published/$code/doc/main';
    // まず版だけを取りに行く (毎秒フルで取ると重いため)。
    final headRes = await http.get(
      Uri.parse('$base?mask.fieldPaths=rev&mask.fieldPaths=lastActiveAt'),
      headers: {'Authorization': 'Bearer $_idToken'},
    );
    if (headRes.statusCode == 404) return; // まだ土台が無い
    if (headRes.statusCode != 200) return;
    int remoteRev = -1;
    int lastActive = 0;
    try {
      final j = jsonDecode(headRes.body) as Map<String, dynamic>;
      final f = j['fields'] as Map<String, dynamic>?;
      final v = (f?['rev'] as Map<String, dynamic>?)?['integerValue'];
      remoteRev = int.tryParse('$v') ?? -1;
      final a = (f?['lastActiveAt'] as Map<String, dynamic>?)?['integerValue'];
      lastActive = int.tryParse('$a') ?? 0;
    } catch (_) {}
    // ── 誰も触らないまま時間が経ったセッションは畳む (= ユーザー要望) ──
    if (lastActive > 0 &&
        DateTime.now()
                .difference(DateTime.fromMillisecondsSinceEpoch(lastActive)) >
            kLiveIdleTimeout) {
      await _expireLiveSession();
      return;
    }
    if (remoteRev <= _liveRev) return; // 変化なし

    final res = await http.get(
      Uri.parse(base),
      headers: {'Authorization': 'Bearer $_idToken'},
    );
    if (res.statusCode != 200) return;
    Map<String, dynamic> fields;
    try {
      final j = jsonDecode(res.body) as Map<String, dynamic>;
      fields = (j['fields'] as Map<String, dynamic>?) ?? {};
    } catch (_) {
      return;
    }

    var changed = false;
    final seenFieldNames = <String>{};
    fields.forEach((key, value) {
      if (!key.startsWith('n_')) return;
      seenFieldNames.add(key);
      final raw = (value as Map<String, dynamic>)['stringValue'] as String?;
      if (raw == null || raw.isEmpty) return;
      Map<String, dynamic> nodeJson;
      try {
        nodeJson = jsonDecode(raw) as Map<String, dynamic>;
      } catch (_) {
        return;
      }
      final id = nodeJson['id'] as String?;
      if (id == null || id.isEmpty) return;
      // 自分がまだ送っていないローカル変更があるノードは上書きしない
      // (次の push で送られる。 = 自分の編集が消えないように)。
      final local = page.nodes[id];
      if (local != null) {
        final localJson = jsonEncode(local.toJson());
        final pushed = _liveLastPushed[id];
        if (pushed != null && pushed != localJson) return; // 未送信の編集あり
        if (localJson == raw) {
          _liveLastPushed[id] = raw;
          return; // 既に同じ
        }
      }
      try {
        page.nodes[id] = MindMapNode.fromJson(nodeJson);
        _liveLastPushed[id] = raw;
        changed = true;
      } catch (_) {}
    });

    // サーバーから消えたノードはこちらでも消す。 ただし「まだ一度も送って
    // いないノード」 (= 作ったばかり) は消さない。
    final toRemove = <String>[];
    for (final id in page.nodes.keys) {
      if (!_liveLastPushed.containsKey(id)) continue;
      if (seenFieldNames.contains(_liveFieldForNode(id))) continue;
      toRemove.add(id);
    }
    for (final id in toRemove) {
      page.nodes.remove(id);
      _liveLastPushed.remove(id);
      changed = true;
    }

    // 接続・装飾は件数が少ないのでまとめて 1 フィールドで扱う。
    final connRaw =
        (fields['connections'] as Map<String, dynamic>?)?['stringValue'];
    if (connRaw is String && connRaw != _liveLastPushedConns) {
      final localConns =
          jsonEncode(page.connections.map((c) => c.toJson()).toList());
      if (_liveLastPushedConns.isEmpty || _liveLastPushedConns == localConns) {
        try {
          final list = jsonDecode(connRaw) as List<dynamic>;
          page.connections
            ..clear()
            ..addAll(list.map(
                (e) => NodeConnection.fromJson(e as Map<String, dynamic>)));
          _liveLastPushedConns = connRaw;
          changed = true;
        } catch (_) {}
      }
    }
    final decoRaw =
        (fields['decorations'] as Map<String, dynamic>?)?['stringValue'];
    if (decoRaw is String && decoRaw != _liveLastPushedDeco) {
      final localDeco =
          jsonEncode(page.decorations.map((d) => d.toJson()).toList());
      if (_liveLastPushedDeco.isEmpty || _liveLastPushedDeco == localDeco) {
        try {
          final list = jsonDecode(decoRaw) as List<dynamic>;
          page.decorations
            ..clear()
            ..addAll(list
                .map((e) => MapDecoration.fromJson(e as Map<String, dynamic>)));
          _liveLastPushedDeco = decoRaw;
          changed = true;
        } catch (_) {}
      }
    }

    _liveRev = remoteRev;
    if (changed) {
      // ignore: discarded_futures
      _saveToStorageLocal();
      notifyListeners();
    }
  }

  /// ローカルの変更をサーバーへ送る (触ったところだけ)。
  /// ページ 1 枚分を published/{code}/doc/main へ丸ごと書き込む
  /// (= 一括共有用。 セッションを張らずに初期データだけ置くので、
  ///  参加者はどのページのコードでもすぐ入れる)。
  Future<void> seedLiveDocForPage(String pageId, String code) async {
    final i = _pages.indexWhere((p) => p.id == pageId);
    if (i < 0 || code.isEmpty) return;
    final page = _pages[i];
    await _ensureFreshToken();
    if (_idToken == null) throw Exception(t('sync.firebaseDisconnected'));

    // 以前の共有で残った古いノードフィールドが混ざらないよう、 先に消して
    // から書く (自分がこのコードでセッション中なら消さない)。
    if (_liveCode != code) {
      try {
        await http.delete(
          Uri.parse('$_firestoreBaseUrl/published/$code/doc/main'),
          headers: {'Authorization': 'Bearer $_idToken'},
        );
      } catch (_) {}
    }

    final fields = <String, dynamic>{};
    final masks = <String>[];
    for (final entry in page.nodes.entries) {
      final f = _liveFieldForNode(entry.key);
      fields[f] = {'stringValue': jsonEncode(entry.value.toJson())};
      masks.add(f);
    }
    fields['connections'] = {
      'stringValue': jsonEncode(page.connections.map((c) => c.toJson()).toList())
    };
    masks.add('connections');
    fields['decorations'] = {
      'stringValue': jsonEncode(page.decorations.map((d) => d.toJson()).toList())
    };
    masks.add('decorations');
    final rev = DateTime.now().millisecondsSinceEpoch;
    fields['rev'] = {'integerValue': '$rev'};
    masks.add('rev');
    fields['lastActiveAt'] = {'integerValue': '$rev'};
    masks.add('lastActiveAt');
    fields['title'] = {'stringValue': page.name};
    masks.add('title');

    final query = masks.map((m) => 'updateMask.fieldPaths=$m').join('&');
    final res = await http.patch(
      Uri.parse('$_firestoreBaseUrl/published/$code/doc/main?$query'),
      headers: {
        'Authorization': 'Bearer $_idToken',
        'Content-Type': 'application/json',
      },
      body: jsonEncode({'fields': fields}),
    );
    if (res.statusCode < 200 || res.statusCode >= 300) {
      throw Exception('HTTP ${res.statusCode}');
    }
    // 自分がこのページのセッション中なら、 送った内容を基準にする。
    if (_liveCode == code && _livePageId == pageId) {
      _liveRev = rev;
    }
  }

  Future<void> _livePush({bool force = false}) async {
    // 閲覧のみの権限では書き込まない (= ユーザー要望: 権限を設定できるように)。
    if (!liveCanEdit) return;
    final code = _liveCode;
    final page = _livePage;
    if (code == null || page == null || _idToken == null) return;

    final fields = <String, dynamic>{};
    final masks = <String>[];

    for (final entry in page.nodes.entries) {
      final id = entry.key;
      // 他の人が編集中のノードは送らない (= 相手の編集を壊さない)。
      if (!force && isNodeLockedByOthers(id)) continue;
      final json = jsonEncode(entry.value.toJson());
      if (!force && _liveLastPushed[id] == json) continue;
      final f = _liveFieldForNode(id);
      fields[f] = {'stringValue': json};
      masks.add(f);
      _liveLastPushed[id] = json;
    }
    // ローカルで削除されたノードはフィールドごと消す (値なし + updateMask)。
    final removed = _liveLastPushed.keys
        .where((id) => !page.nodes.containsKey(id))
        .toList();
    for (final id in removed) {
      masks.add(_liveFieldForNode(id));
      _liveLastPushed.remove(id);
    }

    final connJson =
        jsonEncode(page.connections.map((c) => c.toJson()).toList());
    if (force || connJson != _liveLastPushedConns) {
      fields['connections'] = {'stringValue': connJson};
      masks.add('connections');
      _liveLastPushedConns = connJson;
    }
    final decoJson =
        jsonEncode(page.decorations.map((d) => d.toJson()).toList());
    if (force || decoJson != _liveLastPushedDeco) {
      fields['decorations'] = {'stringValue': decoJson};
      masks.add('decorations');
      _liveLastPushedDeco = decoJson;
    }
    if (masks.isEmpty) return;

    // 版はミリ秒時刻。 これが変わったら他の参加者が取りに来る。
    final rev = DateTime.now().millisecondsSinceEpoch;
    fields['rev'] = {'integerValue': '$rev'};
    masks.add('rev');
    // 最終活動時刻。 これが古くなったらセッションを畳む (= ユーザー要望)。
    fields['lastActiveAt'] = {'integerValue': '$rev'};
    masks.add('lastActiveAt');
    fields['title'] = {'stringValue': page.name};
    masks.add('title');

    final query = masks.map((m) => 'updateMask.fieldPaths=$m').join('&');
    final res = await http.patch(
      Uri.parse('$_firestoreBaseUrl/published/$code/doc/main?$query'),
      headers: {
        'Authorization': 'Bearer $_idToken',
        'Content-Type': 'application/json',
      },
      body: jsonEncode({'fields': fields}),
    );
    if (res.statusCode >= 200 && res.statusCode < 300) {
      // 自分の書き込みで pull が走らないよう、 版を進めておく。
      _liveRev = rev;
      _liveLastError = null;
    } else {
      _liveLastError = 'HTTP ${res.statusCode}';
      debugPrint('共同編集 push 失敗: ${res.statusCode} ${res.body}');
    }
  }

  /// 自分の参加情報 (名前 / 色 / 編集中ノード / 生存時刻) を送る。
  Future<void> _livePushPresence() async {
    final code = _liveCode;
    if (code == null || _idToken == null || _liveClientId.isEmpty) return;
    final name = _displayName?.trim().isNotEmpty == true
        ? _displayName!.trim()
        : t('live.anonymous');
    try {
      await http.patch(
        Uri.parse('$_firestoreBaseUrl/published/$code/peers/$_liveClientId'
            '?updateMask.fieldPaths=name'
            '&updateMask.fieldPaths=color'
            '&updateMask.fieldPaths=lockNodeId'
            '&updateMask.fieldPaths=lastSeen'),
        headers: {
          'Authorization': 'Bearer $_idToken',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({
          'fields': {
            'name': {'stringValue': name},
            'color': {'integerValue': '$_liveMyColorRgb'},
            'lockNodeId': {'stringValue': _liveEditingNodeId ?? ''},
            'lastSeen': {
              'stringValue': DateTime.now().toUtc().toIso8601String()
            },
          },
        }),
      );
    } catch (e) {
      debugPrint('共同編集 presence 送信失敗: $e');
    }
  }

  /// セッションの最終活動時刻を更新する (参加者が居る間は生き続ける)。
  Future<void> _liveTouchActivity() async {
    final code = _liveCode;
    if (code == null || _idToken == null) return;
    try {
      await http.patch(
        Uri.parse('$_firestoreBaseUrl/published/$code/doc/main'
            '?updateMask.fieldPaths=lastActiveAt'),
        headers: {
          'Authorization': 'Bearer $_idToken',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({
          'fields': {
            'lastActiveAt': {
              'integerValue': '${DateTime.now().millisecondsSinceEpoch}'
            },
          },
        }),
      );
    } catch (_) {}
  }

  /// 参加者一覧を取り込む。
  Future<void> _livePullPeers() async {
    final code = _liveCode;
    if (code == null || _idToken == null) return;
    final res = await http.get(
      Uri.parse('$_firestoreBaseUrl/published/$code/peers?pageSize=50'),
      headers: {'Authorization': 'Bearer $_idToken'},
    );
    if (res.statusCode != 200) return;
    final next = <LivePeer>[];
    try {
      final j = jsonDecode(res.body) as Map<String, dynamic>;
      final docs = j['documents'] as List<dynamic>? ?? const [];
      for (final d in docs) {
        final m = d as Map<String, dynamic>;
        final path = (m['name'] as String?) ?? '';
        final cid = path.contains('/') ? path.split('/').last : path;
        final f = (m['fields'] as Map<String, dynamic>?) ?? {};
        String str(String k) =>
            ((f[k] as Map<String, dynamic>?)?['stringValue'] as String?) ?? '';
        final lastSeen = DateTime.tryParse(str('lastSeen'))?.toLocal();
        if (lastSeen == null) continue;
        final colorRaw =
            (f['color'] as Map<String, dynamic>?)?['integerValue'];
        final lock = str('lockNodeId');
        next.add(LivePeer(
          clientId: cid,
          name: str('name'),
          colorRgb: int.tryParse('$colorRaw') ?? kLivePeerColors.first,
          lockNodeId: lock.isEmpty ? null : lock,
          lastSeen: lastSeen,
        ));
      }
    } catch (e) {
      debugPrint('共同編集 参加者の解析に失敗: $e');
      return;
    }
    _livePeers
      ..clear()
      ..addAll(next);
    // 期限切れの参加者はサーバーからも掃除する (ロックを残さない)。
    for (final p in next) {
      if (p.isStale && p.clientId != _liveClientId) {
        try {
          // ignore: discarded_futures
          http.delete(
            Uri.parse('$_firestoreBaseUrl/published/$code/peers/${p.clientId}'),
            headers: {'Authorization': 'Bearer $_idToken'},
          );
        } catch (_) {}
      }
    }
    notifyListeners();
  }

  // ─── マップ容量計算 ───────────────────────────────────────────────────
  /// マップ（ページ）の合計データサイズをバイト単位で返す
  /// JSON + ローカル存在するファイル（添付・動画・サムネイル）の合計
  int calculatePageSizeBytes(MindMapPage page) {
    int total = 0;
    try {
      total += utf8.encode(jsonEncode(page.toJson())).length;
    } catch (_) {}
    for (final node in page.nodes.values) {
      // 添付ファイル（画像・PDF等）
      final ap = node.attachmentPath ?? '';
      if (ap.isNotEmpty && !ap.startsWith('http')) {
        try {
          final f = File(ap);
          if (f.existsSync()) total += f.lengthSync();
        } catch (_) {}
      }
      // 動画サムネイル
      final vth = node.videoThumbnailPath ?? '';
      if (vth.isNotEmpty) {
        try {
          final f = File(vth);
          if (f.existsSync()) total += f.lengthSync();
        } catch (_) {}
      }
      // ローカル動画ファイル（mp4等が youtubeUrl にローカルパスで入る場合）
      final yu = node.youtubeUrl ?? '';
      if (yu.isNotEmpty && !yu.startsWith('http') && !yu.startsWith('https')) {
        try {
          final f = File(yu);
          if (f.existsSync()) total += f.lengthSync();
        } catch (_) {}
      }
    }
    return total;
  }

  /// バイト数を読みやすい単位 (B / KB / MB / GB) に整形
  static String formatBytes(int bytes) {
    if (bytes < 1024) return '$bytes B';
    if (bytes < 1024 * 1024) {
      return '${(bytes / 1024).toStringAsFixed(1)} KB';
    }
    if (bytes < 1024 * 1024 * 1024) {
      return '${(bytes / (1024 * 1024)).toStringAsFixed(1)} MB';
    }
    return '${(bytes / (1024 * 1024 * 1024)).toStringAsFixed(2)} GB';
  }

  /// クラウドページの合計サイズ（バイト）を取得（HEADで実ファイルサイズも合算）
  /// 重い処理なのでダウンロードダイアログで一度だけ呼ぶ想定
  Future<int> fetchCloudPageSizeBytes(MindMapPage page) async {
    int total = 0;
    try {
      total += utf8.encode(jsonEncode(page.toJson())).length;
    } catch (_) {}
    if (_idToken == null) return total;
    // 重複URLを排除
    final urls = <String>{};
    for (final node in page.nodes.values) {
      final asu = node.attachmentStorageUrl ?? '';
      if (asu.isNotEmpty) urls.add(asu);
      final vsu = node.videoStorageUrl ?? '';
      if (vsu.isNotEmpty) urls.add(vsu);
    }
    for (final u in urls) {
      try {
        final res = await http.head(
          Uri.parse(u),
          headers: {'Authorization': 'Bearer $_idToken'},
        );
        final cl = res.headers['content-length'];
        if (cl != null) {
          final n = int.tryParse(cl);
          if (n != null) total += n;
        }
      } catch (_) {}
    }
    return total;
  }

  @override
  void notifyListeners() {
    // 非同期ロード・HTTP 完了が Provider 破棄後に戻ってくる場合がある。
    // ChangeNotifier の dispose 後通知を一元的に遮断する。
    if (_disposed) return;
    // 一括生成中 (フォルダー取り込み等) は通知をためて最後に 1 回だけ流す
    // (= ノード 1 個ごとに画面全体を作り直すと実質フリーズするため)。
    if (_notifyBatchDepth > 0) {
      _notifyPending = true;
      return;
    }
    super.notifyListeners();
  }

  @override
  void dispose() {
    if (_disposed) return;
    _lastPdfPagePersistTimer?.cancel();
    _lastPdfPagePersistTimer = null;
    if (_lastPdfPagesDirty) {
      unawaited(_persistLastPdfPages());
    }
    _disposed = true;
    _crossInstanceTimer?.cancel();
    _crossInstanceTimer = null;
    _syncTimer?.cancel();
    _autoSyncDebounce?.cancel();
    _startupSafetyTimer?.cancel();
    _developerModeRestoreTimer?.cancel();
    _developerModeRestoreTimer = null;
    _billing.dispose();
    if (!_initialLoadCompleter.isCompleted) {
      _initialLoadCompleter.complete();
    }
    super.dispose();
  }

  /// ★ 起動ハング対策 (= ユーザー報告: Android で「ずっと読み込み中」のまま) ★
  /// 画面は `pages.isEmpty` の間ずっとローディング (くるくる) を出すので、
  /// この関数が「何があっても」必ず最後に pages を 1 枚以上にして
  /// notifyListeners() を呼ぶことが死活的に重要。 そのため:
  ///   1. 全体を try/catch で囲み、 例外が外へ漏れて Future が reject されない
  ///      (= reject すると constructor 側で notify されず永久ローディング) ようにする。
  ///   2. ページは 1 枚ずつ独立にパースし、 1 枚壊れても残りは読む
  ///      (= 旧実装は途中で throw すると全ページ破棄 → データ全消失だった)。
  ///   3. クラウド/ディスク保存 (_saveToStorage) は notifyListeners の「後」に
  ///      await せず行う (= ネットワーク待ちで UI が出ないのを防ぐ)。
  int _pageTimestampFromJson(String? raw) {
    if (raw == null || raw.isEmpty) return 0;
    try {
      final decoded = jsonDecode(raw);
      if (decoded is! Map) return 0;
      return (decoded['lastModifiedAt'] as num?)?.toInt() ?? 0;
    } catch (_) {
      return 0;
    }
  }

  Map<String, int> _intMapFromJson(dynamic value) {
    if (value is! Map) return <String, int>{};
    final result = <String, int>{};
    value.forEach((dynamic key, dynamic rawValue) {
      final parsed = rawValue is num
          ? rawValue.toInt()
          : int.tryParse(rawValue?.toString() ?? '');
      if (parsed != null && parsed >= 0) result[key.toString()] = parsed;
    });
    return result;
  }

  Map<String, List<int>> _intListMapFromJson(dynamic value) {
    if (value is! Map) return <String, List<int>>{};
    final result = <String, List<int>>{};
    value.forEach((dynamic key, dynamic rawValue) {
      if (rawValue is! List) return;
      final values = rawValue
          .map((dynamic item) =>
              item is num ? item.toInt() : int.tryParse(item?.toString() ?? ''))
          .whereType<int>()
          .where((item) => item > 0)
          .toSet()
          .toList();
      if (values.length > 64) {
        result[key.toString()] = values.sublist(values.length - 64);
      } else {
        result[key.toString()] = values;
      }
    });
    return result;
  }

  _PageStorageSnapshot? _decodeCoordinatedPageStorage(String? raw) {
    if (raw == null || raw.isEmpty) return null;
    try {
      final decoded = jsonDecode(raw);
      if (decoded is! Map || decoded['pages'] is! List) return null;
      final pagesJson = <String, String>{};
      final physicalOrder = <String>[];
      for (final item in decoded['pages'] as List<dynamic>) {
        if (item is! Map) continue;
        final id = item['id']?.toString();
        if (id == null || id.isEmpty) continue;
        pagesJson[id] = jsonEncode(item);
        physicalOrder.add(id);
      }
      final storedOrder = (decoded['order'] as List<dynamic>?)
              ?.map((dynamic id) => id.toString())
              .where(pagesJson.containsKey)
              .toList() ??
          physicalOrder;
      for (final id in physicalOrder) {
        if (!storedOrder.contains(id)) storedOrder.add(id);
      }
      final pageWriteTimes = _intMapFromJson(decoded['pageWriteTimes']);
      for (final entry in pagesJson.entries) {
        pageWriteTimes.putIfAbsent(
          entry.key,
          () => _pageTimestampFromJson(entry.value),
        );
      }
      return _PageStorageSnapshot(
        revision: (decoded['revision'] as num?)?.toInt() ?? 0,
        commitId: decoded['commitId']?.toString() ?? '',
        writtenAtMs: (decoded['writtenAtMs'] as num?)?.toInt() ?? 0,
        pagesJson: pagesJson,
        order: storedOrder,
        pageWriteTimes: pageWriteTimes,
        pageAncestors: _intListMapFromJson(decoded['pageAncestors']),
        tombstones: _intMapFromJson(decoded['deletedPages']),
        orderWriteTimeMs: (decoded['orderWriteTimeMs'] as num?)?.toInt() ?? 0,
      );
    } catch (_) {
      return null;
    }
  }

  _PageStorageSnapshot? _decodeLegacyPageStorage(String? raw) {
    if (raw == null || raw.isEmpty) return null;
    try {
      final decoded = jsonDecode(raw);
      if (decoded is! List) return null;
      final pagesJson = <String, String>{};
      final order = <String>[];
      final writeTimes = <String, int>{};
      var writtenAt = 0;
      for (final item in decoded) {
        if (item is! Map) continue;
        final id = item['id']?.toString();
        if (id == null || id.isEmpty) continue;
        final pageJson = jsonEncode(item);
        pagesJson[id] = pageJson;
        order.add(id);
        final pageTime = _pageTimestampFromJson(pageJson);
        writeTimes[id] = pageTime;
        writtenAt = math.max(writtenAt, pageTime);
      }
      if (pagesJson.isEmpty) return null;
      return _PageStorageSnapshot(
        revision: 0,
        commitId: 'legacy',
        writtenAtMs: writtenAt,
        pagesJson: pagesJson,
        order: order,
        pageWriteTimes: writeTimes,
        pageAncestors: const <String, List<int>>{},
        tombstones: const <String, int>{},
        orderWriteTimeMs: writtenAt,
      );
    } catch (_) {
      return null;
    }
  }

  _PageStorageSnapshot _emptyPageStorageSnapshot() =>
      const _PageStorageSnapshot(
        revision: 0,
        commitId: '',
        writtenAtMs: 0,
        pagesJson: <String, String>{},
        order: <String>[],
        pageWriteTimes: <String, int>{},
        pageAncestors: <String, List<int>>{},
        tombstones: <String, int>{},
        orderWriteTimeMs: 0,
      );

  void _adoptInitialPageStorageBaseline(_PageStorageSnapshot snapshot) {
    _pageStorageBaselineLoaded = true;
    _pageStorageRevision = snapshot.revision;
    _pageStorageBaseJson
      ..clear()
      ..addAll(snapshot.pagesJson);
    _pageStorageBaseWriteTimes
      ..clear()
      ..addAll(snapshot.pageWriteTimes);
    _pageStorageBaseAncestors
      ..clear()
      ..addAll(snapshot.pageAncestors.map(
        (id, values) => MapEntry(id, List<int>.from(values)),
      ));
    _pageStorageBaseOrder
      ..clear()
      ..addAll(snapshot.order);
    _pageStorageBaseOrderWriteTimeMs = snapshot.orderWriteTimeMs;
    _pageDeletionTombstones
      ..clear()
      ..addAll(snapshot.tombstones);
  }

  _PageStorageCapture _capturePageStorage({
    required bool touchChangedPages,
  }) {
    final now = DateTime.now().toUtc().millisecondsSinceEpoch;
    final basePagesJson =
        Map<String, String>.unmodifiable(_pageStorageBaseJson);
    final basePageWriteTimes =
        Map<String, int>.unmodifiable(_pageStorageBaseWriteTimes);
    final basePageAncestors =
        Map<String, List<int>>.unmodifiable(_pageStorageBaseAncestors.map(
      (id, values) => MapEntry(id, List<int>.unmodifiable(values)),
    ));
    final baseOrder = List<String>.unmodifiable(_pageStorageBaseOrder);
    final baseOrderWriteTimeMs = _pageStorageBaseOrderWriteTimeMs;
    final pagesJson = <String, String>{};
    final pageWriteTimes = <String, int>{};
    final pageAncestors = <String, List<int>>{};
    final order = <String>[];
    for (final page in _pages) {
      var raw = jsonEncode(page.toJson());
      final changed = raw != basePagesJson[page.id];
      if (changed && touchChangedPages) {
        // 地方時で持つ。 isUtc: true にすると保存される数値は同じでも
        //   `.hour` が UTC の時刻を返し、 一覧の 「今日 HH:mm」 が
        //   時差の分だけずれて出ていた (日本なら 9 時間前)。 起動し直すと
        //   読み込み側が地方時で作り直すので直る、 という分かりにくい不具合。
        page.lastModifiedAt = DateTime.fromMillisecondsSinceEpoch(now);
        raw = jsonEncode(page.toJson());
      }
      pagesJson[page.id] = raw;
      order.add(page.id);
      pageWriteTimes[page.id] = changed
          ? now
          : (basePageWriteTimes[page.id] ?? _pageTimestampFromJson(raw));
      final ancestors = List<int>.from(basePageAncestors[page.id] ?? const []);
      if (changed) {
        final baseVersion = basePageWriteTimes[page.id] ?? 0;
        if (baseVersion > 0 && !ancestors.contains(baseVersion)) {
          ancestors.add(baseVersion);
        }
      }
      pageAncestors[page.id] = ancestors.length > 64
          ? ancestors.sublist(ancestors.length - 64)
          : ancestors;
    }

    final tombstones = Map<String, int>.from(_pageDeletionTombstones);
    // 削除経路を将来追加した際にマーカーの付け忘れがあっても、ロード時に
    // 存在していたページが消えていれば削除として扱う。
    for (final id in basePagesJson.keys) {
      if (!pagesJson.containsKey(id)) {
        tombstones[id] = math.max(tombstones[id] ?? 0, now);
        final ancestors = List<int>.from(basePageAncestors[id] ?? const []);
        final baseVersion = basePageWriteTimes[id] ?? 0;
        if (baseVersion > 0 && !ancestors.contains(baseVersion)) {
          ancestors.add(baseVersion);
        }
        pageAncestors[id] = ancestors.length > 64
            ? ancestors.sublist(ancestors.length - 64)
            : ancestors;
      }
    }
    _pageDeletionTombstones.addAll(tombstones);

    final orderChanged = !listEquals(order, baseOrder);
    return _PageStorageCapture(
      capturedAtMs: now,
      basePagesJson: basePagesJson,
      basePageWriteTimes: basePageWriteTimes,
      basePageAncestors: basePageAncestors,
      baseOrder: baseOrder,
      baseOrderWriteTimeMs: baseOrderWriteTimeMs,
      pagesJson: pagesJson,
      order: order,
      pageWriteTimes: pageWriteTimes,
      pageAncestors: pageAncestors,
      tombstones: tombstones,
      orderWriteTimeMs: orderChanged ? now : baseOrderWriteTimeMs,
    );
  }

  bool _pageStorageCaptureUsesCurrentBaseline(
    _PageStorageCapture capture,
  ) {
    if (!mapEquals(capture.basePagesJson, _pageStorageBaseJson) ||
        !mapEquals(
          capture.basePageWriteTimes,
          _pageStorageBaseWriteTimes,
        ) ||
        !listEquals(capture.baseOrder, _pageStorageBaseOrder) ||
        capture.baseOrderWriteTimeMs != _pageStorageBaseOrderWriteTimeMs) {
      return false;
    }
    if (capture.basePageAncestors.length != _pageStorageBaseAncestors.length) {
      return false;
    }
    for (final entry in capture.basePageAncestors.entries) {
      if (!listEquals(
        entry.value,
        _pageStorageBaseAncestors[entry.key],
      )) {
        return false;
      }
    }
    return true;
  }

  void _mergeMaxTimestamps(
    Map<String, int> target,
    Map<String, int> source,
  ) {
    for (final entry in source.entries) {
      target[entry.key] = math.max(target[entry.key] ?? 0, entry.value);
    }
  }

  bool _samePageContent(String? left, String? right) {
    if (left == right) return true;
    if (left == null || right == null) return false;
    try {
      final leftJson = Map<String, dynamic>.from(jsonDecode(left) as Map)
        ..remove('lastModifiedAt');
      final rightJson = Map<String, dynamic>.from(jsonDecode(right) as Map)
        ..remove('lastModifiedAt');
      return jsonEncode(leftJson) == jsonEncode(rightJson);
    } catch (_) {
      return false;
    }
  }

  String _stableStorageHash(String value) {
    var hash = 0x811c9dc5;
    for (final unit in value.codeUnits) {
      hash = ((hash ^ unit) * 0x01000193) & 0xffffffff;
    }
    return hash.toRadixString(16).padLeft(8, '0');
  }

  bool _isPageConflictCopyId(String pageId) => pageId.contains('_conflict_');

  dynamic _canonicalStorageJson(dynamic value) {
    if (value is Map) {
      final keys = value.keys.map((key) => key.toString()).toList()..sort();
      return <String, dynamic>{
        for (final key in keys) key: _canonicalStorageJson(value[key]),
      };
    }
    if (value is List) {
      return value.map(_canonicalStorageJson).toList(growable: false);
    }
    return value;
  }

  /// 更新時刻・競合コピー用の ID/表示接尾辞を除いたページ内容の指紋。
  ///
  /// 従来は version と更新時刻込みの raw JSON から競合コピー ID を作っていた
  /// ため、同じ内容でも保存のたびに別 ID となり、競合コピーが増殖し得た。
  String? _pageConflictContentFingerprint(String raw) {
    try {
      final pageJson = Map<String, dynamic>.from(jsonDecode(raw) as Map)
        ..remove('id')
        ..remove('lastModifiedAt');
      var name = pageJson['name']?.toString() ?? '';
      const suffixes = <String>['（競合コピー）', ' (conflict copy)'];
      var stripped = true;
      while (stripped) {
        stripped = false;
        for (final suffix in suffixes) {
          if (name.endsWith(suffix)) {
            name = name.substring(0, name.length - suffix.length);
            stripped = true;
          }
        }
      }
      pageJson['name'] = name;
      final canonical = jsonEncode(_canonicalStorageJson(pageJson));
      return '${_stableStorageHash(canonical)}_${canonical.length}';
    } catch (_) {
      return null;
    }
  }

  bool _containsEquivalentPageConflictCopy(
    String originalId,
    String raw,
    Iterable<Map<String, String>> sources,
  ) {
    final fingerprint = _pageConflictContentFingerprint(raw);
    if (fingerprint == null) return false;
    final prefix = '${originalId}_conflict_';
    for (final source in sources) {
      for (final entry in source.entries) {
        if (!entry.key.startsWith(prefix)) continue;
        if (_pageConflictContentFingerprint(entry.value) == fingerprint) {
          return true;
        }
      }
    }
    return false;
  }

  ({String id, String json})? _makePageConflictCopy(
    String originalId,
    String raw,
    int version,
  ) {
    // 競合コピー同士をさらに競合コピー化すると
    // foo_conflict_..._conflict_... の連鎖が収束しないため生成しない。
    if (_isPageConflictCopyId(originalId)) return null;
    try {
      final pageJson = Map<String, dynamic>.from(jsonDecode(raw) as Map);
      final originalName = pageJson['name']?.toString() ?? '';
      final suffix = _appLanguage == 'ja' ? '（競合コピー）' : ' (conflict copy)';
      final fingerprint = _pageConflictContentFingerprint(raw);
      if (fingerprint == null) return null;
      // 論理内容だけから決まる ID にする。同じ競合を再検出しても putIfAbsent
      // で同じ一件へ収束し、更新時刻の違いだけで項目が増えない。
      final conflictId = '${originalId}_conflict_$fingerprint';
      pageJson
        ..['id'] = conflictId
        ..['name'] = originalName.endsWith(suffix)
            ? originalName
            : '$originalName$suffix'
        ..['lastModifiedAt'] = math.max(version, 1);
      return (id: conflictId, json: jsonEncode(pageJson));
    } catch (_) {
      return null;
    }
  }

  _PageStorageSnapshot _mergePageStorage(
    _PageStorageCapture local,
    _PageStorageSnapshot remote,
  ) {
    final mergedPages = <String, String>{};
    final mergedWriteTimes = <String, int>{};
    final mergedAncestors = <String, List<int>>{};
    final mergedTombstones = <String, int>{};
    final conflictOrder = <String>[];
    _mergeMaxTimestamps(mergedTombstones, remote.tombstones);
    _mergeMaxTimestamps(mergedTombstones, local.tombstones);

    final ids = <String>{
      ...local.basePagesJson.keys,
      ...local.pagesJson.keys,
      ...remote.pagesJson.keys,
      ...mergedTombstones.keys,
    };
    for (final id in ids) {
      final baseJson = local.basePagesJson[id];
      final localJson = local.pagesJson[id];
      final remoteJson = remote.pagesJson[id];
      final localChanged = localJson != baseJson;
      final remoteChanged = remoteJson != baseJson;
      final localVersion = localJson == null
          ? (local.tombstones[id] ?? local.capturedAtMs)
          : (local.pageWriteTimes[id] ?? _pageTimestampFromJson(localJson));
      final remoteVersion = remoteJson == null
          ? (remote.tombstones[id] ?? remote.writtenAtMs)
          : (remote.pageWriteTimes[id] ?? _pageTimestampFromJson(remoteJson));
      final localAncestors =
          List<int>.from(local.pageAncestors[id] ?? const []);
      final remoteAncestors =
          List<int>.from(remote.pageAncestors[id] ?? const []);

      String? selectedJson;
      int selectedVersion;
      List<int> selectedAncestors;
      String? losingJson;
      int losingVersion = 0;
      List<int> losingAncestors = const [];
      if (localJson == remoteJson) {
        selectedJson = localJson;
        selectedVersion = math.max(localVersion, remoteVersion);
        selectedAncestors = <int>{
          ...localAncestors,
          ...remoteAncestors,
        }.toList();
      } else if (!localChanged) {
        selectedJson = remoteJson;
        selectedVersion = remoteVersion;
        selectedAncestors = remoteAncestors;
        final baseVersion = local.basePageWriteTimes[id] ?? 0;
        final remoteDescendsFromBase = baseVersion <= 0 ||
            remoteVersion == baseVersion ||
            remoteAncestors.contains(baseVersion);
        if (!remoteDescendsFromBase &&
            localJson != null &&
            !_samePageContent(localJson, remoteJson)) {
          losingJson = localJson;
          losingVersion = localVersion;
          losingAncestors = localAncestors;
        }
      } else if (!remoteChanged) {
        selectedJson = localJson;
        selectedVersion = localVersion;
        selectedAncestors = localAncestors;
      } else if (localVersion > remoteVersion) {
        selectedJson = localJson;
        selectedVersion = localVersion;
        selectedAncestors = localAncestors;
        losingJson = remoteJson;
        losingVersion = remoteVersion;
        losingAncestors = remoteAncestors;
      } else {
        // 同一ミリ秒の場合も全タブが同じ選択をするよう remote を優先し、
        // 競合再試行が互いに上書きし続ける状態を避ける。
        selectedJson = remoteJson;
        selectedVersion = remoteVersion;
        selectedAncestors = remoteAncestors;
        losingJson = localJson;
        losingVersion = localVersion;
        losingAncestors = localAncestors;
      }

      final losingAlreadyAncestor =
          losingVersion > 0 && selectedAncestors.contains(losingVersion);
      if (losingVersion > 0 && !selectedAncestors.contains(losingVersion)) {
        selectedAncestors.add(losingVersion);
      }
      for (final ancestor in losingAncestors) {
        if (!selectedAncestors.contains(ancestor)) {
          selectedAncestors.add(ancestor);
        }
      }
      if (selectedAncestors.length > 64) {
        selectedAncestors =
            selectedAncestors.sublist(selectedAncestors.length - 64);
      }
      if (selectedJson != null || selectedAncestors.isNotEmpty) {
        mergedAncestors[id] = selectedAncestors;
      }

      final deletedAt = mergedTombstones[id] ?? 0;
      // ミリ秒精度で編集と削除が同時刻になった場合は、復元不能なデータ損失を
      // 避けるためページ側を優先する。明確に新しい削除だけがページを抑止する。
      if (selectedJson != null && selectedVersion >= deletedAt) {
        mergedPages[id] = selectedJson;
        mergedWriteTimes[id] = selectedVersion;
      }
      if (!losingAlreadyAncestor &&
          losingJson != null &&
          !_samePageContent(losingJson, selectedJson) &&
          !_isPageConflictCopyId(id) &&
          !_containsEquivalentPageConflictCopy(
            id,
            losingJson,
            <Map<String, String>>[
              local.pagesJson,
              remote.pagesJson,
              mergedPages,
            ],
          )) {
        final conflict = _makePageConflictCopy(id, losingJson, losingVersion);
        // ユーザーが削除した競合コピーは、同じ競合を持つ古いタブが再送しても
        // 復活させない。内容指紋ベースの ID と tombstone の組み合わせで収束する。
        if (conflict != null && !mergedTombstones.containsKey(conflict.id)) {
          mergedPages.putIfAbsent(conflict.id, () => conflict.json);
          mergedWriteTimes.putIfAbsent(
            conflict.id,
            () => math.max(losingVersion, 1),
          );
          mergedAncestors.putIfAbsent(
            conflict.id,
            () => List<int>.from(losingAncestors),
          );
          if (!conflictOrder.contains(conflict.id)) {
            conflictOrder.add(conflict.id);
          }
        }
      }
    }

    final localOrderChanged = !listEquals(local.order, local.baseOrder);
    final remoteOrderChanged = !listEquals(remote.order, local.baseOrder);
    final List<String> preferredOrder;
    final int mergedOrderWriteTime;
    if (!localOrderChanged) {
      preferredOrder = remote.order;
      mergedOrderWriteTime = remote.orderWriteTimeMs;
    } else if (!remoteOrderChanged ||
        local.orderWriteTimeMs > remote.orderWriteTimeMs) {
      preferredOrder = local.order;
      mergedOrderWriteTime = local.orderWriteTimeMs;
    } else {
      preferredOrder = remote.order;
      mergedOrderWriteTime = remote.orderWriteTimeMs;
    }
    final mergedOrder = <String>[];
    void appendOrder(Iterable<String> source) {
      for (final id in source) {
        if (mergedPages.containsKey(id) && !mergedOrder.contains(id)) {
          mergedOrder.add(id);
        }
      }
    }

    appendOrder(preferredOrder);
    appendOrder(local.order);
    appendOrder(remote.order);
    appendOrder(conflictOrder);
    final remaining = mergedPages.keys
        .where((id) => !mergedOrder.contains(id))
        .toList()
      ..sort();
    mergedOrder.addAll(remaining);

    return _PageStorageSnapshot(
      revision: math.max(_pageStorageRevision, remote.revision),
      commitId: '',
      writtenAtMs: math.max(local.capturedAtMs, remote.writtenAtMs),
      pagesJson: mergedPages,
      order: mergedOrder,
      pageWriteTimes: mergedWriteTimes,
      pageAncestors: mergedAncestors,
      tombstones: mergedTombstones,
      orderWriteTimeMs: mergedOrderWriteTime,
    );
  }

  String _encodeCoordinatedPageStorage(_PageStorageSnapshot snapshot) {
    final orderedPages = <dynamic>[];
    for (final id in snapshot.order) {
      final raw = snapshot.pagesJson[id];
      if (raw == null) continue;
      try {
        orderedPages.add(jsonDecode(raw));
      } catch (_) {}
    }
    return jsonEncode({
      'schema': 4,
      'revision': snapshot.revision,
      'commitId': snapshot.commitId,
      'writtenAtMs': snapshot.writtenAtMs,
      'orderWriteTimeMs': snapshot.orderWriteTimeMs,
      'order': snapshot.order,
      'pageWriteTimes': snapshot.pageWriteTimes,
      'pageAncestors': snapshot.pageAncestors,
      'deletedPages': snapshot.tombstones,
      'pages': orderedPages,
    });
  }

  String _encodeLegacyPageList(_PageStorageSnapshot snapshot) {
    final pages = <dynamic>[];
    for (final id in snapshot.order) {
      final raw = snapshot.pagesJson[id];
      if (raw == null) continue;
      try {
        pages.add(jsonDecode(raw));
      } catch (_) {}
    }
    return jsonEncode(pages);
  }

  void _acceptCommittedPageStorage(
    _PageStorageCapture capture,
    _PageStorageSnapshot committed,
  ) {
    _pageStorageBaselineLoaded = true;
    _pageStorageRevision = math.max(
      _pageStorageRevision,
      committed.revision,
    );
    var currentJson = <String, String>{
      for (final page in _pages) page.id: jsonEncode(page.toJson()),
    };
    final currentPageId = _pages.isNotEmpty &&
            _currentPageIndex >= 0 &&
            _currentPageIndex < _pages.length
        ? _pages[_currentPageIndex].id
        : null;
    var memoryChanged = false;

    // ローカルが基準から変わっておらず、かつ保存待ちの間にも変化していない
    // ページだけ、別タブで確定した内容をメモリにも反映する。これにより古い
    // 表示を後から編集して、同一ページの新しい変更を上書きするのを防ぐ。
    final candidateIds = <String>{
      ...capture.basePagesJson.keys,
      ...capture.pagesJson.keys,
      ...committed.pagesJson.keys,
    };
    final remotelyWonConflictIds = candidateIds.where((id) {
      final captured = capture.pagesJson[id];
      return captured != capture.basePagesJson[id] &&
          currentJson[id] == captured &&
          committed.pagesJson[id] != captured;
    }).toList();
    final externallyChangedIds = candidateIds.where((id) {
      final captured = capture.pagesJson[id];
      return (captured == capture.basePagesJson[id] ||
              remotelyWonConflictIds.contains(id)) &&
          currentJson[id] == captured &&
          committed.pagesJson[id] != captured;
    }).toList();

    // 追加・更新を先に適用し、その後に削除する。別タブが「旧ページを削除し
    // 新ページを追加」した commit でも、常に最低一ページを維持できる。
    for (final id in externallyChangedIds) {
      final raw = committed.pagesJson[id];
      if (raw == null) continue;
      try {
        final page = MindMapPage.fromJson(
          jsonDecode(raw) as Map<String, dynamic>,
        );
        final index = _pages.indexWhere((candidate) => candidate.id == id);
        if (index >= 0) {
          _pages[index] = page;
        } else {
          _pages.add(page);
        }
        _undoStacks.remove(id);
        _redoStacks.remove(id);
        memoryChanged = true;
      } catch (_) {}
    }
    for (final id in externallyChangedIds) {
      if (committed.pagesJson.containsKey(id) || _pages.length <= 1) {
        continue;
      }
      final index = _pages.indexWhere((candidate) => candidate.id == id);
      if (index >= 0) {
        _pages.removeAt(index);
        _undoStacks.remove(id);
        _redoStacks.remove(id);
        memoryChanged = true;
      }
    }

    final orderUnchangedSinceCapture = listEquals(
      currentJson.keys.toList(),
      capture.order,
    );
    if (orderUnchangedSinceCapture) {
      final byId = <String, MindMapPage>{
        for (final page in _pages) page.id: page,
      };
      final reordered = <MindMapPage>[];
      for (final id in committed.order) {
        final page = byId.remove(id);
        if (page != null) reordered.add(page);
      }
      reordered.addAll(byId.values);
      if (!listEquals(
        reordered.map((page) => page.id).toList(),
        _pages.map((page) => page.id).toList(),
      )) {
        _pages
          ..clear()
          ..addAll(reordered);
        memoryChanged = true;
      }
    }

    if (currentPageId != null) {
      final newIndex = _pages.indexWhere((page) => page.id == currentPageId);
      _currentPageIndex = newIndex >= 0
          ? newIndex
          : _currentPageIndex.clamp(0, _pages.length - 1);
    } else {
      _currentPageIndex = _currentPageIndex.clamp(0, _pages.length - 1);
    }
    if (_selectedNodeId != null &&
        !_pages[_currentPageIndex].nodes.containsKey(_selectedNodeId)) {
      _selectedNodeId = null;
    }

    currentJson = <String, String>{
      for (final page in _pages) page.id: jsonEncode(page.toJson()),
    };

    // 確定内容が capture と同じなら、メモリがその先へ進んでいても同一ローカル
    // 系列の祖先として基準を進める。これを行わないと B1 の保存待ちに B2 が
    // queue された時、B1 確定後も基準が A のままとなり、B2 対 B1 を同時編集と
    // 誤判定して競合コピーを作り続ける。
    //
    // remote が勝って committed != capture かつ current も別内容の場合は、
    // ローカル系列の祖先ではないため基準を進めない。
    for (final entry in committed.pagesJson.entries) {
      final committedCapturedLocal =
          capture.pagesJson[entry.key] == entry.value;
      if (currentJson[entry.key] == entry.value || committedCapturedLocal) {
        _pageStorageBaseJson[entry.key] = entry.value;
        _pageStorageBaseWriteTimes[entry.key] =
            committed.pageWriteTimes[entry.key] ?? capture.capturedAtMs;
        _pageStorageBaseAncestors[entry.key] = List<int>.from(
          committed.pageAncestors[entry.key] ?? const [],
        );
      }
    }
    final removedBaseIds = _pageStorageBaseJson.keys
        .where((id) =>
            !currentJson.containsKey(id) &&
            !committed.pagesJson.containsKey(id))
        .toList();
    for (final id in removedBaseIds) {
      _pageStorageBaseJson.remove(id);
      _pageStorageBaseWriteTimes.remove(id);
      _pageStorageBaseAncestors.remove(id);
    }
    _mergeMaxTimestamps(
      _pageDeletionTombstones,
      committed.tombstones,
    );

    final currentOrder = _pages.map((page) => page.id).toList();
    if (listEquals(currentOrder, committed.order)) {
      _pageStorageBaseOrder
        ..clear()
        ..addAll(committed.order);
      _pageStorageBaseOrderWriteTimeMs = committed.orderWriteTimeMs;
    }
    if (memoryChanged) notifyListeners();
  }

  // ── 複数インスタンス間の同期 (= ユーザー要望: 複数アプリを立ち上げた時に
  //    編集内容が同期されるように) ──
  //
  //   保存の仕組み自体は既に三方向マージ対応で、 書き込み時に相手の内容を
  //   取り込む。 足りなかったのは「相手が書いたことに気付く手段」 で、
  //   これまではアプリを前面に戻した時しか調停していなかった。
  //
  //   そこで、 書き込みのたびに小さな目印ファイル (数十バイト) へ
  //   「誰が・どの版を」 書いたかを残し、 それを数秒ごとに読む。
  //   中身が変わっていて、 かつ自分の書き込みでなければ調停を回す。
  //   ページ本体を読み直さないので、 監視のコストはほぼゼロ。
  static const Duration _kCrossInstancePoll = Duration(seconds: 2);
  Timer? _crossInstanceTimer;
  String _lastSeenStorageBeacon = '';

  Future<File> _pageStorageBeaconFile() async {
    final dir = await getApplicationSupportDirectory();
    if (!await dir.exists()) await dir.create(recursive: true);
    return File(
      '${dir.path}${Platform.pathSeparator}mindmap_pages_v4.beacon',
    );
  }

  /// 書き込みが成立した直後に、 自分の版を目印として残す。
  /// ページのバックアップを置くフォルダ。
  Future<Directory> pageBackupDir() async {
    final dir = await getApplicationSupportDirectory();
    final d = Directory(
        '${dir.path}${Platform.pathSeparator}page_backups');
    if (!await d.exists()) await d.create(recursive: true);
    return d;
  }

  /// 保存でページ数が減る時だけ、 直前の状態を控える (最大 30 世代)。
  ///
  /// 1 ページ消しただけでも残すので、 誤って消した直後でも戻せる。
  /// 内容が同じ連続バックアップは作らない。
  Future<void> _backupPagesIfShrinking(
    SharedPreferences prefs,
    _PageStorageSnapshot next,
  ) async {
    if (kIsWeb) return;
    try {
      final beforeRaw = prefs.getString(_coordinatedStorageKey);
      if (beforeRaw == null || beforeRaw.isEmpty) return;
      final before = _decodeCoordinatedPageStorage(beforeRaw);
      if (before == null) return;
      // 減っていない (= 追加・編集だけ) なら何もしない。
      if (next.order.length >= before.order.length) return;
      final dir = await pageBackupDir();
      final stamp = DateTime.now()
          .toIso8601String()
          .replaceAll(':', '-')
          .replaceAll('.', '-');
      final f = File('${dir.path}${Platform.pathSeparator}'
          'pages_${before.order.length}p_$stamp.json');
      await f.writeAsString(beforeRaw, flush: true);
      // 古い世代を捨てる (新しい 30 個だけ残す)。
      final files = (await dir.list().toList())
          .whereType<File>()
          .where((e) => e.path.endsWith('.json'))
          .toList()
        ..sort((a, b) => b.path.compareTo(a.path));
      for (final old in files.skip(30)) {
        try {
          await old.delete();
        } catch (_) {}
      }
      debugPrint('page backup saved: ${f.path}');
    } catch (e) {
      debugPrint('page backup failed: $e');
    }
  }

  /// バックアップ一覧 (新しい順)。 画面から選んで戻すのに使う。
  Future<List<Map<String, dynamic>>> listPageBackups() async {
    try {
      final dir = await pageBackupDir();
      final files = (await dir.list().toList())
          .whereType<File>()
          .where((e) => e.path.endsWith('.json'))
          .toList()
        ..sort((a, b) => b.path.compareTo(a.path));
      final out = <Map<String, dynamic>>[];
      for (final f in files) {
        try {
          final snap = _decodeCoordinatedPageStorage(await f.readAsString());
          if (snap == null) continue;
          out.add({
            'path': f.path,
            'pages': snap.order.length,
            'at': (await f.stat()).modified,
            'names': [
              for (final id in snap.order.take(6))
                (() {
                  try {
                    final m =
                        jsonDecode(snap.pagesJson[id] ?? '{}')
                            as Map<String, dynamic>;
                    return '${m['name'] ?? ''}';
                  } catch (_) {
                    return '';
                  }
                })()
            ],
          });
        } catch (_) {}
      }
      return out;
    } catch (_) {
      return const [];
    }
  }

  /// バックアップから復元する。 今あるページは消さず、 足りないページだけ戻す
  /// (= 戻したせいで最近の作業が消えることが無いように)。
  Future<int> restorePagesFromBackup(String path) async {
    try {
      final snap = _decodeCoordinatedPageStorage(
          await File(path).readAsString());
      if (snap == null) return 0;
      final existing = _pages.map((p) => p.id).toSet();
      var restored = 0;
      for (final id in snap.order) {
        if (existing.contains(id)) continue;
        final raw = snap.pagesJson[id];
        if (raw == null) continue;
        try {
          final page =
              MindMapPage.fromJson(jsonDecode(raw) as Map<String, dynamic>);
          _pages.add(page);
          // 削除記録が残っていると再び消えるので必ず外す。
          _pageDeletionTombstones.remove(id);
          restored++;
        } catch (_) {}
      }
      if (restored > 0) {
        _saveToStorage();
        notifyListeners();
      }
      return restored;
    } catch (e) {
      debugPrint('restorePagesFromBackup failed: $e');
      return 0;
    }
  }

  Future<void> _writePageStorageBeacon(String commitId) async {
    if (kIsWeb) return;
    final content = '$_pageStorageWriterId|$commitId';
    _lastSeenStorageBeacon = content;
    try {
      final f = await _pageStorageBeaconFile();
      await f.writeAsString(content, flush: true);
    } catch (e) {
      debugPrint('storage beacon write failed: $e');
    }
  }

  /// 他インスタンスの書き込みを一定間隔で見張る。
  void _startCrossInstanceWatch() {
    if (kIsWeb) return;
    _crossInstanceTimer?.cancel();
    _crossInstanceTimer = Timer.periodic(_kCrossInstancePoll, (_) {
      // ignore: discarded_futures
      _pollOtherInstances();
    });
  }

  Future<void> _pollOtherInstances() async {
    if (_disposed) return;
    // 初期化前や、 自分の保存が進行中の時は触らない (競合を増やさない)。
    if (_pages.isEmpty || !_pageStorageBaselineLoaded) return;
    if (_pageStorageSaveRunning || _pendingPageStorageCapture != null) return;
    // 自分がまさに保存待ちの時だけ見送る。 ただし編集がずっと続く場合でも
    //   取り込みが止まりっぱなしにならないよう、 最後の編集から 5 秒以上
    //   経っていれば取り込む (= ユーザー要望: 不整合を起こさない)。
    if (_saveDebounceTimer != null) {
      final last = _lastLocalEditAt;
      if (last == null ||
          DateTime.now().difference(last) < const Duration(seconds: 5)) {
        return;
      }
    }
    try {
      final f = await _pageStorageBeaconFile();
      if (!await f.exists()) return;
      final content = (await f.readAsString()).trim();
      if (content.isEmpty || content == _lastSeenStorageBeacon) return;
      _lastSeenStorageBeacon = content;
      // 自分が書いた版なら取り込む必要はない。
      if (content.startsWith('$_pageStorageWriterId|')) return;
      await reconcilePageStorageFromOtherTabs();
    } catch (e) {
      debugPrint('cross-instance poll failed: $e');
    }
  }

  Future<RandomAccessFile?> _acquirePageStorageFileLock() async {
    if (kIsWeb) return null;
    final supportDirectory = await getApplicationSupportDirectory();
    if (!await supportDirectory.exists()) {
      await supportDirectory.create(recursive: true);
    }
    final lockFile = File(
      '${supportDirectory.path}${Platform.pathSeparator}'
      'mindmap_pages_v4.lock',
    );
    final handle = await lockFile.open(mode: FileMode.append);
    try {
      // ★ 無期限に待たない ★
      //   異常終了したプロセスがロックを握ったままだと、 次に起動した
      //   アプリがここで永久に止まり「起動できない」 状態になる
      //   (= ユーザー報告: 別ウィンドウを閉じた後にアプリが起動しなくなる)。
      //   一定時間で諦めてロック無しで進む。 保存は三方向マージなので、
      //   ロックが取れなくても内容が壊れることはない (取り合いになった時に
      //   書き込みが 1 回やり直しになるだけ)。
      await handle
          .lock(FileLock.blockingExclusive)
          .timeout(const Duration(seconds: 5));
      return handle;
    } on TimeoutException {
      debugPrint('page storage lock timed out; continuing without the lock');
      try {
        await handle.close();
      } catch (_) {}
      return null;
    } catch (_) {
      try {
        await handle.close();
      } catch (_) {}
      rethrow;
    }
  }

  Future<void> _releasePageStorageFileLock(
    RandomAccessFile? handle,
  ) async {
    if (handle == null) return;
    try {
      await handle.unlock();
    } catch (error) {
      debugPrint('page storage lock release failed: $error');
    }
    try {
      await handle.close();
    } catch (error) {
      debugPrint('page storage lock close failed: $error');
    }
  }

  Future<void> _writeCoordinatedPageStorage(
    _PageStorageCapture capture, {
    required bool persistFontSettings,
  }) async {
    RandomAccessFile? storageLock;
    try {
      // SharedPreferences の reload/set はネイティブではプロセス間の原子性を
      // 保証しないため、read-modify-write と検証を同じ OS ロック内で行う。
      // Web はファイル API がないので commitId + retry の best-effort 調停。
      storageLock = await _acquirePageStorageFileLock();
      final prefs = await _prefsWithRetry();
      _PageStorageSnapshot? lastCommitted;
      Object? lastError;
      StackTrace? lastStackTrace;
      for (var attempt = 0; attempt < 4; attempt++) {
        try {
          await prefs.reload();
          final remote = _decodeCoordinatedPageStorage(
                prefs.getString(_coordinatedStorageKey),
              ) ??
              _decodeLegacyPageStorage(prefs.getString(_storageKey)) ??
              _emptyPageStorageSnapshot();
          final merged = _mergePageStorage(capture, remote);
          final now = DateTime.now().toUtc().millisecondsSinceEpoch;
          final commitId =
              '$_pageStorageWriterId-${++_pageStorageCommitSequence}-$now';
          final committed = _PageStorageSnapshot(
            revision: math.max(merged.revision, remote.revision) + 1,
            commitId: commitId,
            writtenAtMs: now,
            pagesJson: merged.pagesJson,
            order: merged.order,
            pageWriteTimes: merged.pageWriteTimes,
            pageAncestors: merged.pageAncestors,
            tombstones: merged.tombstones,
            orderWriteTimeMs: merged.orderWriteTimeMs,
          );
          lastCommitted = committed;
          // ★ ページが減る書き込みの前に、 直前の内容を丸ごと控えておく。
          //   誤操作や不具合で大量のページが消えても、 ここから戻せる
          //   (= 実際にページが一括で消える事故が起きたため)。
          await _backupPagesIfShrinking(prefs, committed);
          await prefs.setString(
            _coordinatedStorageKey,
            _encodeCoordinatedPageStorage(committed),
          );
          // 旧バージョンからの読み込み互換用。現行版は必ず v4 を正とする。
          await prefs.setString(_storageKey, _encodeLegacyPageList(committed));

          // ほぼ同時に別タブが書いた場合を commitId で検出し、その内容を再度
          // 三方向マージする。短い安定待ちを置くことで同時書込みを拾いやすくする。
          await Future<void>.delayed(const Duration(milliseconds: 12));
          await prefs.reload();
          final observed = _decodeCoordinatedPageStorage(
            prefs.getString(_coordinatedStorageKey),
          );
          if (observed?.commitId == commitId) {
            _acceptCommittedPageStorage(capture, committed);
            // 他インスタンスに「書いたよ」 と知らせる目印を残す。
            unawaited(_writePageStorageBeacon(commitId));
            if (persistFontSettings) {
              await prefs.setDouble(
                'defaultTitleFontSize',
                defaultTitleFontSize,
              );
              await prefs.setDouble(
                'defaultMemoFontSize',
                defaultMemoFontSize,
              );
            }
            return;
          }
          lastError = StateError(
            'page storage commit was superseded before verification',
          );
          lastStackTrace = StackTrace.current;
        } catch (error, stackTrace) {
          lastError = error;
          lastStackTrace = stackTrace;
        }
        if (attempt < 3) {
          await Future<void>.delayed(
            Duration(milliseconds: 20 * (attempt + 1)),
          );
        }
      }
      // 最終書込み自体は成功している可能性がある。基準を進めず、呼出元へ
      // 失敗を返す。fire-and-forget 経路のログ処理は queue 側で行う。
      debugPrint(
        'page storage commit was repeatedly superseded; '
        'will reconcile on next save '
        '(${lastCommitted?.commitId}, error: $lastError)',
      );
      if (lastError != null && lastStackTrace != null) {
        Error.throwWithStackTrace(lastError, lastStackTrace);
      }
      throw StateError(
        'page storage commit failed after all retry attempts',
      );
    } finally {
      await _releasePageStorageFileLock(storageLock);
    }
  }

  Future<void> _queuePageStorageSave(
    _PageStorageCapture capture, {
    required bool persistFontSettings,
  }) {
    // ドラッグ中は保存要求が高頻度で発生する。実行中の一件と最新の待機中
    // 一件だけを残し、中間状態をまとめて I/O 待ちの長いキューを作らない。
    _pendingPageStorageCapture = capture;
    _pendingPageStoragePersistsFonts =
        _pendingPageStoragePersistsFonts || persistFontSettings;
    var completer = _pendingPageStorageCompleter;
    if (completer == null) {
      completer = Completer<void>();
      _pendingPageStorageCompleter = completer;
      // 元の Future は await 呼出元へエラーを伝える。同時に派生 Future で
      // 即座にエラーを消費・記録し、fire-and-forget 呼出の未処理例外を防ぐ。
      unawaited(
        completer.future.then<void>(
          (_) {},
          onError: (Object error, StackTrace stackTrace) {
            debugPrint(
              'coordinated page save failed: $error\n$stackTrace',
            );
          },
        ),
      );
    }
    unawaited(_drainPageStorageSaves());
    return completer.future;
  }

  Future<void> _drainPageStorageSaves() async {
    if (_pageStorageSaveRunning) return;
    _pageStorageSaveRunning = true;
    try {
      while (_pendingPageStorageCapture != null) {
        var capture = _pendingPageStorageCapture!;
        final persistFonts = _pendingPageStoragePersistsFonts;
        final completer = _pendingPageStorageCompleter;
        _pendingPageStorageCapture = null;
        _pendingPageStoragePersistsFonts = false;
        _pendingPageStorageCompleter = null;
        // 先行 commit の accept で基準やメモリが更新された後、古い基準を持つ
        // immutable capture をそのまま使うと直列の B1→B2 を競合と誤認する。
        // 現在メモリを最新基準上で再 capture してから次 commit を作る。
        if (!_pageStorageCaptureUsesCurrentBaseline(capture)) {
          capture = _capturePageStorage(touchChangedPages: false);
        }
        try {
          await _writeCoordinatedPageStorage(
            capture,
            persistFontSettings: persistFonts,
          );
          if (completer != null && !completer.isCompleted) {
            completer.complete();
          }
        } catch (error, stackTrace) {
          if (completer != null && !completer.isCompleted) {
            completer.completeError(error, stackTrace);
          }
        }
      }
    } finally {
      _pageStorageSaveRunning = false;
      // finally と次のイベントの境界で追加された要求も取りこぼさない。
      if (_pendingPageStorageCapture != null) {
        unawaited(_drainPageStorageSaves());
      }
    }
  }

  void _markPageDeletedForStorage(String pageId) {
    if (pageId.isEmpty) return;
    final now = DateTime.now().toUtc().millisecondsSinceEpoch;
    _pageDeletionTombstones[pageId] =
        math.max(_pageDeletionTombstones[pageId] ?? 0, now);
  }

  Future<void> _loadFromStorage() async {
    try {
      // フォルダー一覧を先に読む（ページ読み込み時に検証で使う）。
      // ここで失敗してもページ読み込みは続行する。
      try {
        await _loadFoldersFromStorage();
      } catch (_) {}

      final prefs = await _prefsWithRetry();
      try {
        await prefs.reload();
      } catch (_) {}

      // v4 は複数タブ調停済みの原本。存在する場合は空のスナップショットも
      // 削除結果として尊重し、古い v3 を復活させない。
      final coordinated = _decodeCoordinatedPageStorage(
        prefs.getString(_coordinatedStorageKey),
      );
      bool loaded = false;
      bool needsCoordinatedMigration = false;
      if (coordinated != null) {
        loaded = _tryLoadPagesFrom(_encodeLegacyPageList(coordinated));
        _adoptInitialPageStorageBaseline(coordinated);
      } else {
        // v3 → 失敗(0枚)なら v2 から移行。いずれも 1 枚ずつ復元する。
        var legacyRaw = prefs.getString(_storageKey);
        var legacy = _decodeLegacyPageStorage(legacyRaw);
        loaded = _tryLoadPagesFrom(legacyRaw);
        if (!loaded) {
          legacyRaw = prefs.getString('mindmap_pages_v2');
          legacy = _decodeLegacyPageStorage(legacyRaw);
          loaded = _tryLoadPagesFrom(legacyRaw);
        }
        if (legacy != null) _adoptInitialPageStorageBaseline(legacy);
        needsCoordinatedMigration = loaded;
      }

      final bool freshOrEmpty = _pages.isEmpty;
      if (freshOrEmpty) {
        _seedDefaultPages();
        // 新規インストールは補充不要 (二重作成防止のためフラグだけ立てる)。
        // ignore: discarded_futures
        _markMobileDefaultPagesSeeded();
      }
      // ── 既存ページの移行 ──
      // テンプレ背景は常に不透明度 100% で使う (= ユーザー報告: モバイルで
      // ミッドナイトが白っぽくもやが掛かる。 既定 50% が明るいテーマの下地と
      // 混ざっていた)。 選択 UI も 100% 固定なので一律で直してよい。
      for (final pg in _pages) {
        if ((pg.backgroundImagePath ?? '')
                .startsWith('builtin-map-background:') &&
            pg.backgroundOpacityPercent != 100) {
          pg.backgroundOpacityPercent = 100;
        }
      }
      // モバイルの既定 4 ページを一度だけ補充 (既存インストールの移行)。
      if (!freshOrEmpty) {
        // ignore: discarded_futures
        _ensureMobileDefaultPages();
      }
      _currentPageIndex = 0;

      // ★ まず UI を出す（ここまで来れば必ず pages は 1 枚以上）。
      notifyListeners();

      // 旧形式からの移行 / 新規デフォルト作成時のみ、 UI 表示後に保存する
      // (await しない = ネットワーク自動同期で起動が固まらないように)。
      if (needsCoordinatedMigration || freshOrEmpty) {
        // ignore: discarded_futures
        _saveToStorage();
      }
    } catch (e, st) {
      debugPrint('_loadFromStorage 致命的エラー (ローディング固まり防止のため復旧): $e\n$st');
      // 最後の砦: 何が起きても使える UI を保証する。
      if (_pages.isEmpty) {
        try {
          _addDefaultPage(force: true);
        } catch (_) {}
        _currentPageIndex = 0;
      }
      notifyListeners();
    }
  }

  /// 保存済みページ JSON 文字列を 1 ページずつ `_pages` に復元する。
  /// 1 ページの fromJson が throw しても、 そのページだけスキップして残りを
  /// 読む (= 1 枚の破損で全データを失わない)。 1 枚以上読めたら true。
  bool _tryLoadPagesFrom(String? jsonStr) {
    if (jsonStr == null || jsonStr.isEmpty) return false;
    List<dynamic> list;
    try {
      final decoded = jsonDecode(jsonStr);
      if (decoded is! List) return false;
      list = decoded;
    } catch (_) {
      return false;
    }
    final int before = _pages.length;
    for (final item in list) {
      try {
        _pages.add(MindMapPage.fromJson(item as Map<String, dynamic>));
      } catch (e) {
        debugPrint('破損ページをスキップ: $e');
      }
    }
    if (_pages.length > before) {
      // 存在しないフォルダーIDを参照しているページは folderId を null に戻す
      _sanitizePageFolderIds();
      return true;
    }
    return false;
  }

  /// フォルダー一覧を SharedPreferences から読み込み
  Future<void> _loadFoldersFromStorage() async {
    final prefs = await _prefsWithRetry();
    final raw = prefs.getString(_foldersStorageKey);
    if (raw == null) return;
    try {
      final List<dynamic> list = jsonDecode(raw) as List<dynamic>;
      _folders.clear();
      for (final item in list) {
        _folders.add(MindMapFolder.fromJson(item as Map<String, dynamic>));
      }
    } catch (_) {}
  }

  /// フォルダー一覧の保存
  Future<void> _saveFoldersToStorage() async {
    final prefs = await _prefsWithRetry();
    await prefs.setString(_foldersStorageKey,
        jsonEncode(_folders.map((f) => f.toJson()).toList()));
  }

  /// 存在しないフォルダーIDを参照しているページの folderId を null に戻す
  void _sanitizePageFolderIds() {
    final ids = _folders.map((f) => f.id).toSet();
    for (final p in _pages) {
      if (p.folderId != null && !ids.contains(p.folderId)) {
        p.folderId = null;
      }
    }
  }

  Future<void> _loadFontSettings() async {
    final prefs = await _prefsWithRetry();
    defaultTitleFontSize = prefs.getDouble('defaultTitleFontSize') ?? 15.0;
    defaultMemoFontSize = prefs.getDouble('defaultMemoFontSize') ?? 12.0;
    _snapEnabled = prefs.getBool('snapEnabled') ?? true;
    // Esc で閲覧画面を閉じるか (= ユーザー要望: 誤爆を止められるように)。
    _closeViewerWithEsc = prefs.getBool('closeViewerWithEsc') ?? true;
    // 「アプリで開く」 を別アプリで開くか (= ユーザー要望)。
    _openWithNewInstance = prefs.getBool('openWithNewInstance') ?? false;
    // メモ欄一括折りたたみ (デフォルト false = 従来通り全文表示)
    _memoCollapsedGlobal = prefs.getBool('memoCollapsedGlobal') ?? false;
    // 動画ノードの重複生成許可フラグ (デフォルト false)
    _allowDuplicateVideoNodes =
        prefs.getBool('allowDuplicateVideoNodes') ?? false;
    // 旧設定からの移行
    _channelMode = prefs.getString('channelMode') ??
        ((prefs.getBool('includeShorts') ?? false) ? 'both' : 'videos');
  }

  Future<void> _loadChannelFilterSettings() async {
    final prefs = await _prefsWithRetry();
    _autoDeleteWatched = prefs.getBool('autoDeleteWatched') ?? false;
    // 連番オートフィル: デフォルト ON (= 親切寄り)
    _autofillSequenceEnabled = prefs.getBool('autofillSequenceEnabled') ?? true;
    _unwatchedLimit = prefs.getInt('unwatchedLimit') ?? 5;
    _minViewCount = prefs.getInt('minViewCount') ?? 0;
    _includeKeywords = prefs.getString('chFilterInclude') ?? '';
    _excludeKeywords = prefs.getString('chFilterExclude') ?? '';
    // 動画再生倍率の上限 (1.5〜16.0)
    _videoMaxRate = (prefs.getDouble('videoMaxRate') ?? 4.0).clamp(1.5, 16.0);
    // オフライン動画の左右キーのシーク秒数 (1〜60、 既定 5)
    _videoSeekSeconds = (prefs.getInt('videoSeekSeconds') ?? 5).clamp(1, 60);
    // 直近の動画再生倍率 (起動を跨いで引き継ぐ)。
    // 1.0 〜 videoMaxRate の範囲にクランプ (videoMaxRate を後から下げた
    // ケースで前回値がそれを超えていたら丸める)。
    _lastVideoPlaybackRate = (prefs.getDouble('lastVideoPlaybackRate') ?? 1.0)
        .clamp(1.0, _videoMaxRate);
    // クイック子要素生成数 (Ctrl+Shift+A) の復元
    _quickAddChildrenCount =
        (prefs.getInt('quickAddChildrenCount') ?? 5).clamp(1, 30);
    // バックグラウンド再生 (画面オフ時の継続再生) フラグ
    _backgroundPlaybackEnabled =
        prefs.getBool('backgroundPlaybackEnabled') ?? false;
    // 音楽サイトのバックグラウンド再生 (= ユーザー要望)。 既定 OFF。
    _webAudioBackground = prefs.getBool('webAudioBackground') ?? false;
    // PiP ミニプレイヤーの拡大率 (0.5〜2.0)
    _pipScale = (prefs.getDouble('pipScale') ?? 1.0).clamp(0.5, 2.0);
    // カレンダーのタイムゾーン (オプション、未設定なら null = 端末ローカル)
    if (prefs.containsKey('calendarTzOffset')) {
      _calendarTzOffsetMinutes = prefs.getInt('calendarTzOffset');
      _calendarTzLabel = prefs.getString('calendarTzLabel') ?? '';
    }
  }

  // ── 保存要求のまとめ (= ユーザー報告: 操作中にフリーズする) ──
  //   _capturePageStorage は全ページを jsonEncode するため重い。 編集のたび
  //   に同期実行すると UI スレッドが詰まるので、 少し待って 1 回にまとめる。
  //   待機中にアプリを閉じる場合は flushSaveToStorage() で即座に書き出す。
  static const Duration _kSaveDebounce = Duration(milliseconds: 350);
  Timer? _saveDebounceTimer;
  Completer<void>? _saveDebounceCompleter;

  /// 最後にこのインスタンスで編集した時刻 (他インスタンス取り込みの判断用)。
  DateTime? _lastLocalEditAt;

  Future<void> _saveToStorage() {
    _lastLocalEditAt = DateTime.now();
    var completer = _saveDebounceCompleter;
    if (completer == null) {
      completer = Completer<void>();
      _saveDebounceCompleter = completer;
      // fire-and-forget の呼出が大半なので、 ここで必ずエラーを消費して
      //   未処理例外にしない (実処理の Future 側は呼出元へ伝わる)。
      unawaited(completer.future.then<void>(
        (_) {},
        onError: (Object e, StackTrace st) {
          debugPrint('debounced page save failed: $e\n$st');
        },
      ));
    }
    _saveDebounceTimer?.cancel();
    _saveDebounceTimer = Timer(_kSaveDebounce, () {
      // ignore: discarded_futures
      _runPendingSave();
    });
    return completer.future;
  }

  /// 待機中の保存を今すぐ実行する (アプリの終了 / バックグラウンド移行時)。
  Future<void> flushSaveToStorage() {
    _saveDebounceTimer?.cancel();
    _saveDebounceTimer = null;
    return _runPendingSave();
  }

  Future<void> _runPendingSave() {
    _saveDebounceTimer?.cancel();
    _saveDebounceTimer = null;
    final completer = _saveDebounceCompleter;
    _saveDebounceCompleter = null;
    final done = _saveToStorageNow();
    if (completer != null && !completer.isCompleted) {
      done.then<void>(
        (_) {
          if (!completer.isCompleted) completer.complete();
        },
        onError: (Object e, StackTrace st) {
          if (!completer.isCompleted) completer.completeError(e, st);
        },
      );
    }
    return done;
  }

  Future<void> _saveToStorageNow() {
    // 基準スナップショットとの差分があるページだけ更新扱いにする。
    // 「現在ページだから」という理由だけで時刻を進めると、古いタブを触った
    // だけで別タブの新しい編集を上書きしてしまうため。
    final capture = _capturePageStorage(touchChangedPages: true);
    final save = _queuePageStorageSave(
      capture,
      persistFontSettings: true,
    );
    // 自動同期が有効なページがあればデバウンス付きで同期
    _triggerAutoSync();
    // ── linkedDir フォルダーへの自動書き出し ──
    // 現在のページが「ディスク連動フォルダー」に属していれば、
    // 編集内容を JSON として自動保存する。失敗しても黙殺 (UI を妨げない)。
    if (_pages.isNotEmpty &&
        _currentPageIndex >= 0 &&
        _currentPageIndex < _pages.length) {
      // await しない (UI への影響を避けるため fire-and-forget)
      autoSavePageIfLinked(_pages[_currentPageIndex].id);
    }
    return save;
  }

  /// Firestoreからの受信時に使用（ループ防止のためFirestore書き込みをしない）
  Future<void> _saveToStorageLocal() => _queuePageStorageSave(
        _capturePageStorage(touchChangedPages: false),
        persistFontSettings: false,
      );

  /// Web タブ／別ウィンドウから復帰した時に、未編集のページへ外部 commit を
  /// 反映する。ローカルに差分があれば通常の三方向マージで保護される。
  /// 初期ロード後に呼ぶ。 他インスタンスの監視を開始する。
  void startCrossInstanceSync() => _startCrossInstanceWatch();

  Future<void> reconcilePageStorageFromOtherTabs() {
    // 初回ロード中に受信データを適用すると、その直後のロード処理が同じページを
    // append して重複するため、初期基準が確定するまでは何もしない。
    if (_pages.isEmpty || !_pageStorageBaselineLoaded) {
      return Future<void>.value();
    }
    return _queuePageStorageSave(
      _capturePageStorage(touchChangedPages: false),
      persistFontSettings: false,
    );
  }

  /// ページ種別ごとの既定名プレフィックス (= ユーザー要望: ビデオエディター
  /// なのに「マップ10」 と付くのはおかしい → 種類毎に名前/番号を付ける)。
  /// normal は従来の言語別「マップ/Map」。 それ以外は ja/en の短い接頭辞。
  /// ページ種別の表示名 (末尾の空白を落としたもの)。 同期ダイアログなどで
  /// 「ノード数」 の代わりに種別を出すのに使う (= ユーザー要望: ギャラリーや
  /// フリーノートをノード数で表現しない)。
  String pageTypeLabel(String pageType) =>
      _typePagePrefix(pageType, _appLanguage).trim();

  static String _typePagePrefix(String pageType, String lang) {
    final ja = lang == 'ja';
    switch (pageType) {
      case 'videoEditor':
        return ja ? 'ビデオ ' : 'Video ';
      case 'paint':
        return ja ? 'フリーノート ' : 'Free Note ';
      case 'document':
        return ja ? 'フリーノート ' : 'Free Note ';
      case 'markdown':
        return ja ? 'Markdown ' : 'Markdown ';
      case 'gantt':
        return ja ? 'ガント ' : 'Gantt ';
      case 'bookshelf':
        return ja ? 'ギャラリー ' : 'Gallery ';
      case 'memberSchedule':
        return ja ? '予定表 ' : 'Schedule ';
      default:
        return _defaultPageNamePrefixFor(lang);
    }
  }

  /// 同じ pageType の既存ページ数 + 1 (= 種類毎の連番)。
  int _nextTypeNumber(String pageType) {
    int c = 0;
    for (final p in _pages) {
      if (p.pageType == pageType) c++;
    }
    return c + 1;
  }

  /// 初回起動時の既定ページを用意する。
  /// モバイルはマインドマップ / ギャラリー / フリーノート / ビデオエディタの
  /// 4 ページが最初から開いている状態にする (= ユーザー要望)。
  void _seedDefaultPages() {
    _addDefaultPage(force: true);
    if (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) {
      _addDefaultPage(pageType: 'bookshelf', force: true);
      _addDefaultPage(pageType: 'paint', force: true);
      _addDefaultPage(pageType: 'videoEditor', force: true);
    }
  }

  /// 既存インストールの移行: モバイルで既定 4 種のうち無いものを一度だけ
  /// 補充する (= 新規作成を Pro 化したため、 無料ユーザーが既定ページを
  /// 持たないままにならないように)。
  Future<void> _markMobileDefaultPagesSeeded() async {
    if (kIsWeb || !(Platform.isAndroid || Platform.isIOS)) return;
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setBool('mobileDefaultPagesSeeded_v1', true);
    } catch (_) {}
  }

  Future<void> _ensureMobileDefaultPages() async {
    if (kIsWeb || !(Platform.isAndroid || Platform.isIOS)) return;
    try {
      // 初回ロードの完了を待ってから判定する (ロード途中の空の状態を
      // 「ページが無い」 と誤認して二重に作らないため)。
      await initialLoadDone;
      if (_pages.isEmpty) return;
      final prefs = await _prefsWithRetry();
      if (prefs.getBool('mobileDefaultPagesSeeded_v1') == true) return;
      var added = false;
      for (final t in ['normal', 'bookshelf', 'paint', 'videoEditor']) {
        if (pageTypeCount(t) == 0) {
          _addDefaultPage(pageType: t, force: true);
          added = true;
        }
      }
      await prefs.setBool('mobileDefaultPagesSeeded_v1', true);
      if (added) {
        await _saveToStorage();
        notifyListeners();
      }
    } catch (_) {}
  }

  MindMapPage? _addDefaultPage(
      {String? name,
      String? folderId,
      String pageType = 'normal',
      bool force = false}) {
    // force は起動時の既定ページ作成用 (プラン制限を通さない)。
    if (!force && !canCreatePageType(pageType)) return null;
    // 名前が指定されていない場合は種別+言語に合わせた既定名を使う。
    // normal は従来どおり全ページ通し番号 (言語切替で自動追従)。
    // それ以外は「ビデオ N」「お絵かき N」 など種類毎の連番。
    final n =
        pageType == 'normal' ? _pages.length + 1 : _nextTypeNumber(pageType);
    final defaultName = '${_typePagePrefix(pageType, _appLanguage)}$n';
    final page = MindMapPage(
        id: _uuid.v4(),
        name: name ?? defaultName,
        folderId: folderId,
        pageType: pageType);
    // ── 既定のテンプレ背景 (= ユーザー要望: ギャラリーにも) ──
    // 一番最初のページはミッドナイト。 以降はページを作る度にテンプレ背景から
    // ランダムに選ぶ。 作成時に一度だけ割り当てるので、 ユーザーが後から
    // 自分で変えた背景はそのまま残る。
    if (pageType == 'normal' || pageType == 'bookshelf') {
      final id = _pages.isEmpty
          ? 'midnight'
          : kBgTemplateIdsForNewPage[
              math.Random().nextInt(kBgTemplateIdsForNewPage.length)];
      page.backgroundImagePath = 'builtin-map-background:$id';
      // テンプレは常に不透明度 100% (= ユーザー報告: モバイルで背景が
      // 白っぽくもやが掛かる。 既定の 50% が明るいテーマと混ざっていた)。
      page.backgroundOpacityPercent = 100;
    }
    // 仕様変更(2026-04):
    // メインテーマ(ルート)ノードは作成しない。完全に空のマップから開始する。
    // ユーザーは + ボタン / FAB / Ctrl+1 などで好きなノードから組み立てる。
    _pages.add(page);
    return page;
  }

  /// 新規ページの背景抽選に使う組み込みテンプレ ID
  /// (screen 側 `_mapBackgroundTemplates` と同じ一覧)。
  static const List<String> kBgTemplateIdsForNewPage = [
    'wood', 'chalkboard', 'ocean', 'sakura', 'fireworks', 'castle',
    'aurora', 'nightSky', 'galaxy', 'rain', 'nature', 'blueprint',
    'midnight', 'sage', 'sunset',
  ];

  void addPage({String? name, String? folderId}) {
    final page = _addDefaultPage(name: name, folderId: folderId);
    if (page == null) return;
    _currentPageIndex = _pages.length - 1;
    _selectedNodeId = null;
    _saveToStorage();
    notifyListeners();
    // 新規ページが連動フォルダーに属していれば即座にディスクへ書き出す
    if (folderId != null) {
      autoSavePageIfLinked(page.id);
    }
  }

