  /// ページを切り替える直前に、 他インスタンスの書き込みを取り込む
  /// (= ユーザー要望: 複数立ち上げた時にデータの不整合が起きないように)。
  /// 目印ファイルが変わっていた時だけ調停するので、 普段は無視できる負荷。
  void switchPage(int index) {
    // ignore: discarded_futures
    _pollOtherInstances();
    if (index < 0 || index >= _pages.length) return;
    _currentPageIndex = index;
    _selectedNodeId = null;
    // ギャラリーページに切り替えたら整列して格子キャッシュを最新化する。
    //   = ユーザー報告「時々 +ボックスと要素がかみ合わなくなる」 の対策:
    //   読み込み直後/ページ切替直後でも、 要素配置と同じ格子で +ボックスを描くため。
    //   sizeTextNode は内容ベースで決まり stretch 後の高さに依存しないので冪等。
    _autoArrangeIfBookshelf();
    // 最後に開いたページ ID を永続化 (起動時の復元用)
    _persistLastOpenedPageId(_pages[index].id);
    // 共同編集中に別の共有済みページへ移ったら、 セッションをその
    // ページのコードへ自動で張り替える (= ユーザー要望: 複数ページを
    // 一度に共有して、 どのページでも共同編集できるように)。
    _maybeSwitchLiveSessionForCurrentPage();
    notifyListeners();
  }

  /// 共有済みページへの切替時にセッションを張り替える。
  /// 相手の内容を上書きしないよう、 初回 push はしない (参加と同じ扱い)。
  void _maybeSwitchLiveSessionForCurrentPage() {
    if (!liveActive) return;
    if (_currentPageIndex < 0 || _currentPageIndex >= _pages.length) return;
    final page = _pages[_currentPageIndex];
    if (page.id == _livePageId) return;
    final rec = _publishedPages[page.id];
    final code = rec?['code'] ?? '';
    if (code.isEmpty) return;
    final perm = rec?['permission'] == 'view' ? 'view' : 'edit';
    // ignore: discarded_futures
    startLiveSession(
            pageId: page.id, code: code, permission: perm, pushInitial: false)
        .catchError((e) {
      debugPrint('共同編集の自動切替に失敗: $e');
    });
  }

  /// 最後に開いていたマップページ ID を SharedPreferences に保存。
  /// 次回起動時にこの ID で switchPage して、 前回の作業を続けられるようにする。
  Future<void> _persistLastOpenedPageId(String pageId) async {
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setString('last_opened_page_id', pageId);
    } catch (_) {}
  }

  /// 起動時に last_opened_page_id を読み出して該当ページに切り替える。
  /// 該当ページが見つからない (= 削除済み等) なら 0 番目のページを開く。
  /// 初回起動 (= 保存値なし) も 0 番目を開く。
  Future<void> _restoreLastOpenedPage() async {
    try {
      // ── ホーム画面/デスクトップのショートカットから起動された場合 ──
      // そのマップ(ページ)を最優先で開く (= ユーザー要望: マップごとに
      //   アプリ風ショートカットを作って直接そのマップを開けるように)。
      final shortcutId = await HomeShortcutService.initialPageId();
      if (shortcutId != null && shortcutId.isNotEmpty) {
        final sidx = _pages.indexWhere((p) => p.id == shortcutId);
        if (sidx >= 0) {
          _currentPageIndex = sidx;
          notifyListeners();
          return;
        }
      }
      final prefs = await _prefsWithRetry();
      final saved = prefs.getString('last_opened_page_id');
      if (saved == null || saved.isEmpty) return;
      final idx = _pages.indexWhere((p) => p.id == saved);
      if (idx >= 0 && idx < _pages.length) {
        _currentPageIndex = idx;
        notifyListeners();
      }
    } catch (_) {}
  }

  /// ページ ID を指定してそのページへ切り替える (ショートカットからの起動・
  /// 起動中タップで使用)。 見つからなければ何もしない。
  void openPageById(String pageId) {
    final idx = _pages.indexWhere((p) => p.id == pageId);
    if (idx >= 0 && idx < _pages.length) {
      _currentPageIndex = idx;
      _selectedNodeId = null;
      notifyListeners();
    }
  }

  void renamePage(int index, String name) {
    if (index < 0 || index >= _pages.length) return;
    _pages[index].name = name;
    // ★ 利用者が自分で付けた名前は、 以後 AI に上書きさせない
    //   (= ユーザー要望)。 自動で付けた印を外す。
    if (_autoNamedPageIds.remove(_pages[index].id)) {
      unawaited(_saveAutoNamedPages());
    }
    _saveToStorage();
    notifyListeners();
  }

  _DeletedPageUndoRecord? _lastDeletedPageUndo;

  MindMapPage _clonePageForUndo(MindMapPage page) {
    return MindMapPage.fromJson(
      jsonDecode(jsonEncode(page.toJson())) as Map<String, dynamic>,
    );
  }

  AiPageContext _cloneAiPageContextForUndo(AiPageContext source) {
    final copy = AiPageContext(
      fileName: source.fileName,
      textContent: source.textContent,
      filePath: source.filePath,
      ext: source.ext,
    );
    copy.qaHistory.addAll(source.qaHistory);
    return copy;
  }

  _DeletedPageUndoRecord _captureDeletedPageUndo(
    MindMapPage page,
    int index,
  ) {
    final id = page.id;
    final aiContext = _aiPageContexts[id];
    return _DeletedPageUndoRecord(
      page: _clonePageForUndo(page),
      index: index,
      wasHidden: _hiddenPageIds.contains(id),
      wasFavorite: _favoritePageIds.contains(id),
      undoStack: _undoStacks[id] == null
          ? null
          : List<_PageSnapshot>.from(_undoStacks[id]!),
      redoStack: _redoStacks[id] == null
          ? null
          : List<_PageSnapshot>.from(_redoStacks[id]!),
      lastEditedAt: _pageLastEditedAt[id],
      aiContext:
          aiContext == null ? null : _cloneAiPageContextForUndo(aiContext),
      namedGroups: _namedGroups[id]?.map(
        (name, nodeIds) => MapEntry(name, Set<String>.from(nodeIds)),
      ),
      groupColors: _groupColors[id] == null
          ? null
          : Map<String, int>.from(_groupColors[id]!),
      groupFontSizes: _groupFontSizes[id] == null
          ? null
          : Map<String, double>.from(_groupFontSizes[id]!),
      groupFontFamilies: _groupFontFamilies[id] == null
          ? null
          : Map<String, String>.from(_groupFontFamilies[id]!),
      groupLayoutRows: _groupLayoutRows[id] == null
          ? null
          : Map<String, int>.from(_groupLayoutRows[id]!),
      groupLayoutModes: _groupLayoutModes[id] == null
          ? null
          : Map<String, String>.from(_groupLayoutModes[id]!),
      groupPadding: _groupPadding[id]?.map(
        (name, padding) => MapEntry(name, List<double>.from(padding)),
      ),
    );
  }

  String? get lastDeletedPageName => _lastDeletedPageUndo?.page.name;
  bool get canUndoDeletedPage => _lastDeletedPageUndo != null;

  void deletePage(int index) {
    if (_pages.length <= 1) return;
    if (index < 0 || index >= _pages.length) return;
    final deletedPage = _pages[index];
    final deletedId = deletedPage.id;
    _lastDeletedPageUndo = _captureDeletedPageUndo(deletedPage, index);
    _markPageDeletedForStorage(deletedId);
    _pages.removeAt(index);
    _currentPageIndex = _currentPageIndex.clamp(0, _pages.length - 1);
    _selectedNodeId = null;
    // AI 追加質問の文脈もページ削除と同時に消す (孤立データを残さない)
    _clearDeletedPageRuntimeState(deletedId);
    // ── クラウド上のデータは消さない (= ユーザー報告: ダウンロードした
    //    ページを手元から消しただけでクラウドのデータまで消えてしまう)。
    //    クラウドからの削除は「クラウドのマップ一覧」 の削除操作
    //    (deleteCloudPages) だけが行う。 ──
    _saveNamedGroups();
    _saveToStorage();
    notifyListeners();
  }

  bool undoLastDeletedPage() {
    final record = _lastDeletedPageUndo;
    if (record == null) return false;
    final pageId = record.page.id;
    if (_pages.any((page) => page.id == pageId)) {
      _lastDeletedPageUndo = null;
      notifyListeners();
      return false;
    }
    final insertAt = record.index.clamp(0, _pages.length);
    final restored = _clonePageForUndo(record.page)
      ..lastModifiedAt = DateTime.now().toUtc();
    _pageDeletionTombstones.remove(pageId);
    _pages.insert(insertAt, restored);
    _currentPageIndex = insertAt;
    _selectedNodeId = null;
    if (record.undoStack != null) {
      _undoStacks[pageId] = List<_PageSnapshot>.from(record.undoStack!);
    }
    if (record.redoStack != null) {
      _redoStacks[pageId] = List<_PageSnapshot>.from(record.redoStack!);
    }
    if (record.lastEditedAt != null) {
      _pageLastEditedAt[pageId] = record.lastEditedAt!;
    }
    if (record.aiContext != null) {
      _aiPageContexts[pageId] = _cloneAiPageContextForUndo(record.aiContext!);
    }
    if (record.namedGroups != null) {
      _namedGroups[pageId] = record.namedGroups!.map(
        (name, nodeIds) => MapEntry(name, Set<String>.from(nodeIds)),
      );
    }
    if (record.groupColors != null) {
      _groupColors[pageId] = Map<String, int>.from(record.groupColors!);
    }
    if (record.groupFontSizes != null) {
      _groupFontSizes[pageId] =
          Map<String, double>.from(record.groupFontSizes!);
    }
    if (record.groupFontFamilies != null) {
      _groupFontFamilies[pageId] =
          Map<String, String>.from(record.groupFontFamilies!);
    }
    if (record.groupLayoutRows != null) {
      _groupLayoutRows[pageId] = Map<String, int>.from(record.groupLayoutRows!);
    }
    if (record.groupLayoutModes != null) {
      _groupLayoutModes[pageId] =
          Map<String, String>.from(record.groupLayoutModes!);
    }
    if (record.groupPadding != null) {
      _groupPadding[pageId] = record.groupPadding!.map(
        (name, padding) => MapEntry(name, List<double>.from(padding)),
      );
    }
    if (record.wasHidden) _hiddenPageIds.add(pageId);
    if (record.wasFavorite) _favoritePageIds.add(pageId);
    if (record.wasHidden) unawaited(_persistHiddenPages());
    if (record.wasFavorite) unawaited(_persistFavoritePages());
    _lastDeletedPageUndo = null;
    _saveToStorage();
    unawaited(_saveNamedGroups());
    notifyListeners();
    return true;
  }

  void _clearDeletedPageRuntimeState(String pageId) {
    _aiPageContexts.remove(pageId);
    _undoStacks.remove(pageId);
    _redoStacks.remove(pageId);
    _pageLastEditedAt.remove(pageId);
    _namedGroups.remove(pageId);
    _groupColors.remove(pageId);
    _groupFontSizes.remove(pageId);
    _groupFontFamilies.remove(pageId);
    _groupLayoutRows.remove(pageId);
    _groupLayoutModes.remove(pageId);
    _groupPadding.remove(pageId);
    final hiddenChanged = _hiddenPageIds.remove(pageId);
    final favoriteChanged = _favoritePageIds.remove(pageId);
    if (hiddenChanged) unawaited(_persistHiddenPages());
    if (favoriteChanged) unawaited(_persistFavoritePages());
  }

  /// ページ並び替え（Drawerからのドラッグ＆ドロップ）
  /// Ctrl+1〜9 ショートカットの「ルート(フォルダー外のページ群)」を表す
  /// 特殊な ID。実際のフォルダー ID と衝突しないよう __ プレフィックス付き。
  static const String shortcutRootSentinel = '__ROOT__';

  /// Ctrl+1〜9 ショートカットの基準フォルダーを設定する。
  /// - 通常のフォルダー ID: そのフォルダー内のページが対象
  /// - shortcutRootSentinel ('__ROOT__'): ルート (フォルダー外のページ) が対象
  /// - null: 全ページ (従来動作にリセット)
  /// フォルダー ID が無効な場合は ignore する (削除済みなど)。
  Future<void> setShortcutFolder(String? folderId) async {
    if (folderId != null &&
        folderId != shortcutRootSentinel &&
        !_folders.any((f) => f.id == folderId)) {
      return;
    }
    _shortcutFolderId = folderId;
    final prefs = await _prefsWithRetry();
    if (folderId == null) {
      await prefs.remove(_kShortcutFolderId);
    } else {
      await prefs.setString(_kShortcutFolderId, folderId);
    }
    notifyListeners();
  }

  /// Ctrl+1〜9 のショートカットで切り替えるべきページを返す。
  /// _shortcutFolderId の値:
  ///   - null: ルート (フォルダー外のページ) から N 番目 ※既定動作
  ///   - shortcutRootSentinel: ルートから N 番目 (null と同じ)
  ///   - 通常のフォルダー ID: そのフォルダー内の N 番目
  ///   - 不正/削除済み ID: ルートにフォールバック
  /// 該当ページが無ければ null を返す。
  ///
  /// 既定 (null) を「ルートのみ」とすることで、ユーザーから見ると
  /// 「フォルダーの中のマップに Ctrl+1〜9 が勝手に割り振られる」事故が起きない。
  /// 個別フォルダーを基準にしたい場合は、フォルダー右クリックから
  /// 「Ctrl+1〜9 の基準にする」を選んで明示的に設定できる。
  MindMapPage? pageForShortcutSlot(int idx) {
    if (idx < 0) return null;
    // ★ ドロワーの表示順と一致させる (= ユーザー要望: 上から Ctrl+1,2,3…)。
    //   pagesInFolder はピン留め(お気に入り)を先頭に寄せる並びなので、
    //   ここでも同じ pagesInFolder を使わないと「一番上のマップに Ctrl+2」
    //   のような番号ずれが起きる。
    final List<MindMapPage> scope;
    if (_shortcutFolderId != null &&
        _shortcutFolderId != shortcutRootSentinel &&
        _folders.any((f) => f.id == _shortcutFolderId)) {
      // 指定フォルダー内のページが対象
      scope = pagesInFolder(_shortcutFolderId);
    } else {
      // null / sentinel / 不正 ID → ルート (フォルダー外) のページのみ
      scope = pagesInFolder(null);
    }
    if (idx >= scope.length) return null;
    return scope[idx];
  }

  void reorderPages(int oldIndex, int newIndex) {
    if (oldIndex < 0 || oldIndex >= _pages.length) return;
    if (newIndex > _pages.length) newIndex = _pages.length;
    if (newIndex > oldIndex) newIndex -= 1;
    if (newIndex == oldIndex) return;
    final currentId = _pages.isNotEmpty ? _pages[_currentPageIndex].id : null;
    final page = _pages.removeAt(oldIndex);
    _pages.insert(newIndex, page);
    if (currentId != null) {
      final newCurrent = _pages.indexWhere((p) => p.id == currentId);
      if (newCurrent >= 0) _currentPageIndex = newCurrent;
    }
    _saveToStorage();
    notifyListeners();
  }

  // ─── フォルダー操作 ─────────────────────────────────────────────────────
  /// フォルダー一覧（読み取り専用）
  List<MindMapFolder> get folders => List.unmodifiable(_folders);

  /// ページが連動フォルダー内にある場合、そのフォルダーのディレクトリを返す。
  String? linkedDirectoryForPage(String pageId) {
    final p = _pages.firstWhere((e) => e.id == pageId,
        orElse: () => MindMapPage(id: '', name: ''));
    if (p.id.isEmpty || p.folderId == null) return null;
    final f = _folders.firstWhere((e) => e.id == p.folderId,
        orElse: () => MindMapFolder(id: '', name: ''));
    final path = f.linkedDirPath?.trim();
    if (f.id.isEmpty || path == null || path.isEmpty) return null;
    return path;
  }

  /// 新規フォルダーを作成して、その ID を返す
  String addFolder({String? name, String? linkedDirPath}) {
    final id = _uuid.v4();
    _folders.add(MindMapFolder(
      id: id,
      name: name ?? 'フォルダー ${_folders.length + 1}',
      linkedDirPath: linkedDirPath,
    ));
    _saveFoldersToStorage();
    notifyListeners();
    return id;
  }

  /// 既存フォルダーに連動ディレクトリを設定 / 解除する
  Future<void> setFolderLinkedDir(String folderId, String? path) async {
    final f = _folders.firstWhere((e) => e.id == folderId,
        orElse: () => MindMapFolder(id: '', name: ''));
    if (f.id.isEmpty) return;
    f.linkedDirPath = path;
    _saveFoldersToStorage();
    notifyListeners();
  }

  /// 指定フォルダーのページを連動ディレクトリへ自動書き出しする。
  /// linkedDirPath が設定されていなければ no-op。
  /// 各ページが個別の .json として保存される (ファイル名はページ名 .sanitize)。
  /// 既存ファイルは上書き。同期方向は「アプリ → ディスク」のみ。
  /// ページの toJson() 結果を「ポータブル」化する。
  /// 各ノードの attachmentPath がローカルファイル絶対パスを指している場合、
  /// そのファイルを読み込んで data:URL (base64 + mime) に変換し、JSON に
  /// 埋め込む。これにより別環境(別 PC やパスが変わった環境)でも画像/PDF
  /// が表示できるようになる。
  /// data:URL や http(s)://、空のものはそのまま。
  Future<Map<String, dynamic>> _pageToPortableJson(MindMapPage p) async {
    final json = p.toJson();
    final nodes = json['nodes'];
    if (nodes is! List) return json;
    for (final n in nodes) {
      if (n is! Map) continue;
      final path = n['attachmentPath'] as String?;
      if (path == null || path.isEmpty) continue;
      // 既に埋め込み済み or リモート URL ならスキップ
      if (path.startsWith('data:') ||
          path.startsWith('http://') ||
          path.startsWith('https://')) continue;
      try {
        final f = File(path);
        if (!await f.exists()) continue;
        final bytes = await f.readAsBytes();
        // 拡張子から MIME を推定
        final ext = path.toLowerCase().split('.').last;
        final mime = _mimeFromExt(ext);
        final b64 = base64Encode(bytes);
        n['attachmentPath'] = 'data:$mime;base64,$b64';
        // attachmentName が無ければファイル名を補完
        if ((n['attachmentName'] as String?)?.isEmpty ?? true) {
          n['attachmentName'] = _baseName(path);
        }
      } catch (_) {
        // 読み込み失敗はスキップ (元のパスのまま)
      }
    }
    return json;
  }

  /// 拡張子 → MIME タイプの簡易マッピング (画像/PDF/動画/オーディオ)
  String _mimeFromExt(String ext) {
    switch (ext) {
      case 'jpg':
      case 'jpeg':
        return 'image/jpeg';
      case 'png':
        return 'image/png';
      case 'gif':
        return 'image/gif';
      case 'webp':
        return 'image/webp';
      case 'svg':
        return 'image/svg+xml';
      case 'pdf':
        return 'application/pdf';
      case 'mp4':
        return 'video/mp4';
      case 'webm':
        return 'video/webm';
      case 'mov':
        return 'video/quicktime';
      case 'mp3':
        return 'audio/mpeg';
      case 'wav':
        return 'audio/wav';
      case 'zip':
        return 'application/zip';
      case 'json':
        return 'application/json';
      case 'txt':
        return 'text/plain';
      case 'csv':
        return 'text/csv';
    }
    return 'application/octet-stream';
  }

  Future<void> syncFolderToLinkedDir(String folderId) async {
    final f = _folders.firstWhere((e) => e.id == folderId,
        orElse: () => MindMapFolder(id: '', name: ''));
    if (f.id.isEmpty) return;
    final dirPath = f.linkedDirPath;
    if (dirPath == null) return;
    try {
      final dir = Directory(dirPath);
      if (!await dir.exists()) return;
      for (final p in _pages.where((e) => e.folderId == folderId)) {
        // ページ名から不正文字を除去してファイル名に
        var safeName = p.name.replaceAll(RegExp(r'[\\/:*?"<>|]'), '_').trim();
        if (safeName.isEmpty) safeName = p.id;
        final filePath = '$dirPath${Platform.pathSeparator}$safeName.json';
        // 単一ページを { pages: [...] } 形式で書き出す。
        // 画像/PDF などの添付は data:URL として埋め込み (ポータブル化)。
        final pageJson = await _pageToPortableJson(p);
        final json = jsonEncode({
          'version': 3,
          'pages': [pageJson],
        });
        await File(filePath).writeAsString(json);
      }
    } catch (e) {
      debugPrint('syncFolderToLinkedDir failed: $e');
    }
  }

  /// 指定ページが「連動ディレクトリのフォルダー」に所属しているなら、
  /// そのページだけを単独で保存する。新規ページ作成 / 編集後に呼ばれる。
  Future<void> autoSavePageIfLinked(String pageId) async {
    final p = _pages.firstWhere((e) => e.id == pageId,
        orElse: () => MindMapPage(id: '', name: ''));
    if (p.id.isEmpty || p.folderId == null) return;
    final f = _folders.firstWhere((e) => e.id == p.folderId,
        orElse: () => MindMapFolder(id: '', name: ''));
    if (f.id.isEmpty || f.linkedDirPath == null) return;
    try {
      final dir = Directory(f.linkedDirPath!);
      if (!await dir.exists()) return;
      var safeName = p.name.replaceAll(RegExp(r'[\\/:*?"<>|]'), '_').trim();
      if (safeName.isEmpty) safeName = p.id;
      final filePath =
          '${f.linkedDirPath}${Platform.pathSeparator}$safeName.json';
      // 画像/PDF をポータブルな data:URL に埋め込んで書き出す
      final pageJson = await _pageToPortableJson(p);
      final json = jsonEncode({
        'version': 3,
        'pages': [pageJson],
      });
      await File(filePath).writeAsString(json);
    } catch (e) {
      debugPrint('autoSavePageIfLinked failed: $e');
    }
  }

  /// フォルダー名を変更
  void renameFolder(String folderId, String newName) {
    final f = _folders.firstWhere((e) => e.id == folderId,
        orElse: () => MindMapFolder(id: '', name: ''));
    if (f.id.isEmpty) return;
    f.name = newName;
    _saveFoldersToStorage();
    notifyListeners();
  }

  /// フォルダーの展開/折り畳み状態を切り替え
  void toggleFolderExpanded(String folderId) {
    final f = _folders.firstWhere((e) => e.id == folderId,
        orElse: () => MindMapFolder(id: '', name: ''));
    if (f.id.isEmpty) return;
    f.expanded = !f.expanded;
    _saveFoldersToStorage();
    notifyListeners();
  }

  /// フォルダーを削除（中のページはルートに戻す。中身のページは削除しない）
  void deleteFolder(String folderId, {bool deletePages = false}) {
    final idx = _folders.indexWhere((e) => e.id == folderId);
    if (idx < 0) return;
    if (deletePages) {
      // フォルダー内のページも削除
      final toDelete = _pages.where((p) => p.folderId == folderId).toList();
      for (final p in toDelete) {
        final i = _pages.indexOf(p);
        if (i >= 0 && _pages.length > 1) {
          _markPageDeletedForStorage(p.id);
          _pages.removeAt(i);
          // クラウド上のデータは残す (deletePage と同じ理由)。
        }
      }
      _currentPageIndex = _currentPageIndex.clamp(0, _pages.length - 1);
    } else {
      // 中のページはルートに戻す
      for (final p in _pages) {
        if (p.folderId == folderId) p.folderId = null;
      }
    }
    _folders.removeAt(idx);
    // 削除したフォルダーが Ctrl+1〜9 の基準なら null にリセット
    if (_shortcutFolderId == folderId) {
      _shortcutFolderId = null;
      _prefsWithRetry().then((prefs) => prefs.remove(_kShortcutFolderId));
    }
    _saveFoldersToStorage();
    _saveToStorage();
    notifyListeners();
  }

  /// 複数のフォルダー & ページを一括削除する。
  /// - フォルダー削除時、その中のページも一緒に削除
  /// - 既存の deleteFolder/deletePage を内部で再利用するが、notifyListeners は
  ///   最後に 1 回だけ発火する (UI のチラつき防止)
  /// - 削除後に最低 1 ページ残るよう自動で保護する
  void bulkDeletePagesAndFolders({
    required List<String> folderIds,
    required List<String> pageIds,
  }) {
    if (folderIds.isEmpty && pageIds.isEmpty) return;
    // 削除対象ページ ID を集計 (重複なし)
    final allTargetPages = <String>{};
    allTargetPages.addAll(pageIds);
    for (final fid in folderIds) {
      for (final p in _pages.where((e) => e.folderId == fid)) {
        allTargetPages.add(p.id);
      }
    }
    // ── ページ削除 ──
    // 最低 1 ページは残す (currentPage アクセスでクラッシュしないため)
    for (final pid in allTargetPages) {
      if (_pages.length <= 1) break;
      final i = _pages.indexWhere((e) => e.id == pid);
      if (i < 0) continue;
      _markPageDeletedForStorage(pid);
      _pages.removeAt(i);
      // クラウド上のデータは残す (deletePage と同じ理由)。
    }
    _currentPageIndex = _currentPageIndex.clamp(0, _pages.length - 1);
    // ── フォルダー削除 ──
    for (final fid in folderIds) {
      _folders.removeWhere((f) => f.id == fid);
      // 残ったページがそのフォルダーを参照していたらルートに戻す
      for (final p in _pages) {
        if (p.folderId == fid) p.folderId = null;
      }
    }
    // ショートカット基準フォルダーが削除されていたら null に戻す
    if (_shortcutFolderId != null && folderIds.contains(_shortcutFolderId)) {
      _shortcutFolderId = null;
      _prefsWithRetry().then((prefs) => prefs.remove(_kShortcutFolderId));
    }
    _saveFoldersToStorage();
    _saveToStorage();
    notifyListeners();
  }

  /// 指定ページを指定フォルダーに移動（folderId が null ならルートに戻す）
  void movePageToFolder(String pageId, String? folderId) {
    final p = _pages.firstWhere((e) => e.id == pageId,
        orElse: () => MindMapPage(id: '', name: ''));
    if (p.id.isEmpty) return;
    // 存在しないフォルダーIDなら拒否
    if (folderId != null && !_folders.any((f) => f.id == folderId)) {
      return;
    }
    p.folderId = folderId;
    _saveToStorage();
    notifyListeners();
    // 移動先が連動フォルダーなら、そのページもディスクに書き出す
    if (folderId != null) autoSavePageIfLinked(pageId);
  }

  /// 複数ページを一括で指定フォルダーに移動 (notifyListeners は最後に 1 回)。
  /// drawer の複数選択 → Ctrl+G で新規フォルダー作成 → そこへ全部入れる、
  /// という操作で使用。
  void movePagesToFolder(Iterable<String> pageIds, String? folderId) {
    bool changed = false;
    final movedIds = <String>[];
    for (final id in pageIds) {
      final idx = _pages.indexWhere((e) => e.id == id);
      if (idx < 0) continue;
      if (folderId != null && !_folders.any((f) => f.id == folderId)) {
        continue;
      }
      _pages[idx].folderId = folderId;
      movedIds.add(id);
      changed = true;
    }
    if (changed) {
      _saveToStorage();
      notifyListeners();
      // 移動先が連動フォルダーなら、移動した全ページをディスクに書き出す
      if (folderId != null) {
        for (final id in movedIds) {
          autoSavePageIfLinked(id);
        }
      }
    }
  }

  /// 指定フォルダーに所属するページのリスト（ページ並び順を保持）
  List<MindMapPage> pagesInFolder(String? folderId) {
    final list = _pages.where((p) => p.folderId == folderId).toList();
    // ── ピン止め (お気に入り) されたマップを先頭に ──
    // ユーザー要望「ピンで留めたマップが一番上に出るように」 への対応。
    // 安定ソート: ピン同士・非ピン同士は元の _pages 順 (= 作成/並べ替え順)
    // を維持したまま、 ピンされたものだけをグループ先頭へ寄せる。
    if (_favoritePageIds.isEmpty) return list;
    final pinned = <MindMapPage>[];
    final others = <MindMapPage>[];
    for (final p in list) {
      if (_favoritePageIds.contains(p.id)) {
        pinned.add(p);
      } else {
        others.add(p);
      }
    }
    return [...pinned, ...others];
  }

  // ─── JSON エクスポート / インポート ─────────────────────────────────────
  /// 単一ページを JSON 文字列にエクスポート
  String exportPageAsJson(String pageId) {
    final p = _pages.firstWhere((e) => e.id == pageId,
        orElse: () => MindMapPage(id: '', name: ''));
    if (p.id.isEmpty) return '{}';
    return _jsonEncodePretty({
      'type': 'mindmap_page',
      'version': 1,
      'exportedAt': DateTime.now().millisecondsSinceEpoch,
      'page': p.toJson(),
    });
  }

  /// フォルダー（とその中のページ全部）を JSON 文字列にエクスポート
  String exportFolderAsJson(String folderId) {
    final f = _folders.firstWhere((e) => e.id == folderId,
        orElse: () => MindMapFolder(id: '', name: ''));
    if (f.id.isEmpty) return '{}';
    final pages = _pages.where((p) => p.folderId == folderId).toList();
    return _jsonEncodePretty({
      'type': 'mindmap_folder',
      'version': 1,
      'exportedAt': DateTime.now().millisecondsSinceEpoch,
      'folder': f.toJson(),
      'pages': pages.map((p) => p.toJson()).toList(),
    });
  }

  /// JSON 文字列からインポート。
  /// - 'mindmap_page' タイプ: 1 ページとして追加
  /// - 'mindmap_folder' タイプ: フォルダーを新規作成して中身ページを全部追加
  /// 戻り値: インポート結果を表す Map
  ///   { 'success': bool, 'addedPages': int, 'addedFolders': int,
  ///     'firstPageId': String?, 'message': String? }
  /// 自己完結 HTML プレビュー (= ユーザー要望のエクスポート形式) から、
  /// 埋め込まれたマップ JSON を取り出す。 生 JSON はそのまま返す。
  String _extractEmbeddedMapJson(String s) {
    final t = s.trimLeft();
    if (!t.startsWith('<')) return s; // 生 JSON
    const marker = 'id="mindmap-data"';
    final mi = s.indexOf(marker);
    if (mi < 0) return s;
    final open = s.indexOf('>', mi);
    if (open < 0) return s;
    final close = s.indexOf('</script>', open);
    if (close < 0) return s;
    return s.substring(open + 1, close).replaceAll('<\\/', '</').trim();
  }

  Map<String, dynamic> importFromJsonString(String jsonStr,
      {String? targetFolderId}) {
    try {
      // 自己完結 HTML プレビュー形式で出力された場合は埋め込み JSON を抽出。
      jsonStr = _extractEmbeddedMapJson(jsonStr);
      final dynamic raw = jsonDecode(jsonStr);
      if (raw is! Map) {
        return {
          'success': false,
          'addedPages': 0,
          'addedFolders': 0,
          'message': 'JSON が不正です',
        };
      }
      final m = raw.cast<String, dynamic>();
      final type = m['type'] as String?;
      if (type == 'mindmap_page') {
        final pageData = m['page'] as Map<String, dynamic>?;
        if (pageData == null) {
          return {
            'success': false,
            'addedPages': 0,
            'addedFolders': 0,
            'message': 'page フィールドがありません',
          };
        }
        final page = _importSinglePage(pageData, targetFolderId);
        _saveToStorage();
        notifyListeners();
        return {
          'success': true,
          'addedPages': 1,
          'addedFolders': 0,
          'firstPageId': page.id,
        };
      } else if (type == 'mindmap_folder') {
        // フォルダー新規作成
        final folderData = m['folder'] as Map<String, dynamic>?;
        final folderName = (folderData?['name'] as String?) ?? 'インポートフォルダー';
        final newFolderId = addFolder(name: folderName);
        final pageList = m['pages'] as List<dynamic>? ?? [];
        int added = 0;
        String? firstId;
        for (final item in pageList) {
          if (item is Map) {
            final p =
                _importSinglePage(item.cast<String, dynamic>(), newFolderId);
            firstId ??= p.id;
            added++;
          }
        }
        _saveToStorage();
        notifyListeners();
        return {
          'success': true,
          'addedPages': added,
          'addedFolders': 1,
          'firstPageId': firstId,
        };
      } else {
        // 単独 page オブジェクトを直接渡された場合の互換
        if (m.containsKey('nodes')) {
          final page = _importSinglePage(m, targetFolderId);
          _saveToStorage();
          notifyListeners();
          return {
            'success': true,
            'addedPages': 1,
            'addedFolders': 0,
            'firstPageId': page.id,
          };
        }
        return {
          'success': false,
          'addedPages': 0,
          'addedFolders': 0,
          'message': '未対応の type: $type',
        };
      }
    } catch (e) {
      return {
        'success': false,
        'addedPages': 0,
        'addedFolders': 0,
        'message': 'JSON 解析エラー: $e',
      };
    }
  }

  /// 内部: page JSON を読み取って _pages に追加
  MindMapPage _importSinglePage(
      Map<String, dynamic> pageJson, String? folderId) {
    var page = MindMapPage.fromJson(pageJson);
    // ID 衝突チェック: 同じ ID のページが既にあれば新しい ID を振る
    if (_pages.any((p) => p.id == page.id)) {
      // toJson/fromJson 経由で全フィールドを保ったままページ ID だけを
      // 振り直す。個別コンストラクタで作り直すと装飾・背景・ページ種別・
      // ギャラリー行列設定などが失われ、共有元と異なるページになっていた。
      final copyJson = Map<String, dynamic>.from(page.toJson())
        ..['id'] = _uuid.v4()
        ..['folderId'] = folderId;
      if (folderId == null) copyJson.remove('folderId');
      page = MindMapPage.fromJson(copyJson);
    } else {
      page.folderId = folderId;
    }
    _pages.add(page);
    return page;
  }

  /// 整形済み JSON 文字列を生成（読みやすさ重視。サイズは少し大きくなる）
  String _jsonEncodePretty(Object obj) {
    const encoder = JsonEncoder.withIndent('  ');
    return encoder.convert(obj);
  }

  void selectNode(String? id) {
    _selectedNodeId = id;
    notifyListeners();
  }

  /// FABから呼ばれる：指定位置に単独ノードを追加
  void addNodeAtCenter(Offset position) {
    addNodeAtCenterReturning(position);
  }

  /// addNodeAtCenter と同じだが、生成した MindMapNode を返す
  MindMapNode addNodeAtCenterReturning(Offset position) {
    const nodeW = 160.0;
    const nodeH = 42.0;
    const gap = 24.0;
    const canvasW = 20000.0;
    const canvasH = 20000.0;
    final nodeMap = currentPage.nodes;

    Offset candidate = Offset(
      position.dx.clamp(gap, canvasW - nodeW - gap),
      position.dy.clamp(gap, canvasH - nodeH - gap),
    );
    for (int i = 0; i < 30; i++) {
      bool overlap = false;
      for (final n in nodeMap.values) {
        if (_nodesOverlap(candidate, nodeW, nodeH, n, gap)) {
          overlap = true;
          candidate = Offset(
              candidate.dx,
              (n.position.dy + n.visualHeight + gap)
                  .clamp(gap, canvasH - nodeH - gap));
          break;
        }
      }
      if (!overlap) break;
    }
    final newNode = MindMapNode(
      id: _uuid.v4(),
      title: '',
      position: candidate,
      color: _childColor(),
      // 今いる作業レイヤーに置く (= ユーザー要望)。
      layer: activeLayer,
    );
    _pushUndo();
    nodeMap[newNode.id] = newNode;
    _selectedNodeId = newNode.id;
    // ギャラリーページなら追加直後にタイル整列 (= ユーザー要望: 自動で並ぶ)。
    _autoArrangeIfBookshelf();
    _saveToStorage();
    notifyListeners();
    return newNode;
  }

  // ─── MCP サーバー (= ユーザー要望: アプリ内蔵型で Claude からマップを
  //     編集できるように)。 公開 facade + ON/OFF 管理 ─────────────────────

  bool _mcpServerEnabled = false;
  bool get mcpServerEnabled => _mcpServerEnabled;
  McpServer? _mcpServer;
  String? get mcpServerUrl => _mcpServer?.url;

  /// 外部アプリ (Claude Desktop 等) からの接続を許すか
  /// (= ユーザー要望: 別のプログラムからは操作できないように)。
  ///
  /// 既定は false = **アプリ内の AI チャットからしか操作できない**。
  /// アプリ内チャットは HTTP を通さず直接ツールを呼ぶので、 サーバーを
  /// 立てなくても普通に動く。 true にした時だけ 127.0.0.1 で待ち受け、
  /// その場合も合言葉付き URL を知らないと入れない。
  bool _mcpExternalAllowed = false;
  bool get mcpExternalAllowed => _mcpExternalAllowed;

  Future<void> setMcpExternalAllowed(bool on) async {
    _mcpExternalAllowed = on;
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool('mcp_external_allowed', on);
    } catch (_) {}
    // 許可を切ったら即座に待ち受けを止める。
    if (!on) {
      await _mcpServer?.stop();
    } else if (_mcpServerEnabled) {
      await _startMcpListener();
    }
    notifyListeners();
  }

  Future<void> _loadMcpServerSetting() async {
    if (kIsWeb || !(Platform.isWindows || Platform.isMacOS || Platform.isLinux)) {
      return;
    }
    try {
      final prefs = await SharedPreferences.getInstance();
      _mcpExternalAllowed = prefs.getBool('mcp_external_allowed') ?? false;
      if (prefs.getBool('mcp_server_enabled') ?? false) {
        await setMcpServerEnabled(true, persist: false);
      }
    } catch (_) {}
  }

  /// 外部公開が許可されている時だけ待ち受けを開始する。
  Future<String?> _startMcpListener() async {
    if (!_mcpExternalAllowed) return null;
    _mcpServer ??= McpServer(this);
    // 起動のたびに新しい合言葉を作る。
    return _mcpServer!.start(token: _uuid.v4().replaceAll('-', ''));
  }

  /// MCP サーバーを起動 / 停止する。 起動成功でエンドポイント URL を返す。
  Future<String?> setMcpServerEnabled(bool on, {bool persist = true}) async {
    _mcpServerEnabled = on;
    if (persist) {
      try {
        final prefs = await SharedPreferences.getInstance();
        await prefs.setBool('mcp_server_enabled', on);
      } catch (_) {}
    }
    if (on) {
      // 外部公開が許可されていなければ待ち受けは立てない
      // (= アプリ内チャットは HTTP 不要でそのまま動く)。
      final url = await _startMcpListener();
      notifyListeners();
      return url;
    }
    await _mcpServer?.stop();
    notifyListeners();
    return null;
  }

  MindMapPage? mcpPageById(String pageId) {
    // AI は create_page の戻りを取り違えて空の pageId を渡すことがある。
    // その場合は「今開いているページ」 として扱う (= 指示が通らず
    // 「作成しました」 とだけ言われる事故を防ぐ)。
    if (pageId.trim().isEmpty) return _pages.isEmpty ? null : currentPage;
    for (final p in _pages) {
      if (p.id == pageId) return p;
    }
    return null;
  }

  // ── MCP で作った物を「今見ている場所」 に置くための状態 ──
  //    (= ユーザー要望: 右下に作られて探すのが面倒)。
  //    画面側が表示中の中心 (キャンバス座標) を随時教えてくれる。
  Offset? _mcpViewCenter;
  void setMcpViewCenter(Offset c) => _mcpViewCenter = c;

  /// MCP が書き込んだ後、 画面にそこへ寄ってもらうための合図。
  /// 画面側はこの番号の変化を見て、 対象ページへ切り替えて中央に寄せる。
  int _mcpFocusSeq = 0;
  int get mcpFocusSeq => _mcpFocusSeq;
  String? _mcpFocusPageId;
  String? get mcpFocusPageId => _mcpFocusPageId;
  void _requestMcpFocus(String pageId) {
    _mcpFocusPageId = pageId;
    _mcpFocusSeq++;
  }

  // ── MCP チャットの会話 (= ユーザー要望: セッションを分けて保存) ──
  //    1 セッション = {id, title, at, msgs:[{role,text,at}]}。
  //    prefs キー: mcp_chat_sessions_v1 / mcp_chat_current_v1
  List<Map<String, dynamic>> _mcpSessions = [];
  String? _mcpCurrentSessionId;

  List<Map<String, dynamic>> get mcpSessions => List.unmodifiable(_mcpSessions);
  String? get mcpCurrentSessionId => _mcpCurrentSessionId;

  Map<String, dynamic>? get _currentSession {
    if (_mcpCurrentSessionId == null) return null;
    for (final s in _mcpSessions) {
      if (s['id'] == _mcpCurrentSessionId) return s;
    }
    return null;
  }

  /// 今のセッションのやり取り。
  List<Map<String, dynamic>> get mcpChatHistory {
    final s = _currentSession;
    if (s == null) return const [];
    final m = s['msgs'];
    return m is List
        ? [
            for (final e in m)
              if (e is Map) e.cast<String, dynamic>()
          ]
        : const [];
  }

  Future<void> loadMcpChatHistory() async {
    try {
      final prefs = await _prefsWithRetry();
      final raw = prefs.getString('mcp_chat_sessions_v1');
      if (raw != null && raw.isNotEmpty) {
        final j = jsonDecode(raw);
        if (j is List) {
          _mcpSessions = [
            for (final e in j)
              if (e is Map) e.cast<String, dynamic>()
          ];
        }
      }
      _mcpCurrentSessionId = prefs.getString('mcp_chat_current_v1');
      if (_currentSession == null) {
        // 保存が無い / 壊れている時は新しい会話から始める。
        if (_mcpSessions.isNotEmpty) {
          _mcpCurrentSessionId = '${_mcpSessions.last['id']}';
        } else {
          await newMcpSession(save: false);
        }
      }
      notifyListeners();
    } catch (e) {
      debugPrint('MCP 履歴の読み込みに失敗: $e');
    }
  }

  /// AI にいつも守らせたい前提 (= ユーザー要望: Markdown のように自分で
  /// 書いて置ける)。 毎回の指示の先頭に添える。
  String _mcpPreamble = '';
  String get mcpPreamble => _mcpPreamble;
