    _mcpPreamble = v;
    notifyListeners();
    try {
      final prefs = await _prefsWithRetry();
      await prefs.setString('mcp_preamble_v1', v);
    } catch (_) {}
  }

  Future<void> loadMcpPreamble() async {
    try {
      final prefs = await _prefsWithRetry();
      _mcpPreamble = prefs.getString('mcp_preamble_v1') ?? '';
      notifyListeners();
    } catch (_) {}
  }

  // ─── AI に既定で渡すアプリの説明書 (= ユーザー要望: skills / AGENTS.md の
  //     ように、 アプリのキーで AI を使う場面では既定で渡しておく) ──────────
  //
  // 二段構えにしている:
  //   ① AGENTS.md … 毎回そのまま渡す軽い前提 (数 KB)
  //   ② docs/*.md … 詳細。 毎回渡すとトークンを食い潰すので、 AI が
  //                  read_app_doc ツールで必要な時だけ取り寄せる
  static const Map<String, String> _kAppDocAssets = {
    'billing': 'assets/ai/docs/billing.md',
    'mcp': 'assets/ai/docs/mcp.md',
    'features': 'assets/ai/docs/features.md',
    'layout': 'assets/ai/docs/layout.md',
    'qa': 'assets/ai/docs/qa.md',
    'website': 'assets/ai/docs/website.md',
  };

  static const Map<String, String> _kAppDocTitles = {
    'billing': '決済・サブスク・AI クレジット',
    'mcp': 'MCP サーバーとツールの全仕様',
    'features': '起動・保存・同期・通知など主要機能の流れ',
    'layout': 'ノードの配置・押しのけ・自動整列',
    'qa': 'バグチェックリスト (過去の不具合と確認手順)',
    'website': '公開サイト hisator-notebook.com の作り',
  };

  String _appAgentsGuide = '';

  /// AI に毎回渡すアプリの説明書 (読み込み前は空)。
  String get appAgentsGuide => _appAgentsGuide;

  /// AGENTS.md を同梱アセットから読む (1 回だけ)。
  Future<String> loadAppAgentsGuide() async {
    if (_appAgentsGuide.isNotEmpty) return _appAgentsGuide;
    try {
      _appAgentsGuide = await rootBundle.loadString('assets/ai/AGENTS.md');
    } catch (e) {
      debugPrint('AGENTS.md の読み込みに失敗: $e');
      _appAgentsGuide = '';
    }
    return _appAgentsGuide;
  }

  /// 読める説明書の一覧 (MCP の list_app_docs 用)。
  List<Map<String, String>> mcpListAppDocs() => [
        for (final e in _kAppDocTitles.entries)
          {'name': e.key, 'title': e.value}
      ];

  /// 説明書 1 本を読む (MCP の read_app_doc 用)。 無ければ null。
  /// [maxChars] を超える分は切り詰めて、 続きの読み方を末尾に添える。
  Future<String?> mcpReadAppDoc(String name, {int maxChars = 20000}) async {
    final key = _kAppDocAssets[name.trim().toLowerCase()];
    if (key == null) return null;
    try {
      final text = await rootBundle.loadString(key);
      if (text.length <= maxChars) return text;
      return '${text.substring(0, maxChars)}\n\n'
          '…(長いのでここまで。 全 ${text.length} 文字)';
    } catch (e) {
      debugPrint('説明書の読み込みに失敗 ($name): $e');
      return null;
    }
  }

  /// prefs 側に中身を持つページ (フリーノート/文書/動画編集) を MCP が
  /// 書き換えた回数。 画面はこれを ValueKey に混ぜて読み直す
  /// (中身はページ JSON に乗らないので notifyListeners だけでは反映されない)。
  int _mcpContentTick = 0;
  int get mcpContentTick => _mcpContentTick;

  /// モデル名と残りトークンの行を隠すか (= ユーザー要望: 文字が気になるので
  /// 表示/非表示を切り替えたい)。
  bool _mcpModelBarHidden = false;
  bool get mcpModelBarHidden => _mcpModelBarHidden;
